/* Erzeugt von scripts/build-syntax-glossary.mjs aus content/syntax-glossary/. Nicht von Hand ändern. */
var RP_GLOSSARY=[{"id":"html","label":"HTML","codeLang":"html","intro":"Beschreibt Struktur und Bedeutung einer Seite. Zuerst das passende Element wählen, erst danach das Aussehen mit CSS.","notice":"Die Beispiele werden nicht ausgeführt. Zum Ausprobieren in eine .html-Datei kopieren und im Browser öffnen.","runner":"","entries":[{"id":"html-doc","cat":"Dokument","term":"<!doctype html> und Grundgerüst","syntax":"<!doctype html>\n<html lang=\"de\">…</html>","text":"Jede Seite beginnt mit dem Doctype. lang am html-Element nennt die Sprache (wichtig für Screenreader und Silbentrennung). Im head stehen Zeichensatz, Viewport und Titel.","code":"<!doctype html>\n<html lang=\"de\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Meine Seite</title>\n</head>\n<body>\n  <h1>Hallo</h1>\n</body>\n</html>","pitfall":"Ohne meta viewport wird die Seite auf Smartphones als verkleinerte Desktop-Seite gezeigt.","lesson":"html-m1-l1","tested":false},{"id":"html-headings","cat":"Struktur","term":"h1 bis h6","syntax":"<h1>…</h1> … <h6>…</h6>","text":"Überschriften gliedern die Seite. Es gibt eine h1 pro Seite, darunter folgen h2, h3 … ohne Ebenen zu überspringen.","code":"<h1>Rezepte</h1>\n<h2>Suppen</h2>\n<h3>Tomatensuppe</h3>","pitfall":"Überschriftenebenen nicht nach der Schriftgröße wählen. Größe bestimmt CSS, die Ebene die Struktur.","lesson":"html-m1-l2","tested":false},{"id":"html-landmarks","cat":"Struktur","term":"header, nav, main, footer, section, article","syntax":"<main>…</main>","text":"Semantische Bereiche statt <div>. main gibt es einmal pro Seite, nav enthält Navigation, article ist in sich abgeschlossen, section ein Themenabschnitt mit Überschrift.","code":"<header>…</header>\n<nav aria-label=\"Hauptnavigation\">…</nav>\n<main id=\"inhalt\">\n  <article>\n    <h2>Artikel</h2>\n  </article>\n</main>\n<footer>…</footer>","pitfall":"Gibt es mehrere nav-Bereiche, braucht jeder ein eigenes aria-label, damit Screenreader sie unterscheiden können.","lesson":"html-m1-l2","tested":false},{"id":"html-text","cat":"Text","term":"p, strong, em, code","syntax":"<p>…</p>    <strong>…</strong>    <em>…</em>","text":"p ist ein Absatz. strong markiert wichtige Stellen, em betont. code zeigt Quelltext. Zeilenumbrüche setzt man nicht mit <br> zur Abstandsgestaltung.","code":"<p>Das ist <strong>wichtig</strong> und das <em>betont</em>. Befehl: <code>git status</code></p>","pitfall":"Nicht <b> und <i> verwenden, nur um etwas fett oder kursiv darzustellen. Sie tragen keine Bedeutung.","lesson":"html-m1-l2","tested":false},{"id":"html-link","cat":"Links und Medien","term":"a (Link)","syntax":"<a href=\"ziel\">Text</a>","text":"Link zu einer anderen Seite, Datei oder Stelle (#anker). Der Linktext soll das Ziel beschreiben. Für Aktionen ohne Navigation gehört stattdessen ein <button> hin.","code":"<a href=\"/kontakt\">Kontakt aufnehmen</a>\n<a href=\"https://example.org\" rel=\"noopener\" target=\"_blank\">Beispiel (neues Fenster)</a>","pitfall":"Linktexte wie „hier klicken“ sagen Screenreader-Nutzern nichts. Bei target=\"_blank\" den Hinweis „neues Fenster“ in den Text aufnehmen.","lesson":"html-m1-l3","tested":false},{"id":"html-lists","cat":"Text","term":"ul, ol, li","syntax":"<ul><li>…</li></ul>","text":"ul ist eine Liste ohne Reihenfolge, ol eine nummerierte Liste. Direkte Kinder sind nur li-Elemente.","code":"<ol>\n  <li>Wasser kochen</li>\n  <li>Nudeln hinzufügen</li>\n</ol>","pitfall":"Navigationen sind Listen von Links. Das als ul in nav auszuzeichnen hilft Screenreadern beim Zählen der Einträge.","lesson":"html-m1-l3","tested":false},{"id":"html-img","cat":"Links und Medien","term":"img","syntax":"<img src=\"datei.jpg\" alt=\"Beschreibung\" width=\"800\" height=\"600\">","text":"Bindet ein Bild ein. alt beschreibt den Inhalt, bei rein dekorativen Bildern bleibt es leer (alt=\"\"). width und height verhindern Layout-Sprünge. loading=\"lazy\" lädt Bilder unterhalb des sichtbaren Bereichs später.","code":"<img src=\"team.jpg\" alt=\"Das Team vor dem Büro\" width=\"800\" height=\"600\" loading=\"lazy\">","pitfall":"Das wichtigste Bild am Seitenanfang (LCP) niemals lazy laden. Das verzögert die Anzeige.","lesson":"html-m1-l3","tested":false},{"id":"html-button","cat":"Formulare","term":"button","syntax":"<button type=\"button\">Text</button>","text":"Schaltfläche für Aktionen. Ohne type innerhalb eines Formulars sendet sie das Formular ab. Mit type=\"button\" tut sie das nicht.","code":"<button type=\"button\">Menü öffnen</button>\n<button type=\"submit\">Absenden</button>","pitfall":"Kein <div onclick>. Der <button> ist per Tastatur bedienbar und für Screenreader erkennbar, das <div> nicht.","lesson":"html-m1-l4","tested":false},{"id":"html-form","cat":"Formulare","term":"form, label, input","syntax":"<label for=\"id\">Text</label>\n<input id=\"id\" name=\"feld\" type=\"…\">","text":"Jedes Feld hat ein sichtbares label, das per for mit der id des Felds verbunden ist. type wählt die Eingabeart (text, email, number, date, password …), name bestimmt den Parameternamen beim Senden.","code":"<form method=\"post\" action=\"/anmelden\">\n  <label for=\"mail\">E-Mail-Adresse</label>\n  <input id=\"mail\" name=\"email\" type=\"email\" autocomplete=\"email\" required>\n  <button type=\"submit\">Anmelden</button>\n</form>","pitfall":"placeholder ist kein Ersatz für ein label. Er verschwindet beim Tippen und hat oft zu wenig Kontrast.","lesson":"html-m1-l4","tested":false},{"id":"html-validation","cat":"Formulare","term":"required, pattern, min, max, minlength","syntax":"<input required minlength=\"8\" pattern=\"[0-9]{5}\">","text":"Native Prüfregeln. Der Browser zeigt Fehlermeldungen und verhindert das Absenden. Sie ersetzen nicht die Prüfung auf dem Server.","code":"<label for=\"plz\">Postleitzahl</label>\n<input id=\"plz\" name=\"plz\" inputmode=\"numeric\" pattern=\"[0-9]{5}\" required>","pitfall":"Die Browser-Prüfung lässt sich umgehen. Der Server muss immer erneut prüfen.","lesson":"html-m1-l4","tested":false},{"id":"html-select","cat":"Formulare","term":"select, textarea, fieldset","syntax":"<select>…</select>    <textarea>…</textarea>    <fieldset><legend>…</legend></fieldset>","text":"select bietet eine Auswahl, textarea mehrzeiligen Text. fieldset mit legend fasst zusammengehörende Felder (z. B. Radiobuttons) zu einer benannten Gruppe zusammen.","code":"<fieldset>\n  <legend>Zahlungsart</legend>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"karte\"> Karte</label>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"rechnung\"> Rechnung</label>\n</fieldset>","pitfall":"Radiobuttons mit demselben name bilden eine Gruppe. Ohne gemeinsamen name lassen sich mehrere gleichzeitig wählen.","lesson":"html-m1-l4","tested":false},{"id":"html-table","cat":"Tabellen","term":"table, th, td","syntax":"<table><caption>…</caption><thead>…</thead><tbody>…</tbody></table>","text":"Tabellen sind für Daten gedacht, nicht fürs Layout. caption beschreibt sie, th mit scope=\"col\" oder \"row\" kennzeichnet Überschriftenzellen.","code":"<table>\n  <caption>Preise</caption>\n  <thead>\n    <tr><th scope=\"col\">Artikel</th><th scope=\"col\">Preis</th></tr>\n  </thead>\n  <tbody>\n    <tr><th scope=\"row\">Tee</th><td>3,50 €</td></tr>\n  </tbody>\n</table>","pitfall":"Auf schmalen Bildschirmen laufen breite Tabellen über. Sie in einen Container mit overflow-x: auto setzen.","lesson":"html-m1-l5","tested":false},{"id":"html-aria","cat":"Barrierefreiheit","term":"aria-label und aria-describedby","syntax":"<button aria-label=\"Menü schließen\">✕</button>","text":"ARIA ergänzt Namen und Beziehungen, wenn natives HTML nicht reicht. aria-label benennt Elemente ohne sichtbaren Text, aria-describedby verknüpft Hilfe- oder Fehlertexte mit einem Feld.","code":"<label for=\"pw\">Passwort</label>\n<input id=\"pw\" type=\"password\" aria-describedby=\"pw-hilfe\">\n<p id=\"pw-hilfe\">Mindestens 12 Zeichen.</p>","pitfall":"Kein ARIA ist besser als falsches ARIA. Erst prüfen, ob ein natives Element (button, label, nav) die Aufgabe schon erfüllt.","lesson":"html-m1-l5","tested":false},{"id":"html-meta","cat":"Dokument","term":"link und script","syntax":"<link rel=\"stylesheet\" href=\"stil.css\">\n<script src=\"app.js\" defer></script>","text":"link bindet Stylesheets ein, script bindet JavaScript ein. defer lädt das Skript parallel und führt es nach dem Parsen aus. type=\"module\" lädt ES-Module.","code":"<link rel=\"stylesheet\" href=\"stil.css\">\n<script type=\"module\" src=\"app.js\"></script>","pitfall":"Skripte ohne defer oder type=\"module\" blockieren den Seitenaufbau. Dadurch sinkt die Ladegeschwindigkeit.","lesson":"html-m1-l1","tested":false},{"id":"html-popover","cat":"Struktur","term":"popover und popovertarget","syntax":"<button popovertarget=\"id\">    <div id=\"id\" popover>","text":"Ein Popover ist eine überlagerte Fläche (Menü, Hinweis) ohne JavaScript. Der Browser blendet sie ein und aus, schließt sie mit Escape oder Klick daneben und legt sie über die übrige Seite („Top Layer“). popover=\"manual\" schließt nur auf Befehl.","code":"<button type=\"button\" popovertarget=\"hilfe\">Hilfe</button>\n<div id=\"hilfe\" popover>\n  <p>Alle Felder mit * sind Pflichtfelder.</p>\n  <button type=\"button\" popovertarget=\"hilfe\" popovertargetaction=\"hide\">Schließen</button>\n</div>","pitfall":"Ein Popover ist kein Dialog: Es hat keine Fokusfalle und gilt nicht als modal. Für Fenster, die Eingaben erzwingen, dialog mit showModal() verwenden.","lesson":"html-m1-l2","tested":false},{"id":"html-datalist","cat":"Formulare","term":"datalist (Vorschläge) und autocomplete","syntax":"<input list=\"id\">  <datalist id=\"id\"><option value=\"…\"></datalist>    autocomplete=\"email\"","text":"datalist bietet Vorschläge an, der Nutzer darf aber auch etwas anderes eintippen. autocomplete mit festen Schlüsselwörtern (email, given-name, postal-code, new-password) lässt den Browser Felder zuverlässig ausfüllen.","code":"<label for=\"stadt\">Stadt</label>\n<input id=\"stadt\" name=\"stadt\" list=\"staedte\" autocomplete=\"address-level2\">\n<datalist id=\"staedte\">\n  <option value=\"Berlin\"></option>\n  <option value=\"Hamburg\"></option>\n  <option value=\"München\"></option>\n</datalist>\n\n<label for=\"mail\">E-Mail</label>\n<input id=\"mail\" name=\"mail\" type=\"email\" autocomplete=\"email\" required>","pitfall":"Die Auswahl in einer datalist ist nur ein Vorschlag, keine Prüfung. Die Eingabe muss serverseitig validiert werden. autocomplete=\"off\" bei Passwortfeldern stört Passwortmanager und ist ein Barrierefreiheitsproblem.","lesson":"html-m1-l4","tested":false},{"id":"html-more-inputs","cat":"Formulare","term":"file, range, color, checkbox, radio","syntax":"<input type=\"file\" accept=\"image/*\">    type=\"range\"    type=\"color\"    type=\"checkbox|radio\"","text":"file wählt Dateien (accept schränkt die Typen ein, multiple erlaubt mehrere). range ist ein Schieberegler, color eine Farbauswahl. Radiobuttons mit gleichem name sind eine Gruppe, in der genau eine Option gilt, Checkboxen sind unabhängig.","code":"<label for=\"bild\">Profilbild (JPG oder PNG, höchstens 2 MB)</label>\n<input id=\"bild\" name=\"bild\" type=\"file\" accept=\"image/jpeg,image/png\">\n\n<label for=\"lautstaerke\">Lautstärke</label>\n<input id=\"lautstaerke\" name=\"lautstaerke\" type=\"range\" min=\"0\" max=\"100\" value=\"50\">\n\n<fieldset>\n  <legend>Zahlungsart</legend>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"rechnung\" checked> Rechnung</label>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"lastschrift\"> Lastschrift</label>\n</fieldset>","pitfall":"accept ist nur ein Vorschlag an den Dateidialog. Größe und tatsächlichen Typ immer serverseitig prüfen. Gruppen von Radiobuttons gehören in ein fieldset mit legend.","lesson":"html-m1-l4","tested":false},{"id":"html-form-attributes","cat":"Formulare","term":"form: method, action, enctype, novalidate","syntax":"<form method=\"post\" action=\"/senden\" enctype=\"multipart/form-data\" novalidate>","text":"method=\"get\" hängt die Daten an die Adresse (für Suchen), method=\"post\" sendet sie im Körper (für Änderungen). enctype=\"multipart/form-data\" ist für Datei-Uploads nötig. novalidate schaltet die Browser-Prüfung ab, wenn man selbst validiert. Der name eines Felds ist der Schlüssel im gesendeten Datensatz.","code":"<form method=\"post\" action=\"/kontakt\" autocomplete=\"on\">\n  <label for=\"nachricht\">Nachricht</label>\n  <textarea id=\"nachricht\" name=\"nachricht\" required minlength=\"10\"></textarea>\n  <button type=\"submit\">Nachricht senden</button>\n</form>\n\n<form method=\"get\" action=\"/suche\" role=\"search\">\n  <label for=\"q\">Suche</label>\n  <input id=\"q\" name=\"q\" type=\"search\">\n  <button type=\"submit\">Suchen</button>\n</form>","pitfall":"Felder ohne name werden nicht gesendet. Kein get für Passwörter oder personenbezogene Daten (Adresse landet in Verlauf und Logs). Bei Änderungen CSRF-Schutz serverseitig einbauen.","lesson":"html-m1-l4","tested":false},{"id":"html-script-loading","cat":"Dokument","term":"script: defer, async, type=\"module\"","syntax":"<script src=\"a.js\" defer>    <script src=\"b.js\" async>    <script type=\"module\" src=\"c.js\">","text":"Ohne Zusatz blockiert ein Skript das Parsen der Seite. defer lädt parallel und führt nach dem Parsen in Reihenfolge aus. async führt aus, sobald es geladen ist (Reihenfolge offen). Module sind automatisch deferred und strikt.","code":"<script src=\"/js/hauptprogramm.js\" defer></script>\n<script src=\"/js/statistik.js\" async></script>\n<script type=\"module\" src=\"/js/app.js\"></script>\n<script nomodule src=\"/js/alt.js\"></script>","pitfall":"defer und async wirken nur bei Skripten mit src, nicht bei Inline-Skripten. Skripte von Drittanbietern erst nach Einwilligung laden.","lesson":"html-m1-l1","tested":false},{"id":"html-link-rel","cat":"Links und Medien","term":"Links: target, rel, download, mailto, tel","syntax":"<a href=\"…\" target=\"_blank\" rel=\"noopener noreferrer\">    <a href=\"datei.pdf\" download>    <a href=\"mailto:…\">","text":"target=\"_blank\" öffnet einen neuen Tab (moderne Browser setzen noopener automatisch, trotzdem rel angeben schadet nicht). rel=\"nofollow\" oder \"sponsored\" kennzeichnet Links für Suchmaschinen. download lädt statt zu navigieren. mailto: und tel: starten Mail- oder Telefon-Apps.","code":"<a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\">Externe Seite<span class=\"visually-hidden\"> (öffnet in neuem Tab)</span></a>\n<a href=\"/preisliste.pdf\" download>Preisliste (PDF, 240 KB)</a>\n<a href=\"mailto:info@example.org\">E-Mail schreiben</a>\n<a href=\"tel:+4930123456\">030 123456</a>","pitfall":"Neue Tabs ohne Hinweis verwirren Screenreader-Nutzer. Linktexte müssen allein verständlich sein („Preisliste“, nicht „hier klicken“).","lesson":"html-m1-l3","tested":false},{"id":"html-dl-lists","cat":"Text","term":"dl, dt, dd (Beschreibungslisten)","syntax":"<dl><dt>Begriff</dt><dd>Erklärung</dd></dl>","text":"Eine Beschreibungsliste gehört zu Paaren aus Begriff und Erklärung: Glossare, Eigenschaften, technische Daten, Kontaktzeilen. Screenreader kündigen sie als Liste von Begriffen an.","code":"<dl>\n  <dt>Lieferzeit</dt>\n  <dd>2 bis 3 Werktage</dd>\n  <dt>Zahlungsarten</dt>\n  <dd>Rechnung</dd>\n  <dd>Lastschrift</dd>\n</dl>","pitfall":"Keine Tabelle für Layout und keine dl für beliebige Abstände. Für Zahlen mit mehreren Spalten ist eine echte table besser.","lesson":"html-m1-l3","tested":false},{"id":"html-table-a11y","cat":"Tabellen","term":"Tabelle: caption, thead, scope, colspan","syntax":"<table><caption>…</caption><thead><tr><th scope=\"col\">…</th></tr></thead><tbody>…</tbody></table>","text":"Eine zugängliche Tabelle hat eine Beschriftung (caption), Kopfzeilen mit scope=\"col\", bei Zeilenüberschriften scope=\"row\". thead, tbody und tfoot gliedern. colspan und rowspan verbinden Zellen, sollten aber sparsam eingesetzt werden.","code":"<table>\n  <caption>Umsatz je Quartal 2026 (in Euro)</caption>\n  <thead>\n    <tr><th scope=\"col\">Quartal</th><th scope=\"col\">Umsatz</th></tr>\n  </thead>\n  <tbody>\n    <tr><th scope=\"row\">Q1</th><td>12.400</td></tr>\n    <tr><th scope=\"row\">Q2</th><td>15.900</td></tr>\n  </tbody>\n  <tfoot>\n    <tr><th scope=\"row\">Summe</th><td>28.300</td></tr>\n  </tfoot>\n</table>","pitfall":"Breite Tabellen auf dem Handy in einem Container mit overflow-x: auto zeigen und der Region einen Namen geben (role=\"region\" aria-labelledby), sonst läuft die Seite über.","lesson":"html-m1-l5","tested":false},{"id":"html-template-components","cat":"Struktur","term":"template, slot und Custom Elements","syntax":"<template>    customElements.define(\"mein-element\", class extends HTMLElement { … })    <slot>","text":"template hält Markup bereit, das nicht dargestellt wird, bis man es per Skript kopiert. Custom Elements (Namen mit Bindestrich) definieren eigene Tags, Shadow DOM kapselt Stil und Struktur, slot nimmt Inhalte von außen auf. Das ist die Grundlage der Web Components.","code":"<template id=\"karte\">\n  <style>.karte { border: 1px solid; padding: 1rem; }</style>\n  <div class=\"karte\"><slot name=\"titel\"></slot><slot></slot></div>\n</template>\n\n<script>\n  customElements.define('info-karte', class extends HTMLElement {\n    connectedCallback() {\n      const schatten = this.attachShadow({ mode: 'open' });\n      schatten.append(document.getElementById('karte').content.cloneNode(true));\n    }\n  });\n</script>\n\n<info-karte><h3 slot=\"titel\">Hinweis</h3>Text der Karte</info-karte>","pitfall":"Inhalte nur per Skript einzublenden schadet Suchmaschinen und Nutzern ohne JavaScript. Wichtige Texte müssen im HTML stehen. Formularfelder im Shadow DOM brauchen besondere Sorgfalt.","lesson":"js-m1-l5","tested":false},{"id":"html-semantic-text","cat":"Text","term":"mark, kbd, sub, sup, pre, address, search","syntax":"<mark>  <kbd>  <sub> <sup>  <pre><code>  <address>  <search>","text":"Weitere Elemente mit Bedeutung: mark hebt einen Treffer hervor, kbd steht für Tastatureingaben, sub und sup für tiefer- und hochgestellten Text, pre behält Leerraum, address enthält Kontaktdaten, search umschließt einen Suchbereich (Landmark).","code":"<p>Drücke <kbd>Strg</kbd> + <kbd>S</kbd> zum Speichern.</p>\n<p>Wasser: H<sub>2</sub>O, Fläche: 5 m<sup>2</sup></p>\n<pre><code>npm install\nnpm run dev</code></pre>\n<address>Musterfirma GmbH<br>Hauptstraße 1<br>12345 Berlin</address>\n<search>\n  <form action=\"/suche\"><label for=\"s\">Suche</label> <input id=\"s\" name=\"q\" type=\"search\"></form>\n</search>","pitfall":"em, strong und mark nicht nur wegen der Optik verwenden, sondern wegen der Bedeutung. Die Optik gehört ins CSS.","lesson":"html-m1-l2","tested":false},{"id":"html-preload-priority","cat":"Links und Medien","term":"fetchpriority, preload, loading und decoding","syntax":"<img fetchpriority=\"high\">    <link rel=\"preload\" as=\"font\" href=\"…\" crossorigin>    loading=\"lazy\"    decoding=\"async\"","text":"Wichtige Bilder (der größte sichtbare Inhalt, LCP) bekommen fetchpriority=\"high\" und kein lazy. Unterhalb des sichtbaren Bereichs sparen loading=\"lazy\" und decoding=\"async\" Daten und Rechenzeit. preload lädt kritische Schriften früh.","code":"<link rel=\"preload\" href=\"/fonts/inter-latin.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n\n<img src=\"/bilder/held.avif\" alt=\"Werkstatt bei Sonnenaufgang\" width=\"1200\" height=\"600\" fetchpriority=\"high\">\n\n<img src=\"/bilder/team.avif\" alt=\"Das Team\" width=\"600\" height=\"400\" loading=\"lazy\" decoding=\"async\">","pitfall":"Zu viele preload-Angaben bremsen sich gegenseitig. Nur das Bild und die Schrift des ersten Bildschirms vorladen. Schriften immer selbst hosten (DSGVO).","lesson":"html-m1-l3","tested":false},{"id":"html-inline-svg","cat":"Links und Medien","term":"Inline-SVG: title, role und aria-hidden","syntax":"<svg role=\"img\" aria-labelledby=\"t\"><title id=\"t\">Beschreibung</title>…</svg>    aria-hidden=\"true\"","text":"SVG-Grafiken lassen sich direkt im HTML einbetten und per CSS färben. Informative Grafiken brauchen einen Namen (title mit role=\"img\"), rein dekorative werden mit aria-hidden=\"true\" für Screenreader ausgeblendet.","code":"<button type=\"button\">\n  <svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" aria-hidden=\"true\" focusable=\"false\">\n    <path d=\"M3 10l5 5 9-9\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  </svg>\n  Speichern\n</button>\n\n<svg role=\"img\" aria-labelledby=\"diagrammtitel\" viewBox=\"0 0 100 40\" width=\"200\">\n  <title id=\"diagrammtitel\">Umsatz steigt von 10 auf 30 Prozent</title>\n  <polyline points=\"0,35 50,20 100,5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n</svg>","pitfall":"Ein Icon-Button ohne sichtbaren Text braucht einen zugänglichen Namen (aria-label). Mit currentColor übernimmt das Icon die Textfarbe und passt zum Dunkelmodus.","lesson":"html-m1-l5","tested":false},{"id":"html-details","cat":"Struktur","term":"details und summary","syntax":"<details><summary>Titel</summary>Inhalt</details>","text":"Ein aufklappbarer Bereich ohne JavaScript. Das summary-Element ist die sichtbare Überschrift und per Tastatur bedienbar. Mit dem Attribut open startet der Bereich aufgeklappt.","code":"<details>\n  <summary>Wie lange dauert der Versand?</summary>\n  <p>Meist zwei bis drei Werktage.</p>\n</details>","pitfall":"Eigene Akkordeons aus div und Skript brauchen viel ARIA und Tastaturlogik. Erst prüfen, ob details genügt.","lesson":"html-m1-l2","tested":false},{"id":"html-dialog","cat":"Struktur","term":"dialog","syntax":"<dialog id=\"d\">…</dialog>    dialog.showModal()","text":"Natives Dialogfenster. showModal() öffnet es als Modal mit Fokusfalle und Abdunklung, Escape schließt es. Ein Formular mit method=\"dialog\" schließt es beim Absenden.","code":"<button type=\"button\" id=\"auf\">Einstellungen</button>\n<dialog id=\"dlg\" aria-labelledby=\"dlg-titel\">\n  <h2 id=\"dlg-titel\">Einstellungen</h2>\n  <form method=\"dialog\">\n    <button>Schließen</button>\n  </form>\n</dialog>\n<script>\n  auf.addEventListener('click', () => dlg.showModal());\n</script>","pitfall":"Dem Dialog einen Namen geben (aria-labelledby) und den Fokus nach dem Schließen auf den auslösenden Button zurückgeben. Der Browser macht das beim Modal meist von selbst.","lesson":"js-m2-l4","tested":false},{"id":"html-picture","cat":"Links und Medien","term":"picture, srcset und sizes","syntax":"<img srcset=\"a.jpg 480w, b.jpg 960w\" sizes=\"(min-width: 60rem) 50vw, 100vw\">","text":"Liefert je nach Bildschirm und Format das passende Bild. srcset nennt Varianten mit Breite, sizes sagt, wie breit das Bild dargestellt wird. picture mit source wählt zusätzlich nach Format (AVIF, WebP).","code":"<picture>\n  <source type=\"image/avif\" srcset=\"team-480.avif 480w, team-960.avif 960w\" sizes=\"(min-width: 60rem) 50vw, 100vw\">\n  <img src=\"team-960.jpg\" srcset=\"team-480.jpg 480w, team-960.jpg 960w\" sizes=\"(min-width: 60rem) 50vw, 100vw\"\n       alt=\"Das Team\" width=\"960\" height=\"640\">\n</picture>","pitfall":"Ohne width und height springt das Layout beim Laden. Das img-Element mit alt bleibt Pflicht, auch innerhalb von picture.","lesson":"html-m1-l3","tested":false},{"id":"html-video","cat":"Links und Medien","term":"video, audio und track","syntax":"<video controls src=\"film.mp4\"><track kind=\"captions\" src=\"de.vtt\" srclang=\"de\"></video>","text":"Bindet Medien ein. controls zeigt Bedienelemente, track liefert Untertitel. Videos mit Ton dürfen nicht von selbst starten. poster zeigt ein Vorschaubild.","code":"<video controls preload=\"metadata\" poster=\"vorschau.jpg\" width=\"640\" height=\"360\">\n  <source src=\"film.webm\" type=\"video/webm\">\n  <source src=\"film.mp4\" type=\"video/mp4\">\n  <track kind=\"captions\" src=\"untertitel-de.vtt\" srclang=\"de\" label=\"Deutsch\" default>\n</video>","pitfall":"Untertitel oder Transkript sind für Barrierefreiheit (WCAG) Pflicht. Videos von Drittanbietern erst nach Einwilligung laden (Zwei-Klick-Lösung).","lesson":"html-m1-l3","tested":false},{"id":"html-input-types","cat":"Formulare","term":"Eingabetypen und inputmode","syntax":"<input type=\"email|tel|url|number|date|search|password\" inputmode=\"numeric\">","text":"Der type bestimmt Tastatur, Prüfung und Bedienung auf Smartphones. inputmode wählt nur die Tastatur, ohne die Prüfung zu ändern. autocomplete hilft beim Ausfüllen.","code":"<label for=\"tel\">Telefon</label>\n<input id=\"tel\" name=\"tel\" type=\"tel\" autocomplete=\"tel\">\n<label for=\"alter\">Alter</label>\n<input id=\"alter\" name=\"alter\" type=\"number\" min=\"0\" max=\"120\" inputmode=\"numeric\">\n<label for=\"datum\">Termin</label>\n<input id=\"datum\" name=\"datum\" type=\"date\">","pitfall":"type=\"number\" ist für Zahlen zum Rechnen, nicht für Postleitzahlen oder Telefonnummern (führende Nullen gehen verloren). Dafür type=\"text\" mit inputmode.","lesson":"html-m1-l4","tested":false},{"id":"html-progress","cat":"Formulare","term":"progress, meter und output","syntax":"<progress value=\"30\" max=\"100\">    <meter min=\"0\" max=\"10\" value=\"7\">","text":"progress zeigt einen Fortschritt, meter einen Wert innerhalb eines Bereichs (z. B. Speicherplatz), output das Ergebnis einer Berechnung. Alle drei sind für Screenreader ansprechbar.","code":"<label for=\"p\">Upload</label>\n<progress id=\"p\" value=\"30\" max=\"100\">30 %</progress>\n<label for=\"m\">Passwortstärke</label>\n<meter id=\"m\" min=\"0\" max=\"4\" low=\"2\" high=\"3\" optimum=\"4\" value=\"3\">3 von 4</meter>","pitfall":"Der Text zwischen den Tags ist die Rückfallanzeige. Fehlt das value-Attribut, zeigt progress einen unbestimmten Zustand („lädt“).","lesson":"html-m1-l4","tested":false},{"id":"html-time-abbr","cat":"Text","term":"time, abbr, blockquote, figure","syntax":"<time datetime=\"2026-11-13\">    <abbr title=\"…\">    <figure><figcaption>","text":"Weitere Auszeichnungen mit Bedeutung. time gibt ein maschinenlesbares Datum, abbr erklärt Abkürzungen, blockquote markiert Zitate, figure mit figcaption ein Bild oder Diagramm samt Beschriftung.","code":"<p>Veröffentlicht am <time datetime=\"2026-11-13\">13. November 2026</time>.</p>\n<p>Die <abbr title=\"Allgemeine Datenschutz-Grundverordnung\">DSGVO</abbr> gilt seit 2018.</p>\n<figure>\n  <img src=\"kurve.png\" alt=\"Kurve: Nutzerzahlen steigen seit Juni\" width=\"600\" height=\"300\">\n  <figcaption>Abbildung 1: Nutzerzahlen 2026</figcaption>\n</figure>","pitfall":"Bei Diagrammen im alt-Text die Aussage beschreiben, nicht nur „Diagramm“.","lesson":"html-m1-l2","tested":false},{"id":"html-data-hidden","cat":"Struktur","term":"data-*, hidden und inert","syntax":"<li data-id=\"42\">    <div hidden>    <div inert>","text":"data-Attribute speichern eigene Werte am Element (im Skript über dataset). hidden blendet ein Element aus. inert macht einen Bereich unbedienbar und für Screenreader unsichtbar, praktisch hinter geöffneten Dialogen.","code":"<li data-id=\"42\" data-status=\"offen\">Aufgabe</li>\n<p hidden id=\"fehler\">Bitte Name angeben.</p>\n<script>\n  const li = document.querySelector('li');\n  console.log(li.dataset.id, li.dataset.status);\n</script>","pitfall":"In data-Attribute gehören keine Geheimnisse und keine großen Datenmengen. Sie sind für jeden im Quelltext lesbar.","lesson":"js-m1-l5","tested":false},{"id":"html-meta-seo","cat":"Dokument","term":"Meta-Angaben für Suchmaschinen und Teilen","syntax":"<meta name=\"description\" content=\"…\">    <link rel=\"canonical\" href=\"…\">","text":"Titel und Beschreibung erscheinen in Suchergebnissen. canonical nennt die bevorzugte Adresse einer Seite, robots steuert die Indexierung. Open-Graph-Angaben bestimmen die Vorschau beim Teilen.","code":"<title>Syntax-Glossar – ROOTPFAD</title>\n<meta name=\"description\" content=\"Befehle von HTML bis ABAP nachschlagen: Syntax, Beispiel und typische Fehler.\">\n<link rel=\"canonical\" href=\"https://example.org/glossar\">\n<meta property=\"og:title\" content=\"Syntax-Glossar\">\n<meta name=\"robots\" content=\"index, follow\">","pitfall":"Jede Seite braucht einen eigenen Titel und eine eigene Beschreibung. Doppelte Texte schwächen die Auffindbarkeit.","lesson":"html-m1-l1","tested":false},{"id":"html-skiplink","cat":"Barrierefreiheit","term":"Skip-Link und lang-Wechsel","syntax":"<a href=\"#inhalt\" class=\"skip\">Zum Inhalt</a>    <span lang=\"en\">…</span>","text":"Ein Skip-Link am Seitenanfang lässt Tastaturnutzer die Navigation überspringen. lang an einem Element markiert Fremdsprache, damit Screenreader richtig aussprechen.","code":"<a class=\"skip\" href=\"#inhalt\">Zum Inhalt springen</a>\n<nav aria-label=\"Hauptnavigation\">…</nav>\n<main id=\"inhalt\" tabindex=\"-1\">\n  <p>Das nennt man <span lang=\"en\">Dark Mode</span>.</p>\n</main>","pitfall":"Der Skip-Link darf bei Fokus nicht versteckt bleiben. Er muss sichtbar werden, wenn man ihn mit Tab erreicht.","lesson":"html-m1-l5","tested":false},{"id":"html-iframe","cat":"Links und Medien","term":"iframe, loading und sandbox","syntax":"<iframe src=\"…\" title=\"…\" loading=\"lazy\" sandbox>","text":"Bindet eine fremde Seite ein. title beschreibt den Inhalt für Screenreader, loading=\"lazy\" lädt erst bei Bedarf, sandbox schränkt Rechte stark ein. Für Videos und Karten nur nach Einwilligung laden.","code":"<iframe src=\"https://www.youtube-nocookie.com/embed/QrwFrm1R8OY\" title=\"Java 21 Pattern Matching Tutorial\"\n        loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>","pitfall":"Ein iframe lädt sofort Daten vom Anbieter, die IP-Adresse wird übertragen. Nach dem DSGVO-Grundsatz erst nach Klick (Zwei-Klick-Lösung).","lesson":"html-m1-l3","tested":false}]},{"id":"css","label":"CSS","codeLang":"css","intro":"Gestaltet HTML. Eine Regel besteht aus Selektor und Deklarationen: selektor { eigenschaft: wert; }","notice":"Die Beispiele werden nicht ausgeführt. Zum Ausprobieren in ein Stylesheet kopieren und mit einer HTML-Seite verbinden.","runner":"","entries":[{"id":"css-selectors","cat":"Selektoren","term":"Element-, Klassen- und ID-Selektor","syntax":"p { … }    .klasse { … }    #id { … }","text":"Ein Elementselektor trifft alle Elemente dieses Typs, .klasse trifft alle mit class=\"klasse\", #id genau ein Element. In der Praxis arbeitet man überwiegend mit Klassen.","code":"p { color: #222; }\n.karte { padding: 1rem; }\n#kopf { position: sticky; top: 0; }","pitfall":"ID-Selektoren sind sehr spezifisch und lassen sich schwer überschreiben. Für Gestaltung besser Klassen nehmen.","lesson":"css-m1-l1","tested":false},{"id":"css-combinators","cat":"Selektoren","term":"Kombinatoren","syntax":"a b    a > b    a + b    a ~ b","text":"Leerzeichen trifft Nachfahren, > nur direkte Kinder, + das unmittelbar folgende Geschwister, ~ alle folgenden Geschwister.","code":"nav a { text-decoration: none; }\nul > li { margin-block: .25rem; }\nh2 + p { font-size: 1.1rem; }","pitfall":"Lange Selektorketten (a b c d) koppeln CSS stark ans HTML. Besser eine Klasse am Zielelement vergeben.","lesson":"css-m1-l1","tested":false},{"id":"css-pseudo","cat":"Selektoren","term":"Pseudoklassen","syntax":":hover  :focus-visible  :first-child  :not(…)  :has(…)","text":"Wählen Elemente nach Zustand oder Position. :focus-visible zeigt den Fokus bei Tastaturbedienung, :has() wählt Elemente nach ihrem Inhalt, :not() schließt aus.","code":"a:hover { text-decoration: underline; }\n:focus-visible { outline: 3px solid #1a5fb4; outline-offset: 2px; }\n.karte:has(img) { display: grid; }","pitfall":"Den Fokusrahmen nie mit outline: none entfernen, ohne einen sichtbaren Ersatz zu liefern. Tastaturnutzer verlieren sonst die Orientierung.","lesson":"css-m1-l3","tested":false},{"id":"css-specificity","cat":"Kaskade","term":"Spezifität und Reihenfolge","syntax":"Inline > ID > Klasse/Attribut/Pseudoklasse > Element","text":"Treffen mehrere Regeln dasselbe Element, gewinnt die spezifischere. Bei gleicher Spezifität gilt die spätere. !important schaltet diese Ordnung aus und sollte vermieden werden.","code":"p { color: black; }\n.hinweis { color: blue; }      /* gewinnt gegen p */\n.hinweis { color: green; }     /* gewinnt gegen die vorige Regel */","pitfall":"Wer mit !important gegen !important kämpft, hat ein Strukturproblem. Besser Selektoren vereinfachen oder @layer verwenden.","lesson":"css-m1-l1","tested":false},{"id":"css-custom-props","cat":"Kaskade","term":"Custom Properties (var)","syntax":":root { --farbe: #1a5fb4; }    color: var(--farbe, schwarz);","text":"Eigene Variablen mit Namen, die mit -- beginnen. Sie werden vererbt und lassen sich je Bereich überschreiben. Gut für Farben, Abstände und Schriften.","code":":root {\n  --abstand: 1rem;\n  --akzent: #1a5fb4;\n}\n.knopf {\n  padding: var(--abstand);\n  background: var(--akzent);\n}","pitfall":"Custom Properties sind erst zur Laufzeit gültig. Ein Tippfehler im Namen ergibt keinen Fehler, nur einen leeren Wert.","lesson":"css-m1-l1","tested":false},{"id":"css-boxmodel","cat":"Boxmodell","term":"margin, padding, border, box-sizing","syntax":"box-sizing: border-box;","text":"Jedes Element ist eine Box: Inhalt, Innenabstand (padding), Rand (border), Außenabstand (margin). Mit box-sizing: border-box zählen padding und border zur angegebenen Breite.","code":"*, *::before, *::after { box-sizing: border-box; }\n.karte {\n  padding: 1rem;\n  border: 1px solid #ccc;\n  margin-block: 1.5rem;\n}","pitfall":"Vertikale Außenabstände zweier Geschwister verschmelzen („Margin Collapsing“). Der größere gewinnt, sie addieren sich nicht.","lesson":"css-m1-l2","tested":false},{"id":"css-units","cat":"Boxmodell","term":"Einheiten: rem, em, %, vw, ch","syntax":"font-size: 1rem;    width: min(100%, 70ch);","text":"rem bezieht sich auf die Basisschrift der Seite, em auf die des Elements, % auf das Elternelement, vw auf die Fensterbreite, ch auf die Breite einer „0“. Relative Einheiten respektieren die Einstellungen der Nutzer.","code":"body { font-size: 1rem; }\n.text { max-width: 70ch; }\nh1 { font-size: clamp(1.6rem, 4vw, 2.6rem); }","pitfall":"Schriftgrößen in px ignorieren die Schriftgröße-Einstellung des Browsers. Für Text rem verwenden.","lesson":"css-m1-l2","tested":false},{"id":"css-color-font","cat":"Typografie","term":"color, font-family, line-height","syntax":"font: 1rem/1.6 system-ui;","text":"color setzt die Textfarbe, font-family die Schriftart (mit Ersatzschriften), line-height den Zeilenabstand. Ein Zeilenabstand von etwa 1,5 liest sich gut.","code":"body {\n  font-family: \"IBM Plex Sans\", system-ui, sans-serif;\n  line-height: 1.6;\n  color: #1d1d1f;\n}","pitfall":"Textkontrast mindestens 4,5:1 (WCAG AA), bei großer Schrift 3:1. Hellgrau auf Weiß fällt oft durch.","lesson":"css-m1-l3","tested":false},{"id":"css-display","cat":"Layout","term":"display","syntax":"display: block | inline | inline-block | flex | grid | none","text":"Bestimmt, wie sich ein Element ins Layout einfügt. none blendet es samt Platz und aus dem Zugänglichkeitsbaum aus. flex und grid aktivieren die modernen Layoutmodelle für die Kinder.","code":".nav { display: flex; gap: 1rem; }\n.galerie { display: grid; }\n.nur-screenreader { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }","pitfall":"display: none versteckt auch vor Screenreadern. Für Inhalte, die nur sie hören sollen, die Technik „visually hidden“ wie oben verwenden.","lesson":"css-m1-l4","tested":false},{"id":"css-flex","cat":"Layout","term":"Flexbox","syntax":"display: flex; justify-content: …; align-items: …; gap: …; flex-wrap: wrap;","text":"Ordnet Kinder in einer Reihe oder Spalte an (eindimensional). justify-content verteilt entlang der Hauptachse, align-items auf der Querachse, gap setzt Abstände, flex-wrap erlaubt Zeilenumbruch.","code":".leiste {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n  justify-content: space-between;\n  align-items: center;\n}\n.leiste .wachsen { flex: 1 1 12rem; }","pitfall":"Flex-Kinder schrumpfen nicht unter ihre Inhaltsbreite. Langer Text oder Code braucht min-width: 0 am Kind, sonst läuft die Seite über.","lesson":"css-m1-l4","tested":false},{"id":"css-grid","cat":"Layout","term":"Grid","syntax":"display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));","text":"Zweidimensionales Raster aus Zeilen und Spalten. Mit auto-fit und minmax entstehen Kartenlayouts, die sich ohne Media Queries der Breite anpassen.","code":".karten {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));\n  gap: 1rem;\n}","pitfall":"minmax(16rem, 1fr) ohne min(100%, …) kann auf sehr schmalen Bildschirmen zu Überlauf führen.","lesson":"css-m1-l5","tested":false},{"id":"css-position","cat":"Layout","term":"position","syntax":"position: static | relative | absolute | fixed | sticky","text":"relative verschiebt relativ zur normalen Position und dient als Bezug für absolute Kinder. fixed klebt am Fenster, sticky haftet beim Scrollen an einer Kante.","code":".badge-container { position: relative; }\n.badge { position: absolute; top: 0; right: 0; }\n.kopf { position: sticky; top: 0; }","pitfall":"Fixierte Kopfzeilen können Ankerziele und Fokus verdecken. scroll-margin-top und ausreichend Platz einplanen.","lesson":"css-m1-l5","tested":false},{"id":"css-media","cat":"Responsiv","term":"@media","syntax":"@media (min-width: 40rem) { … }","text":"Wendet Regeln nur unter bestimmten Bedingungen an. Mobile First: zuerst das Smartphone-Layout schreiben, mit min-width nach oben erweitern. Auch Nutzereinstellungen wie prefers-reduced-motion und prefers-color-scheme lassen sich abfragen.","code":".karten { display: grid; gap: 1rem; }\n@media (min-width: 48rem) {\n  .karten { grid-template-columns: 1fr 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important; transition: none !important; }\n}","pitfall":"Breakpoints nach dem Inhalt wählen, nicht nach Geräten. Bricht das Layout bei 41rem, ist dort der richtige Breakpoint.","lesson":"css-m1-l6","tested":false},{"id":"css-transition","cat":"Bewegung","term":"transition und transform","syntax":"transition: transform .2s ease;","text":"Lässt eine Änderung weich ablaufen. Am besten werden nur transform und opacity animiert, da sie wenig Rechenaufwand verursachen.","code":".knopf { transition: transform .15s ease; }\n.knopf:hover { transform: translateY(-2px); }\n@media (prefers-reduced-motion: reduce) {\n  .knopf { transition: none; }\n}","pitfall":"Bewegung muss abschaltbar sein. Nutzer mit Vestibularstörungen stellen „Bewegung reduzieren“ ein. Das berücksichtigt prefers-reduced-motion.","lesson":"css-m1-l6","tested":false},{"id":"css-clamp","cat":"Responsiv","term":"clamp, min, max","syntax":"clamp(minimum, bevorzugt, maximum)","text":"Begrenzt einen Wert zwischen zwei Grenzen. So wächst eine Schrift oder ein Abstand flüssig mit der Fensterbreite, bleibt aber lesbar.","code":"h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); }\n.container { width: min(100% - 2rem, 70rem); margin-inline: auto; }","pitfall":"Rein vw-basierte Schrift lässt sich nicht mit Browser-Zoom vergrößern. Immer einen rem-Anteil beimischen, wie oben.","lesson":"css-m1-l6","tested":false},{"id":"css-image","cat":"Responsiv","term":"max-width und aspect-ratio für Bilder","syntax":"img { max-width: 100%; height: auto; }","text":"Verhindert, dass Bilder breiter als ihr Container werden. aspect-ratio hält das Seitenverhältnis stabil, object-fit schneidet Bilder passend zu.","code":"img { max-width: 100%; height: auto; display: block; }\n.vorschau { aspect-ratio: 16 / 9; object-fit: cover; width: 100%; }","pitfall":"Mit object-fit: cover werden Bildränder abgeschnitten. Wichtige Inhalte können dadurch verschwinden.","lesson":"css-m1-l6","tested":false},{"id":"css-calc-env","cat":"Responsiv","term":"calc(), env() und dvh","syntax":"width: calc(100% - 2rem)    padding-bottom: env(safe-area-inset-bottom)    height: 100dvh","text":"calc rechnet mit gemischten Einheiten (Prozent minus Rem). env liest Systemmaße wie die sichere Fläche auf Geräten mit Aussparung. dvh ist die Höhe des sichtbaren Bereichs, die sich mit der Adressleiste mitbewegt (100vh ist auf dem Handy oft zu hoch).","code":".seitenleiste { width: calc(100% - 2rem); }\n.fusszeile { padding-bottom: calc(1rem + env(safe-area-inset-bottom)); }\n.vollbild { min-height: 100dvh; }\n.abstand { margin-block: calc(var(--abstand) * 2); }","pitfall":"In calc() brauchen + und - Leerzeichen auf beiden Seiten. env() nur mit viewport-fit=cover im Meta-Viewport wirksam.","lesson":"css-m1-l6","tested":false},{"id":"css-focus-visible","cat":"Barrierefreiheit","term":":focus-visible und outline","syntax":":focus-visible { outline: 3px solid; outline-offset: 2px }","text":":focus-visible greift, wenn der Fokus per Tastatur gesetzt wird (nicht bei Mausklick). Der outline-Rahmen zeigt, wo man sich befindet. WCAG 2.2 verlangt einen deutlich sichtbaren Fokus mit ausreichendem Kontrast.","code":":focus-visible {\n  outline: 3px solid var(--fokus, #1a56db);\n  outline-offset: 3px;\n  border-radius: 2px;\n}\nbutton:focus:not(:focus-visible) { outline: none; }","pitfall":"outline: none ohne Ersatz macht die Seite mit der Tastatur unbenutzbar. Der Fokusrahmen braucht mindestens 3:1 Kontrast zum Hintergrund.","lesson":"css-m1-l3","tested":false},{"id":"css-user-preferences","cat":"Barrierefreiheit","term":"prefers-reduced-motion, prefers-contrast, forced-colors","syntax":"@media (prefers-reduced-motion: reduce)    @media (prefers-contrast: more)    @media (forced-colors: active)","text":"Nutzer können in ihrem System weniger Bewegung, mehr Kontrast oder Windows-Kontrastmodus wählen. Diese Einstellungen fragt man per Media Query ab und respektiert sie.","code":"@media (prefers-reduced-motion: reduce) {\n  *, ::before, ::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n@media (prefers-contrast: more) { :root { --text: #000; --rand: #000; } }\n@media (forced-colors: active) { .karte { border: 1px solid CanvasText; } }","pitfall":"Bei forced-colors überschreibt das System Farben. Informationen dürfen nicht nur über Farbe oder Hintergrundbilder transportiert werden.","lesson":"css-m1-l6","tested":false},{"id":"css-pseudo-elements","cat":"Selektoren","term":"::before, ::after, ::marker, ::placeholder, ::selection","syntax":"a::after { content: \"↗\" }    li::marker { color: … }    input::placeholder    ::selection","text":"Pseudo-Elemente gestalten Teile eines Elements, ohne zusätzliches HTML. ::before und ::after brauchen content, ::marker formt Aufzählungszeichen, ::placeholder den Platzhaltertext, ::selection die Textmarkierung, ::backdrop den Hintergrund eines Dialogs.","code":"a[target=\"_blank\"]::after { content: \" ↗\"; font-size: .8em; }\nli::marker { color: var(--akzent); }\ninput::placeholder { color: #595959; opacity: 1; }\n::selection { background: #cfe3ff; color: #000; }\ndialog::backdrop { background: rgb(0 0 0 / .5); }","pitfall":"Inhalt aus content wird von manchen Screenreadern vorgelesen. Keine wichtigen Informationen nur per ::before und ::after vermitteln. Platzhalter ersetzen kein Label.","lesson":"css-m1-l3","tested":false},{"id":"css-attr-nth","cat":"Selektoren","term":"Attributselektoren und :nth-child, :not","syntax":"[type=\"email\"]    [href^=\"https\"]    li:nth-child(odd)    :not(.aktiv)","text":"Attributselektoren wählen nach Attributen: = (gleich), ^= (beginnt mit), $= (endet mit), *= (enthält). :nth-child wählt nach Position (2n, odd, even, 3), :not schließt aus, :first-child und :last-child wählen Randelemente.","code":"input[type=\"email\"], input[type=\"tel\"] { font-size: 1rem; }\na[href^=\"https://\"]:not([href*=\"meine-seite.de\"]) { text-decoration-style: dotted; }\ntr:nth-child(even) { background: #f3f3f3; }\nli:not(:last-child) { margin-block-end: .5rem; }","pitfall":"Zu tiefe oder zu spezielle Selektoren machen CSS schwer änderbar. Klassen sind meist die klarere Wahl.","lesson":"css-m1-l3","tested":false},{"id":"css-z-index","cat":"Layout","term":"z-index, Stapelkontext und isolation","syntax":"z-index: 10    position: relative    isolation: isolate","text":"z-index ordnet überlappende Elemente, wirkt aber nur bei positionierten Elementen (und Flex/Grid-Kindern). Jeder Stapelkontext (position mit z-index, transform, opacity < 1, isolation) bildet eine eigene Ebene: Kinder können nie über Elemente außerhalb steigen.","code":":root { --z-menue: 100; --z-dialog: 200; --z-toast: 300; }\n.menue { position: sticky; top: 0; z-index: var(--z-menue); }\n.karte { isolation: isolate; }   /* Stapelkontext ohne z-index-Wert */\n.karte .badge { position: absolute; z-index: 1; }","pitfall":"Wachsende z-index-Zahlen (9999) sind ein Warnzeichen. Ebenen als benannte Variablen definieren und Stapelkontexte bewusst setzen.","lesson":"css-m1-l5","tested":false},{"id":"css-object-fit-filter","cat":"Responsiv","term":"object-fit, filter, backdrop-filter, gradients","syntax":"img { object-fit: cover }    filter: blur(4px)    backdrop-filter: blur(8px)    background: linear-gradient(…)","text":"object-fit passt Bilder in ihren Rahmen ein (cover schneidet zu, contain zeigt ganz). filter und backdrop-filter weichzeichnen, aufhellen oder verfärben. Farbverläufe (linear-, radial-, conic-gradient) ersetzen Hintergrundbilder.","code":".titelbild { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; object-position: center 30%; }\n.glas { backdrop-filter: blur(8px) saturate(120%); background: rgb(255 255 255 / .6); }\n.hero { background: linear-gradient(135deg, #1a56db, #7e3af2); color: #fff; }\n.grau { filter: grayscale(1); }","pitfall":"Text auf Verläufen und Fotos braucht überall ausreichend Kontrast. Backdrop-Filter verlangt viel Rechenleistung. Auf wenige Elemente beschränken.","lesson":"css-m1-l2","tested":false},{"id":"css-text-wrap","cat":"Typografie","term":"text-wrap, hyphens, line-clamp, overflow-wrap","syntax":"h1 { text-wrap: balance }    p { hyphens: auto; overflow-wrap: anywhere }    -webkit-line-clamp","text":"text-wrap: balance verteilt Überschriften gleichmäßig auf die Zeilen, pretty vermeidet einzelne Wörter in der letzten Zeile. hyphens: auto trennt Wörter automatisch (mit lang-Attribut). overflow-wrap bricht lange Wörter und URLs, line-clamp kürzt auf eine Zeilenzahl.","code":"h1, h2 { text-wrap: balance; }\np { text-wrap: pretty; hyphens: auto; overflow-wrap: break-word; max-width: 70ch; }\n.vorschau {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 3;\n  line-clamp: 3;\n  overflow: hidden;\n}","pitfall":"hyphens: auto braucht lang=\"de\" im HTML. text-wrap: pretty ist noch nicht in allen Browsern verfügbar, andere ignorieren es folgenlos.","lesson":"css-m1-l3","tested":false},{"id":"css-subgrid-auto-fit","cat":"Layout","term":"Grid: auto-fit, minmax und subgrid","syntax":"grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr))    grid-template-rows: subgrid","text":"repeat(auto-fit, minmax(…)) erzeugt ein Kartenraster ohne Media Queries: so viele Spalten, wie passen. Mit subgrid übernehmen Kind-Elemente die Zeilen oder Spalten des Eltern-Rasters, sodass Titel, Text und Button über Karten hinweg bündig bleiben.","code":".karten {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));\n  gap: 1.5rem;\n}\n.karte {\n  display: grid;\n  grid-row: span 3;               /* belegt drei Zeilen des Eltern-Rasters */\n  grid-template-rows: subgrid;\n}","pitfall":"auto-fit blendet leere Spuren aus (Karten werden breiter), auto-fill behält sie. min(100%, 16rem) verhindert Überlauf auf sehr schmalen Bildschirmen.","lesson":"css-m1-l5","tested":false},{"id":"css-property-at","cat":"Kaskade","term":"@property (typisierte Variablen)","syntax":"@property --farbe { syntax: \"<color>\"; inherits: false; initial-value: #000 }","text":"@property gibt einer Custom Property einen Typ, einen Startwert und Vererbungsverhalten. Dadurch lassen sich Variablen animieren (Farben, Winkel, Zahlen), was bei normalen Custom Properties nicht geht.","code":"@property --winkel {\n  syntax: \"<angle>\";\n  inherits: false;\n  initial-value: 0deg;\n}\n.ring {\n  background: conic-gradient(from var(--winkel), #1a56db, #7e3af2, #1a56db);\n  animation: drehen 6s linear infinite;\n}\n@keyframes drehen { to { --winkel: 360deg; } }","pitfall":"Seit 2024 in allen großen Browsern, ältere Versionen ignorieren die Animation. Bewegung bei prefers-reduced-motion abschalten.","lesson":"css-m1-l6","tested":false},{"id":"css-starting-style","cat":"Bewegung","term":"@starting-style und transition-behavior","syntax":"@starting-style { … }    transition: opacity .3s, display .3s allow-discrete","text":"Mit @starting-style legt man den Anfangszustand fest, von dem aus ein Element beim Einblenden animiert (zum Beispiel ein Popover oder ein neu erzeugtes Element). transition-behavior: allow-discrete erlaubt Übergänge für display und overlay beim Ausblenden.","code":"[popover] {\n  opacity: 1;\n  transform: translateY(0);\n  transition: opacity .25s, transform .25s, display .25s allow-discrete, overlay .25s allow-discrete;\n}\n[popover]:not(:popover-open) { opacity: 0; transform: translateY(-.5rem); }\n@starting-style {\n  [popover]:popover-open { opacity: 0; transform: translateY(-.5rem); }\n}","pitfall":"Neuere Funktion (seit 2024 in aktuellen Browsern). Ohne Unterstützung erscheint das Element einfach ohne Animation, das ist ein akzeptabler Ausweichzustand.","lesson":"css-m1-l6","tested":false},{"id":"css-view-transitions","cat":"Bewegung","term":"View Transitions","syntax":"document.startViewTransition(() => …)    view-transition-name: karte    @view-transition { navigation: auto }","text":"Weiche Übergänge zwischen zwei Zuständen einer Seite (oder zwischen Seiten). Der Browser macht Vorher- und Nachher-Bild und blendet sie ineinander über. Elemente mit view-transition-name werden einzeln animiert.","code":".titel { view-transition-name: seitentitel; }\n::view-transition-old(seitentitel), ::view-transition-new(seitentitel) { animation-duration: .3s; }\n\n/* Übergang zwischen Seiten derselben Website */\n@view-transition { navigation: auto; }\n\n// JavaScript: Zustandswechsel auf einer Seite\ndocument.startViewTransition(() => aktualisiereListe());","pitfall":"Bei prefers-reduced-motion abschalten. Die Unterstützung (besonders seitenübergreifend) ist noch unterschiedlich. Es muss auch ohne Übergang funktionieren.","lesson":"css-m1-l6","tested":false},{"id":"css-content-visibility","cat":"Responsiv","term":"content-visibility und contain-intrinsic-size","syntax":"content-visibility: auto; contain-intrinsic-size: auto 600px","text":"Der Browser überspringt Layout und Zeichnen für Bereiche außerhalb des Bildschirms, was lange Seiten schneller macht. contain-intrinsic-size reserviert in der Zwischenzeit Platz, damit sich die Scrollleiste nicht sprunghaft ändert.","code":".abschnitt {\n  content-visibility: auto;\n  contain-intrinsic-size: auto 600px;\n}","pitfall":"Nicht auf den Bereich oberhalb der Falz anwenden (verschlechtert den LCP). Suche per Strg+F und Anker funktionieren weiter, aber Höhenwerte sollten realistisch sein.","lesson":"css-m1-l2","tested":false},{"id":"css-scroll-behavior","cat":"Layout","term":"scroll-behavior, scroll-margin, scrollbar-gutter, overscroll","syntax":"html { scroll-behavior: smooth }    h2 { scroll-margin-top: 5rem }    scrollbar-gutter: stable    overscroll-behavior: contain","text":"scroll-behavior glättet Sprünge zu Ankern. scroll-margin-top hält Platz unter einer festen Kopfzeile. scrollbar-gutter: stable verhindert Layoutsprünge, wenn die Scrollleiste erscheint. overscroll-behavior verhindert, dass ein Scrollbereich die Seite dahinter mitbewegt.","code":"@media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }\n:target, h2[id] { scroll-margin-top: 5rem; }\nhtml { scrollbar-gutter: stable; }\n.modal-inhalt { overflow: auto; overscroll-behavior: contain; }","pitfall":"Sanftes Scrollen nur anbieten, wenn der Nutzer keine reduzierte Bewegung wünscht (siehe Media Query).","lesson":"css-m1-l5","tested":false},{"id":"css-accent-color","cat":"Typografie","term":"accent-color, caret-color, field-sizing, color-scheme","syntax":"input { accent-color: #1a56db }    textarea { field-sizing: content }    :root { color-scheme: light dark }","text":"accent-color färbt Checkboxen, Radiobuttons und Schieberegler in der Markenfarbe, ohne sie neu zu bauen. caret-color färbt den Textcursor. field-sizing: content lässt Textfelder mit dem Inhalt wachsen. color-scheme sagt dem Browser, dass die Seite Hell und Dunkel kann (Standardelemente passen sich an).","code":":root { color-scheme: light dark; accent-color: #1a56db; }\ntextarea { field-sizing: content; min-block-size: 4lh; }\ninput { caret-color: currentColor; }","pitfall":"field-sizing ist noch nicht in allen Browsern verfügbar, andere zeigen das Feld einfach in fester Größe. Die Markenfarbe muss ausreichend Kontrast haben.","lesson":"css-m1-l3","tested":false},{"id":"css-print","cat":"Responsiv","term":"@media print und Seitenumbrüche","syntax":"@media print { … }    break-inside: avoid    @page { margin: 2cm }","text":"Mit einer Print-Media-Query gestaltet man die Druckansicht: Navigation ausblenden, Hintergründe weglassen, Linkadressen anzeigen. break-inside: avoid verhindert Trennung von Karten und Tabellenzeilen, @page legt die Ränder fest.","code":"@media print {\n  nav, footer, .werbung, button { display: none; }\n  body { color: #000; background: #fff; font-size: 12pt; }\n  a[href^=\"http\"]::after { content: \" (\" attr(href) \")\"; font-size: .85em; }\n  h2, tr, figure { break-inside: avoid; }\n}\n@page { margin: 2cm; }","pitfall":"Drucken wird oft vergessen, ist aber für Rechnungen, Rezepte und Bescheinigungen wichtig. Vorschau im Browser (Strg+P) prüfen.","lesson":"css-m1-l6","tested":false},{"id":"css-nesting","cat":"Selektoren","term":"CSS-Nesting","syntax":".karte { h2 { … } &:hover { … } }","text":"Regeln lassen sich ineinander schreiben, ohne Präprozessor. & steht für den umschließenden Selektor. So bleibt zusammengehörender Code beisammen.","code":".karte {\n  padding: 1rem;\n  h2 { margin-block: 0 .5rem; }\n  &:hover { background: #f4f4f4; }\n  @media (min-width: 48rem) { padding: 2rem; }\n}","pitfall":"Tiefe Verschachtelung erzeugt sehr spezifische Selektoren, die schwer zu überschreiben sind. Höchstens zwei bis drei Ebenen.","lesson":"css-m1-l1","tested":false},{"id":"css-is-where","cat":"Selektoren","term":":is() und :where()","syntax":":is(h1, h2, h3)    :where(.a, .b)","text":"Fassen mehrere Selektoren zusammen. :is() übernimmt die Spezifität des spezifischsten Arguments, :where() hat immer die Spezifität 0 und eignet sich für überschreibbare Basisstile.","code":":where(h1, h2, h3) { margin-block: 1.5em .5em; }   /* leicht überschreibbar */\n:is(article, section) > :is(h2, h3) { color: #1a5fb4; }","pitfall":"In älteren Browsern führt ein ungültiger Selektor innerhalb einer Liste dazu, dass die ganze Regel ignoriert wird. :is() ist dagegen fehlertolerant.","lesson":"css-m1-l1","tested":false},{"id":"css-layer","cat":"Kaskade","term":"@layer","syntax":"@layer reset, basis, komponenten;    @layer basis { … }","text":"Ebenen legen die Rangfolge von Stilen unabhängig von der Spezifität fest. Spätere Ebenen gewinnen gegen frühere. Stile außerhalb von Ebenen schlagen alle Ebenen.","code":"@layer reset, basis, komponenten;\n\n@layer reset { * { margin: 0; } }\n@layer basis { a { color: #1a5fb4; } }\n@layer komponenten { .knopf { color: white; } }","pitfall":"Die Reihenfolge der Ebenen wird mit der ersten Deklaration festgelegt. Wer sie erst später nennt, bekommt eine andere Rangfolge als erwartet.","lesson":"css-m1-l1","tested":false},{"id":"css-container","cat":"Responsiv","term":"Container Queries","syntax":".wrapper { container-type: inline-size; }    @container (min-width: 30rem) { … }","text":"Bauen ein Bauteil abhängig von der Breite seines Containers statt des Fensters. So sieht eine Karte in einer schmalen Spalte und im Vollbild jeweils passend aus.","code":".karten { container-type: inline-size; }\n.karte { display: grid; gap: .5rem; }\n@container (min-width: 32rem) {\n  .karte { grid-template-columns: 8rem 1fr; }\n}","pitfall":"Das Container-Element selbst kann nicht auf seine eigene Breite reagieren, nur seine Kinder. container-type: inline-size braucht ein Elternelement.","lesson":"css-m1-l6","tested":false},{"id":"css-grid-areas","cat":"Layout","term":"grid-template-areas","syntax":"grid-template-areas: \"kopf kopf\" \"menue inhalt\";","text":"Benannte Bereiche machen komplexe Seitenlayouts lesbar. Die Zeichenketten zeigen das Raster, die Elemente bekommen mit grid-area ihren Platz.","code":".seite {\n  display: grid;\n  grid-template-columns: 14rem 1fr;\n  grid-template-areas:\n    \"kopf kopf\"\n    \"menue inhalt\"\n    \"fuss fuss\";\n}\n.kopf { grid-area: kopf; }\n.menue { grid-area: menue; }\n@media (max-width: 40rem) {\n  .seite { grid-template-columns: 1fr; grid-template-areas: \"kopf\" \"menue\" \"inhalt\" \"fuss\"; }\n}","pitfall":"Die visuelle Reihenfolge darf nicht stark von der Reihenfolge im HTML abweichen. Tastatur und Screenreader folgen dem Quelltext.","lesson":"css-m1-l5","tested":false},{"id":"css-place","cat":"Layout","term":"place-items, inset, aspect-ratio","syntax":"display: grid; place-items: center;    inset: 0;","text":"Abkürzungen: place-items zentriert in Grid-Zellen (align-items plus justify-items), inset setzt top, right, bottom und left zugleich, margin-inline: auto zentriert Blockelemente.","code":".zentriert { display: grid; place-items: center; min-height: 100dvh; }\n.overlay { position: absolute; inset: 0; background: rgb(0 0 0 / .5); }\n.container { width: min(100% - 2rem, 60rem); margin-inline: auto; }","pitfall":"100vh ist auf Smartphones oft höher als der sichtbare Bereich (Adressleiste). 100dvh passt sich an.","lesson":"css-m1-l4","tested":false},{"id":"css-logical","cat":"Boxmodell","term":"Logische Eigenschaften","syntax":"margin-inline  padding-block  inline-size  border-inline-start","text":"Statt links, rechts, oben, unten beschreiben block (Leserichtung nach unten) und inline (Textrichtung). Das Layout funktioniert dadurch auch in Sprachen mit anderer Schreibrichtung.","code":".hinweis {\n  padding-inline: 1rem;\n  padding-block: .5rem;\n  border-inline-start: 4px solid #1a5fb4;\n  margin-block-end: 1rem;\n}","pitfall":"Mit margin-left und -right brechen Layouts bei Rechts-nach-Links-Sprachen. Für neue Projekte direkt logische Werte benutzen.","lesson":"css-m1-l2","tested":false},{"id":"css-color","cat":"Typografie","term":"color-mix, light-dark und Farbschema","syntax":"color-mix(in srgb, red 20%, white)    light-dark(hell, dunkel)    color-scheme: light dark","text":"color-mix mischt Farben im Stylesheet, light-dark() wählt je nach Farbschema des Nutzers, color-scheme sagt dem Browser, dass beide Schemata unterstützt werden (Formularelemente, Scrollbalken).","code":":root {\n  color-scheme: light dark;\n  --text: light-dark(#1d1d1f, #f2f2f7);\n  --flaeche: light-dark(#ffffff, #1c1c1e);\n}\nbody { color: var(--text); background: var(--flaeche); }\n.hinweis { background: color-mix(in srgb, #1a5fb4 12%, var(--flaeche)); }","pitfall":"Auch im Dunkelmodus muss der Kontrast mindestens 4,5:1 betragen. Beide Schemata prüfen, nicht nur das helle.","lesson":"css-m1-l3","tested":false},{"id":"css-fontface","cat":"Typografie","term":"@font-face und font-display","syntax":"@font-face { font-family: …; src: url(…) format(\"woff2\"); font-display: swap; }","text":"Bindet eine eigene Schrift ein. WOFF2 ist das kleinste Format, font-display: swap zeigt zuerst eine Ersatzschrift, bis die echte geladen ist. Selbst gehostete Schriften übertragen keine Daten an Dritte.","code":"@font-face {\n  font-family: \"IBM Plex Sans\";\n  src: url(\"/assets/fonts/ibm-plex-sans-variable-latin.woff2\") format(\"woff2\");\n  font-weight: 100 700;\n  font-display: swap;\n}\nbody { font-family: \"IBM Plex Sans\", system-ui, sans-serif; }","pitfall":"Schriften von Google Fonts direkt von Google einzubinden gilt nach deutscher Rechtsprechung als datenschutzrelevant. Selbst hosten.","lesson":"css-m1-l3","tested":false},{"id":"css-keyframes","cat":"Bewegung","term":"@keyframes und animation","syntax":"@keyframes name { from { … } to { … } }    animation: name 1s ease infinite;","text":"Beschreibt Zwischenschritte einer Animation. animation setzt Name, Dauer, Verlauf und Wiederholung. Besser nur transform und opacity animieren.","code":"@keyframes einblenden {\n  from { opacity: 0; transform: translateY(8px); }\n  to   { opacity: 1; transform: none; }\n}\n.karte { animation: einblenden .3s ease-out both; }\n@media (prefers-reduced-motion: reduce) {\n  .karte { animation: none; }\n}","pitfall":"Endlos blinkende oder sich bewegende Inhalte müssen sich anhalten lassen (WCAG 2.2.2). Nie mehr als dreimal pro Sekunde blitzen.","lesson":"css-m1-l6","tested":false},{"id":"css-focus-within","cat":"Selektoren","term":":focus-within und :has()","syntax":".gruppe:focus-within { … }    .karte:has(:checked) { … }","text":":focus-within trifft ein Element, wenn eines seiner Kinder den Fokus hat. :has() wählt ein Element nach seinen Nachkommen, zum Beispiel eine Zeile, deren Checkbox angehakt ist.","code":".feld:focus-within { outline: 3px solid #1a5fb4; outline-offset: 2px; }\n.zeile:has(input:checked) { background: #e8f0fe; }","pitfall":":has() ist erst seit 2023 in allen großen Browsern verfügbar. Für wichtige Funktionen einen Rückfall ohne :has() bereitstellen (@supports selector(:has(*))).","lesson":"css-m1-l3","tested":false},{"id":"css-visually-hidden","cat":"Barrierefreiheit","term":"Visually hidden","syntax":"position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%);","text":"Versteckt Text optisch, lässt ihn aber für Screenreader lesbar, zum Beispiel Beschriftungen für Symbolknöpfe. display: none und visibility: hidden entfernen den Text auch aus dem Zugänglichkeitsbaum.","code":".sr-only {\n  position: absolute;\n  width: 1px; height: 1px;\n  margin: -1px; padding: 0;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}","pitfall":"Ein sichtbarer Text ist meist besser als ein versteckter. Nicht alle verstehen Symbole allein.","lesson":"css-m1-l3","tested":false},{"id":"css-scroll-snap","cat":"Layout","term":"overflow, text-overflow und scroll-snap","syntax":"overflow-x: auto;    text-overflow: ellipsis;    scroll-snap-type: x mandatory;","text":"overflow steuert, was bei zu viel Inhalt passiert (auto zeigt Scrollbalken nur bei Bedarf). text-overflow kürzt einzeilige Texte mit „…“. scroll-snap lässt Karussells an Elementen einrasten.","code":".tabelle { overflow-x: auto; }\n.titel { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.galerie { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; gap: 1rem; }\n.galerie > * { flex: 0 0 80%; scroll-snap-align: start; }","pitfall":"Scrollbare Bereiche brauchen Tastaturzugang (tabindex=\"0\") und einen sichtbaren Fokus, sonst sind sie für Tastaturnutzer unerreichbar.","lesson":"css-m1-l6","tested":false},{"id":"css-supports","cat":"Responsiv","term":"@supports und prefers-color-scheme","syntax":"@supports (display: grid) { … }    @media (prefers-color-scheme: dark) { … }","text":"@supports wendet Regeln nur an, wenn der Browser eine Funktion kennt (Progressive Enhancement). prefers-color-scheme und prefers-contrast greifen auf Einstellungen der Nutzer zu.","code":".layout { display: block; }\n@supports (display: grid) {\n  .layout { display: grid; grid-template-columns: 1fr 2fr; }\n}\n@media (prefers-contrast: more) {\n  :root { --rand: #000; }\n}\n@media (forced-colors: active) {\n  .knopf { border: 1px solid ButtonText; }\n}","pitfall":"Im Modus für erzwungene Farben (Windows Hochkontrast) verschwinden Hintergrundfarben. Wichtige Rahmen und Fokusmarkierungen brauchen echte Ränder.","lesson":"css-m1-l3","tested":false}]},{"id":"js","label":"JavaScript / TypeScript","codeLang":"javascript","intro":"Sprache des Browsers und von Node.js. TypeScript ergänzt Typen, die vor dem Ausführen entfernt werden.","notice":"Die Beispiele sind mit Node.js 22 ausgeführt und geprüft. Browser-Beispiele (DOM, fetch, localStorage) sowie Import und Export werden nur gezeigt, nicht ausgeführt.","runner":"Node.js","entries":[{"id":"js-const","cat":"Variablen","term":"const","syntax":"const name = wert;","text":"Legt eine Variable an, die nicht neu zugewiesen werden kann. Das ist die Standardwahl. Bei Objekten und Arrays bleibt der Inhalt veränderbar, nur die Bindung ist fest.","code":"const preis = 20;\nconst liste = [1, 2];\nliste.push(3);\nconsole.log(preis, liste);","out":"20 [ 1, 2, 3 ]","pitfall":"const macht Objekte nicht unveränderlich. Wer den Inhalt schützen will, braucht Object.freeze oder kopiert statt zu verändern.","lesson":"js-m1-l1","tested":true},{"id":"js-let","cat":"Variablen","term":"let","syntax":"let name = wert;","text":"Legt eine Variable an, die später einen neuen Wert bekommen darf. Sie gilt nur im Block { … }, in dem sie steht.","code":"let zaehler = 0;\nfor (let i = 0; i < 3; i++) {\n  zaehler += i;\n}\nconsole.log(zaehler);","out":"3","pitfall":"Nur let verwenden, wenn sich der Wert wirklich ändert. Sonst const.","lesson":"js-m1-l1","tested":true},{"id":"js-var","cat":"Variablen","term":"var","syntax":"var name = wert;","text":"Alte Form der Variablendeklaration. Sie gilt in der ganzen Funktion statt nur im Block und wird nach oben „gehoben“. In neuem Code nicht mehr verwenden.","code":"if (true) {\n  var innen = 'sichtbar';\n}\nconsole.log(innen);","out":"sichtbar","pitfall":"Mit let oder const wäre innen außerhalb des Blocks nicht erreichbar. Genau diese Überraschung vermeiden die neuen Schlüsselwörter.","lesson":"js-m1-l1","tested":true},{"id":"js-typeof","cat":"Typen und Werte","term":"typeof","syntax":"typeof wert","text":"Liefert den Typ eines Werts als Text: \"string\", \"number\", \"boolean\", \"undefined\", \"object\", \"function\", \"bigint\" oder \"symbol\".","code":"console.log(typeof 'a', typeof 1, typeof null, typeof [], typeof (() => 1));","out":"string number object object function","pitfall":"typeof null ist \"object\" (alter Fehler der Sprache), und Arrays sind ebenfalls \"object\". Arrays erkennt man mit Array.isArray.","lesson":"js-m1-l1","tested":true},{"id":"js-equality","cat":"Typen und Werte","term":"=== und !==","syntax":"a === b","text":"Strikter Vergleich: Wert und Typ müssen übereinstimmen. Der lockere Vergleich == wandelt vorher Typen um und liefert Überraschungen.","code":"console.log(1 === '1', 1 == '1', null === undefined, null == undefined);","out":"false true false true","pitfall":"Immer === und !== benutzen. == ist nur bei „x == null“ (null oder undefined) bewusst sinnvoll.","lesson":"js-m1-l1","tested":true},{"id":"js-nullish","cat":"Typen und Werte","term":"?? und ?.","syntax":"a ?? b    obj?.eigenschaft","text":"?? liefert den rechten Wert nur, wenn links null oder undefined steht. ?. liest eine Eigenschaft nur, wenn das Objekt davor existiert, sonst kommt undefined.","code":"const nutzer = { name: 'Mia', adresse: null };\nconsole.log(nutzer.adresse?.ort);\nconsole.log(0 ?? 10, 0 || 10);","out":"undefined\n0 10","pitfall":"|| ersetzt auch 0, \"\" und false durch den Standardwert. Für „fehlt“ statt „falsy“ ?? verwenden.","lesson":"js-m1-l1","tested":true},{"id":"js-template","cat":"Typen und Werte","term":"Template-String","syntax":"`Text ${ausdruck}`","text":"Text in Backticks, in den mit ${…} beliebige Ausdrücke eingesetzt werden. Er darf über mehrere Zeilen gehen.","code":"const name = 'Ada';\nconsole.log(`Hallo ${name}, 2 + 3 = ${2 + 3}`);","out":"Hallo Ada, 2 + 3 = 5","pitfall":"Nutzereingaben nie ungeprüft per Template-String in HTML oder SQL setzen. Das führt zu XSS bzw. SQL-Injection.","lesson":"js-m1-l1","tested":true},{"id":"js-if","cat":"Kontrollfluss","term":"if / else","syntax":"if (bedingung) { … } else if (…) { … } else { … }","text":"Führt einen Block nur aus, wenn die Bedingung wahr ist. Falsy sind false, 0, \"\", null, undefined, NaN; alles andere ist truthy.","code":"const punkte = 72;\nif (punkte >= 90) console.log('sehr gut');\nelse if (punkte >= 70) console.log('gut');\nelse console.log('weiter üben');","out":"gut","pitfall":"Auch bei einer Zeile geschweifte Klammern setzen, sonst gehört eine später ergänzte Zeile nicht zum Block.","lesson":"js-m1-l1","tested":true},{"id":"js-ternary","cat":"Kontrollfluss","term":"Bedingungsoperator","syntax":"bedingung ? wennWahr : wennFalsch","text":"Kurzform von if/else, die einen Wert liefert. Passt für einfache Auswahl innerhalb eines Ausdrucks.","code":"const alter = 17;\nconsole.log(alter >= 18 ? 'volljährig' : 'minderjährig');","out":"minderjährig","pitfall":"Verschachtelte Bedingungsoperatoren sind schwer lesbar; dann besser if/else oder eine Funktion.","lesson":"js-m1-l1","tested":true},{"id":"js-switch","cat":"Kontrollfluss","term":"switch","syntax":"switch (wert) { case a: …; break; default: … }","text":"Wählt anhand eines Werts einen von mehreren Fällen. Ohne break läuft die Ausführung in den nächsten Fall weiter.","code":"const tag = 'sa';\nswitch (tag) {\n  case 'sa':\n  case 'so':\n    console.log('Wochenende');\n    break;\n  default:\n    console.log('Werktag');\n}","out":"Wochenende","pitfall":"Vergessenes break ist die häufigste Fehlerquelle. Das gezielte Durchfallen (sa/so oben) sollte ein Kommentar erklären.","lesson":"js-m1-l1","tested":true},{"id":"js-for","cat":"Schleifen","term":"for","syntax":"for (let i = 0; i < n; i++) { … }","text":"Zählschleife mit Startwert, Bedingung und Schritt. Gut, wenn der Index gebraucht wird.","code":"for (let i = 1; i <= 3; i++) {\n  console.log(i * i);\n}","out":"1\n4\n9","pitfall":"Mit <= statt < läuft die Schleife einmal zu oft (Off-by-one). Beim Arbeiten mit Arrays bis i < liste.length zählen.","lesson":"js-m1-l1","tested":true},{"id":"js-for-of","cat":"Schleifen","term":"for … of","syntax":"for (const element of sammlung) { … }","text":"Läuft über die Elemente von Arrays, Strings, Maps und Sets. Kein Index nötig.","code":"for (const farbe of ['rot', 'grün']) {\n  console.log(farbe);\n}","out":"rot\ngrün","pitfall":"for … in läuft über die Schlüssel (bei Arrays die Indizes als Text) und gehört nicht zu Arrays. Für Elemente for … of.","lesson":"js-m1-l1","tested":true},{"id":"js-function","cat":"Funktionen","term":"function","syntax":"function name(parameter) { return wert; }","text":"Benannte Funktion. Sie wird nach oben gehoben und kann deshalb vor der Deklaration aufgerufen werden. Ohne return liefert sie undefined.","code":"function summe(a, b = 0) {\n  return a + b;\n}\nconsole.log(summe(2, 3), summe(5));","out":"5 5","pitfall":"Standardwerte (b = 0) greifen nur bei undefined, nicht bei null.","lesson":"js-m1-l2","tested":true},{"id":"js-arrow","cat":"Funktionen","term":"Pfeilfunktion","syntax":"(a, b) => a + b","text":"Kurzschreibweise für Funktionen. Ohne geschweifte Klammern ist der Ausdruck der Rückgabewert. Pfeilfunktionen haben kein eigenes this.","code":"const verdopple = (x) => x * 2;\nconsole.log([1, 2, 3].map(verdopple));","out":"[ 2, 4, 6 ]","pitfall":"Ein Objekt direkt zurückgeben braucht Klammern: () => ({ a: 1 }). Ohne sie liest JavaScript { … } als Funktionskörper.","lesson":"js-m1-l2","tested":true},{"id":"js-closure","cat":"Funktionen","term":"Closure","syntax":"function außen() { let x; return () => x; }","text":"Eine Funktion merkt sich die Variablen ihrer Umgebung, auch nachdem die äußere Funktion beendet ist.","code":"function zaehler() {\n  let n = 0;\n  return () => ++n;\n}\nconst naechster = zaehler();\nnaechster();\nconsole.log(naechster());","out":"2","pitfall":"Jede Closure hält ihre Daten im Speicher. Lang lebende Closures mit großen Objekten können Speicher binden.","lesson":"js-m1-l2","tested":true},{"id":"js-rest-spread","cat":"Funktionen","term":"Rest und Spread","syntax":"...liste","text":"Spread (...) verteilt Elemente eines Arrays oder Objekts in ein neues. Rest (...) sammelt übrige Parameter oder Elemente in einem Array.","code":"const a = [1, 2];\nconst b = [...a, 3];\nconst o = { ...{ x: 1 }, y: 2 };\nconst summe = (...zahlen) => zahlen.reduce((s, z) => s + z, 0);\nconsole.log(b, o, summe(1, 2, 3));","out":"[ 1, 2, 3 ] { x: 1, y: 2 } 6","pitfall":"Spread kopiert nur die oberste Ebene. Verschachtelte Objekte teilen sich weiter dieselbe Referenz.","lesson":"js-m1-l3","tested":true},{"id":"js-destructuring","cat":"Objekte und Arrays","term":"Destructuring","syntax":"const { a, b } = obj;    const [x, y] = liste;","text":"Entpackt Eigenschaften eines Objekts oder Elemente eines Arrays direkt in Variablen. Mit = lassen sich Standardwerte setzen, mit : umbenennen.","code":"const nutzer = { name: 'Mia', alter: 30 };\nconst { name, rolle = 'Gast' } = nutzer;\nconst [erstes, zweites] = ['a', 'b'];\nconsole.log(name, rolle, erstes, zweites);","out":"Mia Gast a b","pitfall":"Bei Objekten zählen die Namen, bei Arrays die Position. Fehlt die Eigenschaft, entsteht undefined, kein Fehler.","lesson":"js-m1-l3","tested":true},{"id":"js-object-literal","cat":"Objekte und Arrays","term":"Objekt-Literal","syntax":"{ schluessel: wert, kurz, [berechnet]: 1 }","text":"Fasst benannte Werte zusammen. Kurzschreibweise: { name } ist { name: name }. Eckige Klammern berechnen den Schlüssel.","code":"const name = 'Ada';\nconst feld = 'rolle';\nconst o = { name, [feld]: 'Admin' };\nconsole.log(o);","out":"{ name: 'Ada', rolle: 'Admin' }","pitfall":"Objekte werden als Referenz weitergegeben. Zwei Variablen können dasselbe Objekt meinen, eine Änderung wirkt auf beide.","lesson":"js-m1-l3","tested":true},{"id":"js-array-map","cat":"Objekte und Arrays","term":"map","syntax":"liste.map((element, index) => neuerWert)","text":"Erzeugt ein neues Array, indem jedes Element durch eine Funktion umgewandelt wird. Die Länge bleibt gleich, das Original bleibt unverändert.","code":"console.log([1, 2, 3].map((n) => n * 10));","out":"[ 10, 20, 30 ]","pitfall":"map für Umwandlungen nutzen, nicht nur für Nebenwirkungen. Dafür gibt es forEach oder for … of.","lesson":"js-m1-l3","tested":true},{"id":"js-array-filter","cat":"Objekte und Arrays","term":"filter","syntax":"liste.filter((element) => bedingung)","text":"Liefert ein neues Array mit den Elementen, für die die Funktion einen wahren Wert zurückgibt.","code":"console.log([5, 12, 8, 20].filter((n) => n > 9));","out":"[ 12, 20 ]","pitfall":"Das Ergebnis ist immer ein Array, auch wenn nichts passt (dann leer). Für genau ein Element find verwenden.","lesson":"js-m1-l3","tested":true},{"id":"js-array-reduce","cat":"Objekte und Arrays","term":"reduce","syntax":"liste.reduce((summe, element) => …, startwert)","text":"Faltet ein Array zu einem einzelnen Wert zusammen, etwa Summe, Zähltabelle oder Objekt.","code":"const summe = [1, 2, 3, 4].reduce((s, n) => s + n, 0);\nconsole.log(summe);","out":"10","pitfall":"Den Startwert immer angeben. Ohne ihn schlägt reduce bei einem leeren Array mit einem Fehler fehl.","lesson":"js-m1-l3","tested":true},{"id":"js-array-find","cat":"Objekte und Arrays","term":"find, some, every, includes","syntax":"liste.find(fn)    liste.some(fn)    liste.includes(wert)","text":"find liefert das erste passende Element (oder undefined). some fragt „mindestens eins?“, every fragt „alle?“, includes prüft auf einen konkreten Wert.","code":"const z = [3, 8, 15];\nconsole.log(z.find((n) => n > 5), z.some((n) => n > 10), z.every((n) => n > 5), z.includes(8));","out":"8 true false true","pitfall":"find liefert das Element selbst, nicht den Index. Der Index kommt aus findIndex.","lesson":"js-m1-l3","tested":true},{"id":"js-array-sort","cat":"Objekte und Arrays","term":"sort","syntax":"liste.sort((a, b) => a - b)    liste.toSorted(…)","text":"Sortiert ein Array. Ohne Vergleichsfunktion wird als Text sortiert. toSorted liefert ein sortiertes Array, ohne das Original zu verändern.","code":"const z = [10, 9, 1];\nconsole.log(z.toSorted(), z.toSorted((a, b) => a - b), z);","out":"[ 1, 10, 9 ] [ 1, 9, 10 ] [ 10, 9, 1 ]","pitfall":"sort verändert das Array direkt. Ohne Vergleichsfunktion steht 10 vor 9, weil Text verglichen wird.","lesson":"js-m1-l3","tested":true},{"id":"js-map-set","cat":"Objekte und Arrays","term":"Map und Set","syntax":"new Map([[k, v]])    new Set([…])","text":"Map speichert Schlüssel-Wert-Paare mit beliebigen Schlüsseln und merkt sich die Einfügereihenfolge. Set speichert jeden Wert höchstens einmal.","code":"const m = new Map([['a', 1]]);\nm.set('b', 2);\nconst s = new Set([1, 1, 2]);\nconsole.log(m.get('b'), m.size, [...s]);","out":"2 2 [ 1, 2 ]","pitfall":"JSON.stringify kennt weder Map noch Set und liefert {}. Vorher in Array oder Objekt umwandeln.","lesson":"js-m1-l3","tested":true},{"id":"js-class","cat":"Objekte und Arrays","term":"class","syntax":"class Name { constructor() {} methode() {} }","text":"Vorlage für Objekte mit Eigenschaften und Methoden. extends erbt von einer anderen Klasse; #feld ist wirklich privat.","code":"class Konto {\n  #stand = 0;\n  einzahlen(betrag) { this.#stand += betrag; return this; }\n  get stand() { return this.#stand; }\n}\nconsole.log(new Konto().einzahlen(50).stand);","out":"50","pitfall":"this hängt vom Aufruf ab. Eine Methode als Callback übergeben verliert this, sofern sie nicht gebunden oder als Pfeilfunktion definiert wird.","lesson":"js-m1-l3","tested":true},{"id":"js-this","cat":"Objekte und Arrays","term":"this","syntax":"this.eigenschaft","text":"Verweist in einer Methode auf das Objekt, an dem sie aufgerufen wurde. Bei Pfeilfunktionen wird this von außen übernommen.","code":"const o = {\n  name: 'Ada',\n  sagHallo() { return 'Hallo ' + this.name; },\n};\nconst lose = o.sagHallo;\nconsole.log(o.sagHallo());\ntry { lose(); } catch (e) { console.log('Fehler:', e.constructor.name); }","out":"Hallo Ada\nFehler: TypeError","pitfall":"Eine herausgelöste Methode verliert ihr Objekt. Abhilfe: o.sagHallo.bind(o) oder eine Pfeilfunktion als Wrapper.","lesson":"js-m1-l3","tested":true},{"id":"js-json","cat":"Daten","term":"JSON.stringify und JSON.parse","syntax":"JSON.stringify(wert)    JSON.parse(text)","text":"Wandelt Werte in JSON-Text um und zurück. So werden Daten gespeichert oder über das Netz geschickt.","code":"const text = JSON.stringify({ a: 1, b: [true, null] });\nconsole.log(text);\nconsole.log(JSON.parse(text).b[0]);","out":"{\"a\":1,\"b\":[true,null]}\ntrue","pitfall":"JSON.parse wirft bei ungültigem Text einen Fehler. Daten von außen in try/catch parsen und danach prüfen, nicht blind vertrauen.","lesson":"js-m1-l5","tested":true},{"id":"js-try-catch","cat":"Fehler","term":"try / catch / finally","syntax":"try { … } catch (fehler) { … } finally { … }","text":"Fängt Fehler, die im try-Block geworfen werden. finally läuft immer, auch nach einem Fehler oder return. throw wirft einen eigenen Fehler.","code":"try {\n  JSON.parse('{kaputt');\n} catch (fehler) {\n  console.log(fehler.name);\n} finally {\n  console.log('fertig');\n}","out":"SyntaxError\nfertig","pitfall":"Fehler nicht stumm verschlucken. Entweder sinnvoll behandeln oder weiterwerfen. Immer Error-Objekte werfen, keine Strings.","lesson":"js-m1-l4","tested":true},{"id":"js-promise","cat":"Asynchron","term":"Promise","syntax":"new Promise((resolve, reject) => …)    .then(…).catch(…)","text":"Steht für ein Ergebnis, das erst später vorliegt. then verarbeitet den Erfolg, catch den Fehler. Ketten geben jeweils eine neue Promise zurück.","code":"Promise.resolve(2)\n  .then((n) => n * 5)\n  .then((n) => console.log(n))\n  .catch((e) => console.log('Fehler', e))\n  .finally(() => console.log('aus'));","out":"10\naus","pitfall":"Ohne return in einem then-Schritt geht der Wert verloren. Immer catch am Ende der Kette setzen.","lesson":"js-m1-l4","tested":true},{"id":"js-async-await","cat":"Asynchron","term":"async / await","syntax":"async function f() { const x = await promise; }","text":"async-Funktionen liefern immer eine Promise. await wartet in ihnen auf eine Promise, ohne den restlichen Code zu blockieren, und liest sich wie normaler Ablauf.","code":"const warte = (ms) => new Promise((r) => setTimeout(r, ms));\nasync function lade() {\n  await warte(10);\n  return 'geladen';\n}\nconsole.log(await lade());","out":"geladen","pitfall":"Unabhängige Aufgaben nicht nacheinander awaiten. Sie laufen mit Promise.all parallel. Fehler fängt man mit try/catch.","lesson":"js-m1-l4","tested":true},{"id":"js-promise-all","cat":"Asynchron","term":"Promise.all","syntax":"await Promise.all([p1, p2])","text":"Startet mehrere Promises gemeinsam und liefert ein Array aller Ergebnisse. Schlägt eine fehl, schlägt das Ganze fehl. Promise.allSettled meldet jedes Ergebnis einzeln.","code":"const [a, b] = await Promise.all([Promise.resolve(1), Promise.resolve(2)]);\nconsole.log(a + b);\nconst r = await Promise.allSettled([Promise.reject(new Error('x')), Promise.resolve(1)]);\nconsole.log(r.map((x) => x.status));","out":"3\n[ 'rejected', 'fulfilled' ]","pitfall":"Bei Promise.all gehen die Ergebnisse der übrigen verloren, sobald eine ablehnt. Wenn Teilergebnisse zählen, allSettled nehmen.","lesson":"js-m1-l4","tested":true},{"id":"js-fetch","cat":"Asynchron","term":"fetch","syntax":"const antwort = await fetch(url, optionen)","text":"Ruft eine URL ab und liefert eine Antwort. antwort.json() liest den Rumpf als JSON. Das Ergebnis immer auf antwort.ok prüfen.","code":"const antwort = await fetch('/api/aufgaben');\nif (!antwort.ok) throw new Error('HTTP ' + antwort.status);\nconst daten = await antwort.json();","pitfall":"fetch wirft bei HTTP 404 oder 500 keinen Fehler. Nur Netzwerkfehler werden zur Ausnahme. Immer ok oder status prüfen.","lesson":"js-m1-l5","tested":false},{"id":"js-import-export","cat":"Module","term":"import / export","syntax":"import { a } from './datei.js';    export const a = 1;","text":"Teilt Code in Dateien (ES-Module). export macht etwas verfügbar, import holt es. Mit export default gibt es genau einen Standardexport.","code":"// mathe.js\nexport const PI = 3.14;\nexport default function quadrat(x) { return x * x; }\n\n// app.js\nimport quadrat, { PI } from './mathe.js';","pitfall":"Im Browser braucht das Skript type=\"module\". Bei Node muss die Dateiendung .mjs sein oder package.json \"type\": \"module\" enthalten.","lesson":"js-m1-l4","tested":false},{"id":"js-dom-query","cat":"Browser (DOM)","term":"querySelector","syntax":"document.querySelector('.klasse')","text":"Liefert das erste Element, das zum CSS-Selektor passt, oder null. querySelectorAll liefert alle Treffer.","code":"const knopf = document.querySelector('#senden');\nknopf?.addEventListener('click', () => {\n  knopf.textContent = 'Gesendet';\n});","pitfall":"Gibt es keinen Treffer, ist das Ergebnis null. Vor dem Zugriff prüfen oder ?. verwenden. Nutzertexte mit textContent setzen, nicht mit innerHTML.","lesson":"js-m1-l5","tested":false},{"id":"js-events","cat":"Browser (DOM)","term":"addEventListener","syntax":"element.addEventListener('click', funktion)","text":"Meldet eine Funktion an, die bei einem Ereignis (click, input, submit, keydown …) aufgerufen wird. Die Funktion bekommt das Event-Objekt.","code":"formular.addEventListener('submit', (event) => {\n  event.preventDefault();\n  console.log(new FormData(formular).get('name'));\n});","pitfall":"Für Aktionen <button> nutzen, nicht <div>, damit Tastatur und Screenreader funktionieren. preventDefault verhindert das Neuladen bei submit.","lesson":"js-m1-l5","tested":false},{"id":"js-storage","cat":"Browser (DOM)","term":"localStorage","syntax":"localStorage.setItem('schluessel', 'text')","text":"Speichert Text dauerhaft im Browser, pro Website. sessionStorage gilt nur bis zum Schließen des Tabs.","code":"localStorage.setItem('theme', 'dunkel');\nconsole.log(localStorage.getItem('theme'));","pitfall":"Nur Text, daher JSON.stringify verwenden. Nichts Geheimes ablegen: jedes Skript der Seite kann es lesen. Zugriffe in try/catch setzen, der Zugriff kann blockiert sein.","lesson":"js-m1-l5","tested":false},{"id":"js-ts-types","cat":"TypeScript","term":"Typannotation","syntax":"let name: string;    function f(a: number): boolean","text":"Hängt einem Wert, Parameter oder Rückgabewert einen Typ an. Der Compiler meldet Verstöße schon vor dem Ausführen. Im Laufzeitcode bleibt nichts davon übrig.","code":"function verdopple(zahl: number): number {\n  return zahl * 2;\n}\nconst text: string = 'Hallo';\nconsole.log(verdopple(4), text);","out":"8 Hallo","pitfall":"Typen prüfen nur den Code, nicht Daten zur Laufzeit. Antworten einer API müssen zusätzlich validiert werden (z. B. mit Zod).","lesson":"js-m1-l7","tested":true},{"id":"js-ts-interface","cat":"TypeScript","term":"interface und type","syntax":"interface Name { feld: typ }    type Alias = …","text":"Beschreiben die Form eines Objekts. type kann zusätzlich Vereinigungen (\"a\" | \"b\") und Hilfskonstrukte ausdrücken. Ein ? macht ein Feld optional.","code":"interface Nutzer {\n  name: string;\n  alter?: number;\n}\ntype Rolle = 'admin' | 'gast';\nconst u: Nutzer = { name: 'Mia' };\nconst r: Rolle = 'gast';\nconsole.log(u.name, r);","out":"Mia gast","pitfall":"as-Umwandlungen (Type Assertions) schalten die Prüfung nur ab. Besser Typen eingrenzen oder die Daten validieren.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-generics","cat":"TypeScript","term":"Generics","syntax":"function f<T>(wert: T): T","text":"Typparameter machen Funktionen und Typen für verschiedene Typen wiederverwendbar, ohne den Typ zu verlieren.","code":"function ersteres<T>(liste: T[]): T | undefined {\n  return liste[0];\n}\nconsole.log(ersteres<string>(['a', 'b']), ersteres([1, 2]));","out":"a 1","pitfall":"Mit noUncheckedIndexedAccess liefert liste[0] den Typ T | undefined. Das ist gewollt: der Fall „leer“ muss behandelt werden.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-unknown","cat":"TypeScript","term":"unknown statt any","syntax":"const daten: unknown = …","text":"unknown nimmt jeden Wert an, erlaubt aber erst nach einer Prüfung (typeof, instanceof, Schema) die Verwendung. any schaltet die Typprüfung dagegen ab.","code":"function laenge(wert: unknown): number {\n  return typeof wert === 'string' ? wert.length : 0;\n}\nconsole.log(laenge('Haus'), laenge(42));","out":"4 0","pitfall":"any breitet sich aus: einmal verwendet, verliert alles, was davon abhängt, seine Prüfung.","lesson":"js-m1-l7","tested":true},{"id":"js-array-copy","cat":"Objekte und Arrays","term":"toSorted, toReversed, with, findLast","syntax":"arr.toSorted()  arr.toReversed()  arr.with(i, wert)  arr.toSpliced(…)  arr.findLast(fn)","text":"Diese Methoden liefern eine veränderte Kopie, das Original bleibt unberührt. Das passt zu Zuständen in Vue und React, wo man Daten nicht direkt ändern soll. findLast sucht von hinten.","code":"const a = [3, 1, 2];\nconsole.log(a.toSorted(), a.toReversed(), a.with(0, 9), a.findLast((x) => x < 3), a);","out":"[ 1, 2, 3 ] [ 2, 1, 3 ] [ 9, 1, 2 ] 2 [ 3, 1, 2 ]","pitfall":"sort(), reverse() und splice() verändern das Original. Wer das vergisst, ändert versehentlich geteilte Daten. Die Kopier-Varianten gibt es in allen aktuellen Browsern und Node 20+.","lesson":"js-m1-l3","tested":true},{"id":"js-group-by","cat":"Objekte und Arrays","term":"Object.groupBy und Map.groupBy","syntax":"Object.groupBy(liste, (x) => schluessel)    Map.groupBy(liste, fn)","text":"Gruppiert eine Liste nach einem berechneten Schlüssel. Object.groupBy liefert ein Objekt aus Arrays, Map.groupBy eine Map (auch mit Objekten als Schlüssel).","code":"const tiere = [{ n: 'Hund', art: 'Säuger' }, { n: 'Adler', art: 'Vogel' }, { n: 'Katze', art: 'Säuger' }];\nconst gruppen = Object.groupBy(tiere, (t) => t.art);\nconsole.log(Object.keys(gruppen), gruppen['Säuger'].map((t) => t.n));","out":"[ 'Säuger', 'Vogel' ] [ 'Hund', 'Katze' ]","pitfall":"Das Ergebnis hat keinen Prototyp (kein toString, kein hasOwnProperty). Mit Object.hasOwn( ) oder `in` prüfen.","lesson":"js-m1-l3","tested":true},{"id":"js-set-methods","cat":"Objekte und Arrays","term":"Set-Mengenoperationen","syntax":"a.union(b)  a.intersection(b)  a.difference(b)  a.isSubsetOf(b)","text":"Mengenlehre direkt am Set: Vereinigung, Schnitt, Differenz und Teilmengen-Prüfung. Das ersetzt Schleifen mit Filter und includes.","code":"const a = new Set([1, 2, 3]);\nconst b = new Set([3, 4]);\nconsole.log([...a.union(b)], [...a.intersection(b)], [...a.difference(b)], a.isSubsetOf(new Set([1, 2, 3, 4])));","out":"[ 1, 2, 3, 4 ] [ 3 ] [ 1, 2 ] true","pitfall":"Die Methoden sind relativ neu (Node 22, aktuelle Browser seit 2024). Für ältere Umgebungen vorher auf caniuse.com prüfen.","lesson":"js-m1-l3","tested":true},{"id":"js-iterator-protocol","cat":"Funktionen","term":"Iterierbare Objekte (Symbol.iterator)","syntax":"*[Symbol.iterator]() { yield … }    for (const x of objekt)","text":"Ein Objekt mit der Methode [Symbol.iterator] ist iterierbar. Dann funktionieren for…of, Spread (...), Array.from und Destructuring damit. Ein Generator macht die Umsetzung kurz.","code":"class Bereich {\n  constructor(von, bis) { this.von = von; this.bis = bis; }\n  *[Symbol.iterator]() {\n    for (let i = this.von; i <= this.bis; i++) yield i;\n  }\n}\nconsole.log([...new Bereich(1, 4)], Math.max(...new Bereich(1, 4)));","out":"[ 1, 2, 3, 4 ] 4","pitfall":"Unendliche Generatoren nie mit Spread oder Array.from lesen. Dort hilft take (Iterator-Helfer) oder eine Schleife mit break.","lesson":"js-m1-l3","tested":true},{"id":"js-private-static","cat":"Objekte und Arrays","term":"Private Felder (#) und static-Block","syntax":"class K { #geheim = 0;  static #zaehler = 0;  static { … } }","text":"Felder mit # sind außerhalb der Klasse nicht erreichbar, nicht einmal per Reflection. static-Blöcke initialisieren Klassenwerte einmalig.","code":"class Zaehler {\n  #n = 0;\n  static #instanzen = 0;\n  static start;\n  static { Zaehler.start = 10; }\n  constructor() { Zaehler.#instanzen++; }\n  erhoehe() { return ++this.#n; }\n  static get anzahl() { return Zaehler.#instanzen; }\n}\nconst z = new Zaehler();\nz.erhoehe();\nconsole.log(z.erhoehe(), Zaehler.anzahl, Zaehler.start, z.n);","out":"2 1 10 undefined","pitfall":"Ein privates Feld lässt sich nicht per z.#n von außen lesen. Das ist ein Syntaxfehler, kein undefined. Für Tests öffentliche Methoden nutzen.","lesson":"js-m1-l3","tested":true},{"id":"js-freeze-assign","cat":"Objekte und Arrays","term":"Object.freeze, assign und hasOwn","syntax":"Object.freeze(obj)    Object.assign(ziel, quelle)    Object.hasOwn(obj, \"key\")","text":"freeze sperrt ein Objekt gegen Änderungen (nur eine Ebene tief). assign kopiert Eigenschaften in ein Ziel (flach). hasOwn prüft, ob ein Schlüssel direkt am Objekt liegt.","code":"const basis = Object.freeze({ a: 1 });\nfunction aendere() {\n  'use strict';\n  try { basis.a = 2; } catch (e) { return e.constructor.name; }\n}\nconsole.log(aendere(), Object.assign({}, basis, { b: 2 }), Object.hasOwn(basis, 'a'));","out":"TypeError { a: 1, b: 2 } true","pitfall":"Ohne 'use strict' wird die Zuweisung an ein eingefrorenes Objekt still ignoriert. Module und Klassen sind automatisch strikt. Verschachtelte Objekte bleiben änderbar.","lesson":"js-m1-l3","tested":true},{"id":"js-promise-combinators","cat":"Asynchron","term":"Promise.allSettled, any, race, withResolvers","syntax":"Promise.allSettled([…])  Promise.any([…])  Promise.race([…])  Promise.withResolvers()","text":"allSettled wartet auf alle und meldet Erfolg oder Fehler je Eintrag. any liefert das erste erfolgreiche Ergebnis. race das erste fertige, egal ob Erfolg oder Fehler. withResolvers gibt Promise samt resolve und reject zurück.","code":"const ok = Promise.resolve(1);\nconst fehler = Promise.reject(new Error('x'));\nconst ergebnis = await Promise.allSettled([ok, fehler]);\nconsole.log(ergebnis.map((e) => e.status));\nconsole.log(await Promise.any([fehler, Promise.resolve('zweiter')]));\nconst { promise, resolve } = Promise.withResolvers();\nsetTimeout(() => resolve('fertig'), 10);\nconsole.log(await promise);","out":"[ 'fulfilled', 'rejected' ]\nzweiter\nfertig","pitfall":"Promise.all bricht beim ersten Fehler ab und verwirft die übrigen Ergebnisse. Wenn Teilergebnisse nützlich sind, allSettled verwenden.","lesson":"js-m1-l4","tested":true},{"id":"js-error-cause","cat":"Fehler","term":"Error mit cause, catch ohne Variable","syntax":"throw new Error('Text', { cause: ursprung })    catch { … }","text":"cause hängt den ursprünglichen Fehler an einen neuen, sodass beim Debuggen die ganze Kette sichtbar bleibt. Wird die Fehlervariable nicht gebraucht, kann man sie im catch weglassen.","code":"try {\n  try { JSON.parse('{x'); } catch (e) { throw new Error('Konfig ungültig', { cause: e }); }\n} catch (fehler) {\n  console.log(fehler.message, '<-', fehler.cause.name);\n}\ntry { null.x; } catch { console.log('ohne Variable'); }","out":"Konfig ungültig <- SyntaxError\nohne Variable","pitfall":"Fehler nie mit einem leeren catch verschlucken. Mindestens protokollieren oder dem Nutzer verständlich melden.","lesson":"js-m1-l4","tested":true},{"id":"js-bigint-date","cat":"Typen und Werte","term":"BigInt und Date","syntax":"2n ** 64n    new Date(iso)    date.toISOString()    Date.UTC(j, m, t)","text":"BigInt (Endung n) rechnet mit beliebig großen ganzen Zahlen. Date speichert einen Zeitpunkt in Millisekunden seit 1970. toISOString gibt ihn in UTC aus. Monate zählen ab 0.","code":"console.log(2n ** 64n, typeof 10n, Number.MAX_SAFE_INTEGER);\nconsole.log(new Date('2026-11-13T10:00:00Z').toISOString(), new Date(Date.UTC(2026, 0, 31)).toISOString());","out":"18446744073709551616n bigint 9007199254740991\n2026-11-13T10:00:00.000Z 2026-01-31T00:00:00.000Z","pitfall":"BigInt und Number lassen sich nicht mischen (TypeError). Bei Date ist Monat 0 der Januar. Für Anzeigen in lokaler Zeit Intl.DateTimeFormat verwenden.","lesson":"js-m1-l1","tested":true},{"id":"js-proxy-weakmap","cat":"Objekte und Arrays","term":"Proxy und WeakMap","syntax":"new Proxy(ziel, { get, set })    new WeakMap()","text":"Ein Proxy fängt Zugriffe auf ein Objekt ab (Validierung, Protokoll, Reaktivität – so arbeitet Vue 3). Eine WeakMap hält Daten zu Objekten, ohne sie am Leben zu halten, sodass der Speicher freigegeben werden kann.","code":"const nutzer = new Proxy({ alter: 30 }, {\n  set(ziel, schluessel, wert) {\n    if (schluessel === 'alter' && wert < 0) throw new RangeError('alter < 0');\n    ziel[schluessel] = wert;\n    return true;\n  }\n});\nnutzer.alter = 31;\ntry { nutzer.alter = -1; } catch (e) { console.log(e.message); }\nconsole.log(nutzer.alter);","out":"alter < 0\n31","pitfall":"Proxys sind langsamer als direkter Zugriff und erschweren das Debuggen. Nur dort einsetzen, wo Abfangen wirklich nötig ist.","lesson":"js-m1-l3","tested":true},{"id":"js-timers-raf","cat":"Browser (DOM)","term":"requestAnimationFrame und queueMicrotask","syntax":"requestAnimationFrame(fn)    cancelAnimationFrame(id)    queueMicrotask(fn)","text":"requestAnimationFrame ruft eine Funktion vor dem nächsten Zeichnen auf (meist 60-mal pro Sekunde) und ist für Animationen richtig. setTimeout ist dafür ungenau. queueMicrotask reiht Arbeit nach dem aktuellen Code, aber vor dem nächsten Timer ein.","code":"let start;\nfunction schritt(zeit) {\n  start ??= zeit;\n  const t = Math.min((zeit - start) / 500, 1);\n  box.style.transform = `translateX(${t * 200}px)`;\n  if (t < 1) requestAnimationFrame(schritt);\n}\nrequestAnimationFrame(schritt);","pitfall":"Bei prefers-reduced-motion keine Bewegung abspielen. In Hintergrund-Tabs pausiert requestAnimationFrame. Ohne Abbruch (cancelAnimationFrame) läuft die Schleife weiter.","lesson":"js-m1-l5","tested":false},{"id":"js-formdata","cat":"Browser (DOM)","term":"FormData und fetch (POST)","syntax":"new FormData(form)    fetch(url, { method: \"POST\", body })","text":"FormData liest alle Felder eines Formulars (auch Dateien) aus. Mit fetch verschickt man es als multipart. Für JSON stringifiziert man selbst und setzt den Content-Type.","code":"form.addEventListener('submit', async (event) => {\n  event.preventDefault();\n  const daten = new FormData(form);\n  const antwort = await fetch('/api/kontakt', { method: 'POST', body: daten });\n  if (!antwort.ok) throw new Error(`Fehler ${antwort.status}`);\n  // JSON-Variante:\n  // fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(daten)) })\n});","pitfall":"Bei FormData den Content-Type-Header nicht selbst setzen, der Browser ergänzt die Trennmarke (boundary). fetch wirft bei HTTP 404/500 nicht, immer response.ok prüfen. Bei POST CSRF-Schutz serverseitig vorsehen.","lesson":"js-m1-l5","tested":false},{"id":"js-intersection-observer","cat":"Browser (DOM)","term":"IntersectionObserver","syntax":"new IntersectionObserver(callback, { threshold }).observe(element)","text":"Meldet, wenn ein Element im sichtbaren Bereich erscheint oder ihn verlässt. Damit lädt man Inhalte nach (Lazy Loading) oder startet Animationen, ohne auf Scroll-Ereignisse zu hören.","code":"const beobachter = new IntersectionObserver((eintraege) => {\n  for (const e of eintraege) {\n    if (e.isIntersecting) {\n      e.target.classList.add('sichtbar');\n      beobachter.unobserve(e.target);\n    }\n  }\n}, { threshold: 0.2 });\ndocument.querySelectorAll('.karte').forEach((karte) => beobachter.observe(karte));","pitfall":"Wichtige Inhalte (LCP-Bild, Überschriften) nicht erst per Observer einblenden. Sie müssen sofort im HTML sichtbar sein.","lesson":"js-m1-l5","tested":false},{"id":"js-history-session","cat":"Browser (DOM)","term":"sessionStorage und history.pushState","syntax":"sessionStorage.setItem(k, v)    history.pushState(state, \"\", url)    popstate","text":"sessionStorage speichert Werte nur bis der Tab schließt. pushState ändert die Adresse ohne Neuladen, Single-Page-Apps nutzen es für Routing. Das popstate-Ereignis meldet Zurück und Vor.","code":"sessionStorage.setItem('entwurf', JSON.stringify({ titel: 'Hallo' }));\nconst entwurf = JSON.parse(sessionStorage.getItem('entwurf') ?? 'null');\n\nhistory.pushState({ seite: 2 }, '', '?seite=2');\naddEventListener('popstate', (e) => console.log('zurück zu', e.state));","pitfall":"Web Storage ist für JavaScript auslesbar (XSS). Keine Tokens oder Passwörter darin ablegen. Der Zugriff kann in privaten Fenstern scheitern, in try/catch kapseln.","lesson":"js-m1-l5","tested":false},{"id":"js-dynamic-import","cat":"Module","term":"Dynamisches import() und top-level await","syntax":"const modul = await import(\"./datei.js\")    export default    export * from","text":"import() lädt ein Modul erst bei Bedarf und liefert ein Promise. So bleiben große Bibliotheken aus dem ersten Bundle. In Modulen darf await auch auf oberster Ebene stehen.","code":"button.addEventListener('click', async () => {\n  const { zeichneDiagramm } = await import('./diagramm.js');\n  zeichneDiagramm(daten);\n});\n\n// Modul mit top-level await\nconst konfig = await fetch('/konfig.json').then((r) => r.json());\nexport default konfig;","pitfall":"Top-level await blockiert alle Module, die dieses Modul importieren, bis es fertig ist. Sparsam einsetzen.","lesson":"js-m1-l5","tested":false},{"id":"js-ts-keyof-mapped","cat":"TypeScript","term":"keyof, typeof, indexed access und Mapped Types","syntax":"keyof T    typeof wert    T[\"feld\"]    { [K in keyof T]: … }","text":"keyof liefert die Schlüssel eines Typs als Union. typeof leitet den Typ aus einem Wert ab. T[\"feld\"] liest den Typ eines Felds. Ein Mapped Type baut aus einem Typ einen neuen, z. B. alle Felder optional oder schreibgeschützt.","code":"const nutzer = { id: 1, name: 'Mia', aktiv: true };\ntype Nutzer = typeof nutzer;            // { id: number; name: string; aktiv: boolean }\ntype Feld = keyof Nutzer;               // 'id' | 'name' | 'aktiv'\ntype Name = Nutzer['name'];             // string\ntype NurLesen<T> = { readonly [K in keyof T]: T[K] };\ntype Formular<T> = { [K in keyof T]: string };   // alles als Eingabetext\n\nfunction lies<T, K extends keyof T>(objekt: T, schluessel: K): T[K] {\n  return objekt[schluessel];\n}","pitfall":"Typen existieren nur zur Entwicklungszeit und werden beim Ausführen entfernt. Daten von außen (fetch, Formulare) trotzdem zur Laufzeit prüfen, z. B. mit Zod.","lesson":"js-m1-l7","tested":false,"codeLang":"typescript"},{"id":"js-ts-conditional","cat":"TypeScript","term":"Conditional Types, infer, ReturnType, Awaited","syntax":"T extends U ? X : Y    infer R    ReturnType<typeof f>    Awaited<Promise<T>>","text":"Ein Conditional Type wählt einen Typ je nach Bedingung. infer holt einen Teil eines Typs heraus. ReturnType, Parameters, Awaited und NonNullable sind fertige Hilfen daraus.","code":"type Element<T> = T extends (infer E)[] ? E : T;\ntype A = Element<string[]>;   // string\ntype B = Element<number>;     // number\n\nasync function ladeNutzer() { return { id: 1, name: 'Mia' }; }\ntype Nutzer = Awaited<ReturnType<typeof ladeNutzer>>;   // { id: number; name: string }\ntype Sicher = NonNullable<string | null | undefined>;   // string","pitfall":"Verschachtelte Conditional Types werden schnell unlesbar. Eine kurze Typ-Alias-Kette mit sprechenden Namen ist besser als ein Einzeiler.","lesson":"js-m1-l7","tested":false,"codeLang":"typescript"},{"id":"js-ts-never-exhaustive","cat":"TypeScript","term":"Discriminated Union und Vollständigkeitsprüfung (never)","syntax":"type Form = { art: 'kreis'; r: number } | { art: 'quadrat'; s: number }    const x: never = wert","text":"Ein gemeinsames Feld (art) unterscheidet die Fälle einer Union. In einem switch grenzt TypeScript den Typ je Fall ein. Mit never im default meldet der Compiler, wenn ein neuer Fall nicht behandelt wurde.","code":"type Form = { art: 'kreis'; r: number } | { art: 'quadrat'; s: number };\n\nfunction flaeche(f: Form): number {\n  switch (f.art) {\n    case 'kreis': return Math.PI * f.r ** 2;\n    case 'quadrat': return f.s ** 2;\n    default: {\n      const unbehandelt: never = f;   // Fehler, sobald ein neuer Fall dazukommt\n      throw new Error(`Unbekannt: ${unbehandelt}`);\n    }\n  }\n}","pitfall":"Ohne die never-Prüfung bleibt ein später ergänzter Fall unbemerkt. Das ist der Hauptgrund für diese Schreibweise.","lesson":"js-m1-l7","tested":false,"codeLang":"typescript"},{"id":"js-ts-tuple-readonly","cat":"TypeScript","term":"Tupel, readonly und Enum-Ersatz","syntax":"type P = [number, number]    readonly string[]    const ROLLEN = [...] as const","text":"Ein Tupel hat feste Länge und Typen je Position. readonly verhindert Änderungen. Statt enum nutzt man meist ein as const-Array oder Objekt und leitet daraus die Union ab. Das erzeugt weniger Laufzeitcode.","code":"type Punkt = [x: number, y: number];\nconst p: Punkt = [3, 4];\n\nconst ROLLEN = ['admin', 'redakteur', 'gast'] as const;\ntype Rolle = (typeof ROLLEN)[number];   // 'admin' | 'redakteur' | 'gast'\n\nfunction zeige(liste: readonly string[]) {\n  // liste.push('x');   // Fehler: readonly\n  return liste.length;\n}","pitfall":"Echte enum-Deklarationen und Namespaces funktionieren nicht mit reinem „Type Stripping“ in Node. Wer sie nutzt, braucht einen Compiler-Schritt.","lesson":"js-m1-l7","tested":false,"codeLang":"typescript"},{"id":"js-ts-tsconfig","cat":"TypeScript","term":"tsconfig.json: strict und tsc","syntax":"\"strict\": true    \"noUncheckedIndexedAccess\": true    npx tsc --noEmit","text":"Die tsconfig.json steuert den Compiler. strict schaltet die wichtigsten Prüfungen ein, noUncheckedIndexedAccess macht arr[0] zu „T oder undefined“. tsc --noEmit prüft nur und schreibt nichts.","code":"{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Bundler\",\n    \"strict\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"verbatimModuleSyntax\": true,\n    \"skipLibCheck\": true\n  },\n  \"include\": [\"src\"]\n}","pitfall":"Neue Projekte immer mit strict beginnen. Nachträglich aktivieren erzeugt viele Fehler auf einmal. Die Werte (target, module) zur eigenen Umgebung passend wählen.","lesson":"js-m1-l7","tested":false,"codeLang":"javascript"},{"id":"js-string-methods","cat":"Typen und Werte","term":"String-Methoden","syntax":"text.slice(a, b)  text.includes(x)  text.split(',')  text.trim()  text.padStart(n, '0')","text":"Strings sind unveränderlich, jede Methode liefert einen neuen Text. slice schneidet aus, includes sucht, split zerlegt in ein Array, trim entfernt Leerraum am Rand, padStart füllt vorn auf.","code":"const s = '  a,b,c  ';\nconsole.log(s.trim().split(','), 'abcdef'.slice(1, 4), 'Haus'.includes('au'), '7'.padStart(3, '0'), 'a-b-a'.replaceAll('a', 'x'));","out":"[ 'a', 'b', 'c' ] bcd true 007 x-b-x","pitfall":"replace ersetzt nur das erste Vorkommen, replaceAll alle. substring und slice behandeln negative Werte unterschiedlich: im Zweifel slice.","lesson":"js-m1-l1","tested":true},{"id":"js-number-math","cat":"Typen und Werte","term":"Number und Math","syntax":"Number(x)  parseInt(x, 10)  x.toFixed(2)  Math.round(x)  Number.isNaN(x)","text":"Zahlen sind immer 64-Bit-Gleitkomma. Number() wandelt streng um (ungültig ergibt NaN), toFixed rundet für die Anzeige (Ergebnis ist ein Text), Math bietet round, floor, ceil, max, min.","code":"console.log(Number('42'), Number('4x2'), parseInt('42px', 10), (0.1 + 0.2).toFixed(2), 0.1 + 0.2 === 0.3, Math.max(3, 9, 4));","out":"42 NaN 42 0.30 false 9","pitfall":"Geldbeträge nie mit Gleitkomma rechnen (0.1 + 0.2 ≠ 0.3). In ganzen Cent rechnen und erst zur Anzeige formatieren.","lesson":"js-m1-l1","tested":true},{"id":"js-array-basics","cat":"Objekte und Arrays","term":"push, pop, slice, splice, at","syntax":"liste.push(x)  liste.pop()  liste.slice(a, b)  liste.at(-1)","text":"push und pop arbeiten am Ende, slice kopiert einen Ausschnitt, splice verändert das Array an Ort und Stelle, at(-1) liest das letzte Element.","code":"const z = [1, 2, 3, 4];\nz.push(5);\nconsole.log(z.pop(), z.slice(1, 3), z.at(-1), z.length);","out":"5 [ 2, 3 ] 4 4","pitfall":"splice und sort verändern das Original, slice und toSorted nicht. In Vue und React führen unbeabsichtigte Mutationen zu Fehlern.","lesson":"js-m1-l3","tested":true},{"id":"js-array-flat","cat":"Objekte und Arrays","term":"flat, flatMap, Array.from","syntax":"liste.flat()  liste.flatMap(fn)  Array.from({ length: n }, fn)","text":"flat macht verschachtelte Arrays eben, flatMap kombiniert map und flat. Array.from erzeugt Arrays aus iterierbaren Werten oder aus einer Länge.","code":"console.log([[1], [2, 3]].flat(), ['a b', 'c'].flatMap((t) => t.split(' ')), Array.from({ length: 3 }, (_, i) => i * i));","out":"[ 1, 2, 3 ] [ 'a', 'b', 'c' ] [ 0, 1, 4 ]","pitfall":"new Array(3).map(…) überspringt die leeren Plätze. Für Listen dieser Art Array.from({ length }) verwenden.","lesson":"js-m1-l3","tested":true},{"id":"js-object-methods","cat":"Objekte und Arrays","term":"Object.keys, entries, fromEntries","syntax":"Object.keys(o)  Object.entries(o)  Object.fromEntries(paare)","text":"Wandeln Objekte in Listen und zurück. entries liefert [Schlüssel, Wert]-Paare, fromEntries baut daraus wieder ein Objekt, so lassen sich Objekte mit map und filter bearbeiten.","code":"const preise = { tee: 3, kaffee: 4 };\nconst teuer = Object.fromEntries(Object.entries(preise).map(([k, v]) => [k, v * 2]));\nconsole.log(Object.keys(preise), teuer);","out":"[ 'tee', 'kaffee' ] { tee: 6, kaffee: 8 }","pitfall":"Die Reihenfolge der Schlüssel folgt festen Regeln: ganzzahlige Schlüssel zuerst und aufsteigend. Für echte Einfügereihenfolge eine Map verwenden.","lesson":"js-m1-l3","tested":true},{"id":"js-structured-clone","cat":"Objekte und Arrays","term":"structuredClone","syntax":"structuredClone(wert)","text":"Erstellt eine tiefe Kopie, im Gegensatz zum Spread (...), der nur die oberste Ebene kopiert. Unterstützt Datum, Map, Set und Zyklen, aber keine Funktionen.","code":"const a = { liste: [1, 2] };\nconst flach = { ...a };\nconst tief = structuredClone(a);\na.liste.push(3);\nconsole.log(flach.liste.length, tief.liste.length);","out":"3 2","pitfall":"Funktionen und Klasseninstanzen verlieren ihre Methoden oder lösen einen Fehler aus. JSON.parse(JSON.stringify(x)) wandelt Datum in Text um und ist keine Alternative.","lesson":"js-m1-l3","tested":true},{"id":"js-getter-static","cat":"Objekte und Arrays","term":"extends, static, get / set","syntax":"class B extends A { static x = 1; get name() { … } }","text":"extends erbt von einer Klasse, super ruft den Elternteil auf. static gehört der Klasse selbst, get und set machen Methoden wie Eigenschaften lesbar.","code":"class Tier {\n  constructor(name) { this.name = name; }\n  sagt() { return `${this.name} macht ein Geräusch`; }\n}\nclass Hund extends Tier {\n  static art = 'Hund';\n  sagt() { return super.sagt() + ': Wuff'; }\n  get gross() { return this.name.toUpperCase(); }\n}\nconst h = new Hund('Rex');\nconsole.log(h.sagt(), h.gross, Hund.art);","out":"Rex macht ein Geräusch: Wuff REX Hund","pitfall":"Im Konstruktor einer abgeleiteten Klasse muss super() vor jeder Nutzung von this stehen.","lesson":"js-m1-l3","tested":true},{"id":"js-iterator-generator","cat":"Funktionen","term":"Generator (function*) und yield","syntax":"function* zahlen() { yield 1; }","text":"Eine Generatorfunktion liefert Werte nacheinander und pausiert bei yield. Das Ergebnis ist iterierbar und lässt sich mit for … of oder Spread verwenden.","code":"function* bis(n) {\n  for (let i = 1; i <= n; i++) yield i;\n}\nconsole.log([...bis(3)]);\nfor (const x of bis(2)) console.log(x);","out":"[ 1, 2, 3 ]\n1\n2","pitfall":"Ein Generator ist nach dem Durchlaufen verbraucht. Für eine zweite Runde einen neuen Aufruf starten.","lesson":"js-m1-l2","tested":true},{"id":"js-timers","cat":"Asynchron","term":"setTimeout und AbortController","syntax":"setTimeout(fn, ms)  clearTimeout(id)  controller.abort()","text":"setTimeout führt eine Funktion später aus und blockiert nichts. clearTimeout bricht sie ab. Ein AbortController bricht laufende Anfragen ab, zum Beispiel bei schnellem Tippen in einem Suchfeld.","code":"const id = setTimeout(() => console.log('nie'), 50);\nclearTimeout(id);\nconst steuerung = new AbortController();\nsteuerung.signal.addEventListener('abort', () => console.log('abgebrochen'));\nsteuerung.abort();","out":"abgebrochen","pitfall":"Das Zeitlimit von setTimeout ist ein Minimum, kein Versprechen. Bei ausgelastetem Event-Loop läuft die Funktion später.","lesson":"js-m1-l4","tested":true},{"id":"js-event-loop","cat":"Asynchron","term":"Reihenfolge: synchron, Microtask, Macrotask","syntax":"console.log  →  Promise.then  →  setTimeout","text":"Zuerst läuft der gesamte synchrone Code, danach die Microtasks (Promise.then, await), erst dann Macrotasks wie setTimeout. Diese Reihenfolge erklärt viele scheinbar zufällige Ausgaben.","code":"setTimeout(() => console.log('Timeout'), 0);\nPromise.resolve().then(() => console.log('Promise'));\nconsole.log('synchron');","out":"synchron\nPromise\nTimeout","pitfall":"Endlose Microtask-Ketten blockieren den Event-Loop, und die Seite reagiert nicht mehr, obwohl nichts „blockiert“.","lesson":"js-m1-l4","tested":true},{"id":"js-regex","cat":"Daten","term":"Reguläre Ausdrücke","syntax":"/muster/flags  text.match(re)  re.test(text)  text.replace(re, ersatz)","text":"Beschreiben Textmuster. \\d steht für eine Ziffer, + für „mindestens eine“, ^ und $ für Anfang und Ende, Klammern fassen Gruppen. Das Flag g findet alle Treffer, i ignoriert Groß- und Kleinschreibung.","code":"const plz = /^\\d{5}$/;\nconsole.log(plz.test('10115'), plz.test('1011'));\nconsole.log('a1b22c333'.match(/\\d+/g));\nconsole.log('2026-11-13'.replace(/(\\d+)-(\\d+)-(\\d+)/, '$3.$2.$1'));","out":"true false\n[ '1', '22', '333' ]\n13.11.2026","pitfall":"Mit regulären Ausdrücken keine E-Mail-Adressen „vollständig“ prüfen. Für Nutzereingaben genügt eine einfache Prüfung plus Bestätigungsmail. Verschachtelte Wiederholungen können den Server lahmlegen (ReDoS).","lesson":"js-m1-l5","tested":true},{"id":"js-intl","cat":"Daten","term":"Intl: Zahlen und Datum formatieren","syntax":"new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' })","text":"Formatiert Zahlen, Währungen und Daten passend zur Sprache. Nie selbst Punkte, Kommas und Monatsnamen zusammenbauen.","code":"const euro = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' });\nconsole.log(euro.format(1234.5));\nconsole.log(new Intl.DateTimeFormat('de-DE', { dateStyle: 'long', timeZone: 'UTC' }).format(new Date('2026-11-13T12:00:00Z')));","out":"1.234,50 €\n13. November 2026","pitfall":"Zwischen Zahl und € steht ein geschütztes Leerzeichen (U+00A0). Beim Vergleichen von Ausgaben im Test beachten.","lesson":"js-m1-l5","tested":true},{"id":"js-url","cat":"Browser (DOM)","term":"URL und URLSearchParams","syntax":"new URL(text)  url.searchParams.get(name)","text":"Zerlegt Adressen und baut Abfrageparameter sicher zusammen, inklusive Kodierung. Für Parameter in URLs nie Strings verketten.","code":"const u = new URL('https://example.org/suche?q=g%C3%A4rtner&seite=2');\nconsole.log(u.hostname, u.searchParams.get('q'), Number(u.searchParams.get('seite')));\nu.searchParams.set('q', 'a&b');\nconsole.log(u.search);","out":"example.org gärtner 2\n?q=a%26b&seite=2","pitfall":"Parameter sind immer Text oder null. Zahlen umwandeln und prüfen, bevor man sie benutzt.","lesson":"js-m1-l5","tested":true},{"id":"js-event-delegation","cat":"Browser (DOM)","term":"Event Delegation","syntax":"liste.addEventListener('click', (e) => e.target.closest('button'))","text":"Statt an jedes Element einen Listener zu hängen, hört ein Listener am Elternelement zu und prüft mit closest(), welches Kind getroffen wurde. Das funktioniert auch für später eingefügte Elemente.","code":"liste.addEventListener('click', (event) => {\n  const knopf = event.target.closest('button[data-id]');\n  if (!knopf || !liste.contains(knopf)) return;\n  console.log('Eintrag', knopf.dataset.id);\n});","pitfall":"event.target kann ein Kindelement des Buttons sein (z. B. ein Icon). Deshalb closest() statt direktem Vergleich.","lesson":"js-m1-l5","tested":false},{"id":"js-ts-narrowing","cat":"TypeScript","term":"Typeingrenzung (Narrowing)","syntax":"typeof x === 'string'    'feld' in obj    x instanceof Klasse","text":"Nach einer Prüfung kennt TypeScript den genaueren Typ innerhalb des Zweigs. Bei Vereinigungstypen mit einem gemeinsamen Feld (type) spricht man von einer diskriminierten Union.","code":"type Ergebnis = { art: 'ok'; wert: number } | { art: 'fehler'; meldung: string };\nfunction text(e: Ergebnis): string {\n  return e.art === 'ok' ? `Wert ${e.wert}` : `Fehler: ${e.meldung}`;\n}\nconsole.log(text({ art: 'ok', wert: 7 }), text({ art: 'fehler', meldung: 'kaputt' }));","out":"Wert 7 Fehler: kaputt","pitfall":"Bei Zugriff auf Felder ohne vorherige Prüfung meldet der Compiler einen Fehler. Das ist die Absicht, nicht mit as umgehen.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-utility","cat":"TypeScript","term":"Hilfstypen: Partial, Pick, Omit, Record","syntax":"Partial<T>  Pick<T, \"a\">  Omit<T, \"a\">  Record<K, V>","text":"Bauen neue Typen aus vorhandenen. Partial macht alle Felder optional, Pick wählt Felder aus, Omit entfernt sie, Record beschreibt ein Objekt mit gleichartigen Werten.","code":"interface Nutzer { id: number; name: string; mail: string }\ntype Aenderung = Partial<Omit<Nutzer, 'id'>>;\nconst a: Aenderung = { name: 'Neu' };\nconst rollen: Record<'admin' | 'gast', number> = { admin: 1, gast: 0 };\nconsole.log(a, rollen);","out":"{ name: 'Neu' } { admin: 1, gast: 0 }","pitfall":"Partial prüft nicht, ob mindestens ein Feld gesetzt ist. Leere Änderungen müssen zur Laufzeit abgefangen werden.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-const-satisfies","cat":"TypeScript","term":"as const und satisfies","syntax":"const x = { … } as const;    const y = { … } satisfies Typ;","text":"as const macht Werte schreibgeschützt und typisiert sie als exakte Literale. satisfies prüft gegen einen Typ, ohne den genaueren abgeleiteten Typ zu verlieren.","code":"const ROLLEN = ['admin', 'gast'] as const;\ntype Rolle = (typeof ROLLEN)[number];\nconst farben = { admin: 'rot', gast: 'grau' } satisfies Record<Rolle, string>;\nconsole.log(ROLLEN.length, farben.admin);","out":"2 rot","pitfall":"as const wirkt nur zur Compile-Zeit. Zur Laufzeit ist das Objekt weiterhin veränderbar, dafür Object.freeze verwenden.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-guard","cat":"TypeScript","term":"Typprädikat (Type Guard)","syntax":"function istX(w: unknown): w is X","text":"Eine Funktion, deren Rückgabetyp „w is X“ lautet, teilt dem Compiler mit: Ist das Ergebnis true, hat w den Typ X. So lassen sich unbekannte Daten sicher eingrenzen.","code":"interface Punkt { x: number; y: number }\nfunction istPunkt(w: unknown): w is Punkt {\n  return typeof w === 'object' && w !== null && typeof (w as Punkt).x === 'number' && typeof (w as Punkt).y === 'number';\n}\nconst daten: unknown = JSON.parse('{\"x\":1,\"y\":2}');\nconsole.log(istPunkt(daten) ? daten.x + daten.y : 'kein Punkt');","out":"3","pitfall":"Der Compiler vertraut dem Prädikat blind. Prüft es zu wenig, entstehen falsche Typen. Bei vielen Feldern ein Schema (Zod) verwenden.","lesson":"js-m1-l7","tested":true}]},{"id":"vue","label":"Vue 3","codeLang":"vue","intro":"Framework für Oberflächen. Komponenten stehen in .vue-Dateien (Template, Skript, Stil). Hier die Schreibweise mit <script setup> und der Composition API.","notice":"Diese Beispiele werden hier nicht ausgeführt. Sie folgen Vue 3.5 mit <script setup>; die vollständigen, getesteten Beispielprojekte liegen in den Labs der Lektionen.","runner":"","entries":[{"id":"vue-sfc","cat":"Komponente","term":"Single-File-Component","syntax":"<script setup lang=\"ts\">…</script>\n<template>…</template>\n<style scoped>…</style>","text":"Eine .vue-Datei enthält Logik, Template und Stil. Alles Deklarierte in <script setup> ist im Template direkt verfügbar. scoped begrenzt den Stil auf diese Komponente.","code":"<script setup lang=\"ts\">\nimport { ref } from 'vue'\nconst name = ref('Ada')\n</script>\n\n<template>\n  <p>Hallo {{ name }}</p>\n</template>","pitfall":"In <script setup> gibt es kein this. Zustand und Funktionen sind einfache Variablen.","lesson":"js-m1-l8","tested":false},{"id":"vue-ref","cat":"Reaktivität","term":"ref","syntax":"const zahl = ref(0)    zahl.value","text":"Macht einen Wert reaktiv. Im Skript greift man über .value zu, im Template wird .value automatisch ergänzt.","code":"const zaehler = ref(0)\nfunction erhoehe() {\n  zaehler.value++\n}","pitfall":"Das Vergessen von .value im Skript ist der häufigste Anfängerfehler. zaehler++ ändert nichts Reaktives.","lesson":"js-m1-l9","tested":false},{"id":"vue-reactive","cat":"Reaktivität","term":"reactive","syntax":"const zustand = reactive({ a: 1 })","text":"Macht ein Objekt reaktiv, der Zugriff erfolgt ohne .value. Es funktioniert nur für Objekte und verliert die Reaktivität, wenn man Eigenschaften einzeln herauslöst.","code":"const form = reactive({ name: '', mail: '' })\nconst { name } = form   // verliert die Reaktivität!\nconst nameRef = toRef(form, 'name')   // bleibt reaktiv","pitfall":"Destructuring von reactive-Objekten und Props trennt die Verbindung. Dafür toRef, toRefs oder storeToRefs (Pinia) verwenden.","lesson":"js-m4-l4","tested":false},{"id":"vue-computed","cat":"Reaktivität","term":"computed","syntax":"const x = computed(() => …)","text":"Berechneter Wert, der sich nur neu berechnet, wenn sich seine Abhängigkeiten ändern. Er ist gedacht für abgeleitete Daten ohne Nebenwirkungen.","code":"const preis = ref(10)\nconst menge = ref(3)\nconst summe = computed(() => preis.value * menge.value)","pitfall":"In computed keine Daten ändern und keine Anfragen senden. Für Reaktionen auf Änderungen gibt es watch.","lesson":"js-m1-l9","tested":false},{"id":"vue-watch","cat":"Reaktivität","term":"watch und watchEffect","syntax":"watch(quelle, (neu, alt) => …)","text":"watch führt eine Funktion aus, wenn sich eine Quelle ändert, etwa um zu laden oder zu speichern. watchEffect läuft sofort und verfolgt automatisch alle benutzten Werte.","code":"watch(suche, async (neu, alt, onCleanup) => {\n  const abbruch = new AbortController()\n  onCleanup(() => abbruch.abort())\n  ergebnisse.value = await lade(neu, abbruch.signal)\n})","pitfall":"Schnell aufeinanderfolgende Änderungen starten mehrere Anfragen. onCleanup bricht die alte ab, sonst gewinnt eine zufällig langsame Antwort.","lesson":"js-m1-l9","tested":false},{"id":"vue-interpolation","cat":"Template","term":"{{ }} und v-bind","syntax":"{{ ausdruck }}    :attribut=\"ausdruck\"","text":"{{ }} setzt Text ein (automatisch maskiert), :attribut (Kurzform von v-bind) bindet ein Attribut an einen Ausdruck.","code":"<img :src=\"bild.url\" :alt=\"bild.beschreibung\">\n<button :disabled=\"laeuft\">{{ laeuft ? 'Lädt …' : 'Speichern' }}</button>","pitfall":"v-html fügt rohes HTML ein und öffnet XSS-Lücken. Nur mit bereinigtem eigenem Inhalt benutzen, niemals mit Nutzertext.","lesson":"js-m1-l8","tested":false},{"id":"vue-if","cat":"Template","term":"v-if, v-else, v-show","syntax":"<p v-if=\"bedingung\">…</p><p v-else>…</p>","text":"v-if erzeugt das Element nur, wenn die Bedingung wahr ist. v-show blendet es lediglich per CSS ein und aus. Für häufiges Umschalten ist v-show günstiger.","code":"<p v-if=\"laedt\">Lade …</p>\n<p v-else-if=\"fehler\" role=\"alert\">{{ fehler }}</p>\n<ul v-else>…</ul>","pitfall":"Zuerst Lade- und Fehlerzustand behandeln, erst dann die Daten zeigen. Sonst blitzen leere oder alte Inhalte auf.","lesson":"js-m1-l8","tested":false},{"id":"vue-for","cat":"Template","term":"v-for und :key","syntax":"<li v-for=\"x in liste\" :key=\"x.id\">","text":"Wiederholt ein Element für jedes Listenelement. :key muss eindeutig und stabil sein (eine ID), damit Vue Elemente beim Verändern der Liste richtig zuordnet.","code":"<li v-for=\"aufgabe in aufgaben\" :key=\"aufgabe.id\">\n  {{ aufgabe.titel }}\n</li>","pitfall":"Den Listenindex als :key zu verwenden bringt bei Einfügen, Löschen oder Umsortieren falsche Zuordnung von Zustand und Fokus. IDs verwenden.","lesson":"js-m4-l5","tested":false},{"id":"vue-on","cat":"Template","term":"@click und Modifikatoren","syntax":"@click=\"funktion\"    @submit.prevent=\"senden\"","text":"@ ist die Kurzform von v-on und hängt Ereignisse an. Modifikatoren wie .prevent, .stop oder .enter (bei Tasten) vereinfachen die Behandlung.","code":"<form @submit.prevent=\"speichern\">\n  <input v-model.trim=\"name\">\n  <button type=\"submit\">Speichern</button>\n</form>","pitfall":"Auch in Vue gilt: Für klickbare Dinge <button> oder <a> verwenden, kein <div @click>, damit die Tastatur funktioniert.","lesson":"js-m1-l8","tested":false},{"id":"vue-model","cat":"Template","term":"v-model","syntax":"<input v-model=\"text\">","text":"Zweiwegebindung für Formularfelder: Der Wert fließt ins Feld, Eingaben zurück in die Variable. Modifikatoren: .trim, .number, .lazy.","code":"<label for=\"mail\">E-Mail</label>\n<input id=\"mail\" type=\"email\" v-model.trim=\"mail\">\n<p>{{ mail }}</p>","pitfall":"v-model.number liefert bei leerem oder ungültigem Feld wieder den Text zurück. Zahlen zusätzlich prüfen.","lesson":"js-m1-l10","tested":false},{"id":"vue-props","cat":"Komponenten","term":"defineProps","syntax":"const props = defineProps<{ titel: string }>()","text":"Deklariert, welche Eingaben eine Komponente von außen bekommt. Props fließen nur nach unten und werden in der Kindkomponente nicht verändert.","code":"const props = withDefaults(defineProps<{ titel: string; offen?: boolean }>(), {\n  offen: false,\n})","pitfall":"Props nicht direkt ändern. Stattdessen ein Ereignis (emit) senden oder defineModel nutzen.","lesson":"js-m1-l10","tested":false},{"id":"vue-emits","cat":"Komponenten","term":"defineEmits","syntax":"const emit = defineEmits<{ speichern: [name: string] }>()","text":"Deklariert die Ereignisse, die eine Komponente nach oben meldet. Der Elternteil hört mit @speichern=\"…\" zu.","code":"const emit = defineEmits<{ speichern: [name: string] }>()\nfunction fertig() {\n  emit('speichern', name.value)\n}","pitfall":"Ereignisnamen sind kein Ersatz für Daten. Sie melden, dass etwas passiert ist, und liefern nur die nötige Nutzlast mit.","lesson":"js-m1-l10","tested":false},{"id":"vue-definemodel","cat":"Komponenten","term":"defineModel","syntax":"const wert = defineModel<string>()","text":"Macht aus einer Komponente ein v-model-fähiges Feld. Die Variable verhält sich wie ein ref, Änderungen fließen automatisch zum Elternteil.","code":"<script setup lang=\"ts\">\nconst text = defineModel<string>({ required: true })\n</script>\n\n<template>\n  <input v-model=\"text\">\n</template>","pitfall":"Erfordert Vue 3.4 oder neuer. Für mehrere Werte benannte Modelle verwenden: defineModel('titel').","lesson":"js-m2-l1","tested":false},{"id":"vue-slots","cat":"Komponenten","term":"Slots","syntax":"<slot />    <template #name=\"props\">","text":"Slots reichen Inhalt von außen in eine Komponente hinein. Benannte Slots (#kopf) legen Bereiche fest, Scoped Slots geben Daten an den Aufrufer zurück.","code":"<!-- Karte.vue -->\n<section>\n  <header><slot name=\"kopf\" /></header>\n  <slot />\n</section>\n\n<!-- Verwendung -->\n<Karte>\n  <template #kopf>Titel</template>\n  Inhalt\n</Karte>","pitfall":"Slot-Inhalt gehört zum Elternteil und sieht nur dessen Variablen, nicht die der Komponente, außer sie werden als Scoped-Slot-Daten übergeben.","lesson":"js-m2-l3","tested":false},{"id":"vue-provide","cat":"Komponenten","term":"provide und inject","syntax":"provide('schluessel', wert)    const x = inject('schluessel')","text":"Reicht Werte über beliebig viele Ebenen nach unten, ohne sie als Props durchzureichen. Mit einem InjectionKey bleibt die Typisierung erhalten.","code":"// Eltern\nprovide(themeKey, theme)\n\n// beliebige Nachkommen\nconst theme = inject(themeKey)\nif (!theme) throw new Error('Theme-Provider fehlt')","pitfall":"inject liefert undefined, wenn kein provide existiert. Das fehlende Szenario ausdrücklich behandeln oder einen Fehler werfen.","lesson":"js-m2-l2","tested":false},{"id":"vue-lifecycle","cat":"Reaktivität","term":"onMounted und onUnmounted","syntax":"onMounted(() => …)","text":"Hooks, die in bestimmten Phasen der Komponente laufen: onMounted nach dem Einfügen in die Seite, onUnmounted vor dem Entfernen. Dort räumt man Timer, Listener und Abonnements auf.","code":"onMounted(() => {\n  window.addEventListener('resize', messen)\n})\nonUnmounted(() => {\n  window.removeEventListener('resize', messen)\n})","pitfall":"Nicht aufgeräumte Listener und Timer sammeln sich bei jedem Öffnen der Komponente an (Speicherleck).","lesson":"js-m1-l9","tested":false},{"id":"vue-composable","cat":"Struktur","term":"Composable","syntax":"function useXyz() { … return { … } }","text":"Eine Funktion mit Namen use…, die reaktiven Zustand und Logik bündelt und wiederverwendbar macht, zum Beispiel für Ladezustände einer API.","code":"export function useAufgaben() {\n  const daten = ref<Aufgabe[]>([])\n  const fehler = ref<string | null>(null)\n  const laedt = ref(false)\n  async function laden() { /* … */ }\n  return { daten, fehler, laedt, laden }\n}","pitfall":"Composables nur synchron im setup-Bereich aufrufen. Ein Aufruf nach einem await oder in einer Schleife verliert den Komponentenbezug.","lesson":"js-m1-l11","tested":false},{"id":"vue-router","cat":"Router und Pinia","term":"RouterLink und useRoute","syntax":"<RouterLink to=\"/pfad\">    const route = useRoute()","text":"RouterLink ist der Link innerhalb der App, ohne vollständiges Neuladen. useRoute liest Pfad, Parameter und Query, useRouter navigiert per Code.","code":"const route = useRoute()\nconst router = useRouter()\nconst id = computed(() => String(route.params.id))\nfunction zurueck() { router.push({ name: 'liste' }) }","pitfall":"Route-Parameter sind Text. Zahlen müssen umgewandelt und geprüft werden, und das Ganze am besten in computed, damit es bei Routenwechsel neu berechnet wird.","lesson":"js-m1-l12","tested":false},{"id":"vue-guard","cat":"Router und Pinia","term":"Navigation Guard","syntax":"router.beforeEach((to, from) => …)","text":"Läuft vor jedem Seitenwechsel. Man kann false oder einen Zielpfad zurückgeben, um die Navigation abzubrechen oder umzuleiten, etwa zur Anmeldung.","code":"router.beforeEach((to) => {\n  const auth = useAuthStore()\n  if (to.meta.requiresAuth && !auth.eingeloggt) {\n    return { name: 'login', query: { weiter: to.fullPath } }\n  }\n})","pitfall":"Ein Guard schützt nur die Oberfläche. Zugriff auf Daten muss der Server selbst prüfen.","lesson":"js-m4-l1","tested":false},{"id":"vue-pinia","cat":"Router und Pinia","term":"Pinia-Store","syntax":"export const useXStore = defineStore('x', () => { … })","text":"Gemeinsamer Zustand über Komponenten hinweg. Im Setup-Stil sind ref-Werte der State, computed-Werte die Getter und Funktionen die Aktionen.","code":"export const useZaehlerStore = defineStore('zaehler', () => {\n  const stand = ref(0)\n  const doppelt = computed(() => stand.value * 2)\n  function erhoehe() { stand.value++ }\n  return { stand, doppelt, erhoehe }\n})\n\n// in der Komponente\nconst store = useZaehlerStore()\nconst { stand } = storeToRefs(store)","pitfall":"Wer State oder Getter mit const { stand } = store herauslöst, verliert die Reaktivität. Dafür storeToRefs nehmen; Aktionen dürfen direkt vom Store kommen.","lesson":"js-m1-l13","tested":false},{"id":"vue-templateref","cat":"Komponenten","term":"useTemplateRef und useId","syntax":"const el = useTemplateRef('name')    const id = useId()","text":"useTemplateRef greift auf ein DOM-Element zu (z. B. für Fokus). useId erzeugt stabile eindeutige IDs für Label und Eingabefeld, auch bei Server-Rendering.","code":"<script setup lang=\"ts\">\nconst feld = useTemplateRef<HTMLInputElement>('feld')\nconst id = useId()\nonMounted(() => feld.value?.focus())\n</script>\n\n<template>\n  <label :for=\"id\">Name</label>\n  <input :id=\"id\" ref=\"feld\">\n</template>","pitfall":"Beide Funktionen sind ab Vue 3.5 verfügbar. Das Element ist erst nach dem Einfügen vorhanden, davor ist feld.value null.","lesson":"js-m4-l3","tested":false},{"id":"vue-zod","cat":"Daten","term":"Zod-Schema","syntax":"const Schema = z.object({ … })    Schema.safeParse(daten)","text":"Beschreibt die erwartete Form von Daten und prüft sie zur Laufzeit. Aus demselben Schema entsteht der TypeScript-Typ. safeParse liefert ein Ergebnisobjekt statt einer Ausnahme.","code":"const Nutzer = z.object({ name: z.string().min(2), alter: z.number().int().min(0) })\ntype Nutzer = z.infer<typeof Nutzer>\n\nconst ergebnis = Nutzer.safeParse(daten)\nif (!ergebnis.success) {\n  console.log(ergebnis.error.issues)\n}","pitfall":"Zod prüft die Struktur, nicht die Berechtigung. Daten vom Server sollten trotzdem am Server validiert werden.","lesson":"js-m3-l1","tested":false},{"id":"vue-query","cat":"Daten","term":"useQuery (TanStack Query)","syntax":"useQuery({ queryKey: [...], queryFn: … })","text":"Lädt Serverdaten, speichert sie in einem Cache und liefert reaktiv data, error und isPending. Der queryKey identifiziert die Daten, bei Änderung wird neu geladen.","code":"const { data, error, isPending } = useQuery({\n  queryKey: ['aufgaben', seite],\n  queryFn: () => ladeAufgaben(seite.value),\n})","pitfall":"Alle Werte, von denen die Anfrage abhängt, gehören in den queryKey. Sonst zeigt der Cache falsche Daten.","lesson":"js-m3-l2","tested":false},{"id":"vue-html-xss","cat":"Template","term":"v-html und Sicherheit (XSS)","syntax":"<div v-html=\"htmlText\"></div>","text":"v-html setzt Text als rohes HTML ein. Das ist die einzige Stelle im Template, an der Vue nicht automatisch maskiert, und damit ein Einfallstor für Cross-Site-Scripting, wenn der Text von Nutzern stammt.","code":"<!-- sicher: Vue maskiert den Text -->\n<p>{{ kommentar }}</p>\n\n<!-- nur mit bereinigtem HTML verwenden -->\n<div v-html=\"sauber\"></div>\n\n<script setup>\nimport DOMPurify from \"dompurify\";\nimport { computed } from \"vue\";\nconst props = defineProps({ roh: String });\nconst sauber = computed(() => DOMPurify.sanitize(props.roh ?? \"\"));\n</script>","pitfall":"Nie Nutzereingaben ungeprüft in v-html. Auch „vertrauenswürdige“ Quellen (CMS, Markdown) vorher mit einer Bereinigungsbibliothek filtern.","lesson":"js-m1-l8","tested":false},{"id":"vue-for-variants","cat":"Template","term":"v-for über Objekte, Bereiche und mit v-if","syntax":"v-for=\"(wert, schluessel, index) in objekt\"    v-for=\"n in 5\"    <template v-for>","text":"v-for läuft auch über Objekte (Wert, Schlüssel, Index) und Zahlen (1 bis n). Für mehrere Elemente je Durchlauf verwendet man <template v-for>. v-if und v-for nie auf demselben Element kombinieren, weil v-if zuerst gilt.","code":"<ul>\n  <li v-for=\"(wert, schluessel) in nutzer\" :key=\"schluessel\">{{ schluessel }}: {{ wert }}</li>\n</ul>\n<span v-for=\"n in 5\" :key=\"n\">{{ n }} </span>\n\n<template v-for=\"aufgabe in aufgaben\" :key=\"aufgabe.id\">\n  <h3>{{ aufgabe.titel }}</h3>\n  <p v-if=\"aufgabe.notiz\">{{ aufgabe.notiz }}</p>\n</template>\n\n<!-- besser: vorher filtern -->\n<li v-for=\"a in offeneAufgaben\" :key=\"a.id\">{{ a.titel }}</li>","pitfall":"Der :key muss eindeutig und stabil sein (ID), nicht der Index, sonst werden Eingaben beim Umsortieren falschen Zeilen zugeordnet.","lesson":"js-m4-l5","tested":false},{"id":"vue-defaults-destructure","cat":"Komponenten","term":"Props mit Standardwerten und Destructuring (3.5)","syntax":"const { titel = \"Ohne Titel\" } = defineProps<{ titel?: string }>()    withDefaults(defineProps<…>(), { … })","text":"Seit Vue 3.5 darf man Props direkt destrukturieren und mit Standardwerten versehen. Die Variablen bleiben reaktiv, weil der Compiler sie in props.x umschreibt. Älter und weiterhin gültig: withDefaults.","code":"<script setup lang=\"ts\">\nconst { titel = \"Ohne Titel\", anzahl = 0 } = defineProps<{ titel?: string; anzahl?: number }>();\n\n// oder ältere Schreibweise\n// const props = withDefaults(defineProps<{ titel?: string }>(), { titel: \"Ohne Titel\" });\n</script>\n\n<template><h2>{{ titel }} ({{ anzahl }})</h2></template>","pitfall":"Props nie in der Komponente verändern (Daten fließen nach unten). Für Änderungen ein Event (emit) oder defineModel verwenden. Standardwerte für Objekte als Funktion angeben.","lesson":"js-m1-l10","tested":false},{"id":"vue-typed-emits","cat":"Komponenten","term":"Typisierte Props und Emits (TypeScript)","syntax":"defineProps<{ x: string }>()    defineEmits<{ speichern: [id: number]; abbrechen: [] }>()","text":"In TypeScript beschreibt man Props und Emits als Typ. Bei defineEmits steht je Ereignis ein Tupel mit den Parametern. So prüft der Editor, dass Eltern- und Kindkomponente zusammenpassen.","code":"<script setup lang=\"ts\">\ninterface Nutzer { id: number; name: string }\nconst props = defineProps<{ nutzer: Nutzer; aktiv?: boolean }>();\nconst emit = defineEmits<{\n  speichern: [id: number];\n  abbrechen: [];\n}>();\n</script>\n\n<template>\n  <button type=\"button\" @click=\"emit('speichern', props.nutzer.id)\">Speichern</button>\n</template>","pitfall":"Typen prüfen nur zur Entwicklungszeit (vue-tsc). Daten von außen (API, Formular) zusätzlich zur Laufzeit validieren, zum Beispiel mit Zod.","lesson":"js-m1-l10","tested":false},{"id":"vue-watch-options","cat":"Reaktivität","term":"watch: immediate, deep, once, onWatcherCleanup","syntax":"watch(quelle, (neu, alt) => …, { immediate: true, deep: true, once: true })","text":"immediate führt den Watcher sofort aus, deep beobachtet auch verschachtelte Änderungen, once nur einmal. Mit onWatcherCleanup (3.5) räumt man vor dem nächsten Lauf auf, zum Beispiel eine laufende Anfrage abbrechen.","code":"import { ref, watch, onWatcherCleanup } from \"vue\";\n\nconst suche = ref(\"\");\nconst treffer = ref([]);\n\nwatch(suche, async (text) => {\n  const abbruch = new AbortController();\n  onWatcherCleanup(() => abbruch.abort());\n  if (!text) { treffer.value = []; return; }\n  const antwort = await fetch(`/api/suche?q=${encodeURIComponent(text)}`, { signal: abbruch.signal });\n  treffer.value = await antwort.json();\n}, { immediate: false });","pitfall":"Für abgeleitete Werte computed verwenden, nicht watch. Watcher sind für Nebenwirkungen (Anfragen, Speichern). deep auf großen Objekten ist teuer.","lesson":"js-m1-l9","tested":false},{"id":"vue-computed-writable","cat":"Reaktivität","term":"computed mit Getter und Setter","syntax":"computed({ get: () => …, set: (wert) => … })","text":"Ein beschreibbares computed liest einen berechneten Wert und schreibt Änderungen zurück an die Quelle. Praktisch für v-model auf abgeleiteten Werten, zum Beispiel Vor- und Nachname aus einem Gesamtnamen.","code":"import { ref, computed } from \"vue\";\n\nconst vorname = ref(\"Mia\");\nconst nachname = ref(\"Muster\");\nconst vollerName = computed({\n  get: () => `${vorname.value} ${nachname.value}`,\n  set: (wert) => {\n    [vorname.value, nachname.value] = wert.split(\" \");\n  }\n});\nvollerName.value = \"Ada Lovelace\";","pitfall":"Der Getter darf keine Nebenwirkungen haben. Der Setter ist der Ort, an dem die Quelle geändert wird.","lesson":"js-m1-l9","tested":false},{"id":"vue-readonly-raw","cat":"Reaktivität","term":"readonly, toRaw und markRaw","syntax":"readonly(objekt)    toRaw(proxy)    markRaw(objekt)","text":"readonly gibt eine schreibgeschützte Sicht auf ein reaktives Objekt weiter (Zustand sicher teilen). toRaw liefert das Original hinter dem Proxy. markRaw macht ein Objekt (große Bibliotheksinstanz, Karte, Diagramm) nie reaktiv.","code":"import { reactive, readonly, toRaw, markRaw } from \"vue\";\n\nconst zustand = reactive({ stand: 0 });\nconst nurLesen = readonly(zustand);   // nurLesen.stand = 1 → Warnung\nconst original = toRaw(zustand);\n\nconst karte = markRaw(new MeineKarte());   // kein Proxy, schneller\nzustand.karte = karte;","pitfall":"markRaw-Objekte lösen bei Änderungen keine Aktualisierung aus. Nur für Objekte verwenden, deren innere Änderungen die Oberfläche nicht betreffen.","lesson":"js-m4-l4","tested":false},{"id":"vue-lifecycle-all","cat":"Reaktivität","term":"Lebenszyklus: onBeforeMount bis onErrorCaptured","syntax":"onBeforeMount  onMounted  onBeforeUpdate  onUpdated  onBeforeUnmount  onUnmounted  onErrorCaptured","text":"Hooks laufen in dieser Reihenfolge: setup, onBeforeMount, onMounted (DOM ist da), bei Änderungen onBeforeUpdate und onUpdated, am Ende onBeforeUnmount und onUnmounted (Aufräumen). onErrorCaptured fängt Fehler von Kindkomponenten ab.","code":"import { onMounted, onBeforeUnmount, onErrorCaptured, ref } from \"vue\";\n\nconst fehler = ref(null);\nlet timer;\n\nonMounted(() => { timer = setInterval(aktualisiere, 5000); });\nonBeforeUnmount(() => clearInterval(timer));\nonErrorCaptured((err) => {\n  fehler.value = \"Etwas ist schiefgelaufen.\";\n  return false;   // Fehler nicht weiter nach oben melden\n});","pitfall":"Timer, Event-Listener und Abonnements immer in onBeforeUnmount oder onUnmounted entfernen, sonst entstehen Speicherlecks.","lesson":"js-m1-l9","tested":false},{"id":"vue-error-handler","cat":"Struktur","term":"app.config.errorHandler und Plugins (app.use)","syntax":"app.config.errorHandler = (err, instance, info) => …    app.use(plugin, optionen)    app.provide(key, wert)","text":"errorHandler fängt alle nicht behandelten Fehler der App ab (zum Beispiel für Protokollierung). Ein Plugin ist ein Objekt mit install oder eine Funktion, die die App erweitert, etwa Router, Pinia oder eigene Bausteine.","code":"import { createApp } from \"vue\";\nimport { createPinia } from \"pinia\";\nimport App from \"./App.vue\";\nimport router from \"./router\";\n\nconst app = createApp(App);\napp.config.errorHandler = (fehler, instanz, info) => {\n  console.error(\"Vue-Fehler:\", info, fehler);\n  // an eigenes Protokollsystem melden, ohne personenbezogene Daten\n};\napp.use(createPinia()).use(router);\napp.provide(\"appName\", \"Rootpfad\");\napp.mount(\"#app\");","pitfall":"Fehlermeldungen an externe Dienste können personenbezogene Daten enthalten. Vor dem Senden prüfen, einwilligungspflichtige Dienste nur mit Zustimmung.","lesson":"js-m1-l8","tested":false},{"id":"vue-directive","cat":"Struktur","term":"Eigene Direktive (v-fokus)","syntax":"const vFokus = { mounted: (el) => el.focus() }    <input v-fokus>","text":"Direktiven kapseln direkten DOM-Zugriff, der sich nicht als Komponente lösen lässt (Fokus, Klick außerhalb, Größenbeobachtung). In <script setup> wird jede Variable mit v-Präfix automatisch zur Direktive.","code":"<script setup>\nconst vFokus = {\n  mounted: (el) => el.focus(),\n};\nconst vKlickAussen = {\n  mounted(el, binding) {\n    el._aussen = (e) => { if (!el.contains(e.target)) binding.value(e); };\n    document.addEventListener(\"click\", el._aussen);\n  },\n  unmounted(el) { document.removeEventListener(\"click\", el._aussen); },\n};\n</script>\n\n<template>\n  <input v-fokus aria-label=\"Suche\">\n  <div v-klick-aussen=\"schliesse\">Menü</div>\n</template>","pitfall":"Automatischer Fokus (autofocus) kann Screenreader-Nutzer verwirren. Nur bei Dialogen und nach Aktionen setzen, nicht beim Laden einer Seite.","lesson":"js-m4-l3","tested":false},{"id":"vue-memo-once","cat":"Template","term":"v-once und v-memo","syntax":"<div v-once>    <li v-memo=\"[a, b]\">","text":"v-once rendert ein Element nur einmal, danach nie wieder. v-memo überspringt das Neuberechnen eines Teilbaums, solange die angegebenen Werte gleich bleiben. Das sind Feinoptimierungen für sehr lange Listen.","code":"<p v-once>Erstellt am {{ datum }}</p>\n\n<ul>\n  <li v-for=\"zeile in zeilen\" :key=\"zeile.id\" v-memo=\"[zeile.id === ausgewaehlt]\">\n    {{ zeile.name }}\n  </li>\n</ul>","pitfall":"Zuerst messen (Vue DevTools), dann optimieren. In den meisten Anwendungen sind diese Direktiven unnötig und verstecken veraltete Anzeigen.","lesson":"js-m4-l5","tested":false},{"id":"vue-router-navigation","cat":"Router und Pinia","term":"useRouter: push, replace, params, query","syntax":"router.push({ name: \"nutzer\", params: { id }, query: { tab } })    router.replace(…)    router.back()","text":"useRouter() liefert den Router für Navigation im Code. push legt einen neuen Verlaufseintrag an, replace ersetzt den aktuellen, back geht zurück. Parameter stehen im Pfad (params), optionale Werte in der Adresse (query).","code":"import { useRoute, useRouter } from \"vue-router\";\n\nconst router = useRouter();\nconst route = useRoute();\n\nfunction oeffneNutzer(id) {\n  router.push({ name: \"nutzer\", params: { id }, query: { tab: \"info\" } });\n}\nconst aktuelleId = route.params.id;\nconst tab = route.query.tab ?? \"info\";\n\n// Route mit props: true\n{ path: \"/nutzer/:id\", name: \"nutzer\", component: NutzerSeite, props: true }","pitfall":"Werte aus params und query sind immer Text und Benutzereingaben. Vor der Verwendung umwandeln und prüfen. Nach dem Anmelden replace statt push, damit „Zurück“ nicht zur Anmeldeseite führt.","lesson":"js-m1-l12","tested":false},{"id":"vue-store-to-refs","cat":"Router und Pinia","term":"storeToRefs und Setup-Store","syntax":"const { liste } = storeToRefs(store)    defineStore(\"x\", () => { … })","text":"Beim Destrukturieren eines Stores gehen State und Getter ihre Reaktivität verloren. storeToRefs macht daraus Refs. Aktionen (Funktionen) darf man direkt entnehmen. Ein Setup-Store ist wie eine Composition-API-Funktion geschrieben.","code":"import { defineStore, storeToRefs } from \"pinia\";\nimport { ref, computed } from \"vue\";\n\nexport const useWarenkorb = defineStore(\"warenkorb\", () => {\n  const positionen = ref([]);\n  const summe = computed(() => positionen.value.reduce((s, p) => s + p.preis * p.menge, 0));\n  function hinzufuegen(artikel) { positionen.value.push({ ...artikel, menge: 1 }); }\n  return { positionen, summe, hinzufuegen };\n});\n\n// in der Komponente\nconst store = useWarenkorb();\nconst { positionen, summe } = storeToRefs(store);\nconst { hinzufuegen } = store;","pitfall":"Im Setup-Store muss alles, was nach außen sichtbar sein soll, aus der Funktion zurückgegeben werden, sonst fehlt es im Store.","lesson":"js-m1-l13","tested":false},{"id":"vue-create-vite","cat":"Struktur","term":"Projekt anlegen und starten (create-vue, Vite)","syntax":"npm create vue@latest    npm run dev    npm run build    npm run preview","text":"create-vue erstellt ein Projekt mit Vite als Entwicklungsserver und Build-Werkzeug. Der Assistent fragt nach TypeScript, Router, Pinia, Vitest und Linter. dev startet mit sofortigem Neuladen, build erzeugt die Auslieferung, preview zeigt sie lokal.","code":"npm create vue@latest\ncd mein-projekt\nnpm install\nnpm run dev\nnpm run build\nnpm run preview\nnpm run test:unit\nnpm run type-check","pitfall":"Umgebungsvariablen mit VITE_ sind im Browser sichtbar. Dort keine Schlüssel oder Passwörter ablegen. Geheimnisse gehören auf den Server.","lesson":"js-m1-l8","tested":false},{"id":"vue-env-vite","cat":"Struktur","term":"import.meta.env und .env-Dateien (Vite)","syntax":"import.meta.env.VITE_API_URL    .env  .env.production","text":"Vite liest Einstellungen aus .env-Dateien und stellt Werte mit dem Präfix VITE_ über import.meta.env bereit. Je nach Modus (development, production) greift die passende Datei. Beim Build werden die Werte fest in den Code eingesetzt.","code":"# .env.production (nicht für Geheimnisse!)\nVITE_API_URL=https://api.example.org\n\n// im Code\nconst basis = import.meta.env.VITE_API_URL;\nif (import.meta.env.DEV) console.debug(\"Entwicklungsmodus\");\nconst antwort = await fetch(`${basis}/aufgaben`);","pitfall":".env mit echten Zugangsdaten nie committen (.gitignore). Alles mit VITE_ landet im ausgelieferten JavaScript und ist für jeden lesbar.","lesson":"js-m1-l8","tested":false},{"id":"vue-class-style","cat":"Template","term":":class und :style","syntax":":class=\"{ aktiv: istAktiv }\"    :style=\"{ color: farbe }\"","text":"Bindet CSS-Klassen und Inline-Stile an Daten. Ein Objekt schaltet Klassen ein und aus, ein Array kombiniert mehrere. Statische und gebundene Klassen lassen sich mischen.","code":"<button class=\"knopf\" :class=\"{ aktiv: gewaehlt, gesperrt: laeuft }\" :aria-pressed=\"gewaehlt\">\n  {{ titel }}\n</button>","pitfall":"Zustände, die für Screenreader wichtig sind (gedrückt, gewählt), zusätzlich als Attribut (aria-pressed, aria-current) setzen. Eine Klasse allein ist nur optisch.","lesson":"js-m1-l8","tested":false},{"id":"vue-component-is","cat":"Template","term":"<component :is> und <KeepAlive>","syntax":"<component :is=\"aktuell\" />    <KeepAlive>…</KeepAlive>","text":"Zeigt dynamisch eine Komponente an. KeepAlive behält den Zustand ausgeblendeter Komponenten, etwa Eingaben in einem Tab, der gerade nicht sichtbar ist.","code":"<script setup lang=\"ts\">\nimport TabA from './TabA.vue'\nimport TabB from './TabB.vue'\nconst tabs = { a: TabA, b: TabB } as const\nconst aktuell = ref<keyof typeof tabs>('a')\n</script>\n\n<template>\n  <KeepAlive>\n    <component :is=\"tabs[aktuell]\" />\n  </KeepAlive>\n</template>","pitfall":"KeepAlive hält Komponenten im Speicher. Mit :max begrenzen. Aufräumen in onDeactivated statt onUnmounted.","lesson":"js-m2-l3","tested":false},{"id":"vue-expose","cat":"Komponenten","term":"defineExpose und Template Refs","syntax":"defineExpose({ fokussieren })    const kind = useTemplateRef(\"kind\")","text":"Komponenten mit <script setup> sind nach außen geschlossen. Was der Elternteil per Template Ref aufrufen darf, muss mit defineExpose ausdrücklich freigegeben werden.","code":"<!-- Eingabe.vue -->\n<script setup lang=\"ts\">\nconst feld = useTemplateRef<HTMLInputElement>('feld')\nfunction fokussieren() { feld.value?.focus() }\ndefineExpose({ fokussieren })\n</script>\n<template><input ref=\"feld\"></template>\n\n<!-- Elternteil -->\n<Eingabe ref=\"eingabe\" />\n<button @click=\"eingabe?.fokussieren()\">Zum Feld</button>","pitfall":"defineExpose bewusst klein halten. Wer viel freigibt, koppelt Eltern und Kind eng, besser sind Props und Ereignisse.","lesson":"js-m4-l3","tested":false},{"id":"vue-attrs","cat":"Komponenten","term":"inheritAttrs und $attrs","syntax":"defineOptions({ inheritAttrs: false })    <input v-bind=\"$attrs\">","text":"Attribute, die nicht als Props deklariert sind (class, aria-label, data-…), fallen automatisch auf das Wurzelelement. Mit inheritAttrs: false und v-bind=\"$attrs\" leitet man sie gezielt an ein inneres Element weiter.","code":"<script setup lang=\"ts\">\ndefineOptions({ inheritAttrs: false })\nconst props = defineProps<{ label: string }>()\nconst id = useId()\n</script>\n\n<template>\n  <div class=\"feld\">\n    <label :for=\"id\">{{ props.label }}</label>\n    <input :id=\"id\" v-bind=\"$attrs\">\n  </div>\n</template>","pitfall":"Bei Komponenten mit mehreren Wurzelelementen warnt Vue, weil unklar ist, wohin die Attribute gehören. Dann $attrs selbst verteilen.","lesson":"js-m1-l10","tested":false},{"id":"vue-teleport","cat":"Komponenten","term":"Teleport","syntax":"<Teleport to=\"body\">…</Teleport>","text":"Rendert einen Teil des Templates an anderer Stelle im DOM, etwa Modale oder Hinweise direkt unter body, ohne dass CSS der Elternelemente (overflow, z-index) stört.","code":"<template>\n  <button @click=\"offen = true\">Öffnen</button>\n  <Teleport to=\"body\">\n    <dialog ref=\"dlg\" aria-labelledby=\"titel\">\n      <h2 id=\"titel\">Titel</h2>\n    </dialog>\n  </Teleport>\n</template>","pitfall":"Das Ziel muss beim Einhängen schon existieren. Der Fokus muss beim Öffnen in den Dialog und beim Schließen zurück zum Auslöser wandern. Das native <dialog> erledigt das.","lesson":"js-m2-l4","tested":false},{"id":"vue-suspense","cat":"Komponenten","term":"defineAsyncComponent und Suspense","syntax":"const Schwer = defineAsyncComponent(() => import('./Schwer.vue'))","text":"Lädt eine Komponente erst bei Bedarf (kleineres Startbündel). <Suspense> zeigt einen Platzhalter, solange asynchrone Abhängigkeiten laden. Suspense ist laut Vue-Dokumentation weiterhin experimentell.","code":"const Diagramm = defineAsyncComponent(() => import('./Diagramm.vue'))\n\n<!-- Template -->\n<Suspense>\n  <Diagramm />\n  <template #fallback>Lädt …</template>\n</Suspense>","pitfall":"Ladefehler brauchen eine eigene Behandlung (onErrorCaptured oder errorComponent), sonst bleibt der Platzhalter stehen.","lesson":"js-m2-l5","tested":false},{"id":"vue-transition","cat":"Template","term":"Transition und TransitionGroup","syntax":"<Transition name=\"fade\">…</Transition>","text":"Animiert das Ein- und Ausblenden von Elementen mit CSS-Klassen (name-enter-active, name-leave-to …). TransitionGroup animiert Listen. Bewegung muss reduzierbar sein.","code":"<Transition name=\"fade\">\n  <p v-if=\"sichtbar\">Hallo</p>\n</Transition>\n\n<style>\n.fade-enter-active, .fade-leave-active { transition: opacity .2s; }\n.fade-enter-from, .fade-leave-to { opacity: 0; }\n@media (prefers-reduced-motion: reduce) {\n  .fade-enter-active, .fade-leave-active { transition: none; }\n}\n</style>","pitfall":"Transition erwartet genau ein Element als Kind. Für Wechsel mehrerer Elemente den Modus mode=\"out-in\" setzen.","lesson":"js-m2-l6","tested":false},{"id":"vue-nexttick","cat":"Reaktivität","term":"nextTick und flush","syntax":"await nextTick()    watch(…, { flush: \"post\" })","text":"Änderungen an Daten wirken im DOM erst im nächsten Aktualisierungszyklus. nextTick wartet darauf, dann kann man neu entstandene Elemente lesen oder fokussieren.","code":"async function hinzufuegen() {\n  eintraege.value.push({ id: naechsteId++, text: '' })\n  await nextTick()\n  letztesFeld.value?.focus()\n}","pitfall":"Direkt nach der Änderung existiert das neue Element noch nicht. Ohne nextTick läuft der Fokus ins Leere.","lesson":"js-m4-l5","tested":false},{"id":"vue-shallow","cat":"Reaktivität","term":"shallowRef, toRef, toRefs","syntax":"shallowRef(großesObjekt)    toRefs(props)    toRef(obj, \"feld\")","text":"shallowRef beobachtet nur den Austausch des Werts, nicht jede innere Änderung (günstig bei großen Datenmengen). toRef und toRefs erzeugen Refs, die mit einem reaktiven Objekt verbunden bleiben.","code":"const props = defineProps<{ seite: number }>()\nconst { seite } = toRefs(props)\nwatch(seite, laden)\n\nconst tabelle = shallowRef<Zeile[]>([])\ntabelle.value = neueZeilen   // löst Aktualisierung aus\ntabelle.value.push(zeile)    // löst NICHT aus","pitfall":"Seit Vue 3.5 bleibt destrukturiertes defineProps im <script setup> reaktiv, in älteren Versionen nicht. Version prüfen.","lesson":"js-m4-l4","tested":false},{"id":"vue-route-meta","cat":"Router und Pinia","term":"Routen mit meta und Lazy Loading","syntax":"{ path: '/admin', component: () => import('./Admin.vue'), meta: { requiresAuth: true } }","text":"Routen werden als Objekte beschrieben. Mit () => import(…) lädt jede Seite erst beim Aufruf. meta trägt eigene Angaben (Rolle, Titel), die Guards auswerten.","code":"const routes = [\n  { path: '/', name: 'start', component: () => import('./views/Start.vue') },\n  { path: '/aufgaben/:id(\\\\d+)', name: 'aufgabe', component: () => import('./views/Aufgabe.vue'), props: true },\n  { path: '/admin', component: () => import('./views/Admin.vue'), meta: { requiresAuth: true, rolle: 'admin' } },\n  { path: '/:pathMatch(.*)*', name: 'nicht-gefunden', component: () => import('./views/NichtGefunden.vue') },\n]","pitfall":"Nach einem Seitenwechsel muss der Fokus auf die neue Seite (Überschrift) gesetzt und der Seitentitel angepasst werden, sonst merkt ein Screenreader den Wechsel nicht.","lesson":"js-m1-l12","tested":false},{"id":"vue-pinia-patch","cat":"Router und Pinia","term":"Pinia: $patch, $reset und Plugins","syntax":"store.$patch({ … })    store.$reset()    store.$subscribe(…)","text":"$patch ändert mehrere Felder in einem Schritt, $reset stellt den Anfangszustand wieder her (bei Setup-Stores selbst zu schreiben), $subscribe beobachtet Änderungen, etwa zum Speichern.","code":"const store = useEinstellungenStore()\nstore.$patch({ sprache: 'de', dunkel: true })\nstore.$subscribe((_mutation, state) => {\n  localStorage.setItem('einstellungen', JSON.stringify(state))\n})","pitfall":"localStorage ist für jedes Skript der Seite lesbar. Nie Tokens oder Geheimnisse dort speichern. Zugriffe in try/catch setzen.","lesson":"js-m1-l13","tested":false},{"id":"vue-mutation","cat":"Daten","term":"useMutation mit optimistischem Update","syntax":"useMutation({ mutationFn, onMutate, onError, onSettled })","text":"Schreibt Daten zum Server. Ein optimistisches Update zeigt die Änderung sofort an und rollt sie zurück, wenn der Server ablehnt. onSettled lädt zum Schluss die echten Daten neu.","code":"const client = useQueryClient()\nconst abhaken = useMutation({\n  mutationFn: (id: number) => api.erledigt(id),\n  onMutate: async (id) => {\n    await client.cancelQueries({ queryKey: ['aufgaben'] })\n    const vorher = client.getQueryData<Aufgabe[]>(['aufgaben'])\n    client.setQueryData<Aufgabe[]>(['aufgaben'], (a) => a?.map((x) => x.id === id ? { ...x, erledigt: true } : x))\n    return { vorher }\n  },\n  onError: (_e, _id, ctx) => client.setQueryData(['aufgaben'], ctx?.vorher),\n  onSettled: () => client.invalidateQueries({ queryKey: ['aufgaben'] }),\n})","pitfall":"Ohne Rollback und ohne Fehlermeldung wirkt ein fehlgeschlagenes Speichern wie ein Erfolg. Fehler immer sichtbar machen (role=\"alert\").","lesson":"js-m3-l3","tested":false},{"id":"vue-test","cat":"Struktur","term":"Komponententest mit Vitest","syntax":"mount(Komponente, { props })    await wrapper.find('button').trigger('click')","text":"Vue Test Utils mountet eine Komponente im Test, find sucht Elemente, trigger löst Ereignisse aus, emitted() prüft gesendete Ereignisse. Besser Verhalten prüfen statt interner Details.","code":"import { mount } from '@vue/test-utils'\nimport { expect, it } from 'vitest'\nimport Zaehler from './Zaehler.vue'\n\nit('erhöht den Zähler bei Klick', async () => {\n  const wrapper = mount(Zaehler)\n  await wrapper.get('button').trigger('click')\n  expect(wrapper.text()).toContain('1')\n})","pitfall":"Auf await vor trigger nicht verzichten, das DOM aktualisiert sich asynchron. Nach Rollen und sichtbarem Text suchen statt nach CSS-Klassen.","lesson":"js-m1-l14","tested":false},{"id":"vue-generic","cat":"Komponenten","term":"Generische Komponenten und defineSlots","syntax":"<script setup lang=\"ts\" generic=\"T extends { id: number }\">","text":"Komponenten, die mit verschiedenen Datentypen arbeiten, tragen einen Typparameter. defineSlots beschreibt, welche Daten ein Scoped Slot liefert, so prüft TypeScript die Verwendung.","code":"<script setup lang=\"ts\" generic=\"T extends { id: number }\">\ndefineProps<{ eintraege: T[] }>()\ndefineSlots<{ default(props: { eintrag: T }): unknown }>()\n</script>\n\n<template>\n  <ul>\n    <li v-for=\"e in eintraege\" :key=\"e.id\"><slot :eintrag=\"e\" /></li>\n  </ul>\n</template>","pitfall":"Ohne :key mit stabiler ID gerät bei Änderungen der Zustand der Zeilen durcheinander. Den Typparameter durch eine Einschränkung (extends) sichern.","lesson":"js-m2-l7","tested":false}]},{"id":"php","label":"PHP","codeLang":"php","intro":"Serverseitige Sprache für Webanwendungen. Variablen beginnen mit $, Anweisungen enden mit Semikolon.","notice":"Die meisten Beispiele sind mit PHP 8.5 ausgeführt und geprüft. Beispiele ohne Markierung (z. B. Namespaces) werden nur gezeigt.","runner":"PHP","entries":[{"id":"php-tag","cat":"Grundlagen","term":"<?php … ?>","syntax":"<?php\ndeclare(strict_types=1);","text":"Der PHP-Block beginnt mit <?php. In reinen PHP-Dateien wird das schließende ?> weggelassen. declare(strict_types=1) macht die Typprüfung bei Funktionsaufrufen streng.","code":"declare(strict_types=1);\necho 'läuft', PHP_EOL;","out":"läuft","pitfall":"Ein ?> am Dateiende mit Leerzeichen oder Zeilenumbruch dahinter erzeugt unerwünschte Ausgabe, bevor Header gesendet werden.","lesson":"m52-l1","tested":true},{"id":"php-echo","cat":"Grundlagen","term":"echo und print_r / var_dump","syntax":"echo $text;    var_dump($wert);","text":"echo gibt Text aus. var_dump zeigt Typ und Wert, print_r ist die lesbare Kurzform für Arrays. Beide dienen dem Debuggen.","code":"$a = ['x' => 1];\necho 'Wert: ', $a['x'], PHP_EOL;\nvar_dump(1.5, 'a', true);","out":"Wert: 1\nfloat(1.5)\nstring(1) \"a\"\nbool(true)","pitfall":"Ausgaben aus dem Browser immer mit htmlspecialchars() maskieren, sonst droht Cross-Site-Scripting.","lesson":"m52-l2","tested":true},{"id":"php-variable","cat":"Variablen und Typen","term":"Variable","syntax":"$name = wert;","text":"Variablen beginnen mit $ und brauchen keine Typdeklaration. Groß- und Kleinschreibung zählt. Konstanten legt man mit const oder define an.","code":"$preis = 19.99;\nconst STEUER = 0.19;\necho round($preis * (1 + STEUER), 2), PHP_EOL;","out":"23.79","pitfall":"Eine nicht gesetzte Variable erzeugt eine Warnung. Vorher mit isset() prüfen oder einen Standardwert verwenden.","lesson":"m42-l2","tested":true},{"id":"php-types","cat":"Variablen und Typen","term":"Typen und Vergleiche","syntax":"$a === $b    $a == $b","text":"Skalare Typen sind int, float, string und bool. === vergleicht Wert und Typ, == wandelt vorher um und liefert dadurch Überraschungen.","code":"var_dump(0 == 'a', '1' == '01', '10' == '1e1', 100 == '1e2', 1 === '1');","out":"bool(false)\nbool(true)\nbool(true)\nbool(true)\nbool(false)","pitfall":"Immer === verwenden. Auch seit PHP 8 sind „1“ == „01“ und „10“ == „1e1“ wahr, weil numerische Strings als Zahlen verglichen werden.","lesson":"m42-l2","tested":true},{"id":"php-string","cat":"Strings","term":"Strings und Verkettung","syntax":"'einfach'    \"doppelt $variable\"    $a . $b","text":"In einfachen Anführungszeichen steht der Text wörtlich, in doppelten werden Variablen eingesetzt. Der Punkt verkettet Strings.","code":"$name = 'Ada';\necho \"Hallo $name\", PHP_EOL;\necho 'Hallo ' . $name . '!', PHP_EOL;\necho strlen('Haus'), ' ', strtoupper('abc'), ' ', str_contains('Werkstatt', 'stat') ? 'ja' : 'nein', PHP_EOL;","out":"Hallo Ada\nHallo Ada!\n4 ABC ja","pitfall":"strlen zählt Bytes. Bei Umlauten liefert mb_strlen() die Anzahl der Zeichen.","lesson":"m52-l2","tested":true},{"id":"php-if","cat":"Kontrollfluss","term":"if / elseif / else","syntax":"if (bedingung) { … } elseif (…) { … } else { … }","text":"Führt einen Block nur aus, wenn die Bedingung wahr ist. Falsch sind false, 0, \"\", \"0\", null und leere Arrays.","code":"$punkte = 72;\nif ($punkte >= 90) {\n    echo 'sehr gut';\n} elseif ($punkte >= 70) {\n    echo 'gut';\n} else {\n    echo 'weiter üben';\n}","out":"gut","pitfall":"Die Zeichenkette \"0\" gilt als falsch. Bei Formulareingaben deshalb nicht nur if ($wert) prüfen, sondern gezielt auf null und \"\".","lesson":"m52-l4","tested":true},{"id":"php-match","cat":"Kontrollfluss","term":"match","syntax":"match ($wert) { a => x, b, c => y, default => z }","text":"Wie switch, aber als Ausdruck mit Rückgabewert, strengem Vergleich und ohne Durchfallen. Wird kein Fall getroffen und gibt es kein default, wirft PHP einen UnhandledMatchError.","code":"$status = 404;\n$text = match ($status) {\n    200 => 'OK',\n    404, 410 => 'Nicht gefunden',\n    default => 'Unbekannt',\n};\necho $text;","out":"Nicht gefunden","pitfall":"match vergleicht strikt: die Zahl 404 passt nicht auf den Text \"404\".","lesson":"m52-l4","tested":true},{"id":"php-ternary","cat":"Kontrollfluss","term":"?: und ??","syntax":"$a ?: $b    $a ?? $b","text":"?? liefert den rechten Wert, wenn links null ist oder nicht existiert, ohne Warnung. ?: nimmt den rechten Wert, wenn links falsch ist.","code":"$eingabe = ['name' => ''];\necho $eingabe['alter'] ?? 'unbekannt', PHP_EOL;\necho $eingabe['name'] ?: 'ohne Namen', PHP_EOL;","out":"unbekannt\nohne Namen","pitfall":"?? ist die richtige Wahl für „Schlüssel fehlt“, ?: für „leer oder falsy“. Beides nicht verwechseln.","lesson":"m52-l4","tested":true},{"id":"php-foreach","cat":"Schleifen","term":"foreach","syntax":"foreach ($liste as $schluessel => $wert) { … }","text":"Läuft über alle Elemente eines Arrays. Mit $schluessel => $wert steht auch der Schlüssel zur Verfügung.","code":"foreach (['a' => 1, 'b' => 2] as $k => $v) {\n    echo \"$k=$v \";\n}","out":"a=1 b=2","pitfall":"Mit foreach ($liste as &$x) bleibt $x nach der Schleife eine Referenz auf das letzte Element. Danach unset($x) aufrufen.","lesson":"m52-l5","tested":true},{"id":"php-for-while","cat":"Schleifen","term":"for und while","syntax":"for ($i = 0; $i < $n; $i++) { … }    while (bedingung) { … }","text":"for ist die Zählschleife, while läuft, solange die Bedingung gilt. break beendet, continue springt zum nächsten Durchlauf.","code":"for ($i = 1; $i <= 3; $i++) {\n    if ($i === 2) continue;\n    echo $i;\n}\n$n = 3;\nwhile ($n > 0) { echo $n--; }","out":"13321","pitfall":"Eine while-Schleife ohne Änderung der Bedingung läuft endlos. Im Zweifel einen Zähler als Sicherung mitführen.","lesson":"m52-l5","tested":true},{"id":"php-array","cat":"Arrays","term":"Array","syntax":"$liste = [1, 2];    $karte = ['schluessel' => 'wert'];","text":"Ein Array ist in PHP Liste und Wörterbuch zugleich. Mit [] wird angehängt, mit isset() prüft man, ob ein Schlüssel existiert, mit count() zählt man.","code":"$a = ['x' => 1];\n$a['y'] = 2;\n$liste = [10, 20];\n$liste[] = 30;\necho count($a), ' ', count($liste), ' ', isset($a['z']) ? 'ja' : 'nein';","out":"2 3 nein","pitfall":"Ein Zugriff auf einen fehlenden Schlüssel erzeugt eine Warnung und liefert null. Mit ?? einen Standardwert vorgeben.","lesson":"m53-l1","tested":true},{"id":"php-array-functions","cat":"Arrays","term":"array_map, array_filter, usort","syntax":"array_map(fn, $liste)    array_filter($liste, fn)    usort($liste, fn)","text":"array_map wandelt jedes Element um, array_filter behält passende (die Schlüssel bleiben erhalten), usort sortiert mit eigener Vergleichsfunktion. Mit <=> wird zahlenmäßig verglichen.","code":"$z = [5, 12, 8];\necho implode(',', array_map(fn ($n) => $n * 2, $z)), PHP_EOL;\necho implode(',', array_filter($z, fn ($n) => $n > 6)), PHP_EOL;\nusort($z, fn ($a, $b) => $b <=> $a);\necho implode(',', $z);","out":"10,24,16\n12,8\n12,8,5","pitfall":"array_filter erhält die ursprünglichen Schlüssel. Mit array_values() die Liste neu durchnummerieren.","lesson":"m53-l2","tested":true},{"id":"php-destructuring","cat":"Arrays","term":"Spread und Destructuring","syntax":"[$a, $b] = $liste;    [...$a, ...$b]","text":"Mit [$a, $b] = … werden Elemente in Variablen verteilt, mit ... werden Arrays zusammengefügt oder als Argumente entpackt.","code":"[$x, $y] = [1, 2];\n['name' => $n] = ['name' => 'Ada'];\n$alle = [...[1, 2], ...[3]];\necho \"$x $y $n \", count($alle);","out":"1 2 Ada 3","pitfall":"Mit String-Schlüsseln im Spread braucht man PHP 8.1 oder neuer. Bei doppelten Schlüsseln gewinnt der spätere.","lesson":"m53-l1","tested":true},{"id":"php-function","cat":"Funktionen","term":"function mit Typen","syntax":"function name(int $a, ?string $b = null): string { … }","text":"Parameter und Rückgabewert können Typen tragen. ?string heißt „string oder null“, void bedeutet „liefert nichts“. Benannte Argumente (name: wert) machen Aufrufe lesbar.","code":"function gruss(string $name, string $anrede = 'Hallo'): string\n{\n    return \"$anrede $name\";\n}\necho gruss(anrede: 'Moin', name: 'Ada');","out":"Moin Ada","pitfall":"Ohne declare(strict_types=1) wandelt PHP Typen still um, aus \"5\" wird 5. Mit strict_types wirft es stattdessen einen TypeError.","lesson":"m42-l4","tested":true},{"id":"php-arrow","cat":"Funktionen","term":"Pfeilfunktion und Closure","syntax":"fn ($x) => $x * 2    function ($x) use ($y) { … }","text":"Pfeilfunktionen übernehmen Variablen aus der Umgebung automatisch (nur lesend). Klassische Closures holen sie mit use. use (&$x) gibt Schreibzugriff.","code":"$faktor = 3;\n$mal = fn ($x) => $x * $faktor;\n$zaehler = 0;\n$erhoehe = function () use (&$zaehler) { $zaehler++; };\n$erhoehe();\necho $mal(4), ' ', $zaehler;","out":"12 1","pitfall":"In Pfeilfunktionen ändert eine Zuweisung die äußere Variable nicht, sie arbeitet auf einer Kopie.","lesson":"m42-l4","tested":true},{"id":"php-class","cat":"Klassen","term":"class mit Konstruktor-Promotion","syntax":"class Name { public function __construct(private readonly int $x) {} }","text":"Parameter mit Sichtbarkeit im Konstruktor werden gleich zu Eigenschaften (Promotion). readonly erlaubt nur eine einmalige Zuweisung. new erzeugt ein Objekt.","code":"final class Punkt\n{\n    public function __construct(\n        public readonly int $x,\n        public readonly int $y = 0,\n    ) {}\n\n    public function summe(): int\n    {\n        return $this->x + $this->y;\n    }\n}\n$p = new Punkt(2, 3);\necho $p->summe();","out":"5","pitfall":"readonly-Eigenschaften lassen sich nicht ändern. Für Änderungen ein neues Objekt erzeugen (withX()-Methoden).","lesson":"m44-l1","tested":true},{"id":"php-interface","cat":"Klassen","term":"interface, abstract, trait","syntax":"interface Name { … }    abstract class …    trait Name { … }","text":"Ein Interface legt Methoden fest, die Klassen anbieten müssen. Abstrakte Klassen teilen Code und erzwingen Methoden. Traits fügen wiederverwendbaren Code in mehrere Klassen ein.","code":"interface Formatierer { public function format(string $s): string; }\ntrait Protokoll { public function log(string $s): string { return '[log] ' . $s; } }\nfinal class Gross implements Formatierer\n{\n    use Protokoll;\n    public function format(string $s): string { return strtoupper($s); }\n}\n$g = new Gross();\necho $g->log($g->format('ok'));","out":"[log] OK","pitfall":"Traits sind keine Vererbung, sondern Codekopie zur Laufzeit. Zu viele Traits verstecken Abhängigkeiten. Oft ist ein Interface plus Objekt die klarere Lösung.","lesson":"m44-l2","tested":true},{"id":"php-enum","cat":"Klassen","term":"enum","syntax":"enum Status: string { case Offen = 'offen'; }","text":"Ein Enum beschreibt eine feste Menge erlaubter Werte. Ein „backed enum“ hat zusätzlich einen Text oder eine Zahl pro Fall. from() liest, tryFrom() liefert bei Unbekanntem null.","code":"enum Status: string\n{\n    case Offen = 'offen';\n    case Fertig = 'fertig';\n\n    public function label(): string\n    {\n        return ucfirst($this->value);\n    }\n}\necho Status::from('fertig')->label(), ' ', var_export(Status::tryFrom('x'), true);","out":"Fertig NULL","pitfall":"Status::from() wirft bei unbekanntem Wert einen ValueError. Eingaben von außen mit tryFrom() prüfen.","lesson":"m44-l3","tested":true},{"id":"php-exception","cat":"Fehler","term":"try / catch / throw","syntax":"try { … } catch (Typ $e) { … } finally { … }","text":"Fängt Ausnahmen. Mehrere Typen lassen sich mit | kombinieren. throw wirft eine neue Ausnahme, das Original kann als previous mitgegeben werden.","code":"try {\n    intdiv(1, 0);\n} catch (DivisionByZeroError $e) {\n    echo get_class($e), ': ', $e->getMessage();\n}","out":"DivisionByZeroError: Division by zero","pitfall":"Error und Exception sind getrennte Zweige. catch (Exception) fängt keinen TypeError. Mit Throwable fängt man beide.","lesson":"m44-l3","tested":true},{"id":"php-namespace","cat":"Klassen","term":"namespace und use","syntax":"namespace App\\Modelle;    use App\\Modelle\\Nutzer;","text":"Namensräume verhindern Namenskollisionen und folgen meist der Ordnerstruktur (PSR-4). use importiert eine Klasse unter ihrem kurzen Namen.","code":"namespace App\\Modelle;\n\nuse DateTimeImmutable;\n\nfinal class Nutzer\n{\n    public function __construct(public DateTimeImmutable $erstellt) {}\n}","pitfall":"Globale Klassen wie DateTimeImmutable brauchen im Namensraum ein führendes \\ oder ein use, sonst sucht PHP sie im aktuellen Namensraum.","lesson":"m44-l4","tested":false},{"id":"php-form","cat":"Web","term":"$_POST, $_GET und htmlspecialchars","syntax":"$_POST['feld']    htmlspecialchars($text, ENT_QUOTES)","text":"Superglobals enthalten die Daten der Anfrage. Sie sind Nutzereingaben und müssen geprüft werden. Vor der Ausgabe in HTML mit htmlspecialchars maskieren.","code":"$eingabe = '<script>alert(1)</script>';\necho htmlspecialchars($eingabe, ENT_QUOTES);","out":"&lt;script&gt;alert(1)&lt;/script&gt;","pitfall":"Validieren (stimmt das Format?) und maskieren (sichere Ausgabe) sind zwei getrennte Schritte. Keiner ersetzt den anderen.","lesson":"m43-l1","tested":true},{"id":"php-pdo","cat":"Web","term":"PDO mit Prepared Statements","syntax":"$stmt = $pdo->prepare('… WHERE id = :id');\n$stmt->execute(['id' => $id]);","text":"Prepared Statements trennen SQL und Daten. Platzhalter (:name oder ?) werden vom Treiber sicher eingesetzt. So ist SQL-Injection ausgeschlossen.","code":"$pdo = new PDO('sqlite::memory:', options: [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);\n$pdo->exec('CREATE TABLE nutzer (id INTEGER PRIMARY KEY, name TEXT)');\n$pdo->prepare('INSERT INTO nutzer (name) VALUES (:name)')->execute(['name' => \"O'Brien\"]);\n$stmt = $pdo->prepare('SELECT name FROM nutzer WHERE id = :id');\n$stmt->execute(['id' => 1]);\necho $stmt->fetchColumn();","out":"O'Brien","pitfall":"Tabellen- oder Spaltennamen lassen sich nicht als Parameter binden. Dafür eine feste Liste erlaubter Namen verwenden.","lesson":"m43-l3","tested":true},{"id":"php-json","cat":"Dateien und Daten","term":"json_encode und json_decode","syntax":"json_encode($daten)    json_decode($text, true, flags: JSON_THROW_ON_ERROR)","text":"Wandelt PHP-Daten in JSON-Text und zurück. Mit true als zweitem Argument entstehen Arrays statt Objekte. JSON_THROW_ON_ERROR wirft bei ungültigem JSON eine Ausnahme.","code":"$text = json_encode(['a' => 1, 'b' => [true, null]]);\necho $text, PHP_EOL;\ntry {\n    json_decode('{kaputt', true, flags: JSON_THROW_ON_ERROR);\n} catch (JsonException $e) {\n    echo 'ungültig';\n}","out":"{\"a\":1,\"b\":[true,null]}\nungültig","pitfall":"Ohne JSON_THROW_ON_ERROR liefert json_decode bei Fehlern stillschweigend null. Dann ist nicht klar, ob der Text „null“ oder kaputt war.","lesson":"m54-l2","tested":true},{"id":"php-datetime","cat":"Dateien und Daten","term":"DateTimeImmutable","syntax":"new DateTimeImmutable('2026-01-31')    ->modify('+1 day')    ->format('d.m.Y')","text":"Unveränderliches Datumsobjekt: jede Änderung liefert ein neues Objekt. Mit format() wird die Darstellung gewählt.","code":"$d = new DateTimeImmutable('2026-01-31', new DateTimeZone('Europe/Berlin'));\n$naechster = $d->modify('+1 day');\necho $d->format('d.m.Y'), ' ', $naechster->format('d.m.Y');","out":"31.01.2026 01.02.2026","pitfall":"Das veränderliche DateTime ändert sich beim Aufruf von modify() selbst. Das führt zu schwer findbaren Fehlern, deshalb DateTimeImmutable verwenden.","lesson":"m53-l4","tested":true},{"id":"php-file","cat":"Dateien und Daten","term":"file_put_contents und file_get_contents","syntax":"file_put_contents($pfad, $text, LOCK_EX)    file_get_contents($pfad)","text":"Schreibt und liest ganze Dateien. LOCK_EX sperrt die Datei beim Schreiben. Bei Fehlern liefern beide false statt einer Ausnahme.","code":"$pfad = sys_get_temp_dir() . '/glossar-test.txt';\nfile_put_contents($pfad, \"Zeile 1\\n\", LOCK_EX);\necho trim(file_get_contents($pfad));\nunlink($pfad);","out":"Zeile 1","pitfall":"Dateipfade aus Nutzereingaben nie direkt verwenden (Path Traversal). Mit basename() und einer festen Zielordner arbeiten.","lesson":"m54-l1","tested":true},{"id":"php-generator","cat":"Funktionen","term":"Generator (yield)","syntax":"function zahlen() { yield 1; yield 2; }","text":"Eine Funktion mit yield liefert die Werte nacheinander, statt eine ganze Liste aufzubauen. Das spart Speicher bei großen Datenmengen.","code":"function bis(int $n): Generator\n{\n    for ($i = 1; $i <= $n; $i++) {\n        yield $i;\n    }\n}\nforeach (bis(3) as $z) { echo $z; }","out":"123","pitfall":"Ein Generator lässt sich nur einmal durchlaufen. Ein zweites foreach darüber wirft eine Ausnahme.","lesson":"m55-l1","tested":true},{"id":"php-nullsafe","cat":"Variablen und Typen","term":"?-> (Nullsafe)","syntax":"$objekt?->methode()?->eigenschaft","text":"Bricht die Kette ab und liefert null, sobald ein Zwischenwert null ist, statt einen Fehler zu werfen.","code":"$nutzer = null;\nvar_dump($nutzer?->adresse?->ort);","out":"NULL","pitfall":"Das Ergebnis kann null sein. Wer den Wert weiterverwendet, muss diesen Fall behandeln.","lesson":"m42-l4","tested":true},{"id":"php-strict-isset","cat":"Variablen und Typen","term":"declare(strict_types=1), isset, empty, unset","syntax":"declare(strict_types=1);    isset($x)    empty($x)    unset($x)","text":"strict_types=1 verbietet stille Typumwandlungen bei Funktionsaufrufen in dieser Datei. isset prüft, ob eine Variable existiert und nicht null ist. empty ist wahr bei „leeren“ Werten (0, \"0\", \"\", null, []). unset entfernt eine Variable oder einen Array-Eintrag.","code":"declare(strict_types=1);\nfunction verdopple(int $n): int { return $n * 2; }\ntry { echo verdopple('5'); } catch (TypeError $e) { echo 'TypeError', PHP_EOL; }\n$a = ['x' => null];\nvar_dump(isset($a['x']), array_key_exists('x', $a), empty('0'));","out":"TypeError\nbool(false)\nbool(true)\nbool(true)","pitfall":"empty(\"0\") ist wahr, empty(\"0.0\") nicht. Für Formularwerte besser genau prüfen (=== '' oder strlen). declare muss die erste Anweisung der Datei sein.","lesson":"m42-l2","tested":true},{"id":"php-str-helpers","cat":"Strings","term":"str_contains, str_starts_with, str_pad, ucwords","syntax":"str_contains($s, $teil)    str_starts_with($s, $p)    str_ends_with($s, $e)    str_pad(…)","text":"Lesbare Prüffunktionen statt strpos mit false-Vergleich. str_pad füllt auf eine Länge auf, ucwords macht jeden Wortanfang groß.","code":"var_dump(str_contains('Werkstatt', 'statt'), str_starts_with('Werkstatt', 'Werk'), str_ends_with('Werkstatt', 'x'));\necho str_pad('7', 3, '0', STR_PAD_LEFT), ' ', ucwords('hallo schöne welt');","out":"bool(true)\nbool(true)\nbool(false)\n007 Hallo Schöne Welt","pitfall":"ucwords, strtoupper und strlen arbeiten byteweise. Bei Umlauten und Sonderzeichen die mb_-Funktionen verwenden (mb_strtoupper, mb_strlen).","lesson":"m53-l3","tested":true},{"id":"php-math-array","cat":"Arrays","term":"array_sum, max, min, range, compact, intdiv","syntax":"array_sum($a)  max($a)  min($a)  count($a)  range(1, 5)  compact(\"a\", \"b\")  intdiv(17, 5)","text":"Kleine Hilfen für Zahlen und Listen. range erzeugt Zahlenfolgen, compact baut aus Variablen ein Array, intdiv teilt ganzzahlig, % liefert den Rest.","code":"$z = [3, 9, 4];\necho array_sum($z), ' ', max($z), ' ', min($z), ' ', count($z), ' ', implode(',', range(1, 5)), ' ', intdiv(17, 5), ' ', 17 % 5, ' ', round(2.5), ' ', round(-2.5), PHP_EOL;\n$name = 'Mia';\n$alter = 30;\nprint_r(compact('name', 'alter'));","out":"16 9 3 3 1,2,3,4,5 3 2 3 -3\nArray\n(\n    [name] => Mia\n    [alter] => 30\n)","pitfall":"round rundet .5 weg von null (2.5 ergibt 3, -2.5 ergibt -3). max und min auf leeren Arrays werfen eine Ausnahme.","lesson":"m53-l2","tested":true},{"id":"php-array-reduce-chunk","cat":"Arrays","term":"array_reduce, array_chunk, array_diff, array_combine, array_flip","syntax":"array_reduce($a, fn($c, $x) => …, $start)    array_chunk($a, 2)    array_diff($a, $b)","text":"reduce faltet eine Liste zu einem Wert. chunk teilt in Gruppen. diff und intersect bilden Differenz und Schnitt (Schlüssel bleiben erhalten). combine verbindet Schlüssel- und Wertelisten, flip vertauscht Schlüssel und Werte.","code":"$a = [1, 2, 3, 4];\necho array_reduce($a, fn($c, $x) => $c + $x, 0), ' ', json_encode(array_chunk($a, 2)), ' ', json_encode(array_diff($a, [2, 3])), ' ', json_encode(array_combine(['a', 'b'], [1, 2])), ' ', json_encode(array_flip(['x' => 1])), PHP_EOL;","out":"10 [[1,2],[3,4]] {\"0\":1,\"3\":4} {\"a\":1,\"b\":2} {\"1\":\"x\"}","pitfall":"array_diff vergleicht Werte als Text. Nach dem Filtern sind die Schlüssel nicht fortlaufend. Mit array_values neu nummerieren, bevor man json_encode nutzt (sonst entsteht ein Objekt statt einer Liste).","lesson":"m53-l2","tested":true},{"id":"php-new-array-funcs","cat":"Arrays","term":"array_first, array_last, array_is_list, json_validate","syntax":"array_first($a)    array_last($a)    array_is_list($a)    json_validate($text)","text":"array_first und array_last (PHP 8.5) liefern erstes und letztes Element. array_is_list prüft auf fortlaufende Schlüssel ab 0. json_validate (PHP 8.3) prüft JSON, ohne es zu dekodieren.","code":"var_dump(array_is_list([1, 2]), array_is_list([1 => 1]));\nvar_dump(json_validate('{\"a\":1}'), json_validate('{a}'));\necho array_first([5, 6, 7]), array_last([5, 6, 7]);","out":"bool(true)\nbool(false)\nbool(true)\nbool(false)\n57","pitfall":"Auf leeren Arrays liefern array_first und array_last null. Die Funktionen gibt es erst ab PHP 8.5. Ältere Server: reset( ) und end( ) verwenden.","lesson":"m55-l3","tested":true},{"id":"php-types-modern","cat":"Funktionen","term":"Union-Typen, never, new in Initialisierern","syntax":"int|string|null    function f(): never    __construct(private Logger $l = new Logger())","text":"Union-Typen erlauben mehrere Typen für einen Parameter. never markiert Funktionen, die nie zurückkehren (werfen oder beenden). Seit PHP 8.1 darf ein Standardwert ein new-Ausdruck sein.","code":"class Logger { public function log(string $t): void { echo \"log: $t\\n\"; } }\nclass Dienst {\n  public function __construct(private Logger $logger = new Logger()) {}\n  public function tue(): static { $this->logger->log('tue'); return $this; }\n}\nfunction stopp(): never { throw new RuntimeException('Ende'); }\nfunction typ(int|string|null $x): string { return get_debug_type($x); }\necho typ(5), ' ', typ('a'), ' ', typ(null), PHP_EOL;\n(new Dienst)->tue();\ntry { stopp(); } catch (RuntimeException $e) { echo $e->getMessage(); }","out":"int string null\nlog: tue\nEnde","pitfall":"Unions mit vielen Typen sind ein Zeichen für unklare Schnittstellen. Möglichst ein Typ oder ein Interface.","lesson":"m42-l4","tested":true},{"id":"php-override-clone","cat":"Klassen","term":"#[Override], typisierte Konstanten, new ohne Klammer, clone mit","syntax":"#[\\Override]    const string X = \"…\";    new Klasse()->methode()    clone($obj, ['feld' => wert])","text":"#[\\Override] lässt PHP prüfen, dass eine Methode wirklich etwas überschreibt. Klassenkonstanten dürfen Typen tragen (8.3). Ein new-Ausdruck kann direkt weiterverkettet werden (8.4). clone mit Array erzeugt eine Kopie mit geänderten Feldern (8.5), ideal für unveränderliche Objekte.","code":"interface Tier { public function laut(): string; }\nclass Hund implements Tier {\n  const string ART = 'Hund';\n  #[\\Override] public function laut(): string { return 'Wau'; }\n}\necho new Hund()->laut(), ' ', Hund::ART, PHP_EOL;\nfinal class Punkt {\n  public function __construct(public readonly int $x = 0, public readonly int $y = 0) {}\n  public function mitX(int $x): static { return clone($this, ['x' => $x]); }\n}\n$q = new Punkt(1, 2)->mitX(5);\necho \"$q->x,$q->y\";","out":"Wau Hund\n5,2","pitfall":"Die Funktionen sind neu (8.3 bis 8.5). Vor dem Einsatz die PHP-Version des Servers prüfen, sonst gibt es Parse-Fehler.","lesson":"m44-l1","tested":true},{"id":"php-countable-iterator","cat":"Klassen","term":"Countable, IteratorAggregate, ArrayAccess","syntax":"implements Countable, IteratorAggregate, ArrayAccess","text":"Mit diesen Schnittstellen verhält sich ein eigenes Objekt wie ein Array: count($objekt), foreach und $objekt['schluessel'] funktionieren. Laravel-Collections nutzen genau dieses Prinzip.","code":"class Liste implements Countable, IteratorAggregate, ArrayAccess {\n  private array $d = [];\n  public function offsetExists(mixed $o): bool { return isset($this->d[$o]); }\n  public function offsetGet(mixed $o): mixed { return $this->d[$o] ?? null; }\n  public function offsetSet(mixed $o, mixed $v): void { if ($o === null) { $this->d[] = $v; } else { $this->d[$o] = $v; } }\n  public function offsetUnset(mixed $o): void { unset($this->d[$o]); }\n  public function count(): int { return count($this->d); }\n  public function getIterator(): Iterator { return new ArrayIterator($this->d); }\n}\n$l = new Liste;\n$l[] = 'a';\n$l['k'] = 'b';\necho count($l), ' ', $l['k'], ' ';\nforeach ($l as $k => $v) echo \"$k=$v \";","out":"2 b 0=a k=b","pitfall":"Die Methoden brauchen die genauen Rückgabetypen (bool, mixed, void), sonst gibt PHP 8.x eine Deprecation-Meldung aus.","lesson":"m44-l2","tested":true},{"id":"php-errors-handler","cat":"Fehler","term":"Fehler in Ausnahmen umwandeln, Throwable","syntax":"set_error_handler(fn() => throw new ErrorException(…))    catch (Throwable $e)    error_log()","text":"PHP unterscheidet Fehler (Error, TypeError, DivisionByZeroError) und Ausnahmen (Exception), beide implementieren Throwable. Warnungen sind keine Ausnahmen, lassen sich aber mit einem Error-Handler in ErrorException umwandeln.","code":"set_error_handler(function (int $no, string $msg) {\n  throw new ErrorException($msg, 0, $no);\n});\ntry { echo intdiv(10, 0); } catch (DivisionByZeroError $e) { echo get_class($e), ': ', $e->getMessage(), PHP_EOL; }\ntry { $x = []; echo $x['fehlt']; } catch (ErrorException $e) { echo $e->getMessage(); }","out":"DivisionByZeroError: Division by zero\nUndefined array key \"fehlt\"","pitfall":"In Produktion keine Fehlermeldungen im Browser anzeigen (display_errors=0), sondern in eine Logdatei schreiben (error_log). Meldungen können interne Pfade und Daten verraten.","lesson":"m44-l3","tested":true},{"id":"php-random-hash","cat":"Web","term":"random_int, random_bytes, hash, hash_equals","syntax":"random_int(1, 6)    bin2hex(random_bytes(16))    hash(\"sha256\", $text)    hash_equals($a, $b)","text":"random_int und random_bytes liefern kryptografisch sichere Zufallswerte (für Tokens, Codes). hash berechnet Prüfsummen. hash_equals vergleicht in konstanter Zeit, damit Angreifer nichts aus der Rechenzeit lesen können.","code":"echo strlen(bin2hex(random_bytes(16))), ' ', hash('sha256', 'a'), PHP_EOL;\nvar_dump(hash_equals(hash('sha256', 'a'), hash('sha256', 'a')));","out":"32 ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb\nbool(true)","pitfall":"rand() und mt_rand() sind nicht sicher genug für Tokens oder Passwörter. Für Passwörter immer password_hash, nie sha256 oder md5.","lesson":"m43-l2","tested":true},{"id":"php-require-autoload","cat":"Grundlagen","term":"require, include und Autoloading","syntax":"require __DIR__ . '/vendor/autoload.php';    require_once    include","text":"require bindet eine Datei ein und bricht bei Fehlern ab. include gibt nur eine Warnung aus. Mit der Composer-Autoload-Datei lädt PHP Klassen automatisch, sobald sie genutzt werden. Dann braucht man kein require pro Klasse.","code":"<?php\ndeclare(strict_types=1);\n\nrequire __DIR__ . '/vendor/autoload.php';\n\nuse App\\Service\\RechnungService;\n\n$dienst = new RechnungService();   // Datei wird bei Bedarf geladen","pitfall":"Pfade immer mit __DIR__ bilden, nie relativ zum aktuellen Verzeichnis. Nutzereingaben niemals in require einsetzen (Dateieinschleusung).","lesson":"m44-l4","tested":false},{"id":"php-composer","cat":"Grundlagen","term":"Composer-Befehle","syntax":"composer init    composer require paket    composer install    composer update    composer dump-autoload","text":"Composer verwaltet Abhängigkeiten. require trägt ein Paket ein und lädt es. install installiert exakt die Versionen aus composer.lock (für Server), update holt neue Versionen innerhalb der erlaubten Grenzen. Das Namespace-Mapping steht in composer.json unter autoload.","code":"composer init\ncomposer require monolog/monolog\ncomposer require --dev phpunit/phpunit\ncomposer install --no-dev --optimize-autoloader\ncomposer audit\ncomposer dump-autoload","pitfall":"composer.lock ins Repository, vendor/ nicht. Auf Servern install statt update nutzen. composer audit zeigt bekannte Sicherheitslücken in Abhängigkeiten.","lesson":"m44-l4","tested":false,"codeLang":"bash"},{"id":"php-json-response","cat":"Web","term":"header, http_response_code und JSON-Antwort","syntax":"header('Content-Type: application/json');    http_response_code(201);    exit;","text":"Ein PHP-Skript kann selbst Statuscode und Kopfzeilen setzen. header() muss vor jeder Ausgabe stehen. Für APIs gibt man JSON mit passendem Content-Type zurück und wählt den richtigen Statuscode.","code":"<?php\nheader('Content-Type: application/json; charset=utf-8');\nhttp_response_code(201);\necho json_encode(['id' => 7, 'status' => 'angelegt'], JSON_THROW_ON_ERROR);\nexit;","pitfall":"Ausgabe vor header() (auch ein Leerzeichen vor <?php) löst „headers already sent“ aus. Bei Umleitungen nach header('Location: …') direkt exit aufrufen.","lesson":"m54-l2","tested":false},{"id":"php-sprintf","cat":"Strings","term":"sprintf und number_format","syntax":"sprintf('%s: %05.1f', $text, $zahl)    number_format($zahl, 2, ',', '.')","text":"sprintf baut Text mit Platzhaltern (%s Text, %d ganze Zahl, %.2f Kommazahl, %05d mit Nullen aufgefüllt). number_format formatiert Zahlen mit Tausender- und Dezimaltrennzeichen.","code":"echo sprintf('%s hat %d Punkte (%.1f %%)', 'Ada', 42, 87.456), PHP_EOL;\necho number_format(1234567.891, 2, ',', '.'), PHP_EOL;\necho sprintf('%05d', 42);","out":"Ada hat 42 Punkte (87.5 %)\n1.234.567,89\n00042","pitfall":"Für Geld besser ganze Cent oder bcmath/Money-Bibliotheken nutzen. number_format rundet nur für die Anzeige.","lesson":"m52-l3","tested":true},{"id":"php-string-funcs","cat":"Strings","term":"explode, implode, str_replace, trim","syntax":"explode(',', $text)    implode(', ', $liste)    str_replace($suche, $ersatz, $text)","text":"explode zerlegt einen Text in ein Array, implode fügt ein Array zu Text zusammen, str_replace ersetzt Teile, trim entfernt Leerraum am Rand. ucfirst und ucwords ändern Großbuchstaben.","code":"$teile = explode(',', 'a, b ,c');\necho implode('|', array_map('trim', $teile)), PHP_EOL;\necho str_replace('Welt', 'PHP', 'Hallo Welt'), ' ', ucfirst('haus'), ' ', substr('Werkstatt', 0, 4);","out":"a|b|c\nHallo PHP Haus Werk","pitfall":"Die Parameterreihenfolge ist nicht einheitlich: explode(Trenner, Text), aber str_contains(Text, Suche). Dokumentation prüfen, nicht raten.","lesson":"m53-l3","tested":true},{"id":"php-mb","cat":"Strings","term":"mb_-Funktionen für Umlaute","syntax":"mb_strlen($text)    mb_substr($text, 0, 3)    mb_strtoupper($text)","text":"Die mb_-Funktionen arbeiten mit Zeichen statt Bytes. Für deutschen Text mit Umlauten sind sie die richtige Wahl.","code":"echo strlen('Müll'), ' ', mb_strlen('Müll'), ' ', strtoupper('müll'), ' ', mb_strtoupper('müll');","out":"5 4 MüLL MÜLL","pitfall":"strlen zählt Bytes (ein ü hat zwei), strtoupper wandelt Umlaute nicht um. Das Ergebnis ist leise falsch, es gibt keine Fehlermeldung.","lesson":"m53-l3","tested":true},{"id":"php-preg","cat":"Strings","term":"preg_match und preg_replace","syntax":"preg_match('/muster/', $text, $treffer)    preg_replace('/muster/', $ersatz, $text)","text":"Reguläre Ausdrücke in PHP. preg_match liefert 1 bei Treffer und füllt $treffer mit den Gruppen, preg_replace ersetzt. Das Muster steht in Begrenzern (/…/).","code":"if (preg_match('/^(\\d{2})\\.(\\d{2})\\.(\\d{4})$/', '13.11.2026', $t)) {\n    echo \"$t[3]-$t[2]-$t[1]\", PHP_EOL;\n}\necho preg_replace('/\\s+/', ' ', \"a   b\\n c\");","out":"2026-11-13\na b c","pitfall":"Muster aus Nutzereingaben mit preg_quote() maskieren. Ungültige Muster liefern false und nur eine Warnung.","lesson":"m53-l3","tested":true},{"id":"php-array-search","cat":"Arrays","term":"in_array, array_key_exists, array_search","syntax":"in_array($x, $liste, true)    array_key_exists($k, $a)","text":"in_array prüft, ob ein Wert vorkommt, array_key_exists, ob ein Schlüssel existiert (auch bei null-Werten), array_search liefert den Schlüssel. Als dritten Parameter true für strengen Vergleich angeben.","code":"var_dump(in_array('1', [1, 2, 3]), in_array('1', [1, 2, 3], true), array_key_exists('a', ['a' => null]), isset(['a' => null]['a']));","out":"bool(true)\nbool(false)\nbool(true)\nbool(false)","pitfall":"isset liefert bei einem Wert null false, array_key_exists aber true. Für „Schlüssel vorhanden?“ array_key_exists nehmen.","lesson":"m53-l1","tested":true},{"id":"php-array-more","cat":"Arrays","term":"array_merge, array_slice, array_unique, array_column","syntax":"array_merge($a, $b)    array_slice($a, 1, 2)    array_unique($a)    array_column($zeilen, \"spalte\")","text":"array_merge hängt Arrays aneinander, array_slice schneidet einen Teil aus, array_unique entfernt Doppelte, array_column holt eine Spalte aus einer Liste von Datensätzen.","code":"$zeilen = [['id' => 1, 'name' => 'Ada'], ['id' => 2, 'name' => 'Bo']];\necho implode(',', array_column($zeilen, 'name')), PHP_EOL;\necho implode(',', array_column($zeilen, 'name', 'id')), PHP_EOL;\necho implode(',', array_unique(array_merge([1, 2], [2, 3]))), PHP_EOL;\necho implode(',', array_slice([10, 20, 30, 40], 1, 2));","out":"Ada,Bo\nAda,Bo\n1,2,3\n20,30","pitfall":"array_merge nummeriert numerische Schlüssel neu und überschreibt gleiche Textschlüssel. Der +-Operator behält die linken Werte.","lesson":"m53-l2","tested":true},{"id":"php-sort","cat":"Arrays","term":"sort, ksort, usort, array_multisort","syntax":"sort($a)    ksort($a)    usort($a, fn)","text":"sort sortiert nach Wert, ksort nach Schlüssel, rsort und krsort absteigend. usort sortiert mit eigener Funktion. Alle verändern das Array selbst und liefern true.","code":"$a = ['b' => 2, 'a' => 3, 'c' => 1];\nasort($a);\necho implode(',', array_keys($a)), ' ';\nksort($a);\necho implode(',', array_keys($a));","out":"c,b,a a,b,c","pitfall":"sort wirft Schlüssel weg, asort behält sie. Wer Zuordnungen braucht, nimmt asort, ksort oder usort.","lesson":"m53-l2","tested":true},{"id":"php-static-const","cat":"Klassen","term":"static, const, self und static::","syntax":"public static function f()    const NAME = 1;    self::NAME    static::f()","text":"static-Eigenschaften und -Methoden gehören der Klasse, nicht dem Objekt. const legt Klassenkonstanten an, self:: greift auf die eigene Klasse zu, static:: auf die zur Laufzeit aufgerufene (späte statische Bindung).","code":"class Konfig\n{\n    public const STEUER = 0.19;\n    private static int $zaehler = 0;\n\n    public static function neu(): static\n    {\n        self::$zaehler++;\n        return new static();\n    }\n\n    public static function anzahl(): int { return self::$zaehler; }\n}\nKonfig::neu(); Konfig::neu();\necho Konfig::anzahl(), ' ', Konfig::STEUER;","out":"2 0.19","pitfall":"Statische Eigenschaften sind globaler Zustand und erschweren Tests. Für Abhängigkeiten besser Objekte per Konstruktor übergeben.","lesson":"m44-l1","tested":true},{"id":"php-magic","cat":"Klassen","term":"__toString, __invoke, __get","syntax":"public function __toString(): string","text":"Magische Methoden werden von PHP automatisch aufgerufen: __toString beim Umwandeln in Text, __invoke wenn man das Objekt wie eine Funktion benutzt, __get bei Zugriff auf unbekannte Eigenschaften.","code":"final class Betrag\n{\n    public function __construct(private int $cent) {}\n    public function __toString(): string { return number_format($this->cent / 100, 2, ',', '.') . ' €'; }\n    public function __invoke(int $faktor): self { return new self($this->cent * $faktor); }\n}\n$b = new Betrag(250);\necho $b, ' ', $b(2);","out":"2,50 € 5,00 €","pitfall":"__get und __set verbergen Fehler und Autovervollständigung. Nur sparsam einsetzen.","lesson":"m44-l1","tested":true},{"id":"php-first-class","cat":"Funktionen","term":"First-Class-Callable-Syntax","syntax":"strlen(...)    $objekt->methode(...)    Klasse::statisch(...)","text":"Die Schreibweise funktion(...) erzeugt aus einer Funktion oder Methode ein Closure-Objekt, ohne Umweg über Strings oder Arrays.","code":"$laenge = strlen(...);\necho implode(',', array_map($laenge, ['a', 'abc', 'ab']));","out":"1,3,2","pitfall":"Das ältere array_map('strlen', …) mit Funktionsnamen als Text ist anfällig für Tippfehler, die IDE erkennt sie nicht.","lesson":"m42-l4","tested":true},{"id":"php-null-assign","cat":"Variablen und Typen","term":"??= (Null-Zuweisung)","syntax":"$a ??= $standard;","text":"Weist nur zu, wenn die Variable noch nicht existiert oder null ist. Praktisch für Standardwerte und Zwischenspeicher.","code":"$optionen = ['tief' => 3];\n$optionen['tief'] ??= 10;\n$optionen['breit'] ??= 20;\nprint_r($optionen);","out":"Array\n(\n    [tief] => 3\n    [breit] => 20\n)","pitfall":"Der Wert false oder 0 zählt nicht als „fehlt“ und wird nicht überschrieben. Genau dafür ist ?? gedacht.","lesson":"m52-l4","tested":true},{"id":"php-readonly-class","cat":"Klassen","term":"readonly class","syntax":"final readonly class Name { … }","text":"Seit PHP 8.2 macht readonly vor der Klasse alle Eigenschaften schreibgeschützt. Ideal für Wertobjekte und DTOs. Mit with-Methoden erzeugt man geänderte Kopien.","code":"final readonly class Geld\n{\n    public function __construct(public int $cent, public string $waehrung = 'EUR') {}\n    public function plus(int $cent): self { return new self($this->cent + $cent, $this->waehrung); }\n}\n$a = new Geld(100);\n$b = $a->plus(50);\necho $a->cent, ' ', $b->cent;\ntry { $a->cent = 1; } catch (Error $e) { echo ' ', get_class($e); }","out":"100 150 Error","pitfall":"readonly schützt nur die Eigenschaft selbst. Ein Objekt oder Array darin kann sich intern weiter ändern.","lesson":"m44-l1","tested":true},{"id":"php-property-hooks","cat":"Klassen","term":"Property Hooks (PHP 8.4)","syntax":"public string $name { set => trim($value); get => … }","text":"Seit PHP 8.4 lassen sich get- und set-Logik direkt an eine Eigenschaft hängen, ohne eigene Methoden. So bleibt der Zugriff $objekt->name, die Prüfung läuft trotzdem.","code":"class Nutzer\n{\n    public string $name {\n        set => trim($value);\n    }\n    public string $anzeige {\n        get => mb_strtoupper($this->name);\n    }\n}\n$n = new Nutzer();\n$n->name = '  Ada ';\necho $n->name, '|', $n->anzeige;","out":"Ada|ADA","pitfall":"Für Verwendung auf einem Server mit PHP unter 8.4 gibt es einen Syntaxfehler. Version prüfen, bevor man das Feature einsetzt.","lesson":"m55-l3","tested":true},{"id":"php-array-find","cat":"Arrays","term":"array_find, array_any, array_all (PHP 8.4)","syntax":"array_find($liste, fn)    array_any($liste, fn)    array_all($liste, fn)","text":"Neue Hilfsfunktionen seit PHP 8.4: array_find liefert das erste passende Element (oder null), array_any und array_all fragen „mindestens eins?“ und „alle?“.","code":"$z = [3, 8, 15];\nvar_dump(array_find($z, fn ($n) => $n > 5), array_any($z, fn ($n) => $n > 10), array_all($z, fn ($n) => $n > 5));","out":"int(8)\nbool(true)\nbool(false)","pitfall":"array_find liefert null auch dann, wenn das gefundene Element selbst null ist. Dann array_find_key nutzen.","lesson":"m55-l3","tested":true},{"id":"php-pipe","cat":"Funktionen","term":"Pipe-Operator |> (PHP 8.5)","syntax":"$wert |> funktion(...) |> andere(...)","text":"Seit PHP 8.5 reicht |> das Ergebnis von links als Argument an die Funktion rechts weiter. Verschachtelte Aufrufe lesen sich dann von links nach rechts.","code":"$ergebnis = '  Hallo Welt  '\n    |> trim(...)\n    |> strtoupper(...)\n    |> (fn ($s) => str_replace(' ', '-', $s));\necho $ergebnis;","out":"HALLO-WELT","pitfall":"Die rechte Seite muss ein Callable mit einem Parameter sein. Für mehr Parameter eine Pfeilfunktion davorsetzen. Nur ab PHP 8.5.","lesson":"m55-l3","tested":true},{"id":"php-attribute","cat":"Klassen","term":"Attribute","syntax":"#[NurLesen]    #[Route('/pfad')]","text":"Attribute hängen strukturierte Metadaten an Klassen, Methoden und Parameter. Frameworks lesen sie per Reflection, zum Beispiel für Routen oder Validierung.","code":"#[Attribute]\nclass Bezeichnung { public function __construct(public string $text) {} }\n\n#[Bezeichnung('Mein Dienst')]\nclass Dienst {}\n\n$attr = (new ReflectionClass(Dienst::class))->getAttributes()[0];\necho $attr->newInstance()->text;","out":"Mein Dienst","pitfall":"Attribute tun nichts von allein. Es braucht Code, der sie ausliest. Tippfehler im Namen fallen erst beim newInstance() auf.","lesson":"m44-l4","tested":true},{"id":"php-password","cat":"Web","term":"password_hash und password_verify","syntax":"password_hash($passwort, PASSWORD_DEFAULT)    password_verify($eingabe, $hash)","text":"Speichert Passwörter nur als Hash mit Salt und passendem Verfahren. password_verify prüft eine Eingabe gegen den gespeicherten Hash. PASSWORD_DEFAULT wählt das aktuell empfohlene Verfahren.","code":"$hash = password_hash('geheim-123', PASSWORD_DEFAULT);\nvar_dump(password_verify('geheim-123', $hash), password_verify('falsch', $hash), strlen($hash) >= 60);","out":"bool(true)\nbool(false)\nbool(true)","pitfall":"Nie md5 oder sha1 für Passwörter. Die Hash-Spalte in der Datenbank großzügig anlegen (mindestens 255 Zeichen) und bei Bedarf mit password_needs_rehash erneuern.","lesson":"m43-l2","tested":true},{"id":"php-filter-var","cat":"Web","term":"filter_var","syntax":"filter_var($wert, FILTER_VALIDATE_EMAIL)    FILTER_VALIDATE_INT","text":"Prüft und wandelt Eingaben: Ganzzahl, E-Mail, URL, Boolean. Bei ungültigem Wert liefert die Funktion false (bzw. null mit FILTER_NULL_ON_FAILURE).","code":"var_dump(filter_var('42', FILTER_VALIDATE_INT), filter_var('4x', FILTER_VALIDATE_INT), filter_var('ada@example.org', FILTER_VALIDATE_EMAIL), filter_var('0', FILTER_VALIDATE_INT));","out":"int(42)\nbool(false)\nstring(15) \"ada@example.org\"\nint(0)","pitfall":"Der Rückgabewert 0 ist gültig, aber falsy. Deshalb === false prüfen, nicht if (!$ergebnis).","lesson":"m43-l1","tested":true},{"id":"php-session","cat":"Web","term":"Sessions und Cookies","syntax":"session_start();    $_SESSION[\"nutzer\"] = $id;    setcookie(…)","text":"Eine Session merkt sich Daten zwischen Anfragen. Der Browser bekommt nur eine zufällige ID im Cookie, die Daten liegen auf dem Server. Nach der Anmeldung die ID mit session_regenerate_id(true) erneuern.","code":"session_start();\nsession_regenerate_id(true);\n$_SESSION['nutzerId'] = 42;\n\nsetcookie('sprache', 'de', [\n    'expires' => time() + 86400 * 30,\n    'path' => '/',\n    'secure' => true,\n    'httponly' => true,\n    'samesite' => 'Lax',\n]);","pitfall":"Cookies immer mit Secure, HttpOnly und SameSite setzen. Nach der Anmeldung die Session-ID erneuern, sonst droht Session Fixation.","lesson":"m43-l2","tested":false},{"id":"php-heredoc","cat":"Strings","term":"Heredoc und Nowdoc","syntax":"<<<TEXT … TEXT;    <<<'TEXT' … TEXT;","text":"Mehrzeilige Texte. Heredoc ersetzt Variablen wie ein doppelt angeführter String, Nowdoc (mit einfachen Anführungszeichen) nicht. Die Einrückung des schließenden Markers wird von allen Zeilen entfernt.","code":"$name = 'Ada';\necho <<<TEXT\n    Hallo {$name},\n    willkommen!\n    TEXT;","out":"Hallo Ada,\nwillkommen!","pitfall":"Nie HTML oder SQL mit Nutzerdaten per Heredoc zusammensetzen, ohne sie zu maskieren oder Platzhalter zu nutzen.","lesson":"m52-l2","tested":true},{"id":"php-yield-from","cat":"Funktionen","term":"yield from und Generator-Schlüssel","syntax":"yield $schluessel => $wert;    yield from $andere;","text":"Generatoren können Schlüssel mitliefern (yield $k => $v) und an andere Generatoren oder Arrays delegieren (yield from).","code":"function zeilen(): Generator\n{\n    yield 'a' => 1;\n    yield from ['b' => 2, 'c' => 3];\n}\nforeach (zeilen() as $k => $v) { echo \"$k=$v \"; }","out":"a=1 b=2 c=3","pitfall":"Mit iterator_to_array() und yield from auf Generatoren mit gleichen Schlüsseln gehen Werte verloren, weil spätere Schlüssel frühere überschreiben. Zweites Argument false verwenden.","lesson":"m55-l1","tested":true}]},{"id":"laravel","label":"Laravel","codeLang":"php","intro":"PHP-Framework für Webanwendungen. Hier stehen die Befehle und Schreibweisen, die in den Laravel-Lektionen vorkommen.","notice":"Diese Beispiele werden nicht ausgeführt. Sie zeigen die Schreibweisen aus den Laravel-Lektionen; Befehle laufen im Projektordner einer Laravel-Anwendung.","runner":"","entries":[{"id":"laravel-artisan","cat":"Artisan (Terminal)","term":"php artisan make:…","syntax":"php artisan make:model Aufgabe -mfc","text":"Erzeugt Dateien mit der richtigen Struktur. Die Optionen -m, -f und -c legen zusätzlich Migration, Factory und Controller an.","code":"php artisan make:model Aufgabe -mf\nphp artisan make:controller AufgabeController --resource\nphp artisan make:request AufgabeRequest","pitfall":"Der Befehl läuft im Projektordner. Dateinamen und Namensräume folgen den Laravel-Konventionen, nicht verschieben ohne Anpassung.","lesson":"m45-l1","tested":false},{"id":"laravel-route","cat":"Routing","term":"Route::get / post / resource","syntax":"Route::get('/pfad', [Controller::class, 'methode'])->name('name');","text":"Verknüpft eine URL und eine HTTP-Methode mit Code. name() vergibt einen Namen, mit dem sich URLs per route() erzeugen lassen. resource() legt die sieben üblichen CRUD-Routen an.","code":"use App\\Http\\Controllers\\AufgabeController;\nuse Illuminate\\Support\\Facades\\Route;\n\nRoute::get('/aufgaben', [AufgabeController::class, 'index'])->name('aufgaben.index');\nRoute::resource('aufgaben', AufgabeController::class)->except(['show']);","pitfall":"Formularrouten (POST, PUT, DELETE) brauchen @csrf im Formular, sonst antwortet Laravel mit Fehler 419.","lesson":"m45-l2","tested":false},{"id":"laravel-route-param","cat":"Routing","term":"Routenparameter und Model Binding","syntax":"Route::get('/aufgaben/{aufgabe}', fn (Aufgabe $aufgabe) => …);","text":"Platzhalter in geschweiften Klammern werden an die Funktion übergeben. Ist der Parametername gleich dem Variablennamen eines Models, lädt Laravel den Datensatz selbst und antwortet bei Nichtfund mit 404.","code":"Route::get('/aufgaben/{aufgabe}', function (Aufgabe $aufgabe) {\n    return view('aufgaben.show', ['aufgabe' => $aufgabe]);\n});","pitfall":"Model Binding prüft nicht, ob der Nutzer den Datensatz sehen darf. Dafür Policies oder Gates verwenden.","lesson":"m45-l2","tested":false},{"id":"laravel-controller","cat":"Controller","term":"Controller-Methode","syntax":"public function store(Request $request): RedirectResponse","text":"Nimmt die Anfrage entgegen, ruft Logik auf und liefert Antwort: eine View, eine Weiterleitung oder JSON. Controller sollen schlank bleiben.","code":"public function store(AufgabeRequest $request): RedirectResponse\n{\n    Aufgabe::create($request->validated());\n\n    return redirect()->route('aufgaben.index')->with('status', 'Gespeichert');\n}","pitfall":"Nie $request->all() an create() übergeben. validated() liefert nur geprüfte Felder, so vermeidet man Mass-Assignment-Lücken.","lesson":"m45-l3","tested":false},{"id":"laravel-blade","cat":"Blade-Templates","term":"{{ }}, @if, @foreach","syntax":"{{ $variable }}    @if (…) … @endif    @foreach ($liste as $x) … @endforeach","text":"Blade ist die Template-Sprache. {{ }} gibt Werte maskiert aus (Schutz vor XSS). @if, @foreach, @forelse und @include steuern die Ausgabe. {!! !!} gibt rohes HTML aus.","code":"@forelse ($aufgaben as $aufgabe)\n    <li>{{ $aufgabe->titel }}</li>\n@empty\n    <li>Keine Aufgaben</li>\n@endforelse","pitfall":"{!! !!} nur für HTML, das du selbst erzeugt oder bereinigt hast. Nutzertexte gehören immer in {{ }}.","lesson":"m45-l3","tested":false,"codeLang":"blade"},{"id":"laravel-blade-component","cat":"Blade-Templates","term":"Blade-Komponente","syntax":"<x-karte titel=\"…\">Inhalt</x-karte>","text":"Wiederverwendbares Stück Oberfläche. Attribute werden zu Variablen, der Inhalt steht in $slot, benannte Slots mit <x-slot:name>.","code":"{{-- resources/views/components/karte.blade.php --}}\n@props(['titel'])\n<section class=\"karte\">\n    <h2>{{ $titel }}</h2>\n    {{ $slot }}\n</section>\n\n{{-- Verwendung --}}\n<x-karte titel=\"Heute\">Drei Aufgaben offen.</x-karte>","pitfall":"Dynamische Werte werden mit Doppelpunkt übergeben: :anzahl=\"$n\". Ohne Doppelpunkt kommt der Text „$n“ an.","lesson":"m56-l1","tested":false,"codeLang":"blade"},{"id":"laravel-migration","cat":"Datenbank","term":"Migration","syntax":"Schema::create('tabelle', function (Blueprint $table) { … });","text":"Beschreibt Änderungen am Datenbankschema in Code. php artisan migrate führt sie aus, migrate:rollback macht den letzten Schritt rückgängig.","code":"Schema::create('aufgaben', function (Blueprint $table) {\n    $table->id();\n    $table->string('titel');\n    $table->boolean('erledigt')->default(false);\n    $table->foreignId('user_id')->constrained()->cascadeOnDelete();\n    $table->timestamps();\n});","pitfall":"Bereits veröffentlichte Migrationen nicht nachträglich ändern. Stattdessen eine neue Migration anlegen.","lesson":"m46-l1","tested":false},{"id":"laravel-eloquent","cat":"Datenbank","term":"Eloquent-Model","syntax":"class Aufgabe extends Model { protected $fillable = ['titel']; }","text":"Ein Model entspricht einer Tabelle. $fillable legt fest, welche Felder per Mass Assignment gesetzt werden dürfen. Abfragen laufen über Methoden wie where(), orderBy(), find() und create().","code":"$offene = Aufgabe::query()\n    ->where('erledigt', false)\n    ->orderByDesc('created_at')\n    ->limit(10)\n    ->get();\n\n$aufgabe = Aufgabe::findOrFail($id);\n$aufgabe->update(['erledigt' => true]);","pitfall":"findOrFail antwortet bei Nichtfund mit 404, find liefert null. Auf null prüfen oder findOrFail verwenden.","lesson":"m46-l2","tested":false},{"id":"laravel-relations","cat":"Datenbank","term":"Beziehungen","syntax":"hasMany, belongsTo, belongsToMany","text":"Beziehungen werden als Methode im Model deklariert und wie eine Eigenschaft gelesen ($user->aufgaben). hasMany ist die „1“-Seite, belongsTo die „n“-Seite.","code":"class User extends Model\n{\n    public function aufgaben(): HasMany\n    {\n        return $this->hasMany(Aufgabe::class);\n    }\n}\n\nclass Aufgabe extends Model\n{\n    public function user(): BelongsTo\n    {\n        return $this->belongsTo(User::class);\n    }\n}","pitfall":"In Schleifen entsteht schnell das N+1-Problem. Mit with('aufgaben') vorab laden.","lesson":"m46-l3","tested":false},{"id":"laravel-eager","cat":"Datenbank","term":"with (Eager Loading)","syntax":"User::with('aufgaben')->get()","text":"Lädt Beziehungen in einer zusätzlichen Abfrage für alle Datensätze gemeinsam, statt pro Datensatz eine neue Abfrage zu stellen.","code":"$nutzer = User::with('aufgaben:id,user_id,titel')->get();\nforeach ($nutzer as $u) {\n    echo $u->aufgaben->count();\n}","pitfall":"Mit Model::preventLazyLoading() in Entwicklung und Tests fallen vergessene with()-Aufrufe sofort auf.","lesson":"m46-l4","tested":false},{"id":"laravel-validate","cat":"Validierung","term":"Form Request","syntax":"public function rules(): array { return ['feld' => ['required', 'string']]; }","text":"Eine eigene Klasse prüft die Eingaben, bevor der Controller läuft. Bei Fehlern leitet Laravel zurück und füllt $errors für Blade. Bei JSON-Anfragen antwortet es mit Status 422.","code":"public function rules(): array\n{\n    return [\n        'titel' => ['required', 'string', 'max:120'],\n        'faellig' => ['nullable', 'date', 'after:today'],\n    ];\n}","pitfall":"Validierung ersetzt nicht die Autorisierung. Wer die Aufgabe ändern darf, regelt authorize() oder eine Policy.","lesson":"m47-l1","tested":false},{"id":"laravel-auth","cat":"Sicherheit","term":"auth, @csrf, Gates","syntax":"Route::middleware('auth')->group(…);    @csrf    $this->authorize('update', $aufgabe);","text":"Die Middleware auth schützt Routen vor Anonymen. @csrf fügt dem Formular den Token gegen Cross-Site-Request-Forgery hinzu. authorize() prüft über Gates und Policies, ob der angemeldete Nutzer etwas darf.","code":"Route::middleware('auth')->group(function () {\n    Route::resource('aufgaben', AufgabeController::class);\n});\n\n// im Controller\n$this->authorize('update', $aufgabe);","pitfall":"Angemeldet heißt nicht berechtigt. Jede Aktion auf einem fremden Datensatz braucht zusätzlich eine Policy-Prüfung.","lesson":"m47-l2","tested":false},{"id":"laravel-api-resource","cat":"APIs","term":"JsonResource","syntax":"return new AufgabeResource($aufgabe);","text":"Legt fest, welche Felder die API ausgibt. So hängt das JSON-Format nicht direkt an der Tabellenstruktur.","code":"class AufgabeResource extends JsonResource\n{\n    public function toArray(Request $request): array\n    {\n        return [\n            'id' => $this->id,\n            'titel' => $this->titel,\n            'erledigt' => $this->erledigt,\n        ];\n    }\n}","pitfall":"Keine internen Felder (Passwort-Hash, Notizen) ausgeben. Nur Felder aufführen, die der Client wirklich braucht.","lesson":"m48-l1","tested":false},{"id":"laravel-queue","cat":"Betrieb","term":"Job und dispatch","syntax":"MeinJob::dispatch($daten);    php artisan queue:work","text":"Ein Job ist Arbeit, die im Hintergrund läuft, etwa E-Mails senden. dispatch() legt sie in die Warteschlange, ein Worker (queue:work) arbeitet sie ab.","code":"class RechnungErzeugen implements ShouldQueue\n{\n    use Queueable;\n\n    public function __construct(public int $bestellungId) {}\n\n    public function handle(): void\n    {\n        // Rechnung erzeugen …\n    }\n}\n\nRechnungErzeugen::dispatch($bestellung->id);","pitfall":"Jobs können mehrfach laufen. Die Arbeit muss idempotent sein, also ein zweiter Lauf darf nichts doppelt tun.","lesson":"m50-l1","tested":false},{"id":"laravel-test","cat":"Betrieb","term":"Feature-Test","syntax":"$this->get('/pfad')->assertOk();","text":"Ruft Routen wie ein Browser auf und prüft Antworten und Datenbankzustand. RefreshDatabase setzt die Datenbank pro Test zurück.","code":"it('zeigt die Aufgabenliste', function () {\n    $user = User::factory()->create();\n\n    $this->actingAs($user)\n        ->get('/aufgaben')\n        ->assertOk();\n});","pitfall":"Tests gegen eine echte Entwicklungsdatenbank können Daten löschen. Für Tests eine eigene Datenbank verwenden.","lesson":"m51-l1","tested":false},{"id":"laravel-eloquent-crud","cat":"Datenbank","term":"Eloquent: create, update, delete, firstOrCreate","syntax":"$fillable = […]    Model::create([…])    $model->update([…])    firstOrCreate(…)    updateOrCreate(…)","text":"create legt einen Datensatz an, update ändert ihn, delete löscht ihn. firstOrCreate sucht oder legt an, updateOrCreate ändert oder legt an. Damit Massenzuweisung funktioniert, nennt das Model die erlaubten Felder in $fillable.","code":"class Aufgabe extends Model\n{\n    protected $fillable = ['titel', 'faellig', 'erledigt'];\n}\n\n$aufgabe = Aufgabe::create(['titel' => 'Bericht']);\n$aufgabe->update(['erledigt' => true]);\n$tag = Tag::firstOrCreate(['name' => 'wichtig']);\nAufgabe::updateOrCreate(['externe_id' => 7], ['titel' => 'Import']);\n$aufgabe->delete();\n\n$gefunden = Aufgabe::findOrFail($id);   // 404 bei unbekannter ID","pitfall":"Nie $guarded = [] mit ungeprüften Eingaben verwenden: Angreifer können sonst Felder wie is_admin setzen (Mass Assignment). Nur validierte Daten ($request->validated()) übergeben.","lesson":"m46-l2","tested":false},{"id":"laravel-query-builder","cat":"Datenbank","term":"Query Builder: where, join, groupBy, selectRaw","syntax":"DB::table(\"t\")->where(\"a\", \">\", 5)->orderBy(\"b\")->get()    ->join(…)    ->groupBy(…)","text":"Der Query Builder baut SQL fließend zusammen und bindet Werte automatisch als Parameter. Er eignet sich für Auswertungen und Abfragen ohne Model. Eloquent nutzt ihn intern, alle Methoden stehen daher auch dort bereit.","code":"$umsatz = DB::table('bestellungen')\n    ->join('kunden', 'kunden.id', '=', 'bestellungen.kunde_id')\n    ->where('bestellungen.status', 'bezahlt')\n    ->whereBetween('bestellungen.created_at', [now()->startOfMonth(), now()])\n    ->groupBy('kunden.land')\n    ->selectRaw('kunden.land, SUM(bestellungen.betrag) as summe')\n    ->orderByDesc('summe')\n    ->get();\n\n$sql = Aufgabe::where('erledigt', false)->toSql();   // zur Kontrolle","pitfall":"In selectRaw und whereRaw Nutzereingaben nie einsetzen, sondern als Bindings übergeben (whereRaw('a = ?', [$wert])). Sonst droht SQL-Injection.","lesson":"m46-l2","tested":false},{"id":"laravel-api-resource-routes","cat":"Routing","term":"Route::apiResource, only, except, fallback","syntax":"Route::apiResource('aufgaben', AufgabeController::class)->only(['index', 'show'])","text":"resource erzeugt alle sieben CRUD-Routen, apiResource lässt create und edit weg (keine Formulare). only und except wählen Routen aus, fallback fängt unbekannte Pfade ab. route:list zeigt das Ergebnis.","code":"Route::apiResource('aufgaben', AufgabeController::class)->only(['index', 'show', 'store']);\nRoute::apiResource('aufgaben.kommentare', KommentarController::class)->shallow();\n\nRoute::fallback(fn () => response()->json(['fehler' => 'Nicht gefunden'], 404));","pitfall":"Jede erzeugte Route ist ein Zugang. Mit only die tatsächlich benötigten auswählen und jede mit Anmeldung und Berechtigung absichern.","lesson":"m45-l2","tested":false},{"id":"laravel-policy","cat":"Sicherheit","term":"Policy: authorize und can","syntax":"php artisan make:policy AufgabePolicy --model=Aufgabe    $this->authorize(\"update\", $aufgabe)    @can","text":"Eine Policy bündelt die Berechtigungen für ein Model (view, update, delete). Im Controller prüft authorize, in Blade @can. Laravel findet die Policy zum Model automatisch.","code":"class AufgabePolicy\n{\n    public function update(User $user, Aufgabe $aufgabe): bool\n    {\n        return $user->id === $aufgabe->user_id;\n    }\n}\n\n// Controller\npublic function update(Request $request, Aufgabe $aufgabe)\n{\n    $this->authorize('update', $aufgabe);   // 403 bei Verbot\n    $aufgabe->update($request->validated());\n}\n\n// Route\nRoute::put('/aufgaben/{aufgabe}', …)->can('update', 'aufgabe');","pitfall":"Jede Aktion prüfen, auch lesende (index: nur eigene Daten zeigen, mit where user_id). Fehlende Prüfung ist die häufigste Ursache für „IDOR“-Lücken (fremde Datensätze per ID aufrufen).","lesson":"m47-l2","tested":false},{"id":"laravel-middleware-custom","cat":"Sicherheit","term":"Eigene Middleware und Alias (bootstrap/app.php)","syntax":"php artisan make:middleware NurAdmin    public function handle(Request $request, Closure $next)","text":"Middleware läuft vor oder nach dem Controller und kann Anfragen ablehnen, ändern oder protokollieren. Seit Laravel 11 registriert man Aliase und globale Middleware in bootstrap/app.php.","code":"class NurAdmin\n{\n    public function handle(Request $request, Closure $next): Response\n    {\n        abort_unless($request->user()?->istAdmin(), 403);\n        return $next($request);\n    }\n}\n\n// bootstrap/app.php\n->withMiddleware(function (Middleware $middleware) {\n    $middleware->alias(['admin' => NurAdmin::class]);\n})\n\n// routes\nRoute::middleware(['auth', 'admin'])->group(…);","pitfall":"Middleware ersetzt keine Policies. Sie prüft Gruppen von Routen, die Policy die konkrete Aktion auf einem Datensatz.","lesson":"m47-l2","tested":false},{"id":"laravel-events","cat":"Betrieb","term":"Events, Listener und Observer","syntax":"BestellungErstellt::dispatch($bestellung)    class Listener implements ShouldQueue    #[ObservedBy(AufgabeObserver::class)]","text":"Ein Event meldet, dass etwas passiert ist (Bestellung erstellt). Listener reagieren darauf, auf Wunsch im Hintergrund (ShouldQueue). Ein Observer reagiert auf Model-Ereignisse wie created, updated, deleted. So bleibt der Controller schlank.","code":"class BestellungErstellt\n{\n    use Dispatchable;\n    public function __construct(public Bestellung $bestellung) {}\n}\n\nclass BestaetigungSenden implements ShouldQueue\n{\n    public function handle(BestellungErstellt $event): void\n    {\n        Mail::to($event->bestellung->kunde)->send(new BestellungBestaetigt($event->bestellung));\n    }\n}\n\nBestellungErstellt::dispatch($bestellung);","pitfall":"Zu viele Observer machen den Ablauf unsichtbar. Für wichtige Fachprozesse lieber expliziten Code oder klar benannte Events.","lesson":"m50-l1","tested":false},{"id":"laravel-queue-worker","cat":"Betrieb","term":"Queue: queue:work, failed, retry","syntax":"php artisan queue:work --tries=3    php artisan queue:failed    php artisan queue:retry all    php artisan queue:restart","text":"Der Worker holt Jobs aus der Warteschlange und führt sie aus. Schlägt ein Job wiederholt fehl, landet er in failed_jobs und kann nach der Fehlerbehebung wiederholt werden. Nach einer Codeänderung muss der Worker mit queue:restart neu starten.","code":"php artisan queue:work --queue=mails,default --tries=3 --backoff=10\nphp artisan queue:failed\nphp artisan queue:retry all\nphp artisan queue:restart\n\n// Job\nclass RechnungErstellen implements ShouldQueue\n{\n    public int $tries = 3;\n    public array $backoff = [10, 60];\n    public function handle(): void { /* … */ }\n    public function failed(Throwable $e): void { /* Fehler melden */ }\n}","pitfall":"Auf dem Server den Worker mit einem Prozessmanager (Supervisor, systemd) dauerhaft laufen lassen. Jobs müssen wiederholbar sein (idempotent), damit ein zweiter Lauf keinen Schaden anrichtet.","lesson":"m50-l1","tested":false},{"id":"laravel-blade-layout","cat":"Blade-Templates","term":"Blade: Layouts, @include, @stack, @vite, @props","syntax":"<x-layout titel=\"…\">…</x-layout>    @include(\"teil\")    @push(\"scripts\")    @vite([…])    @props([…])","text":"Layout-Komponenten (<x-layout>) mit Slots sind der moderne Weg, Seiten zu rahmen. @include fügt Teilvorlagen ein, @push und @stack sammeln Skripte oder Stile aus Unterseiten. @vite bindet die mit Vite gebauten Dateien ein.","code":"{{-- resources/views/components/layout.blade.php --}}\n@props(['titel' => 'Rootpfad'])\n<!doctype html>\n<html lang=\"de\">\n<head>\n    <title>{{ $titel }}</title>\n    @vite(['resources/css/app.css', 'resources/js/app.js'])\n    @stack('kopf')\n</head>\n<body>\n    <main id=\"inhalt\">{{ $slot }}</main>\n    @include('teile.fuss')\n</body>\n</html>\n\n{{-- Verwendung --}}\n<x-layout titel=\"Aufgaben\">\n    @push('kopf') <meta name=\"robots\" content=\"noindex\"> @endpush\n    <h1>Aufgaben</h1>\n</x-layout>","pitfall":"{!! $text !!} gibt rohes HTML ohne Maskierung aus. Nur für eigenen, geprüften Inhalt verwenden, nie für Nutzereingaben. {{ }} maskiert automatisch.","lesson":"m56-l1","tested":false,"codeLang":"blade"},{"id":"laravel-session-flash","cat":"Controller","term":"Redirect, Flash-Meldung und Fehler zurückgeben","syntax":"return redirect()->route('x')->with('status', '…')    return back()->withErrors([…])->withInput()","text":"Nach einem erfolgreichen POST leitet man um (Post/Redirect/Get), damit ein Neuladen die Aktion nicht wiederholt. with legt eine Meldung für genau eine Folgeanfrage ab. Bei Fehlern geht es mit withErrors und withInput zurück ins Formular.","code":"public function store(AufgabeRequest $request): RedirectResponse\n{\n    $aufgabe = $request->user()->aufgaben()->create($request->validated());\n    return redirect()->route('aufgaben.show', $aufgabe)->with('status', 'Aufgabe gespeichert');\n}\n\n{{-- Blade --}}\n@if (session('status'))\n    <p role=\"status\">{{ session('status') }}</p>\n@endif","pitfall":"Meldungen mit role=\"status\" oder role=\"alert\" auszeichnen, damit Screenreader sie vorlesen. Nach dem Anmelden die Sitzung neu erzeugen (regenerate), das macht Laravel Fortify/Breeze bereits.","lesson":"m45-l3","tested":false},{"id":"laravel-upload-rules","cat":"Validierung","term":"Datei-Upload und Validierungsregeln","syntax":"'bild' => ['required', 'image', 'max:2048', 'mimes:jpg,png']    $request->file('bild')->store('bilder')","text":"Eine Datei wird wie ein Feld validiert: image, mimes, mimetypes, max (in Kilobyte), dimensions. store legt sie mit zufälligem Namen im Speicher (disk) ab. storage:link verknüpft den öffentlichen Ordner, wenn Dateien abrufbar sein sollen.","code":"$request->validate([\n    'titel' => ['required', 'string', 'max:120'],\n    'bild'  => ['nullable', 'image', 'mimes:jpg,jpeg,png,webp', 'max:2048', 'dimensions:max_width=4000'],\n    'tags'  => ['array', 'max:5'],\n    'tags.*' => ['string', 'distinct', 'max:30'],\n    'passwort' => ['required', Password::min(12)->letters()->numbers()->uncompromised(), 'confirmed'],\n]);\n\n$pfad = $request->file('bild')?->store('bilder', 'public');   // storage/app/public/bilder/…\n// php artisan storage:link","pitfall":"Dateinamen vom Nutzer nie übernehmen. Dateien mit Namen aus der Datenbank ausliefern, Typen serverseitig prüfen und private Dateien nicht im öffentlichen Ordner speichern.","lesson":"m57-l1","tested":false},{"id":"laravel-validation-rules","cat":"Validierung","term":"Häufige Regeln: required, nullable, in, unique, exists","syntax":"'x' => ['required', 'string', 'max:50', Rule::in([…]), 'unique:users,email', 'exists:kunden,id']","text":"required verlangt ein Feld, nullable erlaubt leer, sometimes prüft nur vorhandene Felder. in begrenzt auf eine Liste, unique und exists prüfen gegen die Datenbank, confirmed vergleicht mit feld_confirmation, after und before prüfen Datumswerte.","code":"$daten = $request->validate([\n    'status'   => ['required', Rule::in(['neu', 'offen', 'erledigt'])],\n    'kunde_id' => ['required', 'integer', 'exists:kunden,id'],\n    'mail'     => ['required', 'email:rfc,dns', Rule::unique('users', 'email')->ignore($user)],\n    'faellig'  => ['nullable', 'date', 'after:today'],\n    'agb'      => ['accepted'],\n]);","pitfall":"Fehlermeldungen in lang/de anpassen und verständlich formulieren. exists und unique sind keine Garantie gegen gleichzeitige Anfragen, zusätzlich einen Datenbank-Unique-Index setzen.","lesson":"m47-l1","tested":false},{"id":"laravel-many-to-many","cat":"Datenbank","term":"belongsToMany: attach, sync, toggle, Pivot","syntax":"$user->rollen()->attach($id)    ->sync([1, 2])    ->toggle($id)    withPivot(…)","text":"Viele-zu-viele-Beziehungen brauchen eine Zwischentabelle (Pivot). attach fügt hinzu, detach entfernt, sync gleicht auf genau die angegebene Liste ab, toggle wechselt. Zusätzliche Felder der Pivot-Tabelle liest man mit withPivot.","code":"// User-Model\npublic function rollen(): BelongsToMany\n{\n    return $this->belongsToMany(Rolle::class)->withPivot('gueltig_bis')->withTimestamps();\n}\n\n$user->rollen()->attach(3, ['gueltig_bis' => now()->addYear()]);\n$user->rollen()->sync([1, 2, 3]);\n$user->rollen()->detach(2);\n\nforeach ($user->rollen as $rolle) {\n    echo $rolle->pivot->gueltig_bis;\n}\n\nUser::whereHas('rollen', fn ($q) => $q->where('name', 'admin'))->get();","pitfall":"sync entfernt alle Verknüpfungen, die nicht in der Liste stehen. Mit syncWithoutDetaching nur hinzufügen. Tabellenname alphabetisch (rolle_user) oder explizit angeben.","lesson":"m46-l3","tested":false},{"id":"laravel-factory-seeder","cat":"Datenbank","term":"Factory, Seeder und fake()","syntax":"Aufgabe::factory()->count(10)->create()    php artisan db:seed --class=AufgabeSeeder","text":"Factories erzeugen Testdaten mit zufälligen Werten (fake()), Seeder befüllen die Datenbank reproduzierbar. States (z. B. erledigt()) variieren Datensätze. In Tests ersetzen Factories handgeschriebene Fixtures.","code":"class AufgabeFactory extends Factory\n{\n    public function definition(): array\n    {\n        return [\n            'titel'  => fake()->sentence(4),\n            'faellig' => fake()->dateTimeBetween('now', '+1 month'),\n            'user_id' => User::factory(),\n        ];\n    }\n    public function erledigt(): static\n    {\n        return $this->state(['erledigt' => true]);\n    }\n}\n\nAufgabe::factory()->count(10)->erledigt()->create();\n// php artisan db:seed --class=AufgabeSeeder","pitfall":"Seeder mit echten oder realistisch wirkenden personenbezogenen Daten gehören nicht in das Repository. fake()-Daten verwenden und Produktionsdaten nie in Tests kopieren.","lesson":"m46-l1","tested":false},{"id":"laravel-lang","cat":"Betrieb","term":"Übersetzungen: __(), lang-Dateien, trans_choice","syntax":"__('messages.willkommen')    __(':name hat Aufgaben', ['name' => $n])    trans_choice('aufgaben', 3)","text":"Texte stehen in lang/de/*.php oder lang/de.json und werden mit __() abgerufen. Platzhalter beginnen mit einem Doppelpunkt. trans_choice wählt Einzahl oder Mehrzahl. app()->setLocale stellt die Sprache pro Anfrage ein.","code":"// lang/de/messages.php\nreturn [\n    'willkommen' => 'Willkommen, :name!',\n    'aufgaben'   => '{0} Keine Aufgaben|{1} Eine Aufgabe|[2,*] :count Aufgaben',\n];\n\necho __('messages.willkommen', ['name' => 'Mia']);\necho trans_choice('messages.aufgaben', 3);\n\n// config/app.php: 'locale' => 'de', 'fallback_locale' => 'en'\n// php artisan lang:publish","pitfall":"Texte nie im Code zusammensetzen, die Satzstellung ist in anderen Sprachen anders. Immer ganze Sätze mit Platzhaltern übersetzen.","lesson":"m56-l1","tested":false},{"id":"laravel-prevent-lazy","cat":"Datenbank","term":"preventLazyLoading und shouldBeStrict","syntax":"Model::preventLazyLoading(! app()->isProduction())    Model::shouldBeStrict()","text":"Diese Schalter in AppServiceProvider::boot machen Fehler in der Entwicklung sichtbar: preventLazyLoading wirft eine Ausnahme bei versteckten N+1-Abfragen, shouldBeStrict prüft zusätzlich Mass Assignment und fehlende Attribute.","code":"// app/Providers/AppServiceProvider.php\npublic function boot(): void\n{\n    Model::shouldBeStrict(! $this->app->isProduction());\n    // oder einzeln\n    Model::preventLazyLoading(! $this->app->isProduction());\n    Model::preventSilentlyDiscardingAttributes(! $this->app->isProduction());\n}","pitfall":"In Produktion nicht aktivieren: Dort würde ein übersehener Fall zu Fehlerseiten statt zu Hinweisen führen. In Tests und Entwicklung dagegen unbedingt.","lesson":"m46-l4","tested":false},{"id":"laravel-exceptions","cat":"Betrieb","term":"abort, Ausnahmebehandlung und eigene Fehlerseiten","syntax":"abort(404)    abort_if($bedingung, 403)    ->withExceptions(function (Exceptions $exceptions) { … })","text":"abort bricht mit einem HTTP-Status ab. Eigene Fehlerseiten legt man als resources/views/errors/404.blade.php an. Zentrales Verhalten (Berichten, Rendern, Ignorieren) stellt man in bootstrap/app.php mit withExceptions ein.","code":"abort_if(! $aufgabe->gehoertZu($user), 403);\nabort_unless($aufgabe, 404);\n\n// bootstrap/app.php\n->withExceptions(function (Exceptions $exceptions) {\n    $exceptions->render(function (BestandReichtNicht $e, Request $request) {\n        return $request->expectsJson()\n            ? response()->json(['fehler' => $e->getMessage()], 422)\n            : back()->withErrors(['menge' => $e->getMessage()]);\n    });\n    $exceptions->dontReport([BestandReichtNicht::class]);\n})","pitfall":"APP_DEBUG muss in Produktion false sein, sonst erscheinen Stacktraces und Konfigurationswerte für jeden Besucher.","lesson":"m51-l4","tested":false},{"id":"laravel-optimize","cat":"Betrieb","term":"optimize, config:cache, down, about","syntax":"php artisan optimize    php artisan config:cache route:cache view:cache    php artisan down    php artisan about","text":"Für den Produktivbetrieb werden Konfiguration, Routen und Views vorab zwischengespeichert (optimize). down schaltet die Anwendung in den Wartungsmodus, up zurück. about zeigt Umgebung, Versionen und Treiber auf einen Blick.","code":"composer install --no-dev --optimize-autoloader\nphp artisan migrate --force\nphp artisan optimize\nphp artisan about\n\nphp artisan down --secret=\"wartung-xyz\"\nphp artisan up\nphp artisan optimize:clear","pitfall":"Nach config:cache liefert env() außerhalb von config/ nichts mehr. APP_KEY, APP_DEBUG=false und Datei-Rechte vor dem Livegang prüfen. Die .env gehört nie ins Repository.","lesson":"m51-l4","tested":false},{"id":"laravel-test-assertions","cat":"Betrieb","term":"Feature-Test: Assertions für Antwort, Datenbank, Sitzung","syntax":"$this->postJson(…)->assertCreated()->assertJsonPath(…)    assertDatabaseHas    assertSessionHasErrors","text":"Feature-Tests rufen die App wie ein Browser auf und prüfen Antwort (assertOk, assertRedirect, assertJson), Datenbank (assertDatabaseHas, assertDatabaseMissing) und Validierung (assertSessionHasErrors, assertInvalid). actingAs meldet einen Nutzer an.","code":"it('legt eine Aufgabe an', function () {\n    $user = User::factory()->create();\n\n    $this->actingAs($user)\n        ->postJson('/api/aufgaben', ['titel' => 'Bericht'])\n        ->assertCreated()\n        ->assertJsonPath('data.titel', 'Bericht');\n\n    $this->assertDatabaseHas('aufgaben', ['titel' => 'Bericht', 'user_id' => $user->id]);\n});\n\nit('verweigert fremden Zugriff', function () {\n    $aufgabe = Aufgabe::factory()->create();\n    $this->actingAs(User::factory()->create())\n        ->getJson(\"/api/aufgaben/{$aufgabe->id}\")\n        ->assertForbidden();\n});","pitfall":"Auch die Verbote testen (fremde Daten, nicht angemeldet, ungültige Eingaben). Die meisten Sicherheitslücken entstehen dort, wo kein Test existierte.","lesson":"m51-l1","tested":false},{"id":"laravel-hash-crypt","cat":"Sicherheit","term":"Hash, Crypt und verschlüsselte Casts","syntax":"Hash::make($pw)    Hash::check($pw, $hash)    Crypt::encryptString($text)    protected $casts = [\"x\" => \"encrypted\"]","text":"Passwörter werden mit Hash::make gehasht (bcrypt oder Argon2), nie verschlüsselt. Hash::check vergleicht. Daten, die man wieder lesen muss (Tokens, Notizen), verschlüsselt man mit Crypt oder dem Cast encrypted. Der Schlüssel ist APP_KEY.","code":"$hash = Hash::make($request->password);\nif (Hash::check($eingabe, $user->password)) { /* ok */ }\nif (Hash::needsRehash($user->password)) { $user->update(['password' => Hash::make($eingabe)]); }\n\nclass Konto extends Model\n{\n    protected function casts(): array\n    {\n        return ['iban' => 'encrypted', 'passwort' => 'hashed'];\n    }\n}","pitfall":"Geht der APP_KEY verloren, sind verschlüsselte Daten unlesbar. Sicher aufbewahren und nie committen. Verschlüsselte Spalten lassen sich nicht in der Datenbank durchsuchen.","lesson":"m47-l2","tested":false},{"id":"laravel-artisan-db","cat":"Artisan (Terminal)","term":"migrate, seed, tinker, route:list","syntax":"php artisan migrate    php artisan migrate:fresh --seed    php artisan tinker    php artisan route:list","text":"migrate führt neue Migrationen aus, migrate:fresh löscht alle Tabellen und baut sie neu (nur Entwicklung), db:seed füllt Testdaten, tinker öffnet eine Konsole für Experimente, route:list zeigt alle Routen.","code":"php artisan migrate\nphp artisan migrate:fresh --seed\nphp artisan route:list --path=api\nphp artisan tinker\n>>> App\\Models\\User::count()","pitfall":"migrate:fresh löscht alle Daten. Auf Produktionssystemen ist es ohne --force gesperrt, trotzdem nie dort ausführen.","lesson":"m46-l1","tested":false},{"id":"laravel-route-group","cat":"Routing","term":"Route::group, prefix, middleware, name","syntax":"Route::prefix('admin')->name('admin.')->middleware('auth')->group(fn () => …)","text":"Fasst Routen mit gemeinsamen Eigenschaften zusammen: Pfadpräfix, Namenspräfix, Middleware. Das hält die Routendatei kurz und verhindert vergessene Schutzregeln.","code":"Route::middleware(['auth', 'verified'])->prefix('konto')->name('konto.')->group(function () {\n    Route::get('/', [KontoController::class, 'show'])->name('show');\n    Route::put('/', [KontoController::class, 'update'])->name('update');\n});","pitfall":"Wer eine Route außerhalb der Gruppe anlegt, verliert die Middleware. route:list regelmäßig prüfen.","lesson":"m45-l2","tested":false},{"id":"laravel-request","cat":"Controller","term":"Request: validate, input, user","syntax":"$request->validate([…])    $request->input('feld')    $request->user()","text":"Das Request-Objekt liefert Eingaben, Dateien und den angemeldeten Nutzer. validate() prüft Eingaben direkt, bei Fehlern leitet Laravel zurück und füllt $errors.","code":"public function update(Request $request): RedirectResponse\n{\n    $daten = $request->validate([\n        'name' => ['required', 'string', 'max:80'],\n        'mail' => ['required', 'email', Rule::unique('users')->ignore($request->user())],\n    ]);\n    $request->user()->update($daten);\n    return back()->with('status', 'Gespeichert');\n}","pitfall":"unique-Regeln beim Aktualisieren mit ignore() für den aktuellen Datensatz versehen, sonst scheitert das Speichern am eigenen Eintrag.","lesson":"m47-l1","tested":false},{"id":"laravel-blade-forms","cat":"Blade-Templates","term":"@csrf, @method, @error, old()","syntax":"<form method=\"POST\">@csrf @method(\"PUT\")    @error(\"feld\") … @enderror    old(\"feld\")","text":"@csrf fügt den Schutz gegen Cross-Site-Request-Forgery ein, @method täuscht PUT oder DELETE vor (HTML-Formulare kennen nur GET und POST), @error zeigt Fehler eines Felds, old() füllt Felder nach einem Fehler wieder aus.","code":"<form method=\"POST\" action=\"{{ route('konto.update') }}\">\n    @csrf\n    @method('PUT')\n    <label for=\"name\">Name</label>\n    <input id=\"name\" name=\"name\" value=\"{{ old('name', $user->name) }}\"\n           @error('name') aria-invalid=\"true\" aria-describedby=\"name-fehler\" @enderror>\n    @error('name')\n        <p id=\"name-fehler\" role=\"alert\">{{ $message }}</p>\n    @enderror\n    <button type=\"submit\">Speichern</button>\n</form>","pitfall":"Passwörter und Zahlungsdaten nie mit old() zurückfüllen. Mit dontFlash in der Exception-Konfiguration ausschließen (Standard bei password).","lesson":"m56-l4","tested":false,"codeLang":"blade"},{"id":"laravel-auth-blade","cat":"Blade-Templates","term":"@auth, @guest, @can","syntax":"@auth … @endauth    @guest … @endguest    @can(\"update\", $aufgabe) … @endcan","text":"Zeigen Teile der Seite je nach Anmeldestatus oder Berechtigung. @can fragt die Policy ab, die auch im Controller gilt.","code":"@auth\n    <p>Angemeldet als {{ auth()->user()->name }}</p>\n@endauth\n@guest\n    <a href=\"{{ route('login') }}\">Anmelden</a>\n@endguest\n@can('update', $aufgabe)\n    <a href=\"{{ route('aufgaben.edit', $aufgabe) }}\">Bearbeiten</a>\n@endcan","pitfall":"Ausgeblendete Links schützen nicht. Die Berechtigung muss zusätzlich im Controller oder per Policy durchgesetzt werden.","lesson":"m47-l3","tested":false,"codeLang":"blade"},{"id":"laravel-scope-cast","cat":"Datenbank","term":"Scopes, Casts und Accessors","syntax":"#[Scope] public function offen(Builder $q)    protected function casts(): array","text":"Scopes bündeln wiederkehrende Bedingungen (Aufgabe::offen()->get()). Casts wandeln Spalten automatisch um (Datum, JSON, Enum, bool). Accessors berechnen Werte beim Lesen.","code":"class Aufgabe extends Model\n{\n    protected function casts(): array\n    {\n        return ['faellig' => 'date', 'erledigt' => 'boolean', 'status' => StatusEnum::class];\n    }\n\n    #[Scope]\n    protected function offen(Builder $query): void\n    {\n        $query->where('erledigt', false);\n    }\n\n    protected function titelGross(): Attribute\n    {\n        return Attribute::get(fn () => mb_strtoupper($this->titel));\n    }\n}\n\n$offene = Aufgabe::offen()->orderBy('faellig')->get();","pitfall":"Das Attribut #[Scope] gibt es seit Laravel 12. In älteren Versionen heißt die Methode scopeOffen() ohne Attribut.","lesson":"m46-l2","tested":false},{"id":"laravel-softdeletes","cat":"Datenbank","term":"SoftDeletes","syntax":"use SoftDeletes;    $table->softDeletes();    withTrashed()  restore()  forceDelete()","text":"Gelöschte Datensätze bekommen nur einen Zeitstempel (deleted_at) und verschwinden aus normalen Abfragen. Mit withTrashed() sieht man sie, mit restore() holt man sie zurück.","code":"// Migration\n$table->softDeletes();\n\n// Model\nclass Aufgabe extends Model { use SoftDeletes; }\n\n$aufgabe->delete();                       // Papierkorb\nAufgabe::onlyTrashed()->restore();         // zurückholen\nAufgabe::withTrashed()->find($id)->forceDelete();  // endgültig","pitfall":"Soft Delete ist keine Löschung im Sinne der DSGVO. Personenbezogene Daten müssen nach der Aufbewahrungsfrist wirklich entfernt werden (Pruning).","lesson":"m58-l4","tested":false},{"id":"laravel-collection","cat":"Datenbank","term":"Collections","syntax":"collect($liste)->map(…)->filter(…)->groupBy(…)->sum(\"feld\")","text":"Fließende Schnittstelle für Listen, die auch Eloquent-Ergebnisse sind. Methoden wie map, filter, pluck, groupBy, sortBy, sum und pipe lassen sich verketten.","code":"$summe = $bestellungen\n    ->where('status', 'bezahlt')\n    ->groupBy('kunde_id')\n    ->map(fn ($gruppe) => $gruppe->sum('betrag'))\n    ->sortDesc();\n\n$namen = $nutzer->pluck('name', 'id');","pitfall":"Collection-Methoden arbeiten im Speicher. Große Tabellen besser in der Datenbank filtern und aggregieren (where, sum) oder mit lazy() / chunk() lesen.","lesson":"m46-l4","tested":false},{"id":"laravel-paginate","cat":"Datenbank","term":"paginate und Links","syntax":"Aufgabe::paginate(15)    {{ $aufgaben->links() }}","text":"Teilt Ergebnisse in Seiten und liefert die Navigation mit. simplePaginate spart die Gesamtzahl-Abfrage, cursorPaginate ist für sehr große Tabellen geeignet.","code":"$aufgaben = Aufgabe::query()->latest()->paginate(15)->withQueryString();\n\n{{-- Blade --}}\n@foreach ($aufgaben as $aufgabe) … @endforeach\n{{ $aufgaben->links() }}","pitfall":"Nach einem Filter withQueryString() aufrufen, sonst gehen Suchparameter beim Blättern verloren.","lesson":"m46-l4","tested":false},{"id":"laravel-transaction","cat":"Datenbank","term":"DB::transaction","syntax":"DB::transaction(function () { … });","text":"Führt mehrere Datenbankänderungen als Einheit aus. Bei einer Ausnahme wird alles zurückgerollt. Mit lockForUpdate() sperrt man Zeilen, die man liest und gleich ändert.","code":"DB::transaction(function () use ($von, $nach, $betrag) {\n    $a = Konto::lockForUpdate()->findOrFail($von);\n    $b = Konto::lockForUpdate()->findOrFail($nach);\n    abort_if($a->stand < $betrag, 422, 'Guthaben reicht nicht');\n    $a->decrement('stand', $betrag);\n    $b->increment('stand', $betrag);\n});","pitfall":"Jobs und Mails innerhalb einer Transaktion erst nach dem Commit starten (afterCommit), sonst liest der Worker noch nicht gespeicherte Daten.","lesson":"m49-l3","tested":false},{"id":"laravel-cache","cat":"Betrieb","term":"Cache::remember","syntax":"Cache::remember('schluessel', 600, fn () => …)","text":"Liefert den gespeicherten Wert oder berechnet ihn neu und legt ihn für die angegebene Zeit (in Sekunden) ab. Für Auflistungen, die teuer zu berechnen sind.","code":"$beliebte = Cache::remember('aufgaben:beliebt', now()->addMinutes(10), function () {\n    return Aufgabe::withCount('kommentare')->orderByDesc('kommentare_count')->limit(5)->get();\n});\n\nCache::forget('aufgaben:beliebt');","pitfall":"Gecachte Daten können veralten. Schlüssel eindeutig benennen, bei Änderung gezielt löschen. Keine nutzerspezifischen Daten unter einem gemeinsamen Schlüssel ablegen.","lesson":"m50-l2","tested":false},{"id":"laravel-storage-mail","cat":"Betrieb","term":"Storage, Mail und Notification","syntax":"Storage::disk('local')->put(…)    Mail::to($user)->send(new …)    $user->notify(new …)","text":"Storage abstrahiert Dateispeicher (lokal, S3), Mail::to()->send() versendet Mailables (mit ->queue() im Hintergrund), notify() verschickt Benachrichtigungen über Kanäle wie Mail, Datenbank oder Slack.","code":"$pfad = $request->file('beleg')->store('belege', 'local');\nMail::to($user)->queue(new BestellungBestaetigt($bestellung));\n$user->notify(new RechnungVersendet($rechnung));","pitfall":"Hochgeladene Dateien nie im öffentlichen Ordner mit dem Originalnamen ablegen. Typ und Größe prüfen, Namen selbst vergeben.","lesson":"m57-l1","tested":false},{"id":"laravel-http-client","cat":"APIs","term":"Http-Client","syntax":"Http::timeout(5)->retry(2, 200)->get($url)->throw()->json()","text":"Bequemer HTTP-Client für Fremdsysteme. timeout begrenzt die Wartezeit, retry wiederholt bei Fehlern, throw() wirft bei 4xx/5xx eine Ausnahme, Http::fake() ersetzt Aufrufe im Test.","code":"$antwort = Http::withToken(config('dienste.wetter.token'))\n    ->timeout(5)\n    ->retry(2, 200, throw: false)\n    ->get('https://api.example.org/wetter', ['ort' => 'Berlin'])\n    ->throw();\n\n$temperatur = $antwort->json('aktuell.temperatur');","pitfall":"Zugangsdaten nie im Code, sondern in .env und config(). Nutzereingaben nicht ungeprüft in URLs setzen (SSRF).","lesson":"m59-l1","tested":false},{"id":"laravel-sanctum","cat":"APIs","term":"Sanctum-Token","syntax":"$user->createToken('name', ['aufgaben:lesen'])->plainTextToken    auth:sanctum","text":"Leichte Token-Anmeldung für APIs und Single-Page-Apps. Ein Token trägt Fähigkeiten (abilities). Die Middleware auth:sanctum schützt Routen, tokenCan() prüft die Fähigkeit.","code":"Route::middleware('auth:sanctum')->get('/aufgaben', function (Request $request) {\n    abort_unless($request->user()->tokenCan('aufgaben:lesen'), 403);\n    return AufgabeResource::collection($request->user()->aufgaben);\n});\n\n$token = $user->createToken('handy', ['aufgaben:lesen'])->plainTextToken;","pitfall":"Das Klartext-Token wird nur einmal angezeigt. In der Datenbank steht nur der Hash. Tokens mit Ablaufdatum und kleinen Rechten ausstellen.","lesson":"m48-l2","tested":false},{"id":"laravel-rate-limit","cat":"APIs","term":"Rate Limiting (throttle)","syntax":"RateLimiter::for('api', fn (Request $r) => Limit::perMinute(60)->by(…))    ->middleware('throttle:api')","text":"Begrenzt die Anfragen pro Zeitraum und Nutzer oder IP. Bei Überschreitung antwortet Laravel mit Status 429 und Retry-After.","code":"RateLimiter::for('login', function (Request $request) {\n    return Limit::perMinute(5)->by($request->input('email') . '|' . $request->ip());\n});\n\nRoute::post('/login', …)->middleware('throttle:login');","pitfall":"Hinter einem Proxy ist die IP sonst immer die des Proxys. TrustProxies korrekt konfigurieren, sonst gilt das Limit für alle gemeinsam.","lesson":"m48-l3","tested":false},{"id":"laravel-schedule","cat":"Betrieb","term":"Scheduler und Artisan-Command","syntax":"Schedule::command('berichte:senden')->dailyAt('07:00')","text":"Zeitgesteuerte Aufgaben werden in routes/console.php beschrieben. Ein einziger Cron-Eintrag (php artisan schedule:run jede Minute) startet sie. Eigene Befehle entstehen mit make:command.","code":"// routes/console.php\nSchedule::command('berichte:senden')->dailyAt('07:00')->withoutOverlapping()->onOneServer();\n\n// Crontab\n* * * * * cd /pfad/zum/projekt && php artisan schedule:run >> /dev/null 2>&1","pitfall":"Bei mehreren Servern läuft die Aufgabe sonst mehrfach. onOneServer() und withoutOverlapping() einsetzen.","lesson":"m50-l4","tested":false},{"id":"laravel-config-env","cat":"Betrieb","term":"config() und env()","syntax":"config('app.name')    env('APP_KEY')","text":"env() liest Umgebungsvariablen aus .env und gehört nur in die Dateien unter config/. Im restlichen Code liest man Werte mit config(). So funktioniert das Zwischenspeichern der Konfiguration (config:cache).","code":"// config/dienste.php\nreturn ['wetter' => ['token' => env('WETTER_TOKEN')]];\n\n// im Code\n$token = config('dienste.wetter.token');","pitfall":"Nach config:cache liefert env() außerhalb von config/ immer null. Das ist eine häufige Fehlerquelle in der Produktion.","lesson":"m51-l4","tested":false},{"id":"laravel-pest","cat":"Betrieb","term":"Pest: Datenbank, Fakes, Zeit","syntax":"uses(RefreshDatabase::class);    Mail::fake();    $this->travelTo(now()->addDay());","text":"RefreshDatabase setzt die Datenbank pro Test zurück. fake() ersetzt Mail, Queue, Event und Http, damit nichts wirklich verschickt wird. travelTo stellt die Uhr, um zeitabhängiges Verhalten zu prüfen.","code":"uses(RefreshDatabase::class);\n\nit('sendet eine Bestätigung', function () {\n    Mail::fake();\n    $user = User::factory()->create();\n\n    $this->actingAs($user)->post('/bestellungen', ['artikel' => 1])->assertRedirect();\n\n    Mail::assertQueued(BestellungBestaetigt::class);\n});","pitfall":"Tests mit Fakes prüfen, dass etwas ausgelöst wurde, nicht dass der Versand wirklich funktioniert. Dafür gibt es wenige gezielte Integrationstests.","lesson":"m51-l2","tested":false}]},{"id":"java","label":"Java","codeLang":"java","intro":"Statisch typisierte, objektorientierte Sprache. Jede Anweisung endet mit Semikolon, Blöcke stehen in geschweiften Klammern.","notice":"Die Beispiele mit Markierung sind mit Java 26 ausgeführt und geprüft. Spring- und JUnit-Ausschnitte brauchen ein Projekt mit den passenden Abhängigkeiten und werden nur gezeigt.","runner":"Java","entries":[{"id":"java-main","cat":"Grundlagen","term":"Hauptprogramm","syntax":"public static void main(String[] args)","text":"Startpunkt eines Programms. Die Klasse trägt den Namen der Datei. Mit „java Main.java“ lässt sich eine einzelne Datei direkt ausführen.","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Hallo Welt\");\n    }\n}","out":"Hallo Welt","pitfall":"Dateiname und öffentliche Klasse müssen übereinstimmen: Main.java enthält public class Main.","lesson":"java-m7-l1","tested":true},{"id":"java-types","cat":"Typen","term":"Primitive Typen","syntax":"int  long  double  boolean  char","text":"Primitive Typen speichern den Wert direkt. int ist ganzzahlig (±2,1 Mrd.), long für größere Zahlen (Endung L), double für Kommazahlen, boolean für wahr/falsch.","code":"int a = 7;\nlong gross = 3_000_000_000L;\ndouble d = 7 / 2;\ndouble e = 7 / 2.0;\nSystem.out.println(d + \" \" + e + \" \" + gross);","out":"3.0 3.5 3000000000","pitfall":"7 / 2 ist bei ganzen Zahlen 3, nicht 3,5. Mindestens ein Operand muss double sein. Für Geld BigDecimal statt double nehmen.","lesson":"java-m7-l2","tested":true},{"id":"java-var","cat":"Typen","term":"var","syntax":"var name = ausdruck;","text":"Lässt den Compiler den Typ der lokalen Variablen ermitteln. Der Typ steht danach genauso fest wie bei ausdrücklicher Angabe.","code":"var liste = new ArrayList<String>();\nliste.add(\"a\");\nvar zahl = 42;\nSystem.out.println(liste + \" \" + zahl);","out":"[a] 42","pitfall":"var nur nutzen, wenn der Typ aus der rechten Seite klar ablesbar ist. Es gibt kein var für Felder und Parameter.","lesson":"java-m7-l2","tested":true},{"id":"java-string","cat":"Strings","term":"String-Methoden","syntax":"length()  charAt()  substring()  equals()  strip()  split()","text":"Strings sind unveränderlich: jede Methode liefert einen neuen String. Inhalte vergleicht man mit equals(), nicht mit ==.","code":"String s = \"  Hallo Welt \";\nSystem.out.println(s.strip().toUpperCase());\nSystem.out.println(\"a\".equals(\"a\") + \" \" + \"Hallo\".substring(1, 3));\nSystem.out.println(String.join(\"-\", \"a b c\".split(\" \")));","out":"HALLO WELT\ntrue al\na-b-c","pitfall":"== vergleicht Referenzen, nicht Inhalt. Bei new String(\"a\") == \"a\" ist das Ergebnis false.","lesson":"java-m7-l3","tested":true},{"id":"java-textblock","cat":"Strings","term":"Textblock und formatted","syntax":"\"\"\"\n  Text\n  \"\"\"","text":"Mehrzeiliger Text zwischen drei Anführungszeichen. Die gemeinsame Einrückung wird entfernt. formatted() setzt Werte wie bei printf ein.","code":"String json = \"\"\"\n    {\"name\": \"%s\", \"alter\": %d}\n    \"\"\".formatted(\"Ada\", 36);\nSystem.out.print(json);","out":"{\"name\": \"Ada\", \"alter\": 36}","pitfall":"Nie Nutzereingaben auf diese Weise in JSON, HTML oder SQL einsetzen. Dafür Bibliotheken oder PreparedStatement verwenden.","lesson":"java-m7-l3","tested":true},{"id":"java-if-switch","cat":"Kontrollfluss","term":"switch-Ausdruck","syntax":"var x = switch (wert) { case A, B -> … ; default -> …; };","text":"Gibt einen Wert zurück, hat keinen Durchfall-Effekt und prüft bei enums und sealed Typen auf Vollständigkeit. Mit -> statt : entfällt das break.","code":"String tag = \"SA\";\nString art = switch (tag) {\n    case \"SA\", \"SO\" -> \"Wochenende\";\n    default -> \"Werktag\";\n};\nSystem.out.println(art);","out":"Wochenende","pitfall":"Ohne default muss der switch bei Strings und Zahlen trotzdem alle Fälle abdecken, sonst Compilerfehler. Bei enums reicht eine vollständige Liste.","lesson":"java-m7-l4","tested":true},{"id":"java-for","cat":"Kontrollfluss","term":"for und for-each","syntax":"for (int i = 0; i < n; i++) { … }    for (var x : liste) { … }","text":"Die klassische for-Schleife zählt, die erweiterte for-Schleife läuft über alle Elemente einer Sammlung. while läuft, solange die Bedingung gilt.","code":"int summe = 0;\nfor (int i = 1; i <= 4; i++) summe += i;\nfor (var s : List.of(\"a\", \"b\")) System.out.print(s);\nSystem.out.println(\" \" + summe);","out":"ab 10","pitfall":"In einer for-each-Schleife darf man die Sammlung nicht verändern (ConcurrentModificationException). Dafür removeIf() oder einen Iterator verwenden.","lesson":"java-m9-l4","tested":true},{"id":"java-class","cat":"Klassen","term":"class, Konstruktor, Methoden","syntax":"class Name { private Typ feld; Name(Typ f) { … } }","text":"Eine Klasse bündelt Daten (Felder) und Verhalten (Methoden). Der Konstruktor hat den Namen der Klasse. private schützt Felder, Zugriff erfolgt über Methoden.","code":"class Konto {\n    private int stand;\n    void einzahlen(int betrag) {\n        if (betrag <= 0) throw new IllegalArgumentException(\"Betrag muss positiv sein\");\n        stand += betrag;\n    }\n    int stand() { return stand; }\n}\nKonto k = new Konto();\nk.einzahlen(50);\nSystem.out.println(k.stand());","out":"50","pitfall":"Felder nicht public machen. Sonst kann jeder den Zustand ohne Prüfung ändern.","lesson":"java-m8-l1","tested":true},{"id":"java-interface","cat":"Klassen","term":"interface und extends","syntax":"interface Name { Typ methode(); }    class A implements Name","text":"Ein Interface legt fest, was eine Klasse können muss. Eine Klasse kann mehrere Interfaces implementieren, aber nur von einer Klasse erben (extends).","code":"interface Tier { String laut(); }\nclass Hund implements Tier {\n    public String laut() { return \"Wuff\"; }\n}\nTier t = new Hund();\nSystem.out.println(t.laut());","out":"Wuff","pitfall":"Methoden eines Interfaces sind automatisch public. Beim Implementieren muss public vor der Methode stehen.","lesson":"java-m8-l3","tested":true},{"id":"java-record","cat":"Klassen","term":"record","syntax":"record Name(Typ a, Typ b) { }","text":"Kompakte, unveränderliche Datenklasse. Konstruktor, Zugriffsmethoden, equals, hashCode und toString entstehen automatisch. Im kompakten Konstruktor lässt sich prüfen.","code":"record Punkt(int x, int y) {\n    Punkt {\n        if (x < 0) throw new IllegalArgumentException(\"x < 0\");\n    }\n}\nvar p = new Punkt(1, 2);\nSystem.out.println(p + \" \" + p.x() + \" \" + p.equals(new Punkt(1, 2)));","out":"Punkt[x=1, y=2] 1 true","pitfall":"Records sind flach unveränderlich. Enthält ein Record eine veränderliche Liste, bleibt die Liste veränderlich. Mit List.copyOf() absichern.","lesson":"java-m8-l4","tested":true},{"id":"java-enum","cat":"Klassen","term":"enum","syntax":"enum Name { A, B, C }","text":"Feste Menge benannter Werte. Enums können Felder und Methoden haben und eignen sich gut für switch.","code":"enum Status {\n    OFFEN(\"offen\"), FERTIG(\"fertig\");\n    private final String text;\n    Status(String text) { this.text = text; }\n    String text() { return text; }\n}\nSystem.out.println(Status.valueOf(\"FERTIG\").text() + \" \" + Status.values().length);","out":"fertig 2","pitfall":"valueOf wirft bei unbekanntem Namen eine IllegalArgumentException. Eingaben von außen abfangen oder vorher prüfen.","lesson":"java-m8-l4","tested":true},{"id":"java-sealed","cat":"Klassen","term":"sealed interface mit Pattern Matching","syntax":"sealed interface Form permits A, B { }","text":"Legt fest, welche Typen ein Interface implementieren dürfen. Ein switch über alle erlaubten Typen braucht dann kein default, und der Compiler meldet fehlende Fälle.","code":"public class Main {\n    sealed interface Form permits Kreis, Quadrat {}\n    record Kreis(double r) implements Form {}\n    record Quadrat(double a) implements Form {}\n\n    static double flaeche(Form f) {\n        return switch (f) {\n            case Kreis k -> Math.PI * k.r() * k.r();\n            case Quadrat q -> q.a() * q.a();\n        };\n    }\n\n    public static void main(String[] args) {\n        System.out.println(flaeche(new Quadrat(3)));\n    }\n}","out":"9.0","pitfall":"Kommt ein neuer Typ hinzu, bricht jeder switch ohne default beim Kompilieren. Das ist gewollt: kein Fall wird vergessen.","lesson":"java-m25-l2","tested":true},{"id":"java-pattern","cat":"Typen","term":"instanceof-Pattern und Record-Pattern","syntax":"if (o instanceof String s) { … }    case Punkt(int x, int y) ->","text":"Prüft den Typ und bindet das Ergebnis gleich an eine Variable. Record-Pattern zerlegen einen Record direkt in seine Komponenten.","code":"record Punkt(int x, int y) {}\nObject o = new Punkt(3, 4);\nif (o instanceof Punkt(int x, int y) && x < y) {\n    System.out.println(\"x=\" + x + \", y=\" + y);\n}\nObject s = \"Text\";\nif (s instanceof String t) System.out.println(t.length());","out":"x=3, y=4\n4","pitfall":"Die Pattern-Variable gilt nur dort, wo der Compiler den Typ sicher kennt (im if-Zweig, nicht danach).","lesson":"java-m25-l1","tested":true},{"id":"java-collections","cat":"Sammlungen","term":"List, Set, Map","syntax":"List<String>  Set<String>  Map<String, Integer>","text":"List behält die Reihenfolge und erlaubt Doppelte, Set kennt jedes Element nur einmal, Map verknüpft Schlüssel mit Werten. List.of und Map.of liefern unveränderliche Sammlungen.","code":"var liste = new ArrayList<>(List.of(\"b\", \"a\", \"b\"));\nvar menge = new TreeSet<>(liste);\nvar zaehler = new TreeMap<String, Integer>();\nfor (var s : liste) zaehler.merge(s, 1, Integer::sum);\nSystem.out.println(liste + \" \" + menge + \" \" + zaehler);","out":"[b, a, b] [a, b] {a=1, b=2}","pitfall":"List.of() ist unveränderlich: add() wirft UnsupportedOperationException. Für eine veränderbare Kopie new ArrayList<>(…) benutzen.","lesson":"java-m9-l1","tested":true},{"id":"java-generics","cat":"Sammlungen","term":"Generics","syntax":"class Kiste<T> { … }    <T extends Comparable<T>> T max(List<T> l)","text":"Typparameter lassen Klassen und Methoden für verschiedene Typen arbeiten, ohne den Typ zu verlieren. Mit extends lässt sich eine Fähigkeit voraussetzen.","code":"static <T extends Comparable<T>> T groesster(List<T> liste) {\n    T max = liste.get(0);\n    for (T t : liste) if (t.compareTo(max) > 0) max = t;\n    return max;\n}\npublic static void main(String[] args) {\n    System.out.println(groesster(List.of(3, 9, 4)) + \" \" + groesster(List.of(\"a\", \"z\")));\n}","out":"9 z","pitfall":"Generische Typen sind zur Laufzeit gelöscht (Type Erasure). new T() und instanceof List<String> sind nicht möglich.","lesson":"java-m9-l3","tested":true},{"id":"java-lambda","cat":"Funktional","term":"Lambda und Methodenreferenz","syntax":"(a, b) -> a + b    Klasse::methode","text":"Ein Lambda ist eine Kurzform für eine Funktion, die als Wert übergeben wird. Es passt zu jedem Interface mit genau einer abstrakten Methode (z. B. Function, Predicate, Comparator).","code":"Function<Integer, Integer> doppelt = x -> x * 2;\nPredicate<String> leer = String::isBlank;\nvar namen = new ArrayList<>(List.of(\"Eva\", \"Al\", \"Bob\"));\nnamen.sort(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));\nSystem.out.println(doppelt.apply(21) + \" \" + leer.test(\" \") + \" \" + namen);","out":"42 true [Al, Bob, Eva]","pitfall":"Lambdas dürfen nur lokale Variablen lesen, die effektiv final sind. Zähler in Lambdas brauchen z. B. AtomicInteger oder einen Stream-Ansatz.","lesson":"java-m11-l1","tested":true},{"id":"java-stream","cat":"Funktional","term":"Stream-Pipeline","syntax":"liste.stream().filter(…).map(…).toList()","text":"Verarbeitet Daten in Schritten: Quelle, Zwischenoperationen (filter, map, sorted), Endoperation (toList, collect, sum, count). Erst die Endoperation startet die Arbeit.","code":"var ergebnis = List.of(5, 12, 8, 20).stream()\n    .filter(n -> n > 7)\n    .map(n -> n * 2)\n    .sorted()\n    .toList();\nSystem.out.println(ergebnis);","out":"[16, 24, 40]","pitfall":"Ein Stream lässt sich nur einmal verwenden. Wer Zwischenergebnisse braucht, speichert sie in einer Liste.","lesson":"java-m11-l2","tested":true},{"id":"java-collectors","cat":"Funktional","term":"Collectors.groupingBy","syntax":"stream.collect(Collectors.groupingBy(klassifizierer, …))","text":"Sammelt Stream-Elemente in Gruppen. Mit einem zweiten Collector (counting, summingInt, mapping) wird jede Gruppe weiter verarbeitet.","code":"var nachLaenge = Stream.of(\"ab\", \"cd\", \"efg\", \"h\")\n    .collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.counting()));\nSystem.out.println(nachLaenge);","out":"{1=1, 2=2, 3=1}","pitfall":"Collectors.toMap wirft bei doppelten Schlüsseln eine Ausnahme, wenn keine Zusammenführungsfunktion angegeben ist.","lesson":"java-m11-l3","tested":true},{"id":"java-optional","cat":"Funktional","term":"Optional","syntax":"Optional<T>    map(…)    orElse(…)    orElseThrow()","text":"Beschreibt „Wert oder nichts“ als Rückgabetyp. map wandelt um, orElse liefert einen Ersatz, orElseThrow wirft bei leerem Optional.","code":"Optional<String> name = Optional.of(\"ada\");\nSystem.out.println(name.map(String::toUpperCase).orElse(\"?\"));\nSystem.out.println(Optional.<String>empty().orElse(\"leer\"));","out":"ADA\nleer","pitfall":"Optional ist für Rückgabewerte gedacht, nicht für Felder oder Parameter. get() ohne Prüfung wirft NoSuchElementException.","lesson":"java-m11-l4","tested":true},{"id":"java-exception","cat":"Fehler","term":"try / catch / finally","syntax":"try { … } catch (Typ e) { … } finally { … }","text":"Fängt Ausnahmen. Checked Exceptions (z. B. IOException) muss man behandeln oder mit throws weitergeben, RuntimeExceptions nicht. finally läuft immer.","code":"try {\n    Integer.parseInt(\"abc\");\n} catch (NumberFormatException e) {\n    System.out.println(\"Ungültig: \" + e.getMessage());\n} finally {\n    System.out.println(\"fertig\");\n}","out":"Ungültig: For input string: \"abc\"\nfertig","pitfall":"Leere catch-Blöcke verschlucken Fehler. Wenigstens protokollieren oder weiterwerfen.","lesson":"java-m10-l1","tested":true},{"id":"java-twr","cat":"Fehler","term":"try-with-resources","syntax":"try (var r = new Resource()) { … }","text":"Schließt Ressourcen (Dateien, Verbindungen) am Blockende automatisch, auch bei Fehlern. Die Ressource muss AutoCloseable sein.","code":"class Tor implements AutoCloseable {\n    Tor() { System.out.println(\"auf\"); }\n    public void close() { System.out.println(\"zu\"); }\n}\ntry (var t = new Tor()) {\n    System.out.println(\"arbeiten\");\n}","out":"auf\narbeiten\nzu","pitfall":"Ohne try-with-resources bleiben Dateien und Datenbankverbindungen bei Fehlern offen (Ressourcenleck).","lesson":"java-m10-l2","tested":true},{"id":"java-equals","cat":"Klassen","term":"equals und hashCode","syntax":"@Override public boolean equals(Object o) …    public int hashCode()","text":"equals definiert, wann zwei Objekte gleich sind, hashCode muss dazu passen (gleiche Objekte, gleicher Hash). Ohne beides funktionieren HashSet und HashMap nicht wie erwartet. Records und IDEs erzeugen sie.","code":"class Euro {\n    final int cent;\n    Euro(int cent) { this.cent = cent; }\n    @Override public boolean equals(Object o) { return o instanceof Euro e && e.cent == cent; }\n    @Override public int hashCode() { return Integer.hashCode(cent); }\n}\nvar set = new HashSet<Euro>();\nset.add(new Euro(100));\nSystem.out.println(set.contains(new Euro(100)));","out":"true","pitfall":"Wer nur equals überschreibt, bricht den Vertrag: Das Objekt wird in HashMap/HashSet womöglich nicht wiedergefunden.","lesson":"java-m9-l2","tested":true},{"id":"java-time","cat":"Daten","term":"java.time","syntax":"LocalDate.of(…)    plusDays(…)    DateTimeFormatter.ofPattern(…)","text":"Die moderne Datum-Zeit-API. LocalDate ohne Uhrzeit, LocalDateTime ohne Zone, ZonedDateTime und Instant mit Bezug zur Weltzeit. Alle Objekte sind unveränderlich.","code":"var d = LocalDate.of(2026, 1, 31);\nSystem.out.println(d.plusMonths(1) + \" \" + d.getDayOfWeek() + \" \" + d.format(java.time.format.DateTimeFormatter.ofPattern(\"dd.MM.yyyy\")));","out":"2026-02-28 SATURDAY 31.01.2026","pitfall":"Auf java.util.Date und SimpleDateFormat verzichten. Sie sind veränderlich und nicht threadsicher.","lesson":"java-m14-l1","tested":true},{"id":"java-thread","cat":"Nebenläufigkeit","term":"ExecutorService","syntax":"try (var ex = Executors.newFixedThreadPool(4)) { … }","text":"Verwaltet einen Pool von Threads. submit() startet eine Aufgabe und liefert ein Future. Ab Java 19 schließt try-with-resources den Executor und wartet auf die Aufgaben.","code":"try (var ex = java.util.concurrent.Executors.newFixedThreadPool(2)) {\n    var f = ex.submit(() -> 6 * 7);\n    System.out.println(f.get());\n}","out":"42","pitfall":"Gemeinsam genutzte veränderliche Daten ohne Synchronisation führen zu Race Conditions. Unveränderliche Objekte oder Atomic-Klassen bevorzugen.","lesson":"java-m13-l3","tested":true},{"id":"java-vthread","cat":"Nebenläufigkeit","term":"Virtual Threads","syntax":"Thread.ofVirtual().start(…)    Executors.newVirtualThreadPerTaskExecutor()","text":"Leichtgewichtige Threads für viele gleichzeitig wartende Aufgaben (Netzwerk, Datenbank). Man legt pro Aufgabe einen eigenen Thread an und muss sie nicht poolen.","code":"try (var ex = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {\n    var f = ex.submit(() -> Thread.currentThread().isVirtual());\n    System.out.println(f.get());\n}","out":"true","pitfall":"Virtual Threads helfen bei Warten (I/O), nicht bei reiner Rechenlast. Dafür bleibt die Zahl der CPU-Kerne die Grenze.","lesson":"java-m25-l4","tested":true},{"id":"java-completable","cat":"Nebenläufigkeit","term":"CompletableFuture","syntax":"CompletableFuture.supplyAsync(…).thenApply(…).thenCombine(…)","text":"Beschreibt Ergebnisse, die später vorliegen, und verkettet Schritte. join() wartet auf das Ergebnis, exceptionally behandelt Fehler.","code":"var a = java.util.concurrent.CompletableFuture.supplyAsync(() -> 20);\nvar b = java.util.concurrent.CompletableFuture.supplyAsync(() -> 22);\nSystem.out.println(a.thenCombine(b, Integer::sum).join());","out":"42","pitfall":"Ohne eigenen Executor nutzt supplyAsync den gemeinsamen Pool. Blockierende Aufrufe darin bremsen alle anderen Aufgaben.","lesson":"java-m13-l4","tested":true},{"id":"java-files","cat":"Daten","term":"Files (NIO.2)","syntax":"Files.readString(path)    Files.writeString(path, text)    Files.lines(path)","text":"Liest und schreibt Dateien. Path beschreibt den Pfad. Files.lines liefert einen Stream, der nach Gebrauch geschlossen werden muss (try-with-resources).","code":"var pfad = java.nio.file.Files.createTempFile(\"glossar\", \".txt\");\njava.nio.file.Files.writeString(pfad, \"a\\nb\\n\");\ntry (var zeilen = java.nio.file.Files.lines(pfad)) {\n    System.out.println(zeilen.count());\n}\njava.nio.file.Files.delete(pfad);","out":"2","pitfall":"Pfade aus Nutzereingaben mit normalize() und einem Basisordner prüfen, sonst droht Path Traversal (../).","lesson":"java-m14-l2","tested":true},{"id":"java-junit","cat":"Tests","term":"JUnit 5","syntax":"@Test void …() { assertEquals(erwartet, tatsaechlich); }","text":"Ein Test ist eine Methode mit @Test. Assertions prüfen das Ergebnis, assertThrows erwartet eine Ausnahme. Gute Tests heißen nach dem Verhalten, das sie prüfen.","code":"class RechnerTest {\n    @Test\n    void additionLiefertSumme() {\n        assertEquals(5, new Rechner().add(2, 3));\n    }\n\n    @Test\n    void divisionDurchNullWirftFehler() {\n        assertThrows(ArithmeticException.class, () -> new Rechner().div(1, 0));\n    }\n}","pitfall":"Bei assertEquals steht der erwartete Wert zuerst. Vertauschte Argumente erzeugen irreführende Fehlermeldungen.","lesson":"java-m15-l1","tested":false},{"id":"java-spring-controller","cat":"Spring Boot","term":"@RestController","syntax":"@RestController @RequestMapping('/api/…')","text":"Markiert eine Klasse, deren Methoden HTTP-Anfragen beantworten. @GetMapping, @PostMapping usw. ordnen Pfad und Methode zu. @PathVariable und @RequestBody holen Daten aus URL und Rumpf.","code":"@RestController\n@RequestMapping(\"/api/aufgaben\")\nclass AufgabeController {\n    private final AufgabeService service;\n\n    AufgabeController(AufgabeService service) { this.service = service; }\n\n    @GetMapping(\"/{id}\")\n    AufgabeDto lesen(@PathVariable long id) { return service.finde(id); }\n\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    AufgabeDto anlegen(@Valid @RequestBody AufgabeRequest request) { return service.anlegen(request); }\n}","pitfall":"Entities nicht direkt als Antwort zurückgeben. DTOs entkoppeln die API von der Datenbank und verhindern, dass interne Felder ausgeliefert werden.","lesson":"java-m22-l1","tested":false},{"id":"java-spring-injection","cat":"Spring Boot","term":"Konstruktorinjektion","syntax":"@Service class A { A(B b) { … } }","text":"Spring übergibt die benötigten Beans über den Konstruktor. So sind Abhängigkeiten sichtbar, Felder können final sein, und Tests brauchen kein Spring.","code":"@Service\nclass RechnungService {\n    private final RechnungRepository repository;\n\n    RechnungService(RechnungRepository repository) {\n        this.repository = repository;\n    }\n}","pitfall":"Feldinjektion mit @Autowired versteckt Abhängigkeiten und macht Tests schwer. Konstruktorinjektion bevorzugen.","lesson":"java-m21-l2","tested":false},{"id":"java-spring-repo","cat":"Spring Boot","term":"Spring Data Repository","syntax":"interface XRepository extends JpaRepository<X, Long>","text":"Ein Interface genügt, Spring erzeugt die Implementierung. Abfragemethoden werden aus dem Namen abgeleitet (findByStatus, existsByEmail). Mit @Query schreibt man eigene Abfragen.","code":"interface AufgabeRepository extends JpaRepository<Aufgabe, Long> {\n    List<Aufgabe> findByErledigtFalseOrderByFaelligAsc();\n\n    @Query(\"select a from Aufgabe a where a.titel like %:text%\")\n    Page<Aufgabe> suche(String text, Pageable pageable);\n}","pitfall":"Beziehungen werden standardmäßig nachgeladen (Lazy). In Schleifen führt das zum N+1-Problem, daher fetch join oder EntityGraph einsetzen.","lesson":"java-m23-l1","tested":false},{"id":"java-spring-transactional","cat":"Spring Boot","term":"@Transactional","syntax":"@Transactional public void methode()","text":"Führt die Methode in einer Datenbanktransaktion aus: Alles oder nichts. Bei einer RuntimeException wird zurückgerollt.","code":"@Transactional\npublic void ueberweisen(long von, long nach, BigDecimal betrag) {\n    konten.abbuchen(von, betrag);\n    konten.gutschreiben(nach, betrag);\n}","pitfall":"Ruft eine Methode eine @Transactional-Methode derselben Klasse auf (this.…), greift die Transaktion nicht, weil der Aufruf am Proxy vorbeigeht.","lesson":"java-m23-l2","tested":false},{"id":"java-spring-validation","cat":"Spring Boot","term":"Bean Validation","syntax":"@NotBlank  @Size  @Email  @Valid","text":"Annotationen an Feldern beschreiben Regeln. @Valid am Parameter löst die Prüfung aus, bei Verstoß antwortet Spring mit 400.","code":"record AufgabeRequest(\n    @NotBlank @Size(max = 120) String titel,\n    @Future LocalDate faellig\n) {}","pitfall":"Validierung am Rand (Request) ersetzt keine Regeln in der Fachlogik. Wichtige Invarianten gehören auch dorthin.","lesson":"java-m22-l2","tested":false},{"id":"java-function-types","cat":"Funktional","term":"Function, Predicate, Supplier, Consumer","syntax":"Function<T,R>  Predicate<T>  Supplier<T>  Consumer<T>  BiFunction<A,B,R>  UnaryOperator<T>","text":"Die eingebauten funktionalen Schnittstellen sind die Typen für Lambdas. Function wandelt um, Predicate prüft, Supplier liefert, Consumer verbraucht. andThen, compose und negate setzen sie zusammen.","code":"Function<Integer, Integer> doppelt = x -> x * 2;\nFunction<Integer, Integer> plusEins = x -> x + 1;\nPredicate<String> leer = String::isBlank;\nSupplier<String> gruss = () -> \"Hallo\";\nBiFunction<Integer, Integer, Integer> summe = Integer::sum;\nSystem.out.println(doppelt.andThen(plusEins).apply(5) + \" \" + doppelt.compose(plusEins).apply(5) + \" \" + leer.negate().test(\"x\") + \" \" + gruss.get() + \" \" + summe.apply(2, 3));","out":"11 12 true Hallo 5","pitfall":"andThen führt zuerst die eigene Funktion aus, compose zuerst die übergebene. Die Reihenfolge wird oft verwechselt.","lesson":"java-m11-l1","tested":true},{"id":"java-comparator","cat":"Sammlungen","term":"Comparator: comparing, thenComparing, reversed","syntax":"list.sort(Comparator.comparing(P::name).thenComparing(P::alter).reversed())","text":"Ein Comparator legt eine Reihenfolge fest. Mit comparing und Methodenreferenzen baut man ihn lesbar zusammen, thenComparing ergänzt ein zweites Kriterium, reversed dreht um, nullsLast behandelt null.","code":"record P(String name, int alter) {}\nvar liste = new ArrayList<>(List.of(new P(\"Bo\", 30), new P(\"Al\", 30), new P(\"Cy\", 25)));\nliste.sort(Comparator.comparingInt(P::alter).reversed().thenComparing(P::name));\nSystem.out.println(liste.stream().map(P::name).toList());","out":"[Al, Bo, Cy]","pitfall":"reversed() dreht den gesamten bisherigen Vergleich um, nicht nur das letzte Kriterium. Reihenfolge der Aufrufe beachten.","lesson":"java-m9-l1","tested":true},{"id":"java-enum-fields","cat":"Klassen","term":"enum mit Feldern, EnumMap, values und valueOf","syntax":"enum Stufe { NIEDRIG(1), HOCH(3); final int punkte; Stufe(int p) { … } }    EnumMap<Stufe, V>","text":"Ein enum darf Felder, Konstruktor und Methoden haben. values() liefert alle Konstanten, valueOf wandelt einen Namen um (wirft bei unbekanntem Namen), ordinal die Position. EnumMap ist eine schnelle Map für enum-Schlüssel.","code":"enum Stufe { NIEDRIG(1), HOCH(3); final int punkte; Stufe(int p) { punkte = p; } }\nvar karte = new EnumMap<Stufe, String>(Stufe.class);\nkarte.put(Stufe.HOCH, \"dringend\");\nkarte.put(Stufe.NIEDRIG, \"später\");\nSystem.out.println(karte + \" \" + Stufe.valueOf(\"HOCH\").punkte + \" \" + Stufe.HOCH.ordinal() + \" \" + Arrays.toString(Stufe.values()));","out":"{NIEDRIG=später, HOCH=dringend} 3 1 [NIEDRIG, HOCH]","pitfall":"ordinal() ändert sich, wenn man Konstanten umsortiert. Nie in Datenbanken speichern, sondern den Namen (@Enumerated(EnumType.STRING)).","lesson":"java-m8-l4","tested":true},{"id":"java-record-compact","cat":"Klassen","term":"record: kompakter Konstruktor und Fabrikmethode","syntax":"record R(int a, int b) { R { if (…) throw …; }  static R of(…) { … } }","text":"Der kompakte Konstruktor hat keine Parameterliste. Er prüft oder normalisiert die Werte, bevor sie den Feldern zugewiesen werden. Ein Record darf Methoden und static-Fabriken haben.","code":"record Bereich(int von, int bis) {\n    Bereich {\n        if (von > bis) throw new IllegalArgumentException(\"von > bis\");\n    }\n    int laenge() { return bis - von; }\n    static Bereich bis(int b) { return new Bereich(0, b); }\n}\nSystem.out.println(new Bereich(2, 7).laenge() + \" \" + Bereich.bis(3));\ntry { new Bereich(5, 1); } catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }","out":"5 Bereich[von=0, bis=3]\nvon > bis","pitfall":"Im kompakten Konstruktor nicht selbst this.von = … schreiben. Die Zuweisung passiert automatisch am Ende. Veränderliche Listen im Record defensiv kopieren (List.copyOf).","lesson":"java-m8-l4","tested":true},{"id":"java-immutable","cat":"Sammlungen","term":"Unveränderliche Sammlungen: List.of, copyOf","syntax":"List.of(…)  Set.of(…)  Map.of(k, v)  List.copyOf(c)  Collections.unmodifiableList(l)","text":"List.of, Set.of und Map.of liefern Sammlungen, die sich nicht ändern lassen und kein null erlauben. copyOf macht aus einer veränderlichen eine unveränderliche Kopie. unmodifiableList ist nur eine Sicht auf das Original.","code":"var liste = List.of(1, 2, 3);\ntry { liste.add(4); } catch (UnsupportedOperationException e) { System.out.println(\"unveränderlich\"); }\nvar kopie = new ArrayList<>(liste);\nkopie.add(4);\nSystem.out.println(kopie + \" \" + List.copyOf(kopie).size() + \" \" + Map.of(\"a\", 1).get(\"a\"));","out":"unveränderlich\n[1, 2, 3, 4] 4 1","pitfall":"Collections.unmodifiableList zeigt Änderungen am Original weiterhin an. Für echte Unveränderlichkeit List.copyOf verwenden. Map.of hat keine feste Reihenfolge.","lesson":"java-m9-l1","tested":true},{"id":"java-string-utils","cat":"Strings","term":"join, repeat, strip, isBlank, lines, compareTo","syntax":"String.join(\",\", a, b)  s.repeat(3)  s.strip()  s.isBlank()  s.lines()  s.compareTo(t)","text":"Weitere nützliche String-Methoden. strip entfernt auch Unicode-Leerraum (besser als trim), isBlank prüft auf nur Leerraum, lines zerlegt in Zeilen, compareTo vergleicht lexikografisch (negativ, 0, positiv).","code":"System.out.println(String.join(\"-\", \"a\", \"b\") + \" \" + \"ab\".repeat(2) + \" \" + \"  x \".strip() + \"|\" + \" \".isBlank() + \" \" + \"a\\nb\".lines().count() + \" \" + \"Zebra\".compareTo(\"Apfel\") + \" \" + \"ÄPFEL\".equalsIgnoreCase(\"äpfel\") + \" \" + \"hallo\".chars().filter(c -> c == 'l').count());","out":"a-b abab x|true 2 25 true 2","pitfall":"Strings nie mit == vergleichen, sondern mit equals. compareTo ist nicht für alphabetisches Sortieren mit Umlauten gedacht, dafür java.text.Collator.","lesson":"java-m7-l3","tested":true},{"id":"java-wildcards","cat":"Sammlungen","term":"Generics: Wildcards und beschränkte Typen","syntax":"<? extends T>  <? super T>  <T extends Comparable<T>>","text":"extends erlaubt Lesen (Produzent), super erlaubt Schreiben (Konsument): „PECS“ – Producer Extends, Consumer Super. Ein beschränkter Typparameter verlangt eine Fähigkeit, z. B. Vergleichbarkeit.","code":"static double summe(List<? extends Number> zahlen) {\n    double s = 0;\n    for (Number n : zahlen) s += n.doubleValue();\n    return s;\n}\nstatic void fuelle(List<? super Integer> ziel) { ziel.add(1); ziel.add(2); }\nstatic <T extends Comparable<T>> T groesster(List<T> liste) {\n    return liste.stream().max(Comparator.naturalOrder()).orElseThrow();\n}\nvoid main() {\n    List<Number> n = new ArrayList<>();\n    fuelle(n);\n    System.out.println(summe(List.of(1, 2.5)) + \" \" + n + \" \" + groesster(List.of(\"b\", \"z\", \"a\")));\n}","out":"3.5 [1, 2] z","pitfall":"List<Integer> ist kein Untertyp von List<Number>. Deshalb braucht man Wildcards bei Methodenparametern.","lesson":"java-m9-l3","tested":true},{"id":"java-concurrent-map","cat":"Nebenläufigkeit","term":"ConcurrentHashMap und Lock","syntax":"ConcurrentHashMap.merge(k, 1, Integer::sum)    synchronized    ReentrantLock","text":"Gemeinsame Daten dürfen nie ungeschützt von mehreren Threads geändert werden. ConcurrentHashMap erledigt Zählen sicher mit merge. Für eigene Abschnitte dienen synchronized oder ein ReentrantLock mit lock/unlock in try-finally.","code":"var zaehler = new java.util.concurrent.ConcurrentHashMap<String, Integer>();\nvar lock = new java.util.concurrent.locks.ReentrantLock();\nint[] gesamt = {0};\nvar threads = new ArrayList<Thread>();\nfor (int i = 0; i < 4; i++) {\n    threads.add(Thread.ofPlatform().start(() -> {\n        for (int j = 0; j < 1000; j++) {\n            zaehler.merge(\"x\", 1, Integer::sum);\n            lock.lock();\n            try { gesamt[0]++; } finally { lock.unlock(); }\n        }\n    }));\n}\nfor (var t : threads) t.join();\nSystem.out.println(zaehler.get(\"x\") + \" \" + gesamt[0]);","out":"4000 4000","pitfall":"unlock immer in finally aufrufen, sonst bleibt der Lock bei einer Ausnahme für immer gesperrt. Mehrere Locks immer in gleicher Reihenfolge nehmen (Deadlock).","lesson":"java-m13-l2","tested":true},{"id":"java-instance-main","cat":"Grundlagen","term":"Kompakte Quelldatei und instance main (Java 25)","syntax":"void main() { … }    java Hallo.java","text":"Seit Java 25 darf ein Programm ohne class und ohne public static void main(String[]) auskommen. Eine Datei mit void main() und beliebigen Methoden genügt und startet mit java Datei.java. Das erleichtert den Einstieg und kleine Skripte.","code":"String gruss(String name) { return \"Hallo \" + name; }\n\nvoid main() {\n    System.out.println(gruss(\"Welt\"));\n}","out":"Hallo Welt","pitfall":"Für größere Anwendungen bleiben normale Klassen, Pakete und ein Build-Werkzeug (Maven, Gradle) die richtige Wahl. Die kompakte Form ist für Lernen und Skripte gedacht.","lesson":"java-m7-l1","tested":true},{"id":"java-scoped-value","cat":"Nebenläufigkeit","term":"ScopedValue (Java 25)","syntax":"ScopedValue.where(KEY, wert).run(() -> …)    KEY.get()","text":"Ein ScopedValue reicht einen Wert (z. B. den angemeldeten Nutzer) an alle aufgerufenen Methoden und Threads weiter, ohne ihn als Parameter durchzureichen. Er ist unveränderlich und nur innerhalb des Blocks gültig, sicherer als ThreadLocal.","code":"static final ScopedValue<String> NUTZER = ScopedValue.newInstance();\n\nvoid main() {\n    ScopedValue.where(NUTZER, \"mia\").run(() -> System.out.println(\"Nutzer: \" + NUTZER.get()));\n    System.out.println(NUTZER.isBound());\n}","out":"Nutzer: mia\nfalse","pitfall":"Außerhalb des where-Blocks wirft get() eine Ausnahme. Mit isBound() oder orElse prüfen. Mit Virtual Threads ist ScopedValue ThreadLocal vorzuziehen.","lesson":"java-m25-l4","tested":true},{"id":"java-scanner-io","cat":"Daten","term":"Eingabe: Scanner und BufferedReader","syntax":"new Scanner(System.in)    new BufferedReader(new InputStreamReader(System.in))","text":"Scanner liest Tastatureingaben komfortabel (nextInt, nextLine). BufferedReader ist schneller für große Eingaben. Beide gehören in try-with-resources, wenn sie nicht System.in kapseln.","code":"try (var scanner = new Scanner(System.in)) {\n    System.out.print(\"Name: \");\n    String name = scanner.nextLine();\n    System.out.print(\"Alter: \");\n    int alter = Integer.parseInt(scanner.nextLine().trim());\n    System.out.println(name + \" ist \" + alter);\n}","pitfall":"Nach nextInt() bleibt der Zeilenumbruch im Puffer, ein folgendes nextLine() liefert einen leeren Text. Immer mit nextLine() lesen und selbst umwandeln. Eingaben prüfen (NumberFormatException).","lesson":"java-m10-l1","tested":false},{"id":"java-junit-param","cat":"Tests","term":"JUnit: @ParameterizedTest, assertThrows, @Nested","syntax":"@ParameterizedTest @CsvSource({ \"1,2,3\" })    assertThrows(X.class, () -> …)","text":"Parametrisierte Tests laufen mit mehreren Datensätzen. assertThrows prüft, dass eine Ausnahme kommt. @Nested gruppiert Tests zu einem Zustand. assertAll sammelt mehrere Prüfungen, auch wenn eine scheitert.","code":"class RechnerTest {\n    @ParameterizedTest\n    @CsvSource({ \"1,2,3\", \"5,5,10\", \"-1,1,0\" })\n    void addiert(int a, int b, int erwartet) {\n        assertEquals(erwartet, new Rechner().add(a, b));\n    }\n\n    @Test\n    void teilenDurchNullWirft() {\n        var e = assertThrows(ArithmeticException.class, () -> new Rechner().teile(1, 0));\n        assertEquals(\"/ by zero\", e.getMessage());\n    }\n}","pitfall":"Tests unabhängig voneinander halten, keine feste Reihenfolge annehmen. Den Fehlerfall genauso testen wie den Normalfall.","lesson":"java-m15-l1","tested":false},{"id":"java-mockito","cat":"Tests","term":"Mockito: when, verify, ArgumentCaptor","syntax":"@ExtendWith(MockitoExtension.class)  @Mock  @InjectMocks  when(…).thenReturn(…)  verify(…)","text":"Mockito ersetzt Abhängigkeiten durch Attrappen. when/thenReturn legt Antworten fest, verify prüft Aufrufe, ArgumentCaptor fängt übergebene Werte ab. So testet man eine Klasse ohne Datenbank und ohne Netzwerk.","code":"@ExtendWith(MockitoExtension.class)\nclass BestellServiceTest {\n    @Mock BestellRepository repo;\n    @Mock MailService mail;\n    @InjectMocks BestellService service;\n\n    @Test\n    void sendetMailNachSpeichern() {\n        when(repo.save(any())).thenAnswer(i -> i.getArgument(0));\n        service.bestelle(\"Buch\");\n        var captor = ArgumentCaptor.forClass(Bestellung.class);\n        verify(repo).save(captor.capture());\n        verify(mail).sendeBestaetigung(captor.getValue());\n    }\n}","pitfall":"Zu viele Mocks machen Tests fragil und prüfen nur die Implementierung. Für Datenbankverhalten lieber ein echter Test mit Testcontainers.","lesson":"java-m24-l2","tested":false},{"id":"java-jdbc","cat":"Daten","term":"JDBC mit PreparedStatement","syntax":"try (var c = DriverManager.getConnection(url); var ps = c.prepareStatement(\"… WHERE id = ?\")) { ps.setLong(1, id); … }","text":"JDBC ist die Grundschnittstelle zu Datenbanken. Mit PreparedStatement und Platzhaltern (?) schützt man vor SQL-Injection. Verbindung, Statement und ResultSet gehören in try-with-resources.","code":"String sql = \"SELECT id, name FROM kunde WHERE land = ?\";\ntry (var verbindung = DriverManager.getConnection(url, benutzer, passwort);\n     var ps = verbindung.prepareStatement(sql)) {\n    ps.setString(1, land);\n    try (var rs = ps.executeQuery()) {\n        while (rs.next()) {\n            System.out.println(rs.getLong(\"id\") + \" \" + rs.getString(\"name\"));\n        }\n    }\n}","pitfall":"SQL nie mit + aus Nutzereingaben zusammenbauen. Zugangsdaten nicht im Code, sondern in Umgebungsvariablen oder der Konfiguration halten.","lesson":"java-m23-l1","tested":false},{"id":"java-spring-mapping","cat":"Spring Boot","term":"@GetMapping, @PathVariable, @RequestParam, @RequestBody","syntax":"@GetMapping(\"/{id}\")  @PostMapping  @PathVariable  @RequestParam  @RequestBody  ResponseEntity","text":"Die Mapping-Annotationen binden HTTP-Methoden an Methoden. @PathVariable liest Teile des Pfads, @RequestParam Query-Parameter, @RequestBody den JSON-Körper. ResponseEntity bzw. @ResponseStatus legen den Statuscode fest.","code":"@RestController\n@RequestMapping(\"/api/aufgaben\")\nclass AufgabeController {\n    @GetMapping(\"/{id}\")\n    Aufgabe eine(@PathVariable long id) { return service.finde(id); }\n\n    @GetMapping\n    List<Aufgabe> alle(@RequestParam(defaultValue = \"0\") int seite) { return service.seite(seite); }\n\n    @PostMapping\n    ResponseEntity<Aufgabe> neu(@Valid @RequestBody AufgabeEingabe eingabe) {\n        var neu = service.anlegen(eingabe);\n        return ResponseEntity.created(URI.create(\"/api/aufgaben/\" + neu.id())).body(neu);\n    }\n}","pitfall":"Nie Entities direkt als Eingabe annehmen (Mass Assignment). Eigene Eingabe-Objekte (DTOs/Records) mit @Valid verwenden.","lesson":"java-m22-l1","tested":false},{"id":"java-spring-stereotypes","cat":"Spring Boot","term":"@Service, @Component, @Repository, @Value, @Profile","syntax":"@Service  @Component  @Repository  @Value(\"${key}\")  @Profile(\"dev\")","text":"Stereotyp-Annotationen machen eine Klasse zu einer Spring-Bean. @Service und @Repository sind spezialisierte @Component. @Value liest einzelne Einstellungen, @Profile aktiviert Beans nur in bestimmten Umgebungen.","code":"@Service\nclass RechnungService {\n    private final RechnungRepository repo;\n    private final double steuersatz;\n\n    RechnungService(RechnungRepository repo, @Value(\"${app.steuersatz:0.19}\") double steuersatz) {\n        this.repo = repo;\n        this.steuersatz = steuersatz;\n    }\n}\n\n@Component\n@Profile(\"dev\")\nclass TestdatenLader implements CommandLineRunner {\n    public void run(String... args) { /* Beispieldaten anlegen */ }\n}","pitfall":"Für viele zusammengehörige Werte @ConfigurationProperties statt vieler @Value. Secrets nie in application.yml im Repository, sondern über Umgebungsvariablen.","lesson":"java-m21-l2","tested":false},{"id":"java-spring-scheduled-cache","cat":"Spring Boot","term":"@Scheduled, @Async, @Cacheable","syntax":"@EnableScheduling  @Scheduled(cron = \"0 0 7 * * *\")  @EnableAsync  @Async  @EnableCaching  @Cacheable(\"name\")","text":"Spring kann Methoden zeitgesteuert, im Hintergrund oder mit Zwischenspeicher ausführen. Jede Funktion muss mit @Enable… aktiviert werden. Die Annotation wirkt nur bei Aufrufen von außen über die Bean.","code":"@Service\nclass BerichtService {\n    @Scheduled(cron = \"0 0 7 * * *\", zone = \"Europe/Berlin\")\n    void taeglicherBericht() { /* … */ }\n\n    @Async\n    CompletableFuture<Void> sendeMail(String an) { /* … */ return CompletableFuture.completedFuture(null); }\n\n    @Cacheable(\"kurse\")\n    BigDecimal kurs(String waehrung) { /* teurer Aufruf */ return BigDecimal.ONE; }\n\n    @CacheEvict(value = \"kurse\", allEntries = true)\n    void kurseZuruecksetzen() {}\n}","pitfall":"Ein Aufruf innerhalb derselben Klasse (this.methode()) umgeht den Proxy: @Async, @Cacheable und @Transactional wirken dann nicht.","lesson":"java-m23-l2","tested":false},{"id":"java-spring-data-query","cat":"Spring Boot","term":"Abgeleitete Abfragen, @Query, Pageable","syntax":"findByNameContainingIgnoreCase(String)  @Query(\"select …\")  Page<T> findAll(Pageable)","text":"Spring Data erzeugt Abfragen aus Methodennamen (findBy…, existsBy…, countBy…). Für Komplexes schreibt man @Query in JPQL. Pageable und Sort liefern Seiten und Sortierung.","code":"interface AufgabeRepository extends JpaRepository<Aufgabe, Long> {\n    List<Aufgabe> findByErledigtFalseOrderByFaelligAsc();\n    boolean existsByTitelIgnoreCase(String titel);\n\n    @Query(\"select a from Aufgabe a where a.besitzer.id = :id and a.faellig < :bis\")\n    List<Aufgabe> ueberfaellige(@Param(\"id\") long id, @Param(\"bis\") LocalDate bis);\n\n    Page<Aufgabe> findByBesitzerId(long id, Pageable pageable);\n}\n\n// Aufruf\nrepo.findByBesitzerId(7, PageRequest.of(0, 20, Sort.by(\"faellig\").descending()));","pitfall":"Lange Methodennamen sind schwer lesbar: ab etwa drei Bedingungen lieber @Query. Parameter immer binden, nie Text zusammensetzen.","lesson":"java-m23-l1","tested":false},{"id":"java-jpa-relations","cat":"Spring Boot","term":"JPA-Beziehungen: @OneToMany, @ManyToOne, LAZY","syntax":"@ManyToOne(fetch = LAZY)  @OneToMany(mappedBy = \"…\", cascade = …)  @EntityGraph","text":"Die „viele“-Seite (@ManyToOne) besitzt den Fremdschlüssel. @OneToMany(mappedBy) ist die Rückrichtung. LAZY lädt Beziehungen erst bei Zugriff. Um das N+1-Problem zu vermeiden, lädt man gezielt mit JOIN FETCH oder @EntityGraph.","code":"@Entity\nclass Bestellung {\n    @Id @GeneratedValue Long id;\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    Kunde kunde;\n    @OneToMany(mappedBy = \"bestellung\", cascade = CascadeType.ALL, orphanRemoval = true)\n    List<Position> positionen = new ArrayList<>();\n}\n\ninterface BestellungRepository extends JpaRepository<Bestellung, Long> {\n    @EntityGraph(attributePaths = \"positionen\")\n    List<Bestellung> findByKundeId(long kundeId);\n}","pitfall":"Entities nicht direkt als JSON zurückgeben (Endlosschleifen, LazyInitializationException, interne Felder). Records als Antwort-Objekte verwenden.","lesson":"java-m23-l1","tested":false},{"id":"java-actuator-logging","cat":"Spring Boot","term":"Actuator und Logging (SLF4J)","syntax":"management.endpoints.web.exposure.include=health,info    private static final Logger log = LoggerFactory.getLogger(…)","text":"Actuator liefert Betriebsendpunkte wie /actuator/health. Protokolliert wird über SLF4J mit Platzhaltern {}. Die Stufen sind TRACE, DEBUG, INFO, WARN, ERROR und lassen sich je Paket in application.yml einstellen.","code":"# application.yml\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,info\nlogging:\n  level:\n    root: INFO\n    de.rootpfad: DEBUG\n\n// im Code\nprivate static final Logger log = LoggerFactory.getLogger(RechnungService.class);\nlog.info(\"Rechnung {} für Kunde {} erstellt\", rechnung.id(), kunde.id());\nlog.error(\"Versand fehlgeschlagen\", exception);","pitfall":"Nur health und info öffentlich freigeben, andere Endpunkte (env, heapdump) schützen. Keine Passwörter oder personenbezogene Daten in Logs schreiben.","lesson":"java-m26-l1","tested":false},{"id":"java-testcontainers","cat":"Tests","term":"Testcontainers mit @ServiceConnection","syntax":"@Testcontainers  @Container @ServiceConnection static PostgreSQLContainer<?> db = new PostgreSQLContainer<>(\"postgres:17\")","text":"Testcontainers startet für den Test eine echte Datenbank in Docker. @ServiceConnection verbindet sie automatisch mit Spring Boot, ohne URL und Passwort von Hand einzutragen. So testet man Migrationen und Abfragen gegen das echte System.","code":"@SpringBootTest\n@Testcontainers\nclass AufgabeRepositoryIT {\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer<?> db = new PostgreSQLContainer<>(\"postgres:17\");\n\n    @Autowired AufgabeRepository repo;\n\n    @Test\n    void speichertUndLiest() {\n        var gespeichert = repo.save(new Aufgabe(\"Test\"));\n        assertTrue(repo.findById(gespeichert.getId()).isPresent());\n    }\n}","pitfall":"Braucht ein laufendes Docker. Image-Version fest angeben (nicht latest), damit Tests reproduzierbar bleiben.","lesson":"java-m24-l2","tested":false},{"id":"java-stringbuilder","cat":"Strings","term":"StringBuilder und String.format","syntax":"new StringBuilder().append(x).toString()    String.format(\"%5.2f\", zahl)","text":"StringBuilder baut Text in Schleifen effizient auf, ohne jedes Mal einen neuen String zu erzeugen. String.format setzt Werte ein (%s Text, %d ganze Zahl, %.2f Kommazahl, %n Zeilenumbruch).","code":"var sb = new StringBuilder();\nfor (int i = 1; i <= 3; i++) sb.append(i).append(i < 3 ? \",\" : \"\");\nSystem.out.println(sb.reverse());\nSystem.out.println(String.format(java.util.Locale.GERMANY, \"%s: %,.2f €\", \"Summe\", 1234.5));","out":"3,2,1\nSumme: 1.234,50 €","pitfall":"String.format ohne Locale nutzt die Sprache des Rechners. Ausgaben können auf anderen Systemen mit Punkt statt Komma erscheinen.","lesson":"java-m7-l3","tested":true},{"id":"java-arrays","cat":"Sammlungen","term":"Arrays","syntax":"int[] a = new int[3];    int[] b = {1, 2, 3};    Arrays.toString(b)","text":"Arrays haben eine feste Länge und beginnen bei Index 0. Die Hilfsklasse Arrays bietet toString, sort, copyOf, fill und equals. Für veränderliche Listen List verwenden.","code":"int[] z = {5, 2, 9};\nArrays.sort(z);\nint[] kopie = Arrays.copyOf(z, 5);\nSystem.out.println(Arrays.toString(z) + \" \" + Arrays.toString(kopie) + \" \" + z.length);\nint[][] raster = new int[2][3];\nSystem.out.println(raster.length + \"x\" + raster[0].length);","out":"[2, 5, 9] [2, 5, 9, 0, 0] 3\n2x3","pitfall":"Ein Zugriff außerhalb der Grenzen wirft ArrayIndexOutOfBoundsException. Println eines Arrays zeigt nur eine Adresse, dafür Arrays.toString verwenden.","lesson":"java-m7-l2","tested":true},{"id":"java-varargs","cat":"Klassen","term":"Varargs","syntax":"static int summe(int... zahlen)","text":"Eine Methode kann beliebig viele Argumente eines Typs annehmen. Innerhalb der Methode ist der Parameter ein Array. Er muss der letzte Parameter sein.","code":"static int summe(int... zahlen) {\n    int s = 0;\n    for (int z : zahlen) s += z;\n    return s;\n}\npublic static void main(String[] args) {\n    System.out.println(summe() + \" \" + summe(1, 2, 3));\n}","out":"0 6","pitfall":"Mehrere überladene Methoden mit Varargs führen schnell zu mehrdeutigen Aufrufen. Eine Liste als Parameter ist oft klarer.","lesson":"java-m8-l1","tested":true},{"id":"java-abstract","cat":"Klassen","term":"abstract, extends, super, @Override","syntax":"abstract class A { abstract void f(); }    class B extends A { @Override void f() { … } }","text":"Abstrakte Klassen teilen Code und erzwingen, dass Unterklassen bestimmte Methoden umsetzen. super ruft den Elternteil auf, @Override lässt den Compiler prüfen, dass wirklich überschrieben wird.","code":"abstract class Form {\n    abstract double flaeche();\n    String beschreibung() { return getClass().getSimpleName() + \" \" + flaeche(); }\n}\nclass Quadrat extends Form {\n    private final double a;\n    Quadrat(double a) { this.a = a; }\n    @Override double flaeche() { return a * a; }\n}\nSystem.out.println(new Quadrat(3).beschreibung());","out":"Quadrat 9.0","pitfall":"Tiefe Vererbungshierarchien werden schnell unübersichtlich. Komposition und Interfaces sind meist die flexiblere Wahl.","lesson":"java-m8-l2","tested":true},{"id":"java-default-method","cat":"Klassen","term":"default- und static-Methoden in Interfaces","syntax":"interface A { default void f() { … } static A neu() { … } }","text":"Interfaces können fertige Methoden mitbringen (default), die Klassen übernehmen oder überschreiben, sowie statische Hilfsmethoden. So lassen sich Interfaces erweitern, ohne bestehende Klassen zu brechen.","code":"interface Gruss {\n    String name();\n    default String hallo() { return \"Hallo \" + name(); }\n    static Gruss von(String n) { return () -> n; }\n}\nSystem.out.println(Gruss.von(\"Ada\").hallo());","out":"Hallo Ada","pitfall":"Erbt eine Klasse dieselbe default-Methode aus zwei Interfaces, muss sie diese selbst überschreiben, sonst gibt es einen Compilerfehler.","lesson":"java-m8-l3","tested":true},{"id":"java-inner-anonymous","cat":"Klassen","term":"Innere und anonyme Klassen","syntax":"new Interface() { … }    static class Inner { … }","text":"Anonyme Klassen implementieren ein Interface direkt an der Stelle, wo man es braucht. Verschachtelte static-Klassen sind eigenständige Hilfsklassen innerhalb einer anderen. Bei einem Interface mit einer Methode ist ein Lambda kürzer.","code":"Comparator<String> nachLaenge = new Comparator<>() {\n    @Override public int compare(String a, String b) { return Integer.compare(a.length(), b.length()); }\n};\nvar l = new ArrayList<>(List.of(\"ccc\", \"a\", \"bb\"));\nl.sort(nachLaenge);\nSystem.out.println(l);","out":"[a, bb, ccc]","pitfall":"Nicht-statische innere Klassen halten eine Referenz auf das äußere Objekt und können so Speicher binden. Wenn möglich static verwenden.","lesson":"java-m8-l3","tested":true},{"id":"java-switch-guard","cat":"Kontrollfluss","term":"switch mit Pattern und when","syntax":"case Typ t when bedingung -> …","text":"Ein switch kann Typen prüfen und mit when zusätzlich Bedingungen verknüpfen. null lässt sich als eigener Fall behandeln. Die Fälle werden von oben nach unten geprüft.","code":"static String art(Object o) {\n    return switch (o) {\n        case null -> \"nichts\";\n        case Integer i when i > 100 -> \"groß\";\n        case Integer i -> \"Zahl \" + i;\n        case String s -> \"Text mit \" + s.length();\n        default -> \"anderes\";\n    };\n}\npublic static void main(String[] args) {\n    System.out.println(art(500) + \", \" + art(7) + \", \" + art(\"Haus\") + \", \" + art(null));\n}","out":"groß, Zahl 7, Text mit 4, nichts","pitfall":"Der allgemeinere Fall darf nicht vor dem spezielleren stehen (case Integer vor Integer i when …), sonst meldet der Compiler einen Fehler.","lesson":"java-m25-l1","tested":true},{"id":"java-unnamed","cat":"Kontrollfluss","term":"Unbenannte Variable _","syntax":"for (var _ : liste)    catch (Exception _)    case Punkt(int x, _)","text":"Wenn ein Wert nicht gebraucht wird, zeigt der Unterstrich das ausdrücklich an. Der Compiler verlangt dann keine Verwendung. Seit Java 22 verfügbar.","code":"int anzahl = 0;\nfor (var _ : List.of(\"a\", \"b\", \"c\")) anzahl++;\nrecord Punkt(int x, int y) {}\nObject o = new Punkt(3, 4);\nif (o instanceof Punkt(int x, _)) System.out.println(anzahl + \" \" + x);","out":"3 3","pitfall":"Ab Java 9 war _ als Name verboten, davor erlaubt. Auf älteren JDKs kompiliert der Code nicht.","lesson":"java-m25-l6","tested":true},{"id":"java-math","cat":"Typen","term":"Math, Überlauf und BigDecimal","syntax":"Math.round(x)  Math.floorMod(a, b)  Math.addExact(a, b)  new BigDecimal(\"0.10\")","text":"Math enthält Rechenfunktionen. int läuft bei Überschreitung des Bereichs lautlos über, addExact und multiplyExact werfen dagegen eine Ausnahme. Geld wird mit BigDecimal berechnet, die aus Text erzeugt wird.","code":"System.out.println(Integer.MAX_VALUE + 1);\ntry { Math.addExact(Integer.MAX_VALUE, 1); } catch (ArithmeticException e) { System.out.println(\"Überlauf\"); }\nSystem.out.println(Math.floorMod(-7, 3) + \" \" + (-7 % 3));\nvar a = new java.math.BigDecimal(\"0.10\");\nSystem.out.println(a.add(new java.math.BigDecimal(\"0.20\")) + \" \" + (0.1 + 0.2));","out":"-2147483648\nÜberlauf\n2 -1\n0.30 0.30000000000000004","pitfall":"new BigDecimal(0.1) übernimmt den ungenauen double-Wert. Immer den Text-Konstruktor oder BigDecimal.valueOf nutzen.","lesson":"java-m7-l2","tested":true},{"id":"java-objects","cat":"Klassen","term":"Objects und Null-Prüfung","syntax":"Objects.requireNonNull(x, \"meldung\")    Objects.equals(a, b)    Objects.requireNonNullElse(x, y)","text":"Objects bietet Helfer für null: requireNonNull bricht früh mit klarer Meldung ab, equals vergleicht ohne NullPointerException, requireNonNullElse liefert einen Ersatzwert.","code":"String s = null;\nSystem.out.println(Objects.equals(s, null) + \" \" + Objects.requireNonNullElse(s, \"leer\"));\ntry { Objects.requireNonNull(s, \"name darf nicht null sein\"); } catch (NullPointerException e) { System.out.println(e.getMessage()); }","out":"true leer\nname darf nicht null sein","pitfall":"Fehler früh melden (am Konstruktor) statt weit entfernt bei der ersten Verwendung. Das spart Zeit bei der Fehlersuche.","lesson":"java-m10-l3","tested":true},{"id":"java-custom-exception","cat":"Fehler","term":"Eigene Exception","syntax":"class MeineException extends RuntimeException { … }","text":"Eigene Ausnahmen drücken Fachfehler aus. Von RuntimeException erben ist unchecked, von Exception erben ist checked (muss deklariert und behandelt werden). Die Ursache lässt sich als cause mitgeben.","code":"class KontoLeer extends RuntimeException {\n    KontoLeer(String message, Throwable cause) { super(message, cause); }\n}\ntry {\n    try { Integer.parseInt(\"x\"); }\n    catch (NumberFormatException e) { throw new KontoLeer(\"Konto konnte nicht gelesen werden\", e); }\n} catch (KontoLeer e) {\n    System.out.println(e.getMessage() + \" <- \" + e.getCause().getClass().getSimpleName());\n}","out":"Konto konnte nicht gelesen werden <- NumberFormatException","pitfall":"Beim Umwandeln einer Ausnahme die Ursache (cause) mitgeben. Ohne sie fehlt im Stacktrace der eigentliche Anlass.","lesson":"java-m10-l3","tested":true},{"id":"java-map-methods","cat":"Sammlungen","term":"Map: getOrDefault, computeIfAbsent, merge","syntax":"map.getOrDefault(k, d)    map.computeIfAbsent(k, f)    map.merge(k, 1, Integer::sum)","text":"Kompakte Operationen für Zähl- und Gruppiermuster. computeIfAbsent legt einen fehlenden Wert an und gibt ihn zurück, merge fasst alten und neuen Wert zusammen.","code":"var gruppen = new TreeMap<Integer, List<String>>();\nfor (var w : List.of(\"ab\", \"cd\", \"efg\"))\n    gruppen.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);\nSystem.out.println(gruppen + \" \" + gruppen.getOrDefault(9, List.of()));","out":"{2=[ab, cd], 3=[efg]} []","pitfall":"Eine HashMap darf beim Durchlaufen nicht verändert werden. In computeIfAbsent keine weitere Änderung derselben Map vornehmen.","lesson":"java-m9-l1","tested":true},{"id":"java-sequenced","cat":"Sammlungen","term":"Sequenced Collections (Java 21)","syntax":"liste.getFirst()  liste.getLast()  liste.reversed()","text":"Seit Java 21 haben geordnete Sammlungen gemeinsame Methoden für Anfang und Ende, statt umständlich liste.get(liste.size() - 1) zu schreiben. reversed() liefert eine umgekehrte Sicht.","code":"var l = new ArrayList<>(List.of(1, 2, 3));\nl.addFirst(0);\nSystem.out.println(l.getFirst() + \" \" + l.getLast() + \" \" + l.reversed());","out":"0 3 [3, 2, 1, 0]","pitfall":"reversed() ist eine Sicht auf dieselbe Liste, keine Kopie. Änderungen wirken in beide Richtungen.","lesson":"java-m25-l3","tested":true},{"id":"java-int-stream","cat":"Funktional","term":"IntStream, flatMap, joining","syntax":"IntStream.rangeClosed(1, n)    stream.flatMap(…)    Collectors.joining(\", \")","text":"IntStream arbeitet ohne Boxing mit Zahlen (sum, average, max). flatMap macht aus mehreren Listen einen Strom, Collectors.joining verbindet Texte.","code":"System.out.println(IntStream.rangeClosed(1, 5).sum() + \" \" + IntStream.of(1, 2, 3, 4).average().orElse(0));\nSystem.out.println(Stream.of(List.of(\"a\", \"b\"), List.of(\"c\")).flatMap(List::stream).collect(Collectors.joining(\", \", \"[\", \"]\")));","out":"15 2.5\n[a, b, c]","pitfall":"average() liefert ein OptionalDouble, weil es bei leerem Strom keinen Mittelwert gibt. Den leeren Fall mit orElse behandeln.","lesson":"java-m11-l2","tested":true},{"id":"java-partition","cat":"Funktional","term":"partitioningBy und toMap","syntax":"Collectors.partitioningBy(bedingung)    Collectors.toMap(keyFn, valueFn, merge)","text":"partitioningBy teilt in „wahr“ und „falsch“, toMap bildet eine Map. Die dritte Funktion in toMap löst doppelte Schlüssel auf.","code":"var teile = Stream.of(1, 2, 3, 4, 5).collect(Collectors.partitioningBy(n -> n % 2 == 0));\nSystem.out.println(teile);\nvar laengen = Stream.of(\"ab\", \"cd\", \"e\").collect(Collectors.toMap(String::length, s -> s, (a, b) -> a + b, TreeMap::new));\nSystem.out.println(laengen);","out":"{false=[1, 3, 5], true=[2, 4]}\n{1=e, 2=abcd}","pitfall":"toMap ohne Zusammenführungsfunktion wirft bei doppelten Schlüsseln eine IllegalStateException.","lesson":"java-m11-l3","tested":true},{"id":"java-gatherers","cat":"Funktional","term":"Stream Gatherers (Java 24)","syntax":"stream.gather(Gatherers.windowFixed(n))","text":"Gatherer sind eigene Zwischenschritte für Streams. Eingebaut sind windowFixed (feste Fenster), windowSliding (gleitende Fenster), fold und scan.","code":"System.out.println(Stream.of(1, 2, 3, 4, 5).gather(Gatherers.windowFixed(2)).toList());\nSystem.out.println(Stream.of(1, 2, 3, 4).gather(Gatherers.windowSliding(3)).toList());","out":"[[1, 2], [3, 4], [5]]\n[[1, 2, 3], [2, 3, 4]]","pitfall":"Erst ab Java 24 final. In Java 22 und 23 nur als Preview mit --enable-preview verfügbar.","lesson":"java-m25-l6","tested":true},{"id":"java-atomic","cat":"Nebenläufigkeit","term":"Thread, join, AtomicInteger","syntax":"new Thread(runnable).start()    thread.join()    new AtomicInteger()","text":"Ein Thread führt Code parallel aus, join wartet auf sein Ende. Zugriffe mehrerer Threads auf dieselbe Zahl brauchen Atomic-Klassen oder synchronized, sonst gehen Änderungen verloren.","code":"var zaehler = new java.util.concurrent.atomic.AtomicInteger();\nvar threads = new ArrayList<Thread>();\nfor (int i = 0; i < 4; i++) {\n    var t = new Thread(() -> { for (int j = 0; j < 1000; j++) zaehler.incrementAndGet(); });\n    threads.add(t);\n    t.start();\n}\nfor (var t : threads) t.join();\nSystem.out.println(zaehler.get());","out":"4000","pitfall":"Mit einem normalen int und count++ wäre das Ergebnis meist kleiner als 4000 (Race Condition) und bei jedem Lauf anders.","lesson":"java-m13-l2","tested":true},{"id":"java-duration","cat":"Daten","term":"Duration, Period, Instant","syntax":"Duration.ofMinutes(90)    Period.between(a, b)    Instant.now()","text":"Duration misst Zeitspannen in Stunden, Minuten, Sekunden, Period in Tagen, Monaten und Jahren. Instant ist ein Zeitpunkt auf der Weltzeitachse, geeignet zum Speichern.","code":"var d = java.time.Duration.ofMinutes(135);\nSystem.out.println(d.toHours() + \"h \" + d.toMinutesPart() + \"min\");\nSystem.out.println(java.time.Period.between(LocalDate.of(2026, 1, 15), LocalDate.of(2026, 11, 13)));","out":"2h 15min\nP9M29D","pitfall":"Für Kalenderangaben (Tage, Monate) Period nehmen, für Uhrzeitspannen Duration. Ein Tag mit Zeitumstellung hat nicht 24 Stunden.","lesson":"java-m14-l1","tested":true},{"id":"java-spring-bean","cat":"Spring Boot","term":"@Configuration und @Bean","syntax":"@Configuration class Config { @Bean Typ name() { … } }","text":"Methoden mit @Bean erzeugen Objekte, die Spring verwaltet und per Konstruktor weitergibt. Sinnvoll für Klassen aus Fremdbibliotheken, die man nicht mit @Component annotieren kann.","code":"@Configuration\nclass ClientConfig {\n    @Bean\n    RestClient bestellClient(RestClient.Builder builder, @Value(\"${bestell.url}\") String url) {\n        return builder.baseUrl(url).build();\n    }\n}","pitfall":"Beans sind standardmäßig Singletons und müssen threadsicher sein. Veränderlichen Zustand darin vermeiden.","lesson":"java-m21-l2","tested":false},{"id":"java-spring-config","cat":"Spring Boot","term":"@ConfigurationProperties und application.yml","syntax":"@ConfigurationProperties(prefix = \"app\") record AppProperties(…)","text":"Bindet Einstellungen aus application.yml oder Umgebungsvariablen an ein typisiertes Objekt. Profile (application-prod.yml, spring.profiles.active) trennen Umgebungen.","code":"# application.yml\napp:\n  mail:\n    absender: no-reply@example.org\n    versuche: 3\n\n// Java\n@ConfigurationProperties(prefix = \"app.mail\")\nrecord MailProperties(String absender, int versuche) {}","pitfall":"Passwörter und Schlüssel gehören nicht in application.yml im Repository, sondern in Umgebungsvariablen oder einen Secret-Speicher.","lesson":"java-m21-l3","tested":false},{"id":"java-spring-advice","cat":"Spring Boot","term":"@RestControllerAdvice und ProblemDetail","syntax":"@ExceptionHandler(Typ.class) ProblemDetail behandle(Typ e)","text":"Zentrale Fehlerbehandlung für alle Controller. ProblemDetail ist das Standardformat (RFC 9457) für Fehlerantworten mit status, title und detail.","code":"@RestControllerAdvice\nclass FehlerBehandlung {\n    @ExceptionHandler(AufgabeNichtGefunden.class)\n    ProblemDetail nichtGefunden(AufgabeNichtGefunden e) {\n        var pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());\n        pd.setTitle(\"Aufgabe nicht gefunden\");\n        return pd;\n    }\n}","pitfall":"Keine Stacktraces oder interne Details im detail-Feld ausgeben. Das verrät Aufbau und Versionen der Anwendung.","lesson":"java-m26-l3","tested":false},{"id":"java-spring-test","cat":"Spring Boot","term":"@SpringBootTest und MockMvc","syntax":"@SpringBootTest @AutoConfigureMockMvc    mockMvc.perform(get(\"/pfad\")).andExpect(status().isOk())","text":"Startet die Anwendung für einen Test, MockMvc ruft Controller ohne echten Netzwerkserver auf. @WebMvcTest testet nur die Webschicht und ist schneller.","code":"@WebMvcTest(AufgabeController.class)\nclass AufgabeControllerTest {\n    @Autowired MockMvc mockMvc;\n    @MockitoBean AufgabeService service;\n\n    @Test\n    void liefert404BeiUnbekannterId() throws Exception {\n        when(service.finde(99)).thenThrow(new AufgabeNichtGefunden(99));\n        mockMvc.perform(get(\"/api/aufgaben/99\")).andExpect(status().isNotFound());\n    }\n}","pitfall":"Seit Spring Boot 3.4 ersetzt @MockitoBean das alte @MockBean. Alte Beispiele im Netz nutzen noch @MockBean.","lesson":"java-m24-l1","tested":false},{"id":"java-spring-entity","cat":"Spring Boot","term":"JPA-Entity","syntax":"@Entity class X { @Id @GeneratedValue Long id; … }","text":"Eine Entity bildet eine Tabelle ab. @Id kennzeichnet den Schlüssel, @Column feinjustiert Spalten, @ManyToOne und @OneToMany beschreiben Beziehungen. Ein Konstruktor ohne Argumente wird von JPA benötigt.","code":"@Entity\nclass Aufgabe {\n    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n\n    @Column(nullable = false, length = 120)\n    private String titel;\n\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    private Nutzer besitzer;\n\n    protected Aufgabe() {}\n}","pitfall":"Bei @ManyToOne und @OneToOne ist der Standard EAGER. Explizit LAZY setzen, um ungewollte Zusatzabfragen zu vermeiden.","lesson":"java-m17-l3","tested":false},{"id":"java-spring-security","cat":"Spring Boot","term":"SecurityFilterChain","syntax":"@Bean SecurityFilterChain filterChain(HttpSecurity http)","text":"Legt fest, welche Pfade öffentlich sind und welche eine Anmeldung oder Rolle verlangen. Alles andere wird standardmäßig geschützt. CSRF-Schutz bleibt für Browseranwendungen aktiv.","code":"@Bean\nSecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http.authorizeHttpRequests(a -> a\n            .requestMatchers(\"/actuator/health\").permitAll()\n            .requestMatchers(\"/admin/**\").hasRole(\"ADMIN\")\n            .anyRequest().authenticated())\n        .formLogin(Customizer.withDefaults());\n    return http.build();\n}","pitfall":"Die Reihenfolge der Regeln zählt: Die erste passende gewinnt. anyRequest() gehört ans Ende.","lesson":"java-m24-l2","tested":false},{"id":"java-flyway","cat":"Spring Boot","term":"Flyway-Migration","syntax":"src/main/resources/db/migration/V1__beschreibung.sql","text":"Datenbankänderungen als versionierte SQL-Dateien. Flyway führt sie beim Start der Reihe nach aus und merkt sich den Stand. Der Name besteht aus V, Versionsnummer, zwei Unterstrichen und Beschreibung.","code":"-- V2__aufgabe_faelligkeit.sql\nALTER TABLE aufgabe ADD COLUMN faellig DATE;\nCREATE INDEX idx_aufgabe_faellig ON aufgabe (faellig);","pitfall":"Eine bereits ausgeführte Migration niemals ändern, Flyway prüft eine Prüfsumme und bricht ab. Änderungen immer in einer neuen Datei.","lesson":"java-m26-l1","tested":false},{"id":"java-maven","cat":"Build","term":"Maven-Befehle","syntax":"./mvnw test    ./mvnw verify    ./mvnw spring-boot:run","text":"Der Maven Wrapper (mvnw) startet die im Projekt festgelegte Maven-Version. test führt die Tests aus, verify zusätzlich Integrationsprüfungen, package baut die JAR-Datei, clean löscht den Ordner target.","code":"./mvnw -B test                  # Tests, nicht interaktiv\n./mvnw clean package -DskipTests # JAR bauen\n./mvnw dependency:tree          # Abhängigkeiten anzeigen","pitfall":"-DskipTests in der Entwicklung ist bequem, gehört aber nicht in die CI-Pipeline.","lesson":"java-m16-l1","tested":false},{"id":"java-restclient","cat":"Spring Boot","term":"RestClient mit Timeout","syntax":"RestClient.create(url).get().uri(…).retrieve().body(Typ.class)","text":"Der moderne synchrone HTTP-Client von Spring. retrieve() löst bei 4xx und 5xx eine Ausnahme aus, body() liest die Antwort als Objekt. Timeouts werden an der Request-Factory gesetzt.","code":"var factory = new JdkClientHttpRequestFactory(\n    HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build());\nfactory.setReadTimeout(Duration.ofSeconds(5));\n\nvar client = RestClient.builder().baseUrl(\"https://api.example.org\").requestFactory(factory).build();\nvar kunde = client.get().uri(\"/kunden/{id}\", 42).retrieve().body(KundeDto.class);","pitfall":"Ohne Timeout wartet ein Aufruf theoretisch ewig und blockiert Threads. Verbindungs- und Lesezeit immer begrenzen.","lesson":"java-m26-l6","tested":false}]},{"id":"sql","label":"SQL (MariaDB)","codeLang":"sql","intro":"Abfragesprache für relationale Datenbanken. Alle Beispiele nutzen dieselben Tabellen kunde und bestellung (siehe „Ausgangsdaten“).","notice":"Die Beispiele mit Markierung laufen in SQLite und zeigen den gemeinsamen SQL-Kern. MariaDB kann in Details abweichen (Typen, AUTO_INCREMENT, Ausgabeformat). MariaDB-Besonderheiten werden nur gezeigt.","runner":"SQLite","entries":[{"id":"sql-select","cat":"Abfragen","term":"SELECT … FROM … WHERE","syntax":"SELECT spalten FROM tabelle WHERE bedingung;","text":"Liest Zeilen aus einer Tabelle. Hinter SELECT stehen die Spalten, hinter FROM die Tabelle, WHERE filtert die Zeilen. Text steht in einfachen Anführungszeichen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name, stadt FROM kunde WHERE stadt = 'Berlin';","out":"Ada | Berlin","pitfall":"SELECT * liefert alle Spalten, auch später hinzugefügte. In Anwendungen die benötigten Spalten nennen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-order","cat":"Abfragen","term":"ORDER BY und LIMIT","syntax":"ORDER BY spalte [DESC]  LIMIT anzahl [OFFSET start]","text":"ORDER BY sortiert aufsteigend (ASC) oder absteigend (DESC). LIMIT begrenzt die Zahl der Zeilen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde ORDER BY name DESC LIMIT 2;","out":"Cy\nBo","pitfall":"Ohne ORDER BY ist die Reihenfolge nicht garantiert. LIMIT ohne Sortierung liefert zufällige Zeilen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-null","cat":"Abfragen","term":"IS NULL","syntax":"WHERE spalte IS NULL    WHERE spalte IS NOT NULL","text":"NULL bedeutet „kein Wert“. Es lässt sich nicht mit = prüfen, sondern nur mit IS NULL oder IS NOT NULL.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE stadt IS NULL;","out":"Cy","pitfall":"stadt = NULL ist nie wahr, auch nicht für leere Zeilen. NULL-Vergleiche liefern „unbekannt“ und filtern die Zeile heraus.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-like-in","cat":"Abfragen","term":"LIKE, IN, BETWEEN","syntax":"name LIKE 'A%'    id IN (1, 2)    betrag BETWEEN 5 AND 15","text":"LIKE sucht Muster (% steht für beliebig viele Zeichen, _ für genau eins). IN prüft auf eine Liste, BETWEEN schließt beide Grenzen ein.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE name LIKE 'A%' OR id IN (3);\nSELECT id FROM bestellung WHERE betrag BETWEEN 6 AND 12 ORDER BY id;","out":"Ada\nCy\n2\n3","pitfall":"LIKE '%text%' kann keinen normalen Index nutzen und wird bei großen Tabellen langsam. Dafür Volltextsuche einsetzen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-distinct-alias","cat":"Abfragen","term":"DISTINCT und AS","syntax":"SELECT DISTINCT spalte AS alias FROM …","text":"DISTINCT entfernt doppelte Zeilen im Ergebnis. AS vergibt einen Namen für Spalten und Tabellen (Alias).","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT DISTINCT kunde_id AS kunde FROM bestellung ORDER BY kunde;","out":"1\n2","pitfall":"DISTINCT versteckt oft einen fehlerhaften Join. Erst prüfen, warum Duplikate entstehen, statt sie wegzufiltern.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-insert","cat":"Daten ändern","term":"INSERT","syntax":"INSERT INTO tabelle (spalten) VALUES (werte);","text":"Fügt eine Zeile ein. Die Spalten immer nennen, damit sich das Statement bei neuen Spalten nicht verschiebt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"INSERT INTO kunde (id, name, stadt) VALUES (4, 'Di', 'Köln');\nSELECT COUNT(*) FROM kunde;","out":"4","pitfall":"Werte aus Nutzereingaben nie per Textverkettung einsetzen. Platzhalter verwenden (Prepared Statements), sonst droht SQL-Injection.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-update","cat":"Daten ändern","term":"UPDATE","syntax":"UPDATE tabelle SET spalte = wert WHERE bedingung;","text":"Ändert vorhandene Zeilen. Ohne WHERE werden alle Zeilen der Tabelle geändert.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"UPDATE kunde SET stadt = 'Bonn' WHERE id = 3;\nSELECT name, stadt FROM kunde WHERE id = 3;","out":"Cy | Bonn","pitfall":"Ein vergessenes WHERE ändert die ganze Tabelle. Vorher mit einem SELECT mit gleicher Bedingung prüfen und in einer Transaktion arbeiten.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-delete","cat":"Daten ändern","term":"DELETE","syntax":"DELETE FROM tabelle WHERE bedingung;","text":"Löscht Zeilen. Auch hier gilt: Ohne WHERE verschwinden alle Zeilen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"DELETE FROM bestellung WHERE id = 3;\nSELECT COUNT(*) FROM bestellung;","out":"2","pitfall":"Gelöscht ist gelöscht. Für Nachvollziehbarkeit oft ein Löschkennzeichen (deleted_at) statt echtem Löschen, sofern der Datenschutz nichts anderes verlangt.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-create","cat":"Schema","term":"CREATE TABLE mit Constraints","syntax":"CREATE TABLE name (spalte typ [NOT NULL] [UNIQUE] [CHECK (…)], PRIMARY KEY …)","text":"Legt eine Tabelle an. Constraints sichern Regeln in der Datenbank selbst: PRIMARY KEY (eindeutig), NOT NULL (Pflicht), UNIQUE (keine Doppelten), CHECK (Bedingung).","code":"CREATE TABLE produkt (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL UNIQUE,\n  preis INTEGER CHECK (preis >= 0)\n);\nINSERT INTO produkt (name, preis) VALUES ('Tee', 3);\nSELECT * FROM produkt;","out":"1 | Tee | 3","pitfall":"In MariaDB heißt der automatische Zähler id INT AUTO_INCREMENT PRIMARY KEY, in SQLite genügt INTEGER PRIMARY KEY. Für kurze Texte nimmt man in MariaDB meist VARCHAR(100) statt TEXT.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-fk","cat":"Schema","term":"FOREIGN KEY","syntax":"FOREIGN KEY (spalte) REFERENCES andere_tabelle (id) ON DELETE …","text":"Verknüpft eine Spalte mit dem Primärschlüssel einer anderen Tabelle. Die Datenbank verhindert dann Verweise ins Leere. ON DELETE legt fest, was beim Löschen passiert (RESTRICT, CASCADE, SET NULL).","code":"CREATE TABLE bestellung (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  kunde_id INT NOT NULL,\n  betrag DECIMAL(10,2) NOT NULL,\n  FOREIGN KEY (kunde_id) REFERENCES kunde (id) ON DELETE RESTRICT\n) ENGINE = InnoDB;","pitfall":"Fremdschlüssel funktionieren in MariaDB nur mit InnoDB. Geldbeträge als DECIMAL speichern, nicht als FLOAT.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-alter","cat":"Schema","term":"ALTER TABLE","syntax":"ALTER TABLE tabelle ADD COLUMN spalte typ;","text":"Ändert eine bestehende Tabelle, etwa eine Spalte hinzufügen. Änderungen am Schema gehören in versionierte Migrationen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"ALTER TABLE kunde ADD COLUMN email TEXT;\nUPDATE kunde SET email = 'ada@example.org' WHERE id = 1;\nSELECT name, email FROM kunde WHERE id = 1;","out":"Ada | ada@example.org","pitfall":"Auf großen Tabellen sperren manche ALTER-Befehle lange. Vor dem Produktiveinsatz an einer Kopie testen.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-join","cat":"Joins","term":"INNER JOIN","syntax":"FROM a JOIN b ON a.id = b.a_id","text":"Verknüpft zwei Tabellen über zusammengehörende Werte. Der INNER JOIN liefert nur Zeilen, für die es auf beiden Seiten einen Treffer gibt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT k.name, b.betrag\nFROM kunde k\nJOIN bestellung b ON b.kunde_id = k.id\nORDER BY b.id;","out":"Ada | 20\nAda | 6\nBo | 12","pitfall":"Kunde Cy ohne Bestellung fehlt im Ergebnis. Wer ihn sehen will, braucht einen LEFT JOIN.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-leftjoin","cat":"Joins","term":"LEFT JOIN","syntax":"FROM a LEFT JOIN b ON …","text":"Liefert alle Zeilen der linken Tabelle, auch ohne Treffer rechts. Dort stehen dann NULL-Werte. Ideal, um „ohne Bestellung“ zu finden.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT k.name, COUNT(b.id) AS anzahl\nFROM kunde k\nLEFT JOIN bestellung b ON b.kunde_id = k.id\nGROUP BY k.id\nORDER BY k.id;","out":"Ada | 2\nBo | 1\nCy | 0","pitfall":"Bedingungen auf die rechte Tabelle gehören in ON, nicht in WHERE. Ein WHERE auf rechte Spalten macht den LEFT JOIN wieder zum INNER JOIN.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-group","cat":"Aggregation","term":"GROUP BY und HAVING","syntax":"GROUP BY spalte HAVING aggregat > wert","text":"GROUP BY fasst Zeilen zu Gruppen zusammen, Aggregatfunktionen rechnen je Gruppe. WHERE filtert vorher einzelne Zeilen, HAVING filtert danach ganze Gruppen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT kunde_id, SUM(betrag) AS summe\nFROM bestellung\nGROUP BY kunde_id\nHAVING SUM(betrag) > 15;","out":"1 | 26","pitfall":"Alle nicht aggregierten Spalten im SELECT müssen im GROUP BY stehen (MariaDB im Modus ONLY_FULL_GROUP_BY).","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-aggregate","cat":"Aggregation","term":"COUNT, SUM, AVG, MIN, MAX","syntax":"COUNT(*)  COUNT(spalte)  SUM(…)  AVG(…)","text":"Fassen viele Zeilen zu einem Wert zusammen. COUNT(*) zählt Zeilen, COUNT(spalte) nur Zeilen mit Wert (ohne NULL).","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT COUNT(*), COUNT(stadt), SUM(id), AVG(id), MIN(name), MAX(name) FROM kunde;","out":"3 | 2 | 6 | 2.0 | Ada | Cy","pitfall":"AVG und SUM ignorieren NULL. Bei komplett leerer Gruppe liefert SUM NULL, nicht 0. COALESCE(SUM(x), 0) nutzen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-subquery","cat":"Aggregation","term":"Unterabfrage","syntax":"WHERE spalte IN (SELECT …)","text":"Eine Abfrage innerhalb einer anderen. IN (SELECT …) prüft, ob ein Wert in einer Ergebnisliste vorkommt. EXISTS fragt, ob es überhaupt Treffer gibt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde\nWHERE id IN (SELECT kunde_id FROM bestellung WHERE betrag > 10)\nORDER BY name;","out":"Ada\nBo","pitfall":"NOT IN (SELECT …) liefert nichts, sobald die Unterabfrage ein NULL enthält. NOT EXISTS ist hier sicherer.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-case","cat":"Abfragen","term":"CASE und COALESCE","syntax":"CASE WHEN … THEN … ELSE … END    COALESCE(a, b)","text":"CASE wählt je Zeile einen Wert nach Bedingungen. COALESCE liefert das erste Argument, das nicht NULL ist, und ersetzt so fehlende Werte.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name,\n  CASE WHEN stadt = 'Berlin' THEN 'Hauptstadt' ELSE 'andere' END AS art,\n  COALESCE(stadt, 'unbekannt') AS ort\nFROM kunde ORDER BY id;","out":"Ada | Hauptstadt | Berlin\nBo | andere | Hamburg\nCy | andere | unbekannt","pitfall":"Für Cy ist stadt = 'Berlin' weder wahr noch falsch (NULL), deshalb greift der ELSE-Zweig. NULL gesondert behandeln, wenn es einen Unterschied macht.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-cte","cat":"Abfragen","term":"WITH (CTE)","syntax":"WITH name AS (SELECT …) SELECT … FROM name","text":"Benennt eine Zwischenabfrage und macht komplexe Abfragen lesbar. Sie wird wie eine temporäre Tabelle verwendet.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"WITH summen AS (\n  SELECT kunde_id, SUM(betrag) AS s FROM bestellung GROUP BY kunde_id\n)\nSELECT k.name, summen.s\nFROM summen JOIN kunde k ON k.id = summen.kunde_id\nORDER BY summen.s DESC;","out":"Ada | 26\nBo | 12","pitfall":"WITH ist in MariaDB ab Version 10.2 verfügbar. Auf älteren Servern gibt es einen Syntaxfehler.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-union","cat":"Abfragen","term":"UNION","syntax":"SELECT … UNION [ALL] SELECT …","text":"Hängt die Ergebnisse zweier Abfragen aneinander. UNION entfernt Doppelte, UNION ALL behält sie und ist schneller. Beide Abfragen brauchen gleich viele Spalten gleichen Typs.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE id = 1\nUNION\nSELECT name FROM kunde WHERE id = 3;","out":"Ada\nCy","pitfall":"Die Spaltennamen kommen von der ersten Abfrage. Die Reihenfolge der Spalten in beiden Abfragen muss übereinstimmen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-transaction","cat":"Transaktionen","term":"BEGIN, COMMIT, ROLLBACK","syntax":"START TRANSACTION; … COMMIT;    ROLLBACK;","text":"Fasst mehrere Änderungen zu einer Einheit zusammen: Entweder alles wird übernommen (COMMIT) oder alles zurückgenommen (ROLLBACK). In MariaDB beginnt man mit START TRANSACTION oder BEGIN.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"BEGIN;\nUPDATE bestellung SET betrag = 0 WHERE id = 1;\nROLLBACK;\nSELECT betrag FROM bestellung WHERE id = 1;","out":"20","pitfall":"Transaktionen funktionieren nur mit transaktionsfähigen Engines (InnoDB). Lange offene Transaktionen halten Sperren und blockieren andere.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-index","cat":"Leistung","term":"CREATE INDEX und EXPLAIN","syntax":"CREATE INDEX name ON tabelle (spalte);    EXPLAIN SELECT …","text":"Ein Index beschleunigt Suche und Sortierung nach einer Spalte. EXPLAIN zeigt, ob die Abfrage ihn nutzt, statt die ganze Tabelle zu lesen.","code":"CREATE INDEX idx_bestellung_kunde ON bestellung (kunde_id);\nEXPLAIN SELECT * FROM bestellung WHERE kunde_id = 1;","pitfall":"Jeder Index macht Schreibzugriffe langsamer und braucht Speicher. Nur anlegen, wenn EXPLAIN und echte Abfragen es zeigen, nicht auf Verdacht.","lesson":"mariadb-m1-l5","tested":false},{"id":"sql-placeholder","cat":"Sicherheit","term":"Platzhalter (Prepared Statement)","syntax":"SELECT … WHERE id = ?    WHERE id = :id","text":"Das SQL steht fest, die Werte werden getrennt übergeben. So kann Nutzereingabe nie als SQL-Befehl ausgeführt werden. Das gilt in PHP (PDO), Java (PreparedStatement) und anderen Sprachen.","code":"-- PHP (PDO)\n$stmt = $pdo->prepare('SELECT * FROM kunde WHERE name = :name');\n$stmt->execute(['name' => $eingabe]);\n\n-- Java (JDBC)\nvar ps = connection.prepareStatement(\"SELECT * FROM kunde WHERE name = ?\");\nps.setString(1, eingabe);","pitfall":"Platzhalter gelten für Werte, nicht für Tabellen-, Spalten- oder Sortierbezeichner. Dafür eine feste Liste erlaubter Namen verwenden.","lesson":"mariadb-m1-l3","tested":false},{"id":"sql-grant","cat":"Sicherheit","term":"GRANT und REVOKE","syntax":"GRANT SELECT, INSERT ON db.* TO 'nutzer'@'host';","text":"Vergibt und entzieht Rechte. Anwendungen bekommen ein eigenes Konto mit den kleinsten nötigen Rechten (Least Privilege), nicht den Administrator.","code":"CREATE USER 'shop_app'@'localhost' IDENTIFIED BY '…';\nGRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'shop_app'@'localhost';\nREVOKE DELETE ON shop.* FROM 'shop_app'@'localhost';","pitfall":"Passwörter nie im Skript und nie im Repository speichern. Sie gehören in Umgebungsvariablen oder einen Secret-Speicher.","lesson":"mariadb-m1-l6","tested":false},{"id":"sql-recursive-cte","cat":"Abfragen","term":"WITH RECURSIVE","syntax":"WITH RECURSIVE name(spalte) AS (Anker UNION ALL Rekursion) SELECT …","text":"Eine rekursive CTE wiederholt sich selbst, bis keine neuen Zeilen mehr entstehen. Typisch für Zahlenreihen, Kalender und Hierarchien (Kategorien, Organigramme). Der Anker liefert die Startzeilen, der zweite Teil baut darauf auf.","code":"WITH RECURSIVE zahlen(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM zahlen WHERE n < 5\n)\nSELECT n FROM zahlen;","out":"1\n2\n3\n4\n5","pitfall":"Ohne Abbruchbedingung (WHERE) läuft die Rekursion endlos bzw. bis zum Limit (MariaDB: max_recursive_iterations). Bei Hierarchien auf Zyklen achten.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-set-ops","cat":"Abfragen","term":"INTERSECT und EXCEPT","syntax":"SELECT … INTERSECT SELECT …    SELECT … EXCEPT SELECT …","text":"INTERSECT liefert Zeilen, die in beiden Abfragen vorkommen, EXCEPT Zeilen der ersten, die in der zweiten fehlen. Die Spaltenzahl und -typen müssen zusammenpassen. Doppelte Zeilen entfallen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT id FROM kunde EXCEPT SELECT kunde_id FROM bestellung;\nSELECT id FROM kunde INTERSECT SELECT kunde_id FROM bestellung ORDER BY 1;","out":"3\n1\n2","pitfall":"MariaDB kennt INTERSECT und EXCEPT erst ab Version 10.3. Für ältere Versionen oder NULL-Behandlung ist NOT EXISTS die sichere Alternative.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-ifnull-nullif","cat":"Abfragen","term":"IFNULL und NULLIF","syntax":"IFNULL(wert, ersatz)    NULLIF(a, b)","text":"IFNULL ersetzt NULL durch einen Wert (COALESCE kann mehrere Alternativen). NULLIF liefert NULL, wenn beide Werte gleich sind, zum Beispiel um eine Division durch 0 zu vermeiden.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name, IFNULL(stadt, 'unbekannt'), NULLIF(stadt, 'Berlin') FROM kunde ORDER BY id;","out":"Ada | Berlin |\nBo | Hamburg | Hamburg\nCy | unbekannt |","pitfall":"Rechnen mit NULL ergibt NULL. Bei Summen und Durchschnitten NULL bewusst behandeln, sonst fehlen Zeilen still im Ergebnis.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-null-logic","cat":"Abfragen","term":"NULL und dreiwertige Logik","syntax":"NULL = NULL → NULL    IS NULL    COUNT(*) vs. COUNT(spalte)","text":"NULL heißt „unbekannt“. Jeder Vergleich mit NULL ergibt NULL (weder wahr noch falsch), deshalb braucht man IS NULL. COUNT(*) zählt Zeilen, COUNT(spalte) nur die mit Wert.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT (NULL = NULL) IS NULL, (1 IN (2, NULL)) IS NULL, COUNT(stadt), COUNT(*) FROM kunde;","out":"1 | 1 | 2 | 3","pitfall":"NOT IN mit einer Liste oder Unterabfrage, die NULL enthält, liefert nie Treffer. NOT EXISTS verwenden.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-conditional-agg","cat":"Aggregation","term":"Bedingte Aggregation (SUM(CASE …))","syntax":"SUM(CASE WHEN bedingung THEN 1 ELSE 0 END)","text":"Mit CASE innerhalb einer Aggregatfunktion zählt oder summiert man nur bestimmte Zeilen und bekommt mehrere Kennzahlen in einer Abfrage, auch als Kreuztabelle (Pivot).","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT SUM(CASE WHEN betrag >= 10 THEN 1 ELSE 0 END) AS gross,\n       SUM(CASE WHEN betrag < 10 THEN 1 ELSE 0 END) AS klein\nFROM bestellung;","out":"2 | 1","pitfall":"Auf eine leere Tabelle angewendet liefert SUM NULL, nicht 0. Bei Bedarf mit COALESCE(SUM(…), 0) umschließen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-top-n-group","cat":"Aggregation","term":"Größter Wert je Gruppe (ROW_NUMBER)","syntax":"ROW_NUMBER() OVER (PARTITION BY gruppe ORDER BY wert DESC) AS rn … WHERE rn = 1","text":"Fensterfunktionen nummerieren Zeilen je Gruppe. Filtert man auf Nummer 1, erhält man die jeweils beste Zeile, zum Beispiel die größte Bestellung pro Kunde. Der Filter geht nur in einer äußeren Abfrage.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT kunde_id, betrag FROM (\n  SELECT kunde_id, betrag,\n         ROW_NUMBER() OVER (PARTITION BY kunde_id ORDER BY betrag DESC) AS rn\n  FROM bestellung\n) AS t WHERE rn = 1 ORDER BY kunde_id;","out":"1 | 20\n2 | 12","pitfall":"Bei Gleichstand wählt ROW_NUMBER willkürlich eine Zeile. Mit einem zweiten Sortierkriterium eindeutig machen oder RANK verwenden.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-returning","cat":"Daten ändern","term":"INSERT … RETURNING","syntax":"INSERT INTO t (…) VALUES (…) RETURNING spalte, …","text":"Liefert die eingefügten Zeilen gleich zurück, zum Beispiel die vergebene id, ohne zweite Abfrage. Ähnlich funktioniert DELETE … RETURNING.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"INSERT INTO kunde (name, stadt) VALUES ('Di', 'Köln') RETURNING id, name;","out":"4 | Di","pitfall":"MariaDB unterstützt INSERT … RETURNING ab Version 10.5 (DELETE … RETURNING schon länger), UPDATE … RETURNING gibt es nicht. Alternative: LAST_INSERT_ID().","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-generated-unique","cat":"Schema","term":"UNIQUE, CHECK und berechnete Spalte","syntax":"UNIQUE (a, b)    CHECK (bedingung)    spalte … GENERATED ALWAYS AS (ausdruck) STORED","text":"Die Datenbank kann Regeln selbst erzwingen: UNIQUE verhindert doppelte Werte, CHECK prüft Bedingungen, eine berechnete Spalte hält einen abgeleiteten Wert (z. B. Brutto aus Netto) immer aktuell.","code":"CREATE TABLE artikel (\n  id INTEGER PRIMARY KEY,\n  sku TEXT NOT NULL UNIQUE,\n  netto INTEGER NOT NULL CHECK (netto >= 0),\n  brutto INTEGER GENERATED ALWAYS AS (netto * 119 / 100) STORED\n);\nINSERT INTO artikel (sku, netto) VALUES ('A1', 100);\nSELECT sku, netto, brutto FROM artikel;","out":"A1 | 100 | 119","pitfall":"CHECK-Bedingungen werden erst ab MariaDB 10.2 wirklich erzwungen (MySQL ab 8.0.16). Rechenregeln wie Steuersätze gehören besser in die Anwendung, wenn sie sich ändern.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-types","cat":"Schema","term":"Datentypen (MariaDB)","syntax":"INT  BIGINT  DECIMAL(10,2)  VARCHAR(n)  TEXT  DATE  DATETIME  TIMESTAMP  BOOLEAN  ENUM  JSON  UUID","text":"Der Typ bestimmt Speicher und Prüfung. Geld immer als DECIMAL oder in ganzen Cent, nie als FLOAT. VARCHAR hat eine Höchstlänge, TEXT ist lang. DATETIME speichert eine Wandzeit, TIMESTAMP rechnet in UTC um. BOOLEAN ist ein Alias für TINYINT(1).","code":"CREATE TABLE bestellung (\n  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,\n  kunde_id BIGINT UNSIGNED NOT NULL,\n  betrag DECIMAL(10,2) NOT NULL,\n  status ENUM('neu','bezahlt','storniert') NOT NULL DEFAULT 'neu',\n  notiz TEXT NULL,\n  erstellt_am DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  daten JSON NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;","pitfall":"Immer utf8mb4 verwenden (voller Unicode-Umfang, auch Emojis). Das alte utf8 in MySQL kennt nur drei Byte pro Zeichen.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-update-join","cat":"Daten ändern","term":"UPDATE und DELETE mit JOIN (MariaDB)","syntax":"UPDATE a JOIN b ON … SET a.x = …    DELETE a FROM a JOIN b ON … WHERE …","text":"MariaDB erlaubt, Tabellen in UPDATE und DELETE zu verbinden, um Zeilen anhand einer zweiten Tabelle zu ändern oder zu löschen. Vorher mit einem SELECT prüfen, welche Zeilen betroffen sind.","code":"UPDATE bestellung b\nJOIN kunde k ON k.id = b.kunde_id\nSET b.betrag = b.betrag * 0.9\nWHERE k.stadt = 'Berlin';\n\nDELETE b FROM bestellung b\nJOIN kunde k ON k.id = b.kunde_id\nWHERE k.gesperrt = 1;","pitfall":"Ohne WHERE trifft die Änderung alle verbundenen Zeilen. Erst als SELECT mit denselben JOIN- und WHERE-Teilen testen, dann in einer Transaktion ausführen.","lesson":"mariadb-m1-l4","tested":false},{"id":"sql-regexp-json","cat":"Abfragen","term":"REGEXP und JSON-Funktionen (MariaDB)","syntax":"spalte REGEXP 'muster'    JSON_VALUE(spalte, '$.pfad')    JSON_OBJECT(…)","text":"REGEXP sucht mit regulären Ausdrücken. JSON_VALUE liest einen Wert aus einer JSON-Spalte, JSON_OBJECT und JSON_ARRAYAGG erzeugen JSON aus Zeilen. Praktisch für halbstrukturierte Daten.","code":"SELECT name FROM kunde WHERE name REGEXP '^[A-C]';\nSELECT id, JSON_VALUE(daten, '$.adresse.plz') AS plz FROM bestellung;\nSELECT JSON_OBJECT('id', id, 'name', name) FROM kunde;","pitfall":"REGEXP nutzt keinen Index und ist bei großen Tabellen langsam. JSON-Spalten nicht als Ersatz für ein sauberes Schema verwenden, Felder, nach denen man oft filtert, gehören in eigene Spalten.","lesson":"mariadb-m1-l3","tested":false},{"id":"sql-trigger-procedure","cat":"Schema","term":"TRIGGER und gespeicherte Prozedur (MariaDB)","syntax":"CREATE TRIGGER … BEFORE INSERT ON …    DELIMITER //    CREATE PROCEDURE …","text":"Ein Trigger läuft automatisch bei INSERT, UPDATE oder DELETE (zum Beispiel für ein Änderungsprotokoll). Eine Prozedur bündelt SQL-Logik unter einem Namen. DELIMITER wechselt das Endezeichen, damit der Client den Block nicht beim ersten ; abschneidet.","code":"DELIMITER //\nCREATE TRIGGER bestellung_protokoll AFTER UPDATE ON bestellung\nFOR EACH ROW\nBEGIN\n  INSERT INTO protokoll (bestellung_id, alt, neu, zeit)\n  VALUES (OLD.id, OLD.betrag, NEW.betrag, NOW());\nEND//\n\nCREATE PROCEDURE kunde_umsatz(IN p_id INT)\nBEGIN\n  SELECT SUM(betrag) AS umsatz FROM bestellung WHERE kunde_id = p_id;\nEND//\nDELIMITER ;\n\nCALL kunde_umsatz(1);","pitfall":"Trigger sind unsichtbare Logik und erschweren das Verständnis und Debugging. Sparsam einsetzen und dokumentieren. Fachlogik gehört meist in die Anwendung.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-explain-analyze","cat":"Leistung","term":"EXPLAIN FORMAT=JSON und ANALYZE (MariaDB)","syntax":"EXPLAIN SELECT …    ANALYZE SELECT …    SET GLOBAL slow_query_log = 1","text":"EXPLAIN zeigt den geplanten Ablauf, ANALYZE führt die Abfrage aus und stellt Plan und tatsächliche Zahlen (Zeilen, Zeit) gegenüber. Das Slow-Query-Log sammelt langsame Abfragen im Betrieb.","code":"EXPLAIN SELECT * FROM bestellung WHERE kunde_id = 1;\nANALYZE FORMAT=JSON SELECT * FROM bestellung WHERE kunde_id = 1;\n\nSET GLOBAL slow_query_log = 1;\nSET GLOBAL long_query_time = 1;","pitfall":"ANALYZE führt die Abfrage wirklich aus. Bei INSERT, UPDATE oder DELETE auf Produktionsdaten nicht verwenden. Zeilenzahl in rows und type = ALL (Volltabellen-Scan) sind die ersten Hinweise.","lesson":"mariadb-m1-l5","tested":false},{"id":"sql-users-security","cat":"Sicherheit","term":"CREATE USER, Rechte und Passwörter","syntax":"CREATE USER 'app'@'localhost' IDENTIFIED BY '…';    GRANT SELECT, INSERT ON db.* TO 'app'@'localhost';","text":"Anwendungen bekommen ein eigenes Konto mit den kleinstmöglichen Rechten (nur SELECT, INSERT, UPDATE, DELETE auf ihre Datenbank), nie root. Rechte lassen sich mit SHOW GRANTS prüfen.","code":"CREATE USER 'rootpfad_app'@'localhost' IDENTIFIED BY '<starkes-passwort>';\nGRANT SELECT, INSERT, UPDATE, DELETE ON rootpfad.* TO 'rootpfad_app'@'localhost';\nSHOW GRANTS FOR 'rootpfad_app'@'localhost';\nDROP USER 'rootpfad_app'@'localhost';","pitfall":"Passwörter nie im Skript oder Repository ablegen. Das Beispiel nutzt einen Platzhalter. Für Migrationen ein getrenntes Konto mit mehr Rechten verwenden.","lesson":"mariadb-m1-l6","tested":false},{"id":"sql-offset","cat":"Abfragen","term":"LIMIT mit OFFSET (Seitenweise)","syntax":"ORDER BY … LIMIT anzahl OFFSET start","text":"Überspringt die ersten Zeilen und liefert die nächsten. Damit lassen sich Seiten bauen. Ohne eindeutige Sortierung sind die Seiten nicht stabil.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT id, name FROM kunde ORDER BY id LIMIT 2 OFFSET 1;","out":"2 | Bo\n3 | Cy","pitfall":"Bei hohem OFFSET muss die Datenbank alle übersprungenen Zeilen lesen. Bei großen Tabellen besser „Keyset-Paginierung“ (WHERE id > letzteId).","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-count-distinct","cat":"Aggregation","term":"COUNT(DISTINCT …)","syntax":"SELECT COUNT(DISTINCT spalte) FROM …","text":"Zählt verschiedene Werte statt Zeilen, etwa „wie viele Kunden haben bestellt?“.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT COUNT(*) AS bestellungen, COUNT(DISTINCT kunde_id) AS kunden FROM bestellung;","out":"3 | 2","pitfall":"COUNT(DISTINCT …) auf sehr großen Tabellen ist teuer. Dafür gegebenenfalls eine Zusammenfassungstabelle pflegen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-exists","cat":"Aggregation","term":"EXISTS und NOT EXISTS","syntax":"WHERE EXISTS (SELECT 1 FROM … WHERE …)","text":"Fragt, ob es zu einer Zeile mindestens einen passenden Datensatz gibt. NOT EXISTS findet Zeilen ohne Gegenstück und ist sicherer als NOT IN.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde k\nWHERE NOT EXISTS (SELECT 1 FROM bestellung b WHERE b.kunde_id = k.id);","out":"Cy","pitfall":"In der Unterabfrage SELECT 1 genügt. Die Bedingung zur äußeren Tabelle (b.kunde_id = k.id) nicht vergessen, sonst ist die Abfrage immer wahr oder immer falsch.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-insert-select","cat":"Daten ändern","term":"INSERT … SELECT","syntax":"INSERT INTO ziel (spalten) SELECT … FROM quelle","text":"Fügt das Ergebnis einer Abfrage als neue Zeilen ein, zum Beispiel für Archivierung oder Kopien.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);\nCREATE TABLE grosse_bestellung (id INTEGER, betrag INTEGER);","code":"INSERT INTO grosse_bestellung (id, betrag)\nSELECT id, betrag FROM bestellung WHERE betrag >= 12;\nSELECT * FROM grosse_bestellung ORDER BY id;","out":"1 | 20\n3 | 12","pitfall":"Anzahl und Reihenfolge der Spalten müssen übereinstimmen. Immer die Zielspalten ausdrücklich nennen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-update-subquery","cat":"Daten ändern","term":"UPDATE mit Unterabfrage","syntax":"UPDATE t SET spalte = (SELECT …) WHERE …","text":"Setzt Werte anhand einer Abfrage, zum Beispiel eine berechnete Summe. Die Unterabfrage muss pro Zeile genau einen Wert liefern.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);\nALTER TABLE kunde ADD COLUMN umsatz INTEGER DEFAULT 0;","code":"UPDATE kunde SET umsatz = (SELECT COALESCE(SUM(betrag), 0) FROM bestellung WHERE kunde_id = kunde.id);\nSELECT name, umsatz FROM kunde ORDER BY id;","out":"Ada | 26\nBo | 12\nCy | 0","pitfall":"Abgeleitete Werte in Spalten zu speichern kann veralten. Besser bei Bedarf berechnen oder per View bereitstellen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-window","cat":"Aggregation","term":"Fensterfunktionen (OVER)","syntax":"ROW_NUMBER() OVER (PARTITION BY a ORDER BY b)","text":"Rechnen über „Fenster“ von Zeilen, ohne sie zusammenzufassen. ROW_NUMBER nummeriert, RANK vergibt Ränge, SUM() OVER bildet laufende Summen. PARTITION BY teilt in Gruppen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT kunde_id, betrag,\n  ROW_NUMBER() OVER (PARTITION BY kunde_id ORDER BY betrag DESC) AS rang,\n  SUM(betrag) OVER (PARTITION BY kunde_id) AS summe\nFROM bestellung ORDER BY kunde_id, rang;","out":"1 | 20 | 1 | 26\n1 | 6 | 2 | 26\n2 | 12 | 1 | 12","pitfall":"Fensterfunktionen sind in MariaDB ab Version 10.2 verfügbar. Sie dürfen nicht im WHERE stehen, dafür eine Unterabfrage oder CTE verwenden.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-self-cross","cat":"Joins","term":"CROSS JOIN und Self Join","syntax":"FROM a CROSS JOIN b    FROM t x JOIN t y ON …","text":"CROSS JOIN bildet alle Kombinationen beider Tabellen. Ein Self Join verknüpft eine Tabelle mit sich selbst, etwa für „Mitarbeiter und Vorgesetzte“.","setup":"CREATE TABLE farbe (f TEXT); INSERT INTO farbe VALUES ('rot'), ('blau');\nCREATE TABLE groesse (g TEXT); INSERT INTO groesse VALUES ('S'), ('M');\nCREATE TABLE person (id INTEGER, name TEXT, chef_id INTEGER);\nINSERT INTO person VALUES (1, 'Ada', NULL), (2, 'Bo', 1);","code":"SELECT f, g FROM farbe CROSS JOIN groesse ORDER BY f, g;\nSELECT p.name, c.name AS chef FROM person p JOIN person c ON c.id = p.chef_id;","out":"blau | M\nblau | S\nrot | M\nrot | S\nBo | Ada","pitfall":"Ein vergessenes ON macht aus jedem JOIN ein Kreuzprodukt. 1.000 mal 1.000 Zeilen sind sofort eine Million.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-view","cat":"Schema","term":"CREATE VIEW","syntax":"CREATE VIEW name AS SELECT …","text":"Speichert eine Abfrage unter einem Namen. Sie lässt sich wie eine Tabelle benutzen, enthält aber keine eigenen Daten. Praktisch für wiederkehrende Joins und zur Begrenzung von Spalten.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"CREATE VIEW kunde_umsatz AS\n  SELECT k.name, SUM(b.betrag) AS umsatz\n  FROM kunde k JOIN bestellung b ON b.kunde_id = k.id\n  GROUP BY k.id;\nSELECT * FROM kunde_umsatz ORDER BY name;","out":"Ada | 26\nBo | 12","pitfall":"Eine View ist nur so schnell wie ihre Abfrage. Sie ersetzt keinen Index. Verschachtelte Views erschweren die Fehlersuche.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-drop-truncate","cat":"Schema","term":"DROP TABLE und TRUNCATE","syntax":"DROP TABLE IF EXISTS t;    TRUNCATE TABLE t;    DELETE FROM t;","text":"DROP entfernt die Tabelle samt Daten, TRUNCATE leert sie schnell und setzt Zähler zurück (MariaDB), DELETE löscht Zeilen einzeln und lässt sich in einer Transaktion zurücknehmen.","code":"DROP TABLE IF EXISTS test_tabelle;\nCREATE TABLE test_tabelle (id INT);\nTRUNCATE TABLE test_tabelle;","pitfall":"In MariaDB löst TRUNCATE (wie DROP) einen impliziten COMMIT aus. Es lässt sich nicht mit ROLLBACK zurücknehmen. Vorsicht auf Produktionsdaten.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-alter-constraint","cat":"Schema","term":"ALTER TABLE … ADD CONSTRAINT","syntax":"ALTER TABLE t ADD CONSTRAINT name FOREIGN KEY (…) REFERENCES …","text":"Ergänzt nachträglich Regeln: Fremdschlüssel, UNIQUE, CHECK. Ein sprechender Name hilft, die Regel später wieder zu entfernen und in Fehlermeldungen zu erkennen.","code":"ALTER TABLE bestellung\n  ADD CONSTRAINT fk_bestellung_kunde FOREIGN KEY (kunde_id) REFERENCES kunde (id);\nALTER TABLE kunde ADD CONSTRAINT uq_kunde_mail UNIQUE (email);","pitfall":"Bestehende Daten müssen die neue Regel schon erfüllen, sonst schlägt der Befehl fehl. Vorher mit einer Abfrage nach Verstößen suchen.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-savepoint","cat":"Transaktionen","term":"SAVEPOINT","syntax":"SAVEPOINT name;    ROLLBACK TO SAVEPOINT name;","text":"Setzt einen Zwischenpunkt innerhalb einer Transaktion. Man kann nur bis dorthin zurückgehen, statt die ganze Transaktion zu verwerfen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"BEGIN;\nUPDATE kunde SET stadt = 'Bonn' WHERE id = 1;\nSAVEPOINT nach_ada;\nUPDATE kunde SET stadt = 'Köln' WHERE id = 2;\nROLLBACK TO SAVEPOINT nach_ada;\nCOMMIT;\nSELECT name, stadt FROM kunde WHERE id IN (1, 2) ORDER BY id;","out":"Ada | Bonn\nBo | Hamburg","pitfall":"Nach ROLLBACK TO bleibt die Transaktion offen. Sie muss trotzdem mit COMMIT oder ROLLBACK beendet werden.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-isolation","cat":"Transaktionen","term":"Isolation und SELECT … FOR UPDATE","syntax":"SET TRANSACTION ISOLATION LEVEL READ COMMITTED;    SELECT … FOR UPDATE;","text":"Die Isolationsstufe legt fest, welche Änderungen anderer Transaktionen man sieht. FOR UPDATE sperrt die gelesenen Zeilen bis zum Ende der Transaktion, damit niemand dazwischen ändert („lesen, prüfen, schreiben“).","code":"START TRANSACTION;\nSELECT stand FROM konto WHERE id = 1 FOR UPDATE;\nUPDATE konto SET stand = stand - 50 WHERE id = 1 AND stand >= 50;\nCOMMIT;","pitfall":"Gesperrte Zeilen blockieren andere Transaktionen. Transaktionen kurz halten und Tabellen immer in derselben Reihenfolge sperren, sonst entstehen Deadlocks.","lesson":"mariadb-m1-l4","tested":false},{"id":"sql-upsert","cat":"Daten ändern","term":"INSERT … ON DUPLICATE KEY UPDATE","syntax":"INSERT … VALUES (…) ON DUPLICATE KEY UPDATE spalte = VALUES(spalte)","text":"MariaDB-Besonderheit: Legt die Zeile an oder aktualisiert sie, wenn der Schlüssel schon existiert. In anderen Datenbanken heißt es MERGE oder ON CONFLICT.","code":"INSERT INTO zaehler (name, anzahl) VALUES ('besuche', 1)\n  ON DUPLICATE KEY UPDATE anzahl = anzahl + 1;","pitfall":"Mit mehreren UNIQUE-Schlüsseln wird bei einem Treffer auf irgendeinem von ihnen aktualisiert, nicht nur auf dem erwarteten.","lesson":"mariadb-m1-l3","tested":false},{"id":"sql-auto-increment","cat":"Schema","term":"AUTO_INCREMENT und LAST_INSERT_ID","syntax":"id INT AUTO_INCREMENT PRIMARY KEY    SELECT LAST_INSERT_ID();","text":"MariaDB vergibt Schlüsselwerte automatisch. LAST_INSERT_ID() liefert den zuletzt erzeugten Wert der eigenen Verbindung. In PDO heißt das lastInsertId().","code":"CREATE TABLE notiz (id INT AUTO_INCREMENT PRIMARY KEY, text VARCHAR(200) NOT NULL);\nINSERT INTO notiz (text) VALUES ('Hallo');\nSELECT LAST_INSERT_ID();","pitfall":"Lücken in der Nummerierung sind normal (zurückgerollte Einfügungen). IDs nie als lückenlose Zählung verwenden.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-functions","cat":"Abfragen","term":"Text- und Datumsfunktionen (MariaDB)","syntax":"CONCAT(a, b)  UPPER(x)  SUBSTRING(x, 1, 3)  CURDATE()  DATE_ADD(d, INTERVAL 7 DAY)  DATE_FORMAT(d, \"%d.%m.%Y\")","text":"Gängige Funktionen in MariaDB. CONCAT verbindet Texte (der Operator || bedeutet in MariaDB standardmäßig ODER), DATE_FORMAT formatiert Datum, CURDATE liefert das heutige Datum.","code":"SELECT CONCAT(vorname, ' ', UPPER(nachname)) AS name,\n       DATE_FORMAT(geburtstag, '%d.%m.%Y') AS geboren,\n       DATEDIFF(CURDATE(), geburtstag) DIV 365 AS alter_jahre\nFROM person;","pitfall":"Die Zeitzone des Servers beeinflusst NOW() und CURDATE(). Zeitpunkte besser als UTC speichern und erst in der Anwendung umrechnen.","lesson":"mariadb-m1-l3","tested":false},{"id":"sql-show","cat":"Betrieb","term":"SHOW, DESCRIBE, EXPLAIN","syntax":"SHOW TABLES;    DESCRIBE tabelle;    SHOW CREATE TABLE tabelle;","text":"Befehle im MariaDB-Client, um Aufbau und Zustand zu erkunden: Tabellen auflisten, Spalten und Typen anzeigen, die vollständige CREATE-Anweisung ausgeben.","code":"SHOW DATABASES;\nUSE shop;\nSHOW TABLES;\nDESCRIBE kunde;\nSHOW INDEX FROM bestellung;","pitfall":"SHOW und DESCRIBE sind MariaDB/MySQL-spezifisch. In anderen Datenbanken heißt das information_schema oder \\d.","lesson":"mariadb-m1-l5","tested":false},{"id":"sql-dump","cat":"Betrieb","term":"Backup und Restore","syntax":"mariadb-dump --single-transaction db > backup.sql    mariadb db < backup.sql","text":"mariadb-dump schreibt Struktur und Daten als SQL-Datei. --single-transaction erzeugt bei InnoDB einen konsistenten Stand, ohne die Datenbank zu sperren. Zurückgespielt wird mit dem Client.","code":"# Sichern\nmariadb-dump --single-transaction --routines shop > shop-2026-11-13.sql\n\n# Wiederherstellen in eine frische Datenbank\nmariadb -e \"CREATE DATABASE shop_restore\"\nmariadb shop_restore < shop-2026-11-13.sql","pitfall":"Ein Backup gilt erst als gut, wenn eine Wiederherstellung einmal getestet wurde. Passwörter nicht auf der Kommandozeile angeben (Prozessliste), stattdessen eine Optionsdatei mit eingeschränkten Rechten.","lesson":"mariadb-m1-l6","tested":false}]},{"id":"git","label":"Git","codeLang":"bash","intro":"Versionsverwaltung im Terminal. Jeder Befehl beginnt mit „git“. Die Beispiele zeigen jeweils den Ausgangszustand und das Ergebnis.","notice":"Die Beispiele sind in einem frischen Testrepository ausgeführt und geprüft. Meldungen erscheinen hier auf Englisch; Git zeigt sie je nach Einstellung auch deutsch.","runner":"Git","entries":[{"id":"git-config","cat":"Einrichten","term":"git config","syntax":"git config --global user.name \"Name\"","text":"Setzt Einstellungen. Name und E-Mail erscheinen in jedem Commit. --global gilt für alle Repositories, ohne die Option nur für das aktuelle.","code":"git config user.name \"Ada Lovelace\"\ngit config --get user.name","out":"Ada Lovelace","pitfall":"Die E-Mail-Adresse aus der Konfiguration steht öffentlich in jedem Commit. Bei öffentlichen Repositories eine Noreply-Adresse verwenden.","lesson":"m61-l2","tested":true},{"id":"git-init","cat":"Einrichten","term":"git init und git clone","syntax":"git init    git clone <url>","text":"init macht aus einem Ordner ein neues Repository (versteckter Ordner .git). clone lädt ein vorhandenes Repository samt Verlauf von einer Adresse herunter.","code":"git status -sb","out":"## No commits yet on main","pitfall":"Den Ordner .git nie von Hand verändern oder löschen: Er enthält den gesamten Verlauf.","lesson":"m61-l2","tested":true},{"id":"git-status","cat":"Grundlagen","term":"git status","syntax":"git status    git status -sb","text":"Zeigt, was sich geändert hat: neu (??), geändert ( M), bereits vorgemerkt (M ). Die Kurzform -s ist knapp, -b zeigt zusätzlich den Branch.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo neu > a.txt\necho zusaetzlich >> datei.txt\ngit status --short","out":" M datei.txt\n?? a.txt","pitfall":"Vor jedem Commit und vor jedem Befehl, der Änderungen verwirft, git status lesen. Es kostet nichts und verhindert Überraschungen.","lesson":"m61-l3","tested":true},{"id":"git-add","cat":"Grundlagen","term":"git add","syntax":"git add <datei>    git add -p","text":"Merkt Änderungen für den nächsten Commit vor (Staging-Bereich). Mit -p wählt man einzelne Abschnitte einer Datei aus.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit add datei.txt\ngit status --short","out":"M  datei.txt","pitfall":"git add . nimmt alles mit, auch versehentlich Geheimnisse und Build-Ordner. Vorher .gitignore pflegen und git status prüfen.","lesson":"m61-l3","tested":true},{"id":"git-commit","cat":"Grundlagen","term":"git commit","syntax":"git commit -m \"Nachricht\"    git commit --amend","text":"Speichert die vorgemerkten Änderungen als Schnappschuss im Verlauf. Die Nachricht erklärt das Warum. --amend ändert den letzten, noch nicht veröffentlichten Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit commit -q -am \"feat: zweite Zeile ergänzen\"\ngit log --format=%s -n 2","out":"feat: zweite Zeile ergänzen\ninit","pitfall":"Commits, die schon gepusht wurden, nicht mit --amend verändern. Das schreibt den gemeinsamen Verlauf um.","lesson":"m61-l4","tested":true},{"id":"git-diff","cat":"Grundlagen","term":"git diff","syntax":"git diff    git diff --staged    git diff a..b","text":"Zeigt Unterschiede. Ohne Option: Arbeitsverzeichnis gegen Staging. Mit --staged: Staging gegen letzten Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit diff --numstat\ngit add datei.txt\ngit diff --staged --numstat","out":"1\t0\tdatei.txt\n1\t0\tdatei.txt","pitfall":"Nach git add zeigt git diff nichts mehr. Die vorgemerkten Änderungen sieht man nur mit --staged.","lesson":"m61-l3","tested":true},{"id":"git-log","cat":"Grundlagen","term":"git log","syntax":"git log --oneline --graph    git log --format=%s    git log -S\"text\"","text":"Zeigt den Verlauf. --oneline kürzt jeden Commit auf eine Zeile, --graph zeichnet Abzweigungen. Mit -S findet man Commits, die einen bestimmten Text hinzugefügt oder entfernt haben.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git log --format=%s\ngit log -S\"zwei\" --format=\"gefunden in: %s\"","out":"zweite Zeile\ninit\ngefunden in: zweite Zeile","pitfall":"git log zeigt nur den aktuellen Branch. Für alle Zweige --all verwenden.","lesson":"m64-l3","tested":true},{"id":"git-gitignore","cat":"Grundlagen","term":".gitignore","syntax":".env\nnode_modules/\n*.log","text":"Textdatei im Projekt mit Mustern für Dateien, die Git ignorieren soll: Geheimnisse, Abhängigkeiten, Build-Ergebnisse. Sie wirkt nur auf noch nicht versionierte Dateien.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"printf '.env\\nnode_modules/\\n' > .gitignore\necho GEHEIM=1 > .env\ngit status --short","out":"?? .gitignore","pitfall":"Wurde eine Datei schon committet, hilft .gitignore nicht mehr. Ein einmal veröffentlichtes Geheimnis ist verbrannt und muss erneuert werden.","lesson":"m61-l5","tested":true},{"id":"git-branch","cat":"Branches","term":"git switch und git branch","syntax":"git switch -c <name>    git switch <name>    git branch","text":"switch wechselt den Branch, -c legt einen neuen an. Ein Branch ist nur ein beweglicher Zeiger auf einen Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -c feature/login\ngit branch --show-current","out":"feature/login","pitfall":"Vor dem Wechsel Änderungen committen oder mit git stash sichern, sonst verweigert Git den Wechsel oder nimmt sie mit.","lesson":"m62-l1","tested":true},{"id":"git-merge","cat":"Branches","term":"git merge","syntax":"git merge <branch>    git merge --no-ff <branch>","text":"Führt die Änderungen eines anderen Branches in den aktuellen zusammen. Mit --no-ff entsteht immer ein eigener Merge-Commit, der die Abzweigung im Verlauf sichtbar lässt.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c feature\necho feature > f.txt\ngit add f.txt\ngit commit -q -m \"feat: f.txt\"\ngit switch -q main\ngit merge -q --no-ff feature -m \"merge feature\"\ngit log --format=%s","out":"merge feature\nfeat: f.txt\ninit","pitfall":"Gemergt wird immer in den Branch, auf dem man gerade steht. Vorher mit git branch --show-current prüfen.","lesson":"m62-l2","tested":true},{"id":"git-conflict","cat":"Branches","term":"Merge-Konflikt","syntax":"<<<<<<< HEAD … ======= … >>>>>>> branch","text":"Ändern zwei Branches dieselbe Stelle, kann Git nicht entscheiden. Es markiert die Stelle in der Datei: oben die eigene Version (HEAD), unten die fremde. Man wählt aus, entfernt die Markierungen, fügt die Datei hinzu und schließt mit einem Commit ab.","setup":"echo a > f.txt\ngit add f.txt\ngit commit -q -m base\ngit switch -q -c feature\necho c > f.txt\ngit commit -q -am feature-change\ngit switch -q main\necho b > f.txt\ngit commit -q -am main-change","code":"git merge feature || true\ncat f.txt","out":"Auto-merging f.txt\nCONFLICT (content): Merge conflict in f.txt\nAutomatic merge failed; fix conflicts and then commit the result.\n<<<<<<< HEAD\nb\n=======\nc\n>>>>>>> feature","pitfall":"Die Markierungen <<<<<<<, ======= und >>>>>>> nie committen. Mit git merge --abort kommt man zum Zustand vor dem Merge zurück. Die Meldungen erscheinen je nach Spracheinstellung deutsch oder englisch.","lesson":"m62-l3","tested":true},{"id":"git-rebase","cat":"Branches","term":"git rebase","syntax":"git rebase <basis>","text":"Setzt die Commits des aktuellen Branches auf eine neue Basis, als wären sie erst jetzt entstanden. Das Ergebnis ist ein gerader Verlauf ohne Merge-Commit.","setup":"echo a > f.txt\ngit add f.txt\ngit commit -q -m base\ngit switch -q -c feature\necho x > x.txt\ngit add x.txt\ngit commit -q -m feature-commit\ngit switch -q main\necho y > y.txt\ngit add y.txt\ngit commit -q -m main-commit","code":"git switch -q feature\ngit rebase -q main\ngit log --format=%s","out":"feature-commit\nmain-commit\nbase","pitfall":"Nie Commits umschreiben (rebase, amend, reset), die andere schon geholt haben. Nach einem Rebase eines geteilten Branches wäre ein Force-Push nötig.","lesson":"m62-l4","tested":true},{"id":"git-stash","cat":"Branches","term":"git stash","syntax":"git stash    git stash pop    git stash list","text":"Legt nicht committete Änderungen beiseite und stellt den sauberen Zustand her. pop holt sie zurück. Praktisch, wenn man kurz den Branch wechseln muss.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo wip >> datei.txt\ngit stash -q\necho \"sauber: $(git status --short | wc -l | tr -d ' ')\"\ngit stash pop -q\ngit status --short","out":"sauber: 0\n M datei.txt","pitfall":"Neue, noch nicht versionierte Dateien nimmt git stash nicht mit. Dafür -u angeben.","lesson":"m62-l5","tested":true},{"id":"git-cherrypick","cat":"Branches","term":"git cherry-pick","syntax":"git cherry-pick <commit>","text":"Übernimmt einen einzelnen Commit von einem anderen Branch als neuen Commit. Praktisch für einen Bugfix, der auch auf einem anderen Zweig gebraucht wird.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c fix\necho fix > fix.txt\ngit add fix.txt\ngit commit -q -m \"fix: kleiner Fehler\"\ngit switch -q main\ngit cherry-pick fix > /dev/null\ngit log --format=%s -n 1","out":"fix: kleiner Fehler","pitfall":"Der Commit existiert danach doppelt (mit verschiedenen Hashes). Wird später der ganze Branch gemergt, kann das Konflikte erzeugen.","lesson":"m62-l5","tested":true},{"id":"git-remote","cat":"Zusammenarbeit","term":"git remote, push, fetch, pull","syntax":"git remote add origin <url>    git push -u origin main    git fetch    git pull","text":"Ein Remote ist ein Repository auf einem Server. push lädt eigene Commits hoch, fetch holt fremde Commits, ohne etwas zu verändern, pull ist fetch plus Zusammenführung.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\nR=$(mktemp -d)\ngit init -q --bare \"$R\"\ngit remote add origin \"$R\"","code":"git push -q -u origin main\ngit status -sb | head -n 1","out":"## main...origin/main","pitfall":"Mit git pull --ff-only holt man sicher: Es bricht ab, statt unbemerkt Merge-Commits zu erzeugen. Vor einem push immer erst fetch oder pull.","lesson":"m63-l1","tested":true},{"id":"git-restore","cat":"Rückgängig machen","term":"git restore","syntax":"git restore <datei>    git restore --staged <datei>","text":"Verwirft Änderungen in einer Datei und stellt den Stand des letzten Commits wieder her. Mit --staged nimmt man nur die Vormerkung zurück und behält die Änderung.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo kaputt > datei.txt\ngit restore datei.txt\ncat datei.txt","out":"eins","pitfall":"git restore ohne --staged verwirft nicht gesicherte Änderungen endgültig. Es gibt keine Rückgängig-Funktion dafür.","lesson":"m64-l1","tested":true},{"id":"git-reset","cat":"Rückgängig machen","term":"git reset","syntax":"git reset --soft HEAD~1    git reset --hard <commit>","text":"Setzt den Branch auf einen früheren Commit. --soft behält die Änderungen vorgemerkt, --mixed (Standard) behält sie im Arbeitsverzeichnis, --hard verwirft sie.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git reset --soft HEAD~1\ngit log --format=%s\ngit status --short","out":"init\nM  datei.txt","pitfall":"--hard verwirft nicht committete Arbeit unwiederbringlich. Vorher git status und notfalls git stash.","lesson":"m64-l1","tested":true},{"id":"git-revert","cat":"Rückgängig machen","term":"git revert","syntax":"git revert <commit>","text":"Macht einen Commit rückgängig, indem ein neuer Commit mit den umgekehrten Änderungen entsteht. Der Verlauf bleibt erhalten, deshalb ist das die Wahl für bereits veröffentlichte Commits.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git revert --no-edit HEAD > /dev/null\ngit log --format=%s -n 1\ncat datei.txt","out":"Revert \"zweite Zeile\"\neins","pitfall":"Reset für lokale, noch nicht geteilte Commits, revert für veröffentlichte. Beides nicht verwechseln.","lesson":"m64-l1","tested":true},{"id":"git-reflog","cat":"Rückgängig machen","term":"git reflog","syntax":"git reflog","text":"Das Protokoll aller Bewegungen von HEAD, auch nach einem harten Reset. Mit dem Hash daraus holt man „verlorene“ Commits zurück (git reset --hard <hash>).","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git reset -q --hard HEAD~1\ngit reflog --format=%gs","out":"reset: moving to HEAD~1\ncommit: zweite Zeile\ncommit (initial): init","pitfall":"Der Reflog ist nur lokal und wird nach einigen Wochen aufgeräumt. Er ersetzt kein Backup.","lesson":"m64-l2","tested":true},{"id":"git-tag","cat":"Zusammenarbeit","term":"git tag","syntax":"git tag -a v1.0.0 -m \"Release\"    git push --tags","text":"Markiert einen Commit dauerhaft, meist für Releases. Annotierte Tags (-a) tragen zusätzlich Autor, Datum und Nachricht.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git tag -a v1.0.0 -m \"Erste Version\"\ngit tag","out":"v1.0.0","pitfall":"Tags werden von git push nicht automatisch hochgeladen. Dafür git push origin v1.0.0 oder --tags.","lesson":"m61-l4","tested":true},{"id":"git-blame","cat":"Fehler finden","term":"git blame und git bisect","syntax":"git blame <datei>    git bisect start / good / bad","text":"blame zeigt zu jeder Zeile, wer sie wann geändert hat. bisect findet per Halbierung den Commit, der einen Fehler eingeführt hat: Man markiert einen guten und einen schlechten Stand, Git schlägt jeweils den mittleren vor.","code":"git blame -L 1,5 datei.txt\n\ngit bisect start\ngit bisect bad            # aktueller Stand ist kaputt\ngit bisect good v1.0.0    # dieser Stand war in Ordnung\n# … testen, dann je Schritt: git bisect good  oder  git bisect bad\ngit bisect reset          # am Ende zurück","pitfall":"blame zeigt, wer die Zeile zuletzt geändert hat, nicht unbedingt, wer den Fehler verursacht hat. Es dient der Nachfrage, nicht der Schuldzuweisung.","lesson":"m64-l3","tested":false},{"id":"git-hook","cat":"Fehler finden","term":"Git-Hook","syntax":".git/hooks/pre-commit","text":"Ein Skript, das Git vor oder nach bestimmten Aktionen ausführt, etwa vor jedem Commit Tests oder Formatierung. Bricht es mit einem Fehlercode ab, wird der Commit verweigert.","code":"#!/bin/sh\n# .git/hooks/pre-commit (ausführbar machen: chmod +x)\nnpm run lint || {\n  echo \"Lint fehlgeschlagen, Commit abgebrochen\"\n  exit 1\n}","pitfall":"Hooks liegen in .git und werden nicht mit gepusht. Das Team nutzt dafür ein Werkzeug (z. B. Husky oder ein Skript), und CI prüft zusätzlich, weil sich Hooks mit --no-verify umgehen lassen.","lesson":"m64-l4","tested":false},{"id":"git-log-search","cat":"Fehler finden","term":"git log: --grep, -S, --graph, --author, --since","syntax":"git log --grep=text    git log -S\"code\"    git log --graph --oneline --all    git log --author=name --since=2.weeks","text":"Durchsucht den Verlauf. --grep sucht in Commit-Nachrichten, -S („Pickaxe“) findet Commits, die das Vorkommen einer Zeichenfolge im Code verändert haben. --graph zeichnet die Verzweigungen. --follow verfolgt eine Datei über Umbenennungen.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git log --format=%s --grep=zweite\ngit log --format=%s -S zwei -- datei.txt\ngit log --graph --format=%s","out":"zweite Zeile\nzweite Zeile\n* zweite Zeile\n* init","pitfall":"-S findet, wo eine Zeichenfolge hinzukam oder verschwand. Das ist ideal, um zu sehen, wann ein Geheimnis oder eine Funktion ins Projekt kam oder entfernt wurde.","lesson":"m64-l3","tested":true},{"id":"git-diff-options","cat":"Grundlagen","term":"git diff: --stat, --staged, --name-only, -w","syntax":"git diff    git diff --staged    git diff --stat    git diff --name-only    git diff -w","text":"Ohne Option vergleicht diff Arbeitsverzeichnis und Staging-Bereich. --staged zeigt, was beim nächsten Commit aufgenommen wird. --stat fasst zusammen, --name-only listet nur Dateinamen, -w ignoriert Leerraum-Änderungen.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit diff --name-only\ngit diff --stat | head -n 1\ngit add datei.txt\ngit diff --staged --stat | tail -n 1","out":"datei.txt\n datei.txt | 1 +\n 1 file changed, 1 insertion(+)","pitfall":"Nach git add zeigt ein einfaches git diff nichts mehr. Die Änderung steckt dann im Staging-Bereich und ist nur mit --staged sichtbar.","lesson":"m61-l3","tested":true},{"id":"git-restore-source","cat":"Rückgängig machen","term":"git restore --source","syntax":"git restore --source=<commit> <datei>    git checkout <commit> -- <datei>","text":"Holt eine Datei in einem früheren Stand zurück ins Arbeitsverzeichnis, ohne den Branch zu wechseln. Die Änderung erscheint als normale, noch nicht committete Änderung.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git restore --source=HEAD~1 datei.txt\ncat datei.txt\ngit status --short","out":"eins\n M datei.txt","pitfall":"Die aktuelle, nicht committete Fassung der Datei wird überschrieben. Vorher mit git stash oder einem Commit sichern.","lesson":"m64-l1","tested":true},{"id":"git-abort","cat":"Branches","term":"git merge --abort, rebase --abort, --continue","syntax":"git merge --abort    git rebase --abort    git rebase --continue    git cherry-pick --abort","text":"Bei einem Konflikt sind Abbrechen und Fortsetzen die zwei Auswege. --abort stellt den Zustand vor dem Befehl wieder her. --continue macht nach dem Lösen der Konflikte (und git add) weiter. Bei einem Rebase überspringt --skip einen Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c konflikt\necho a > datei.txt\ngit commit -q -am a\ngit switch -q main\necho b > datei.txt\ngit commit -q -am b\ngit merge konflikt > /dev/null 2>&1 || true\ngit merge --abort\ngit status --short\ngit log --format=%s -n 1","out":"b","pitfall":"Mit git status erkennt man, ob man mitten in einem Merge oder Rebase steckt. Vor dem Abbruch ungesicherte Konfliktlösungen sichern, sie gehen sonst verloren.","lesson":"m62-l3","tested":true},{"id":"git-rebase-onto","cat":"Branches","term":"git rebase --onto","syntax":"git rebase --onto <neue-basis> <alte-basis> <branch>","text":"Verpflanzt eine Reihe von Commits auf eine andere Basis. Typisch, wenn ein Branch b versehentlich von Branch a abgezweigt wurde, aber eigentlich von main ausgehen soll: Alles ab a bis b wird auf main neu aufgebaut.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c a\necho a > a.txt\ngit add a.txt\ngit commit -q -m a\ngit switch -q -c b\necho b > b.txt\ngit add b.txt\ngit commit -q -m b\ngit switch -q main\ngit rebase -q --onto main a b\ngit log --format=%s b","out":"b\ninit","pitfall":"Rebase schreibt Commits neu (neue Hashes). Nur auf Branches anwenden, die noch niemand sonst verwendet, und danach mit --force-with-lease pushen.","lesson":"m62-l4","tested":true},{"id":"git-fixup-autosquash","cat":"Branches","term":"git commit --fixup und rebase --autosquash","syntax":"git commit --fixup=<commit>    git rebase -i --autosquash <basis>","text":"Eine vergessene Korrektur gehört in den ursprünglichen Commit. --fixup erzeugt einen Korrektur-Commit mit passendem Titel, --autosquash sortiert ihn beim interaktiven Rebase automatisch an die richtige Stelle und verschmilzt ihn.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'feat: zwei'","code":"echo b > b.txt\ngit add b.txt\ngit commit -q --fixup=HEAD\nGIT_SEQUENCE_EDITOR=true GIT_EDITOR=true git rebase -q -i --autosquash --root\ngit log --format=%s\nls","out":"feat: zwei\ninit\nb.txt\ndatei.txt","pitfall":"Nur auf noch nicht geteilte Commits anwenden. Mit git config rebase.autoSquash true wird --autosquash zum Standard.","lesson":"m62-l4","tested":true},{"id":"git-push-upstream","cat":"Zusammenarbeit","term":"git push -u und Remote-Branch löschen","syntax":"git push -u origin <branch>    git push origin --delete <branch>    git branch -vv","text":"-u verknüpft den lokalen Branch dauerhaft mit dem Remote-Branch, danach genügen git push und git pull. --delete entfernt einen Branch auf dem Server. git branch -vv zeigt, welcher lokale Branch wohin verfolgt wird.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\nR=$(mktemp -d)\ngit init -q --bare \"$R\"\ngit remote add origin \"$R\"\ngit push -q -u origin main","code":"git switch -q -c feature\ngit push -q -u origin feature\ngit rev-parse --abbrev-ref @{u}\ngit push -q origin --delete feature\ngit branch -r","out":"origin/feature\n  origin/main","pitfall":"Gelöschte Remote-Branches bleiben lokal als Verweis sichtbar, bis man git fetch --prune ausführt. Mit push.autoSetupRemote true entfällt -u beim ersten Push.","lesson":"m63-l1","tested":true},{"id":"git-remote-manage","cat":"Zusammenarbeit","term":"git remote add, set-url, rename, remove","syntax":"git remote add <name> <url>    git remote set-url <name> <url>    git remote rename alt neu    git remote remove <name>","text":"Verwaltet die Gegenstellen eines Repositories. add legt sie an, set-url ändert die Adresse (z. B. von HTTPS auf SSH), rename benennt um, remove löscht den Eintrag samt Remote-Branches.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"R=$(mktemp -d)\ngit init -q --bare \"$R\"\ngit remote add origin \"$R\"\ngit remote set-url origin \"$R\"\ngit remote rename origin upstream\ngit remote","out":"upstream","pitfall":"Zugangsdaten gehören nicht in die URL (https://nutzer:passwort@…). Dafür SSH-Schlüssel oder einen Credential Helper verwenden.","lesson":"m63-l1","tested":true},{"id":"git-grep","cat":"Fehler finden","term":"git grep","syntax":"git grep -n \"text\"    git grep -c \"text\"    git grep \"text\" <commit>","text":"Durchsucht alle versionierten Dateien, schneller als normales grep und ohne ignorierte Ordner wie node_modules. -n zeigt Zeilennummern, -c zählt Treffer pro Datei, mit einem Commit als Argument sucht man in einem älteren Stand.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git grep -n eins\ngit grep -c eins","out":"datei.txt:1:eins\ndatei.txt:1","pitfall":"git grep findet nur Dateien, die Git kennt. Neue, nicht hinzugefügte Dateien sind nur mit --untracked enthalten.","lesson":"m64-l3","tested":true},{"id":"git-describe-shortlog","cat":"Fehler finden","term":"git describe und git shortlog","syntax":"git describe --tags    git shortlog -sn","text":"describe benennt einen Commit nach dem letzten Tag davor (v1.0-3-gabc123 = drei Commits nach v1.0). Praktisch für Versionsnummern in Builds. shortlog -sn zählt Commits je Autor.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\ngit tag -a v1.0 -m 'Version 1'\necho zwei >> datei.txt\ngit commit -q -am 'zwei'","code":"git describe --tags --long | sed 's/-g[0-9a-f]*$//'\ngit shortlog -sn HEAD | awk '{print $1, $2}'","out":"v1.0-1\n2 Test","pitfall":"describe findet nur annotierte Tags (git tag -a). Leichte Tags nimmt es nur mit --tags. Ohne jeden Tag meldet es einen Fehler.","lesson":"m61-l4","tested":true},{"id":"git-archive","cat":"Zusammenarbeit","term":"git archive","syntax":"git archive --format=zip -o release.zip HEAD    git archive HEAD | tar -t","text":"Packt den Stand eines Commits ohne den .git-Ordner in ein Archiv (zip oder tar). Dateien mit export-ignore in .gitattributes bleiben draußen. Gut für Release-Pakete.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git archive --format=tar HEAD | tar -t","out":"datei.txt","pitfall":"Enthält nur versionierte Dateien. Erzeugte Build-Dateien und .env-Dateien fehlen absichtlich und müssen separat bereitgestellt werden.","lesson":"m61-l5","tested":true},{"id":"git-add-patch","cat":"Grundlagen","term":"git add -p und git restore -p","syntax":"git add -p    git restore -p    git stash push -p","text":"Geht die Änderungen Stück für Stück (Hunk) durch und fragt: y (ja), n (nein), s (aufteilen), e (bearbeiten), q (Ende). So bildet man aus gemischten Änderungen saubere, thematische Commits.","code":"git add -p\n# y = Block aufnehmen, n = überspringen, s = in kleinere Blöcke teilen\n# e = Block von Hand bearbeiten, q = beenden\ngit diff --staged\ngit commit -m \"fix: Rundung bei Rabatt\"","pitfall":"Neue, noch nicht versionierte Dateien erscheint git add -p nicht. Sie vorher mit git add -N <datei> vormerken.","lesson":"m61-l3","tested":false},{"id":"git-submodule","cat":"Zusammenarbeit","term":"git submodule","syntax":"git submodule add <url> <pfad>    git clone --recurse-submodules    git submodule update --init --recursive","text":"Bindet ein fremdes Repository in einen Unterordner ein und merkt sich genau einen Commit davon. Beim Klonen müssen Submodule mit --recurse-submodules oder update --init nachgeladen werden.","code":"git submodule add https://github.com/beispiel/bibliothek.git libs/bibliothek\ngit commit -m \"chore: bibliothek als submodule\"\n\n# später, nach dem Klonen\ngit submodule update --init --recursive\n\n# neuesten Stand der Bibliothek übernehmen\ngit submodule update --remote libs/bibliothek","pitfall":"Der Commit im Hauptprojekt zeigt auf einen festen Stand des Submoduls. Änderungen darin müssen zuerst dort committet und gepusht werden, sonst fehlt der Stand anderen.","lesson":"m65-l4","tested":false},{"id":"git-sparse-partial","cat":"Zusammenarbeit","term":"Teilklon: --depth, --filter, sparse-checkout","syntax":"git clone --depth 1 <url>    git clone --filter=blob:none --sparse <url>    git sparse-checkout set <ordner>","text":"Bei großen Repositories lädt man nur, was man braucht. --depth 1 holt nur den neuesten Commit. --filter=blob:none lädt Dateiinhalte erst bei Bedarf. sparse-checkout legt nur ausgewählte Ordner im Arbeitsverzeichnis an.","code":"git clone --depth 1 https://github.com/beispiel/projekt.git\n\ngit clone --filter=blob:none --sparse https://github.com/beispiel/gross.git\ncd gross\ngit sparse-checkout set docs src/api","pitfall":"Ein flacher Klon (--depth) hat keinen vollständigen Verlauf: log, blame und bisect sind eingeschränkt. Mit git fetch --unshallow holt man den Rest nach.","lesson":"m61-l2","tested":false},{"id":"git-signing","cat":"Zusammenarbeit","term":"Signierte Commits (SSH oder GPG)","syntax":"git config gpg.format ssh    git config user.signingkey <schluessel>    git commit -S    git log --show-signature","text":"Eine Signatur belegt, dass ein Commit wirklich von der Person stammt. Heute reicht ein SSH-Schlüssel dafür, GPG ist nicht mehr nötig. Mit commit.gpgsign true wird jeder Commit signiert. GitHub zeigt dann „Verified“ an.","code":"git config --global gpg.format ssh\ngit config --global user.signingkey ~/.ssh/id_ed25519.pub\ngit config --global commit.gpgsign true\n\ngit commit -m \"feat: signiert\"\ngit log --show-signature -1","pitfall":"Den öffentlichen Schlüssel zusätzlich bei GitHub als „Signing Key“ eintragen, sonst erscheint der Commit nicht als verifiziert. Nie den privaten Schlüssel teilen.","lesson":"m61-l2","tested":false},{"id":"git-config-defaults","cat":"Einrichten","term":"Empfohlene Einstellungen (init, pull, push, rerere)","syntax":"git config --global init.defaultBranch main    pull.rebase true    fetch.prune true    push.autoSetupRemote true    rerere.enabled true","text":"Ein paar Einstellungen ersparen häufigen Ärger: defaultBranch legt den Namen des Startbranches fest, pull.rebase vermeidet unnötige Merge-Commits, fetch.prune räumt gelöschte Remote-Branches auf, push.autoSetupRemote ersetzt -u, rerere merkt sich Konfliktlösungen, merge.conflictstyle zdiff3 zeigt mehr Kontext.","code":"git config --global init.defaultBranch main\ngit config --global pull.rebase true\ngit config --global fetch.prune true\ngit config --global push.autoSetupRemote true\ngit config --global rebase.autoSquash true\ngit config --global rerere.enabled true\ngit config --global merge.conflictstyle zdiff3\ngit config --global --list","pitfall":"--global gilt für alle Repositories des Benutzers. Einstellungen nur für ein Projekt mit --local setzen, zum Beispiel eine andere E-Mail-Adresse.","lesson":"m61-l2","tested":false},{"id":"git-show","cat":"Grundlagen","term":"git show","syntax":"git show <commit>    git show <commit>:<datei>","text":"Zeigt einen einzelnen Commit mit Nachricht und Änderungen. Mit commit:datei sieht man eine Datei so, wie sie in diesem Commit war.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git show HEAD~1:datei.txt\ngit show --stat --format=%s HEAD | head -n 1","out":"eins\nzweite Zeile","pitfall":"HEAD~1 ist der Vorgänger, HEAD^2 der zweite Elternteil eines Merge-Commits. Nicht verwechseln.","lesson":"m61-l3","tested":true},{"id":"git-rm-mv","cat":"Grundlagen","term":"git rm und git mv","syntax":"git rm <datei>    git rm --cached <datei>    git mv alt neu","text":"rm löscht eine Datei und merkt die Löschung vor, mit --cached bleibt sie im Ordner und wird nur nicht mehr versioniert (hilfreich, wenn etwas versehentlich committet wurde). mv benennt um, Git erkennt Umbenennungen automatisch.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git mv datei.txt neu.txt\ngit status --short\ngit rm -q --cached neu.txt\ngit status --short","out":"R  datei.txt -> neu.txt\nD  datei.txt\n?? neu.txt","pitfall":"Ein versehentlich committetes Geheimnis ist mit git rm --cached nicht aus dem Verlauf entfernt. Es muss als kompromittiert gelten und erneuert werden.","lesson":"m61-l5","tested":true},{"id":"git-clean","cat":"Rückgängig machen","term":"git clean","syntax":"git clean -n    git clean -fd","text":"Entfernt nicht versionierte Dateien. -n zeigt nur, was gelöscht würde (Probelauf), -f führt aus, -d schließt Ordner ein.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo egal > temp.txt\ngit clean -n\ngit clean -fq\nls","out":"Would remove temp.txt\ndatei.txt","pitfall":"Gelöschte, nicht versionierte Dateien sind weg und nicht im Papierkorb. Immer erst mit -n prüfen.","lesson":"m64-l1","tested":true},{"id":"git-restore-staged","cat":"Rückgängig machen","term":"git restore --staged","syntax":"git restore --staged <datei>","text":"Nimmt eine Datei aus dem Staging-Bereich zurück, die Änderung bleibt im Arbeitsverzeichnis erhalten. Das ist die Umkehrung von git add.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit add datei.txt\ngit restore --staged datei.txt\ngit status --short","out":" M datei.txt","pitfall":"Der Befehl verwirft nichts. Erst git restore ohne --staged verwirft die Änderung in der Datei.","lesson":"m64-l1","tested":true},{"id":"git-amend","cat":"Rückgängig machen","term":"git commit --amend","syntax":"git commit --amend -m \"neue Nachricht\"    git commit --amend --no-edit","text":"Ersetzt den letzten Commit: neue Nachricht oder vergessene Dateien nachträglich aufnehmen. Der alte Commit wird dabei durch einen neuen mit anderem Hash ersetzt.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git commit -q --amend -m \"feat: erste Version\"\ngit log --format=%s","out":"feat: erste Version","pitfall":"Nur für Commits verwenden, die noch nicht gepusht sind. Auf einem geteilten Branch zwingt es andere zu einem Rebase.","lesson":"m61-l4","tested":true},{"id":"git-merge-squash","cat":"Branches","term":"git merge --squash","syntax":"git merge --squash <branch>","text":"Übernimmt alle Änderungen eines Branches als eine einzige, noch nicht committete Änderung. Praktisch, um viele kleine Arbeitsstand-Commits zu einem sauberen zusammenzufassen.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c feature\necho a > a.txt && git add a.txt && git commit -q -m \"wip 1\"\necho b > b.txt && git add b.txt && git commit -q -m \"wip 2\"\ngit switch -q main\ngit merge --squash feature > /dev/null\ngit commit -q -m \"feat: a und b\"\ngit log --format=%s","out":"feat: a und b\ninit","pitfall":"Der Branch feature gilt danach nicht als gemergt (git branch --merged zeigt ihn nicht). Zum Löschen -D statt -d nötig.","lesson":"m62-l2","tested":true},{"id":"git-branch-delete","cat":"Branches","term":"git branch -d und -D","syntax":"git branch -d <name>    git branch -D <name>    git branch -vv","text":"-d löscht einen Branch nur, wenn er vollständig gemergt ist. -D erzwingt das Löschen. git branch -vv zeigt zu jedem Branch den Upstream und den letzten Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git branch erledigt\ngit branch -d erledigt > /dev/null\ngit branch --format=\"%(refname:short)\"","out":"main","pitfall":"Mit -D gelöschte Commits lassen sich nur über den Reflog (und nur einige Wochen) zurückholen.","lesson":"m62-l1","tested":true},{"id":"git-diff-range","cat":"Branches","term":"git diff a..b und a...b","syntax":"git diff main..feature    git diff main...feature    git log main..feature","text":"Zwei Punkte vergleichen die Enden direkt, drei Punkte vergleichen den Branch mit dem gemeinsamen Vorfahren, also genau das, was auf dem Branch hinzugekommen ist. log a..b listet die Commits, die b hat und a nicht.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c feature\necho x > x.txt && git add x.txt && git commit -q -m \"feat: x\"\ngit switch -q main\necho y > y.txt && git add y.txt && git commit -q -m \"main: y\"\ngit log --format=%s main..feature\ngit diff --name-only main...feature","out":"feat: x\nx.txt","pitfall":"Für „was bringt mein Pull Request“ ist main...feature richtig, main..feature würde auch die Änderungen von main als Gegenrichtung zeigen.","lesson":"m63-l2","tested":true},{"id":"git-rebase-i","cat":"Branches","term":"git rebase -i","syntax":"git rebase -i HEAD~3","text":"Öffnet eine Liste der letzten Commits zum Bearbeiten: pick (behalten), reword (Nachricht ändern), squash oder fixup (mit dem Vorgänger verschmelzen), drop (entfernen), Reihenfolge ändern.","code":"git rebase -i HEAD~3\n\n# Im Editor:\npick   a1b2c3d feat: Formular anlegen\nfixup  d4e5f6a tippfehler\nreword 9f8e7d6 feat: Validierung","pitfall":"Nur lokale oder nicht geteilte Commits umschreiben. Bei einem Fehler hilft git rebase --abort, danach ist alles wie vorher.","lesson":"m62-l4","tested":false},{"id":"git-pull-rebase","cat":"Zusammenarbeit","term":"git pull --rebase und --ff-only","syntax":"git pull --rebase    git pull --ff-only","text":"Standardmäßig holt pull fremde Commits und führt sie per Merge zusammen. Mit --rebase legt Git die eigenen Commits obenauf, mit --ff-only bricht es ab, wenn kein einfaches Vorspulen möglich ist.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\nR=$(mktemp -d)\ngit init -q --bare \"$R\"\ngit remote add origin \"$R\"\ngit push -q -u origin main","code":"git pull --ff-only -q\ngit status -sb | head -n 1","out":"## main...origin/main","pitfall":"Wer unsicher ist, holt zuerst mit git fetch und schaut sich mit git log main..origin/main an, was neu ist.","lesson":"m63-l1","tested":true},{"id":"git-force-lease","cat":"Zusammenarbeit","term":"git push --force-with-lease","syntax":"git push --force-with-lease","text":"Überschreibt den Remote-Branch nur, wenn er noch dem Stand entspricht, den man zuletzt gesehen hat. Das ist die sichere Variante von --force, nötig nach einem Rebase des eigenen Branches.","code":"git rebase main\ngit push --force-with-lease origin feature/login","pitfall":"Nie auf main oder gemeinsam genutzten Branches erzwingen. Branch-Schutz auf dem Server verbietet das ohnehin.","lesson":"m63-l4","tested":false},{"id":"git-remote-v","cat":"Zusammenarbeit","term":"git remote -v und git fetch --prune","syntax":"git remote -v    git fetch --prune    git remote set-url origin <url>","text":"remote -v zeigt alle konfigurierten Remotes mit Adressen. fetch --prune entfernt lokale Verweise auf Branches, die auf dem Server gelöscht wurden.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git remote add origin https://example.org/rootpfad.git\ngit remote -v","out":"origin\thttps://example.org/rootpfad.git (fetch)\norigin\thttps://example.org/rootpfad.git (push)","pitfall":"Zugangsdaten gehören nie in die Remote-URL, sie landen in .git/config im Klartext. SSH-Schlüssel oder einen Credential-Helper verwenden.","lesson":"m63-l1","tested":true},{"id":"git-alias","cat":"Einrichten","term":"git config alias","syntax":"git config --global alias.st \"status -sb\"","text":"Kurzbefehle für häufige Befehle. Der Alias wird danach wie ein eigener Befehl aufgerufen.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git config alias.st \"status -sb\"\ngit st","out":"## main","pitfall":"Aliase gelten nur auf der eigenen Maschine. In Anleitungen und Skripten die vollständigen Befehle verwenden.","lesson":"m61-l2","tested":true},{"id":"git-cat-file","cat":"Interna","term":"git cat-file, rev-parse, ls-files","syntax":"git cat-file -p <hash>    git rev-parse HEAD    git ls-files","text":"Werkzeuge für Einblicke ins Innere: cat-file zeigt Inhalt und Typ von Objekten (commit, tree, blob), rev-parse löst Namen in Hashes auf, ls-files listet die versionierten Dateien.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git cat-file -t HEAD\ngit cat-file -p HEAD^{tree} | cut -f2\ngit ls-files\ngit rev-parse --abbrev-ref HEAD","out":"commit\ndatei.txt\ndatei.txt\nmain","pitfall":"Hashes sind Prüfsummen des Inhalts. Zwei gleiche Dateien teilen sich ein Objekt, eine geänderte Datei bekommt ein neues.","lesson":"m65-l4","tested":true},{"id":"git-bisect-run","cat":"Fehler finden","term":"git bisect run","syntax":"git bisect start <schlecht> <gut>    git bisect run <skript>","text":"Findet den fehlerverursachenden Commit automatisch: Git probiert Stände per Halbierung aus und führt ein Skript aus. Endet es mit 0, gilt der Stand als gut, sonst als schlecht.","setup":"for i in 1 2 3 4 5; do echo $i > zahl.txt; git add zahl.txt; git commit -q -m \"stand $i\"; done","code":"git bisect start HEAD HEAD~4 > /dev/null 2>&1\ngit bisect run sh -c 'test \"$(cat zahl.txt)\" -lt 3' > /dev/null\ngit log -1 --format=%s refs/bisect/bad\ngit bisect reset > /dev/null 2>&1","out":"stand 3","pitfall":"Das Testskript muss deterministisch sein. Instabile Tests führen zu einem falschen Ergebnis. Ein Rückgabewert 125 bedeutet „diesen Stand überspringen“.","lesson":"m64-l3","tested":true},{"id":"git-worktree","cat":"Branches","term":"git worktree","syntax":"git worktree add ../ordner branch","text":"Legt einen zweiten Arbeitsordner für einen anderen Branch an, ohne neu zu klonen. So lässt sich ein Hotfix bearbeiten, ohne die laufende Arbeit zu stashen.","code":"git worktree add ../rootpfad-hotfix -b hotfix/login\ncd ../rootpfad-hotfix\n# … arbeiten, committen, pushen …\ncd ../rootpfad\ngit worktree remove ../rootpfad-hotfix","pitfall":"Derselbe Branch lässt sich nicht gleichzeitig in zwei Arbeitsordnern auschecken.","lesson":"m62-l5","tested":false},{"id":"git-gh-pr","cat":"Zusammenarbeit","term":"Pull Request mit der GitHub-CLI","syntax":"gh pr create    gh pr checkout <nr>    gh pr view --web","text":"Die GitHub-CLI (gh) erstellt und prüft Pull Requests im Terminal. Titel und Beschreibung werden wie eine Commit-Nachricht geschrieben: erst was und warum, dann wie prüfbar.","code":"git push -u origin feature/login\ngh pr create --title \"feat(login): Anmeldung mit Passwort\" --body \"Fügt die Anmeldung hinzu. Test: npm test\"\ngh pr checkout 42   # fremde PR lokal ausprobieren","pitfall":"Keine Geheimnisse in Beschreibung, Kommentaren oder Logs. Auch gelöschte Kommentare können in Benachrichtigungen und Caches erhalten bleiben.","lesson":"m63-l2","tested":false}]},{"id":"abap","label":"ABAP","codeLang":"abap","intro":"Sprache der SAP-Systeme. Jede Anweisung endet mit einem Punkt, Kommentare beginnen mit \" oder * am Zeilenanfang. Groß- und Kleinschreibung ist egal; üblich ist Kleinschreibung.","notice":"Diese Beispiele sind nicht in einem SAP-System ausgeführt oder compiliert. Sie folgen der modernen ABAP-Syntax; vor dem Einsatz im eigenen System prüfen.","runner":"","entries":[{"id":"abap-data","cat":"Grundlagen","term":"DATA und inline DATA( )","syntax":"DATA name TYPE typ.    DATA(name) = ausdruck.","text":"DATA legt eine Variable mit Typ an. Mit der Inline-Deklaration DATA(name) = … leitet ABAP den Typ aus der rechten Seite ab. Der Startwert ist bei TYPE i die 0, bei TYPE string der leere Text.","code":"DATA zaehler TYPE i VALUE 5.\nDATA(text) = |Hallo|.\nzaehler = zaehler + 1.","pitfall":"Kettensätze wie DATA: a TYPE i, b TYPE i. sind erlaubt, werden aber schnell unübersichtlich. Eine Anweisung pro Zeile.","lesson":"abap-m7-l0","tested":false},{"id":"abap-types","cat":"Grundlagen","term":"Elementare Typen","syntax":"i  int8  p  f  string  c  d  t  xstring","text":"i und int8 sind ganze Zahlen, p ist die gepackte Dezimalzahl (für Geldbeträge), f die Gleitkommazahl, string ein Text beliebiger Länge, c ein Text fester Länge, d das Datum, t die Uhrzeit.","code":"DATA betrag TYPE p LENGTH 8 DECIMALS 2 VALUE '19.99'.\nDATA datum  TYPE d.\ndatum = sy-datum.","pitfall":"Für Geld p (oder DDIC-Typen mit Währung) statt f verwenden, sonst entstehen Rundungsfehler. Typ c schneidet zu lange Werte stillschweigend ab.","lesson":"abap-m7-l1","tested":false},{"id":"abap-constants","cat":"Grundlagen","term":"CONSTANTS","syntax":"CONSTANTS name TYPE typ VALUE wert.","text":"Legt einen unveränderlichen Wert fest. Er lässt sich nicht überschreiben, und der Compiler meldet Änderungsversuche.","code":"CONSTANTS max_versuche TYPE i VALUE 3.","pitfall":"Magische Zahlen im Code vermeiden: Besser eine Konstante mit sprechendem Namen.","lesson":"abap-m7-l0","tested":false},{"id":"abap-string-template","cat":"Strings","term":"String-Template | |","syntax":"|Text { ausdruck }|","text":"Text in senkrechten Strichen, in dem Ausdrücke in geschweiften Klammern ausgewertet werden. Mit Formatoptionen: { datum DATE = USER }. Der Zusammenbau mit && verkettet Texte.","code":"DATA(name) = `Ada`.\nDATA(gruss) = |Hallo { name }, Summe: { 2 + 3 }|.\nDATA(lang) = strlen( gruss ).","pitfall":"Mit Backticks (`…`) entsteht ein Text vom Typ string, mit Hochkommas ('…') ein Text vom Typ c, bei dem Leerzeichen am Ende verloren gehen.","lesson":"abap-m7-l2","tested":false},{"id":"abap-if","cat":"Kontrollfluss","term":"IF, ELSEIF, ELSE, CASE","syntax":"IF bedingung. … ELSEIF … ELSE. … ENDIF.","text":"Verzweigung nach Bedingung. CASE wählt nach einem Wert. Vergleichsoperatoren: = <> < > <= >=, außerdem IS INITIAL, IS NOT INITIAL, IS BOUND und CO, CS, CP für Textmuster.","code":"IF punkte >= 70.\n  ergebnis = `bestanden`.\nELSE.\n  ergebnis = `weiter üben`.\nENDIF.\n\nCASE status.\n  WHEN 'A' OR 'B'.\n    \" …\n  WHEN OTHERS.\n    \" …\nENDCASE.","pitfall":"Bei CASE ohne WHEN OTHERS passiert bei unbekanntem Wert nichts. Fehlerfälle ausdrücklich behandeln.","lesson":"abap-m7-l0","tested":false},{"id":"abap-cond-switch","cat":"Kontrollfluss","term":"COND und SWITCH","syntax":"COND #( WHEN … THEN … ELSE … )    SWITCH #( wert WHEN … THEN … )","text":"Ausdrücke mit Rückgabewert statt Anweisungen. COND wertet Bedingungen nacheinander aus, SWITCH wählt nach einem Wert.","code":"DATA(art) = COND string( WHEN betrag > 1000 THEN `groß`\n                         WHEN betrag > 100  THEN `mittel`\n                         ELSE `klein` ).\nDATA(tag) = SWITCH string( wochentag WHEN 6 OR 7 THEN `Wochenende` ELSE `Werktag` ).","pitfall":"Ohne ELSE liefert COND bei keinem Treffer den Initialwert des Typs. Das ist leicht zu übersehen.","lesson":"abap-m7-l2","tested":false},{"id":"abap-loop","cat":"Schleifen","term":"DO, WHILE, LOOP AT","syntax":"DO n TIMES. … ENDDO.    WHILE bedingung. … ENDWHILE.    LOOP AT tabelle INTO DATA(zeile). … ENDLOOP.","text":"DO wiederholt n-mal, WHILE solange eine Bedingung gilt, LOOP AT läuft über eine interne Tabelle. sy-index zählt in DO/WHILE, sy-tabix in LOOP AT. EXIT beendet, CONTINUE springt weiter.","code":"DO 3 TIMES.\n  WRITE / sy-index.\nENDDO.\n\nLOOP AT bestellungen INTO DATA(bestellung) WHERE status = 'OFFEN'.\n  summe = summe + bestellung-betrag.\nENDLOOP.","pitfall":"Eine Tabelle während LOOP AT zu ändern ist riskant. Zum Löschen besser DELETE … WHERE außerhalb der Schleife verwenden.","lesson":"abap-m7-l0","tested":false},{"id":"abap-itab","cat":"Interne Tabellen","term":"Tabellentypen","syntax":"TYPE STANDARD TABLE OF …    SORTED TABLE … WITH UNIQUE KEY …    HASHED TABLE … WITH UNIQUE KEY …","text":"STANDARD ist eine Liste, die per Index zugänglich ist, SORTED hält sich sortiert und sucht binär, HASHED sucht per Schlüssel in konstanter Zeit. Der Tabellentyp sollte zum Zugriffsmuster passen.","code":"TYPES: BEGIN OF ty_kunde,\n         id   TYPE i,\n         name TYPE string,\n       END OF ty_kunde.\nDATA kunden TYPE HASHED TABLE OF ty_kunde WITH UNIQUE KEY id.","pitfall":"READ TABLE auf eine STANDARD-Tabelle mit Schlüssel sucht linear. Bei großen Tabellen ist das ein Leistungsproblem: SORTED oder HASHED wählen.","lesson":"abap-m8-l1","tested":false},{"id":"abap-itab-ops","cat":"Interne Tabellen","term":"APPEND, INSERT, READ TABLE, DELETE","syntax":"APPEND zeile TO tab.    READ TABLE tab INTO … WITH KEY …    tab[ id = 1 ]","text":"APPEND hängt an, INSERT fügt an einer Stelle oder in sortierte Tabellen ein, DELETE entfernt. Der Tabellenausdruck tab[ … ] liest eine Zeile und löst CX_SY_ITAB_LINE_NOT_FOUND aus, wenn sie fehlt. line_exists( ) prüft vorher.","code":"APPEND VALUE #( id = 1 name = `Ada` ) TO kunden.\n\nIF line_exists( kunden[ id = 1 ] ).\n  DATA(kunde) = kunden[ id = 1 ].\nENDIF.\n\nREAD TABLE kunden WITH KEY id = 2 TRANSPORTING NO FIELDS.\nIF sy-subrc <> 0.\n  \" nicht gefunden\nENDIF.","pitfall":"sy-subrc nach READ TABLE immer prüfen. Wer ihn vergisst, arbeitet mit der leeren oder alten Zeile weiter.","lesson":"abap-m8-l1","tested":false},{"id":"abap-value-for","cat":"Interne Tabellen","term":"VALUE, FOR, REDUCE, FILTER","syntax":"VALUE #( FOR x IN tab ( … ) )    REDUCE typ( INIT … FOR … NEXT … )    FILTER #( tab WHERE … )","text":"Ausdrucksbasierte Verarbeitung von Tabellen. VALUE #( ) baut Strukturen und Tabellen, FOR wandelt Zeilen um, REDUCE verdichtet zu einem Wert, FILTER behält passende Zeilen.","code":"DATA(namen) = VALUE string_table( FOR k IN kunden ( k-name ) ).\n\nDATA(summe) = REDUCE i( INIT s = 0\n                        FOR b IN bestellungen\n                        NEXT s = s + b-betrag ).\n\nDATA(offene) = FILTER #( bestellungen WHERE status = 'OFFEN' ).","pitfall":"FILTER braucht für die Spalte im WHERE einen sortierten oder Hash-Schlüssel (oder USING KEY). Sonst meldet der Compiler einen Fehler.","lesson":"abap-m7-l2","tested":false},{"id":"abap-select","cat":"Datenbank (Open SQL)","term":"SELECT","syntax":"SELECT feld1, feld2 FROM tabelle WHERE bedingung INTO TABLE @DATA(ergebnis).","text":"Liest Daten aus der Datenbank. In der modernen Syntax stehen Hostvariablen mit @, Felder durch Komma getrennt und INTO am Ende. ORDER BY, GROUP BY, UP TO n ROWS und JOINs gibt es wie in SQL.","code":"SELECT carrid, connid, price\n  FROM sflight\n  WHERE carrid = @carrier\n  ORDER BY price DESCENDING\n  INTO TABLE @DATA(fluege)\n  UP TO 10 ROWS.\n\nIF sy-subrc <> 0.\n  \" keine Treffer\nENDIF.","pitfall":"SELECT in einer Schleife (ein Aufruf je Zeile) ist die häufigste Ursache für langsame Programme. Einmal gesammelt lesen und mit FOR ALL ENTRIES oder JOIN arbeiten.","lesson":"abap-m9-l1","tested":false},{"id":"abap-select-single","cat":"Datenbank (Open SQL)","term":"SELECT SINGLE","syntax":"SELECT SINGLE felder FROM tabelle WHERE … INTO @DATA(zeile).","text":"Liest genau eine Zeile. Mit vollständigem Schlüssel ist das eindeutig, sonst liefert die Datenbank irgendeinen Treffer.","code":"SELECT SINGLE name, ort\n  FROM kunde\n  WHERE id = @kunden_id\n  INTO @DATA(kunde).\nIF sy-subrc = 0.\n  \" kunde-name verwenden\nENDIF.","pitfall":"SELECT SINGLE ohne vollständigen Schlüssel ist nicht deterministisch. Für mehrere mögliche Treffer UP TO 1 ROWS mit ORDER BY verwenden.","lesson":"abap-m9-l1","tested":false},{"id":"abap-modify-db","cat":"Datenbank (Open SQL)","term":"INSERT, UPDATE, DELETE","syntax":"INSERT dbtab FROM @struktur.    UPDATE dbtab SET … WHERE …    DELETE FROM dbtab WHERE …","text":"Ändern Daten in der Datenbank. sy-subrc zeigt den Erfolg. Die Änderung wird erst mit COMMIT WORK dauerhaft, bis dahin ist sie nur in der laufenden Transaktion.","code":"UPDATE kunde SET ort = @neuer_ort WHERE id = @kunden_id.\nIF sy-subrc = 0.\n  COMMIT WORK.\nELSE.\n  ROLLBACK WORK.\nENDIF.","pitfall":"In ABAP Cloud und bei RAP führt man Änderungen nicht über direkte Datenbankzugriffe aus, sondern über EML (MODIFY ENTITIES), damit Validierungen laufen.","lesson":"abap-m17-l1","tested":false},{"id":"abap-method","cat":"Klassen","term":"CLASS, METHODS, METHOD","syntax":"CLASS name DEFINITION. … ENDCLASS.    CLASS name IMPLEMENTATION. … ENDCLASS.","text":"Eine Klasse hat einen Definitionsteil (Schnittstelle) und einen Implementierungsteil. Methoden haben IMPORTING-, EXPORTING-, CHANGING- und RETURNING-Parameter. Mit RETURNING lässt sich die Methode direkt in Ausdrücken verwenden.","code":"CLASS lcl_rechner DEFINITION FINAL.\n  PUBLIC SECTION.\n    METHODS summe\n      IMPORTING a TYPE i b TYPE i\n      RETURNING VALUE(ergebnis) TYPE i.\nENDCLASS.\n\nCLASS lcl_rechner IMPLEMENTATION.\n  METHOD summe.\n    ergebnis = a + b.\n  ENDMETHOD.\nENDCLASS.\n\nDATA(rechner) = NEW lcl_rechner( ).\nDATA(s) = rechner->summe( a = 2 b = 3 ).","pitfall":"Klassen mit FINAL schließen Vererbung aus. Das ist die sichere Standardwahl, solange keine Unterklassen nötig sind.","lesson":"abap-m10-l1","tested":false},{"id":"abap-interface","cat":"Klassen","term":"INTERFACE","syntax":"INTERFACE name PUBLIC. METHODS … ENDINTERFACE.    INTERFACES name.","text":"Ein Interface legt Methoden fest, ohne sie zu implementieren. Klassen binden es mit INTERFACES ein und implementieren die Methoden. So lassen sich Abhängigkeiten austauschbar machen (z. B. für Tests).","code":"INTERFACE lif_zahlung.\n  METHODS bezahlen IMPORTING betrag TYPE p.\nENDINTERFACE.\n\nCLASS lcl_karte DEFINITION.\n  PUBLIC SECTION.\n    INTERFACES lif_zahlung.\nENDCLASS.\n\nCLASS lcl_karte IMPLEMENTATION.\n  METHOD lif_zahlung~bezahlen.\n    \" …\n  ENDMETHOD.\nENDCLASS.","pitfall":"Methoden eines Interfaces spricht man mit dem Präfix an (lif_zahlung~bezahlen). Wer das vergisst, bekommt einen Syntaxfehler.","lesson":"abap-m10-l1","tested":false},{"id":"abap-exception","cat":"Fehler","term":"TRY, CATCH, RAISE EXCEPTION","syntax":"TRY. … CATCH cx_… INTO DATA(fehler). … ENDTRY.    RAISE EXCEPTION NEW cx_…( ).","text":"Klassenbasierte Ausnahmen. TRY fängt sie, CATCH behandelt sie, CLEANUP räumt auf. Eigene Ausnahmen erben von CX_STATIC_CHECK (muss deklariert werden) oder CX_NO_CHECK. get_text( ) liefert die Meldung.","code":"TRY.\n    DATA(ergebnis) = 10 / nenner.\n  CATCH cx_sy_zerodivide INTO DATA(fehler).\n    DATA(meldung) = fehler->get_text( ).\nENDTRY.\n\nRAISE EXCEPTION NEW cx_sy_zerodivide( ).","pitfall":"Nicht CATCH cx_root verwenden: Das fängt auch Fehler, die man nicht behandeln kann. Konkrete Ausnahmeklassen nennen.","lesson":"abap-m10-l4","tested":false},{"id":"abap-fieldsymbol","cat":"Dynamisch","term":"Feldsymbole und Datenreferenzen","syntax":"FIELD-SYMBOLS <fs> TYPE …    ASSIGN … TO <fs>    REF #( … )","text":"Ein Feldsymbol ist ein Zeiger auf vorhandene Daten, Änderungen wirken direkt darauf. Datenreferenzen (REF) sind Zeiger, die man in Variablen speichert. Beim Durchlaufen großer Tabellen vermeiden sie Kopien.","code":"LOOP AT bestellungen ASSIGNING FIELD-SYMBOL(<b>).\n  <b>-betrag = <b>-betrag * 2.\nENDLOOP.","pitfall":"Ein nicht zugewiesenes Feldsymbol führt bei Zugriff zu einem Laufzeitfehler. Mit IS ASSIGNED prüfen.","lesson":"abap-m7-l3","tested":false},{"id":"abap-cds","cat":"CDS und RAP","term":"CDS-View-Entity","syntax":"define view entity Name as select from tabelle { key feld, … }","text":"Datenmodell in der Datenbankschicht, das mit Annotationen (@…) angereichert wird. View-Entities sind die aktuelle Form. Mit Assoziationen (association) beschreibt man Beziehungen, ohne sofort zu joinen.","code":"@AccessControl.authorizationCheck: #CHECK\ndefine view entity ZI_Kunde\n  as select from zkunde\n{\n  key id    as KundenId,\n      name  as Name,\n      ort   as Ort\n}","pitfall":"Eine Zugriffskontrolle (DCL) gehört zu jeder CDS-Entity, die Daten von Nutzern ausliefert. @AccessControl.authorizationCheck: #NOT_REQUIRED nur bewusst und begründet.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-rap-bdef","cat":"CDS und RAP","term":"Behavior Definition (RAP)","syntax":"managed implementation in class … unique; define behavior for … { create; update; delete; }","text":"Beschreibt das Verhalten eines Business Objects: welche Operationen erlaubt sind, welche Felder nur lesbar sind, welche Validierungen und Determinationen laufen. „managed“ heißt: Das Framework übernimmt Standard-CRUD und Persistenz.","code":"managed implementation in class zbp_i_kunde unique;\nstrict ( 2 );\n\ndefine behavior for ZI_Kunde alias Kunde\npersistent table zkunde\nlock master\nauthorization master ( instance )\n{\n  create;\n  update;\n  delete;\n  field ( readonly ) KundenId;\n  validation pruefeName on save { create; field Name; }\n}","pitfall":"Validierungen laufen beim Speichern auf dem Server. Eine Prüfung allein in der Oberfläche schützt die Daten nicht.","lesson":"abap-m12-quellen-rap-zuerst-verstehen-daten-verhalten-und-managed-unmanaged","tested":false},{"id":"abap-eml","cat":"CDS und RAP","term":"EML: MODIFY ENTITIES und READ ENTITIES","syntax":"MODIFY ENTITIES OF … ENTITY … CREATE FIELDS ( … ) WITH …","text":"Entity Manipulation Language: Zugriff auf RAP-Business-Objects im Code. Sie durchläuft die Verhaltensdefinition, also Validierungen und Berechtigungen. COMMIT ENTITIES schreibt die Änderungen.","code":"MODIFY ENTITIES OF zi_kunde\n  ENTITY Kunde\n    CREATE FIELDS ( Name Ort )\n    WITH VALUE #( ( %cid = 'k1' Name = `Ada` Ort = `Berlin` ) )\n  FAILED   DATA(failed)\n  REPORTED DATA(reported).\n\nCOMMIT ENTITIES RESPONSE OF zi_kunde\n  FAILED DATA(commit_failed)\n  REPORTED DATA(commit_reported).","pitfall":"Die Ausgaben FAILED und REPORTED immer auswerten. Sonst bleiben abgelehnte Änderungen unbemerkt.","lesson":"abap-m12-quellen-validierung-determination-und-action-mit-eml-auseinanderhalten","tested":false},{"id":"abap-unit","cat":"Tests","term":"ABAP Unit","syntax":"CLASS ltcl_test DEFINITION FOR TESTING … METHODS name FOR TESTING.","text":"Testklassen sind lokal in der zu testenden Klasse und mit FOR TESTING gekennzeichnet. cl_abap_unit_assert=>assert_equals( ) prüft das Ergebnis.","code":"CLASS ltcl_rechner DEFINITION FINAL FOR TESTING\n  RISK LEVEL HARMLESS DURATION SHORT.\n  PRIVATE SECTION.\n    METHODS summe_ist_korrekt FOR TESTING.\nENDCLASS.\n\nCLASS ltcl_rechner IMPLEMENTATION.\n  METHOD summe_ist_korrekt.\n    cl_abap_unit_assert=>assert_equals(\n      act = NEW lcl_rechner( )->summe( a = 2 b = 3 )\n      exp = 5 ).\n  ENDMETHOD.\nENDCLASS.","pitfall":"Tests, die auf echte Datenbanktabellen zugreifen, sind unzuverlässig. Zugriffe über Testdoubles (Test Seams oder Interfaces) ersetzen.","lesson":"abap-m16-l3","tested":false},{"id":"abap-read-table-expr","cat":"Interne Tabellen","term":"READ TABLE, Tabellenausdruck, line_exists, lines","syntax":"READ TABLE itab INTO wa WITH KEY f = x.    itab[ f = x ]    line_exists( itab[ … ] )    lines( itab )","text":"Ein einzelnes Element liest man mit READ TABLE (Ergebnis in sy-subrc) oder mit dem Tabellenausdruck itab[ … ]. Der Ausdruck löst CX_SY_ITAB_LINE_NOT_FOUND aus, wenn nichts passt, außer man verpackt ihn mit VALUE #( … OPTIONAL ) oder prüft vorher mit line_exists.","code":"READ TABLE lt_kunden INTO DATA(ls_k) WITH KEY kunnr = '0000100001'.\nIF sy-subrc = 0.\n  \" gefunden\nENDIF.\n\nIF line_exists( lt_kunden[ land = 'DE' ] ).\n  DATA(ls_de) = lt_kunden[ land = 'DE' ].\nENDIF.\nDATA(ls_opt) = VALUE #( lt_kunden[ kunnr = 'X' ] OPTIONAL ).\nDATA(lv_anzahl) = lines( lt_kunden ).\nDATA(lv_pos) = line_index( lt_kunden[ land = 'DE' ] ).","pitfall":"Bei Standardtabellen ist der Zugriff über Nicht-Schlüsselfelder eine lineare Suche. Für große Tabellen Sorted/Hashed-Tabellen oder Sekundärschlüssel verwenden.","lesson":"abap-m8-l1","tested":false},{"id":"abap-loop-variants","cat":"Schleifen","term":"LOOP AT: WHERE, FROM/TO, ASSIGNING, EXIT, CONTINUE","syntax":"LOOP AT itab ASSIGNING FIELD-SYMBOL(<w>) WHERE f = x FROM a TO b.  … ENDLOOP.","text":"WHERE und FROM/TO schränken die Zeilen ein. ASSIGNING liefert einen Zeiger und ändert die Zeile direkt, REFERENCE INTO eine Datenreferenz, INTO eine Kopie. sy-tabix ist der Index. EXIT beendet die Schleife, CONTINUE springt zum nächsten Durchlauf.","code":"LOOP AT lt_bestellungen ASSIGNING FIELD-SYMBOL(<ls_b>) WHERE status = 'N'.\n  IF <ls_b>-betrag = 0.\n    CONTINUE.\n  ENDIF.\n  <ls_b>-status = 'P'.          \" ändert die Tabellenzeile direkt\n  IF sy-tabix >= 100.\n    EXIT.\n  ENDIF.\nENDLOOP.\n\nLOOP AT lt_bestellungen TRANSPORTING NO FIELDS WHERE status = 'P'.\n  DATA(lv_gefunden) = abap_true.\n  EXIT.\nENDLOOP.","pitfall":"Mit INTO arbeitet man auf einer Kopie: Änderungen an der Arbeitsstruktur ändern die Tabelle nicht. Dafür MODIFY oder ASSIGNING nutzen.","lesson":"abap-m8-l1","tested":false},{"id":"abap-modify-itab","cat":"Interne Tabellen","term":"MODIFY, DELETE, INSERT INDEX, COLLECT, CLEAR","syntax":"MODIFY itab FROM wa TRANSPORTING f WHERE …    DELETE itab WHERE …    COLLECT wa INTO itab.    CLEAR / FREE","text":"MODIFY ändert Zeilen, DELETE entfernt sie, INSERT … INDEX fügt an einer Stelle ein. COLLECT addiert numerische Felder gleicher Schlüssel (Summenbildung). CLEAR leert Inhalt, FREE gibt zusätzlich den Speicher frei.","code":"MODIFY lt_artikel FROM VALUE #( status = 'X' ) TRANSPORTING status WHERE bestand = 0.\nDELETE lt_artikel WHERE status = 'X'.\nINSERT VALUE #( id = 99 ) INTO lt_artikel INDEX 1.\n\nLOOP AT lt_zeilen INTO DATA(ls_z).\n  COLLECT VALUE ty_summe( land = ls_z-land menge = ls_z-menge ) INTO lt_summe.\nENDLOOP.\nCLEAR lt_artikel.","pitfall":"COLLECT funktioniert nur, wenn alle Nicht-Schlüsselfelder numerisch sind. Für Gruppierungen ist GROUP BY oder REDUCE moderner und klarer.","lesson":"abap-m8-l1","tested":false},{"id":"abap-secondary-key","cat":"Interne Tabellen","term":"Sekundärschlüssel und Tabellentypen mit Schlüssel","syntax":"TYPES t TYPE SORTED TABLE OF s WITH UNIQUE KEY id WITH NON-UNIQUE SORTED KEY by_land COMPONENTS land.","text":"Ein Sekundärschlüssel macht Zugriffe über andere Felder schnell, ohne die Tabelle umzusortieren. Man wählt ihn mit USING KEY beim Lesen oder Schleifen. Sorted-Tabellen sind nach dem Schlüssel geordnet, Hashed-Tabellen suchen über eine Hash-Funktion.","code":"TYPES: BEGIN OF ty_kunde, kunnr TYPE kunnr, land TYPE land1, name TYPE string, END OF ty_kunde.\nTYPES ty_kunden TYPE SORTED TABLE OF ty_kunde\n  WITH UNIQUE KEY kunnr\n  WITH NON-UNIQUE SORTED KEY by_land COMPONENTS land.\n\nDATA lt_kunden TYPE ty_kunden.\nREAD TABLE lt_kunden WITH KEY by_land COMPONENTS land = 'DE' INTO DATA(ls_de).\nLOOP AT lt_kunden INTO DATA(ls_k) USING KEY by_land WHERE land = 'DE'.\nENDLOOP.\nDATA(ls_expr) = lt_kunden[ KEY by_land land = 'DE' ].","pitfall":"Jeder Sekundärschlüssel kostet Speicher und Zeit beim Einfügen. Nur dort anlegen, wo ein messbar häufiger Zugriff über das Feld stattfindet.","lesson":"abap-m8-l1","tested":false},{"id":"abap-types-struct","cat":"Grundlagen","term":"TYPES, Strukturen und LIKE LINE OF","syntax":"TYPES: BEGIN OF ty_s, a TYPE i, END OF ty_s.    TYPES ty_t TYPE STANDARD TABLE OF ty_s WITH EMPTY KEY.","text":"TYPES definiert eigene Typen, Strukturen gruppieren Felder. WITH EMPTY KEY legt eine Tabelle ohne Schlüssel an, gut für einfache Listen. TYPE bezieht sich auf einen Typ, LIKE auf ein vorhandenes Datenobjekt.","code":"TYPES: BEGIN OF ty_kunde,\n         kunnr TYPE kunnr,\n         name  TYPE string,\n         umsatz TYPE p LENGTH 8 DECIMALS 2,\n       END OF ty_kunde.\nTYPES ty_kunden TYPE STANDARD TABLE OF ty_kunde WITH EMPTY KEY.\n\nDATA lt_kunden TYPE ty_kunden.\nDATA ls_kunde LIKE LINE OF lt_kunden.\nls_kunde-name = 'Muster'.\nAPPEND ls_kunde TO lt_kunden.\nDATA(ls_ref) = REF #( lt_kunden[ 1 ] ).","pitfall":"In ABAP Cloud keine Referenzen auf nicht freigegebene DDIC-Typen. Eigene Typen oder freigegebene Datenelemente verwenden.","lesson":"abap-m7-l1","tested":false},{"id":"abap-select-clauses","cat":"Datenbank (Open SQL)","term":"SELECT: UP TO, ORDER BY, IN, LIKE, DISTINCT","syntax":"SELECT DISTINCT … FROM t WHERE f IN @range AND g LIKE 'A%' ORDER BY f UP TO 10 ROWS INTO TABLE @DATA(lt).","text":"Die üblichen Klauseln: WHERE filtert (IN mit Liste oder Range-Tabelle, LIKE mit % und _), ORDER BY sortiert in der Datenbank, UP TO n ROWS begrenzt die Anzahl, DISTINCT entfernt Doppelte. Host-Variablen werden mit @ gekennzeichnet.","code":"SELECT DISTINCT land1\n  FROM kna1\n  WHERE name1 LIKE 'M%'\n    AND ktokd IN ( 'Z001', 'Z002' )\n  ORDER BY land1\n  INTO TABLE @DATA(lt_laender)\n  UP TO 10 ROWS.\n\nSELECT kunnr, name1 FROM kna1\n  WHERE kunnr IN @s_kunnr\n  INTO CORRESPONDING FIELDS OF TABLE @lt_kunden.","pitfall":"ORDER BY und UP TO in der Datenbank erledigen lassen, nicht erst alle Zeilen laden und dann in ABAP sortieren. Bei Mandantenfähigkeit wird der Mandant automatisch gesetzt.","lesson":"abap-m9-l1","tested":false},{"id":"abap-select-case","cat":"Datenbank (Open SQL)","term":"SELECT: CASE, COALESCE, CAST, UNION, Unterabfrage","syntax":"CASE WHEN … THEN … ELSE … END    COALESCE( a, b )    CAST( x AS CHAR( 10 ) )    UNION","text":"Open SQL kann rechnen und verzweigen: CASE bildet Fallunterscheidungen, COALESCE ersetzt NULL, CAST wandelt Typen, UNION fasst Ergebnisse zusammen. Unterabfragen stehen in Klammern bei IN und EXISTS.","code":"SELECT kunnr,\n       CASE WHEN umsatz > 100000 THEN 'A' WHEN umsatz > 10000 THEN 'B' ELSE 'C' END AS klasse,\n       COALESCE( rabatt, 0 ) AS rabatt,\n       CAST( umsatz AS DEC( 15, 2 ) ) AS umsatz_dec\n  FROM zkunde_umsatz\n  WHERE EXISTS ( SELECT kunnr FROM zbestellung WHERE kunnr = zkunde_umsatz~kunnr )\n  INTO TABLE @DATA(lt_klassen).","pitfall":"Rechenausdrücke im SELECT nutzen die Datenbank. Sie sind schnell, aber nicht überall verfügbar (Version prüfen) und Ergebnisse brauchen oft Aliasnamen mit AS.","lesson":"abap-m9-l1","tested":false},{"id":"abap-select-package","cat":"Datenbank (Open SQL)","term":"SELECT … PACKAGE SIZE und Cursor","syntax":"SELECT … INTO TABLE @DATA(lt) PACKAGE SIZE 1000.  …  ENDSELECT.","text":"Bei sehr großen Datenmengen liest man in Paketen, damit der Speicher nicht überläuft. In der Schleife steht jeweils ein Paket in der Tabelle. Für Mehrfach-Aufrufe in Anwendungen kann ein OPEN CURSOR verwendet werden.","code":"SELECT belnr, buzei, dmbtr\n  FROM bseg\n  WHERE bukrs = @p_bukrs\n  INTO TABLE @DATA(lt_paket)\n  PACKAGE SIZE 10000.\n  LOOP AT lt_paket INTO DATA(ls_p).\n    \" verarbeiten\n  ENDLOOP.\nENDSELECT.","pitfall":"Innerhalb der Schleife keinen COMMIT WORK ausführen, wenn der Cursor offen ist. Außerdem ist der Beispiel-Tabellenname (BSEG) in S/4HANA kein freigegebenes API: dort die freigegebenen CDS-Views verwenden.","lesson":"abap-m9-l1","tested":false},{"id":"abap-selscreen","cat":"Klassisches ABAP","term":"PARAMETERS, SELECT-OPTIONS und Report-Ereignisse","syntax":"PARAMETERS p_x TYPE ….    SELECT-OPTIONS s_x FOR tab-feld.    START-OF-SELECTION.","text":"Ein klassischer Report fragt Eingaben über ein Selektionsbild ab. PARAMETERS ist ein einzelner Wert, SELECT-OPTIONS eine Range mit mehreren Bereichen. START-OF-SELECTION beginnt die Verarbeitung. Ausgaben erfolgen mit WRITE oder als ALV.","code":"REPORT zr_kunden.\nTABLES kna1.\nPARAMETERS p_land TYPE land1 DEFAULT 'DE'.\nSELECT-OPTIONS s_kunnr FOR kna1-kunnr.\n\nINITIALIZATION.\n  \" Vorbelegungen\nAT SELECTION-SCREEN.\n  IF p_land IS INITIAL.\n    MESSAGE 'Land fehlt' TYPE 'E'.\n  ENDIF.\nSTART-OF-SELECTION.\n  SELECT kunnr, name1 FROM kna1\n    WHERE land1 = @p_land AND kunnr IN @s_kunnr\n    INTO TABLE @DATA(lt_kunden).\n  LOOP AT lt_kunden INTO DATA(ls_k).\n    WRITE: / ls_k-kunnr, ls_k-name1.\n  ENDLOOP.","pitfall":"Klassische Reports sind nicht Teil von ABAP Cloud. Dort ersetzt eine Anwendungsklasse (IF_OO_ADT_CLASSRUN) oder ein Fiori-Programm die Selektionsbilder.","lesson":"abap-m7-l0","tested":false},{"id":"abap-alv","cat":"Klassisches ABAP","term":"ALV-Liste mit CL_SALV_TABLE","syntax":"cl_salv_table=>factory( IMPORTING r_salv_table = DATA(lo_alv) CHANGING t_table = lt_daten ).  lo_alv->display( ).","text":"Der SAP List Viewer zeigt interne Tabellen als sortier- und filterbare Liste. Mit cl_salv_table ist das in wenigen Zeilen möglich: Funktionen, Spaltenüberschriften und Sortierung stellt man über die Objekte des Viewers ein.","code":"TRY.\n    cl_salv_table=>factory(\n      IMPORTING r_salv_table = DATA(lo_alv)\n      CHANGING  t_table      = lt_kunden ).\n    lo_alv->get_functions( )->set_all( abap_true ).\n    lo_alv->get_columns( )->set_optimize( abap_true ).\n    lo_alv->get_columns( )->get_column( 'NAME1' )->set_long_text( 'Name' ).\n    lo_alv->display( ).\n  CATCH cx_salv_msg cx_salv_not_found INTO DATA(lx_alv).\n    MESSAGE lx_alv TYPE 'E'.\nENDTRY.","pitfall":"Spaltennamen sind technische Namen in Großbuchstaben. Ein falscher Name löst CX_SALV_NOT_FOUND aus und muss abgefangen werden.","lesson":"abap-m7-l0","tested":false},{"id":"abap-call-function","cat":"Klassisches ABAP","term":"CALL FUNCTION und PERFORM","syntax":"CALL FUNCTION 'NAME' EXPORTING … IMPORTING … EXCEPTIONS …    PERFORM unterroutine USING …","text":"Funktionsbausteine sind die klassischen, wiederverwendbaren Schnittstellen. Man ruft sie über den Namen auf und liest Ergebnisse und Ausnahmen über sy-subrc. FORM/PERFORM-Unterprogramme sind veraltet und sollten durch Methoden ersetzt werden.","code":"CALL FUNCTION 'BAPI_USER_GET_DETAIL'\n  EXPORTING username = sy-uname\n  IMPORTING address  = DATA(ls_adresse)\n  TABLES    return   = lt_return.\nIF line_exists( lt_return[ type = 'E' ] ).\n  \" Fehler behandeln\nENDIF.\n\" statt PERFORM: eine Methode in einer lokalen oder globalen Klasse","pitfall":"Nach einem BAPI mit Änderungen muss man BAPI_TRANSACTION_COMMIT aufrufen. In ABAP Cloud sind nur freigegebene Bausteine und Klassen erlaubt.","lesson":"abap-m10-l1","tested":false},{"id":"abap-inherit","cat":"Klassen","term":"Vererbung: INHERITING FROM, REDEFINITION, ABSTRACT, FINAL","syntax":"CLASS sub DEFINITION INHERITING FROM basis.    METHODS m REDEFINITION.    super->m( ).","text":"Eine Unterklasse erbt Attribute und Methoden. REDEFINITION überschreibt eine Methode, super-> ruft die Version der Oberklasse auf. ABSTRACT-Klassen sind nicht direkt instanziierbar, FINAL-Klassen lassen keine Unterklassen zu.","code":"CLASS lcl_tier DEFINITION ABSTRACT.\n  PUBLIC SECTION.\n    METHODS laut ABSTRACT RETURNING VALUE(rv_laut) TYPE string.\nENDCLASS.\n\nCLASS lcl_hund DEFINITION INHERITING FROM lcl_tier FINAL.\n  PUBLIC SECTION.\n    METHODS laut REDEFINITION.\nENDCLASS.\nCLASS lcl_hund IMPLEMENTATION.\n  METHOD laut.\n    rv_laut = 'Wau'.\n  ENDMETHOD.\nENDCLASS.","pitfall":"Vererbung koppelt Klassen eng. Wo möglich Interfaces und Komposition („hat ein“ statt „ist ein“) bevorzugen. Klassen standardmäßig FINAL machen.","lesson":"abap-m10-l1","tested":false},{"id":"abap-factory","cat":"Klassen","term":"Fabrikmethode und CREATE PRIVATE","syntax":"CLASS x DEFINITION CREATE PRIVATE.    CLASS-METHODS create RETURNING VALUE(ro) TYPE REF TO x.","text":"Mit CREATE PRIVATE kann man Objekte nur über eine eigene statische Fabrikmethode erzeugen. So lässt sich die Erzeugung steuern: Singleton, Testdouble statt echtem Objekt, Prüfung von Parametern.","code":"CLASS zcl_rechnung DEFINITION PUBLIC FINAL CREATE PRIVATE.\n  PUBLIC SECTION.\n    CLASS-METHODS get_instance RETURNING VALUE(ro_rechnung) TYPE REF TO zcl_rechnung.\n    METHODS drucke.\n  PRIVATE SECTION.\n    CLASS-DATA go_instance TYPE REF TO zcl_rechnung.\nENDCLASS.\n\nCLASS zcl_rechnung IMPLEMENTATION.\n  METHOD get_instance.\n    go_instance = COND #( WHEN go_instance IS BOUND THEN go_instance ELSE NEW #( ) ).\n    ro_rechnung = go_instance.\n  ENDMETHOD.\n  METHOD drucke.\n  ENDMETHOD.\nENDCLASS.","pitfall":"Singleton-Zustand erschwert Tests und hält Daten über Aufrufe hinweg. Für Tests eine Injektionsmöglichkeit (set_instance für Testklassen) vorsehen.","lesson":"abap-m10-l1","tested":false},{"id":"abap-exception-class","cat":"Fehler","term":"Eigene Ausnahmeklasse (cx_static_check, IF_T100_MESSAGE)","syntax":"CLASS zcx_x DEFINITION INHERITING FROM cx_static_check.    METHODS m RAISING zcx_x.","text":"Ausnahmeklassen erben von cx_static_check (muss behandelt oder deklariert werden), cx_dynamic_check (wird zur Laufzeit geprüft) oder cx_no_check (nicht prüfbar). Mit IF_T100_MESSAGE erhält die Ausnahme einen übersetzbaren Text aus einer Nachrichtenklasse.","code":"CLASS zcx_bestellung DEFINITION PUBLIC INHERITING FROM cx_static_check CREATE PUBLIC.\n  PUBLIC SECTION.\n    INTERFACES if_t100_message.\n    METHODS constructor\n      IMPORTING textid   LIKE if_t100_message=>t100key OPTIONAL\n                previous LIKE previous OPTIONAL.\nENDCLASS.\n\nCLASS zcx_bestellung IMPLEMENTATION.\n  METHOD constructor ##ADT_SUPPRESS_GENERATION.\n    super->constructor( previous = previous ).\n    CLEAR me->textid.\n    IF textid IS INITIAL.\n      if_t100_message~t100key = if_t100_message=>default_textid.\n    ELSE.\n      if_t100_message~t100key = textid.\n    ENDIF.\n  ENDMETHOD.\nENDCLASS.\n\nMETHODS pruefe IMPORTING is_best TYPE ty_best RAISING zcx_bestellung.","pitfall":"cx_static_check zwingt Aufrufer zur Behandlung, das ist meist gewollt. cx_no_check nur für echte Programmfehler verwenden.","lesson":"abap-m10-l4","tested":false},{"id":"abap-math-ops","cat":"Grundlagen","term":"Rechnen: +=, DIV, MOD, **, round, ceil, floor","syntax":"x += 1.  x = a DIV b.  x = a MOD b.  x = a ** 2.  round( val = … dec = 2 )","text":"Kurzformen wie +=, -=, *= und /= verändern eine Variable. DIV ist die ganzzahlige Division, MOD der Rest. Rechenfunktionen: abs, sign, ceil, floor, round, trunc, sqrt, nmax, nmin.","code":"DATA(lv_summe) = 10.\nlv_summe += 5.\nDATA(lv_div) = 17 DIV 5.         \" 3\nDATA(lv_mod) = 17 MOD 5.         \" 2\nDATA(lv_pot) = 2 ** 10.          \" 1024\nDATA(lv_rund) = round( val = '3.14159' dec = 2 ).\nDATA(lv_auf)  = ceil( '2.1' ).\nDATA(lv_max)  = nmax( val1 = 3 val2 = 9 ).","pitfall":"Division mit i-Typen rundet kaufmännisch (7 / 2 ergibt 4). Für Geldbeträge Typ p oder decfloat verwenden und Rundung bewusst wählen.","lesson":"abap-m7-l1","tested":false},{"id":"abap-bool-logic","cat":"Kontrollfluss","term":"abap_bool, xsdbool, IS INITIAL, BETWEEN, IN","syntax":"DATA f TYPE abap_bool.    xsdbool( bedingung )    IF x IS INITIAL.    IF x BETWEEN a AND b.","text":"ABAP hat keinen eigenen Wahrheitstyp, abap_bool (X und Leerzeichen) ersetzt ihn. xsdbool( … ) wandelt eine Bedingung in abap_true oder abap_false. IS INITIAL prüft auf Startwert, IS BOUND auf gültige Referenz, IS ASSIGNED auf zugewiesenes Feldsymbol.","code":"DATA(lv_gross) = xsdbool( lv_betrag > 1000 ).\nIF lv_gross = abap_true AND lv_status IS NOT INITIAL.\n  \" …\nENDIF.\nIF lv_wert BETWEEN 1 AND 10 OR lv_code IN s_code.\n  \" …\nENDIF.\nIF lo_objekt IS BOUND AND <ls_zeile> IS ASSIGNED.\n  \" …\nENDIF.","pitfall":"IS INITIAL ist bei Zahlen für 0 wahr. Wenn 0 ein gültiger Wert ist, braucht man ein Zusatzfeld oder einen Vergleich mit einem Ersatzwert.","lesson":"abap-m7-l2","tested":false},{"id":"abap-flow-control","cat":"Kontrollfluss","term":"CHECK, CONTINUE, EXIT, RETURN","syntax":"CHECK bedingung.    CONTINUE.    EXIT.    RETURN.","text":"CHECK bricht den aktuellen Durchlauf bzw. die Methode ab, wenn die Bedingung falsch ist. CONTINUE springt in Schleifen zum nächsten Durchlauf, EXIT verlässt die Schleife, RETURN beendet die Methode sofort.","code":"METHOD verarbeite.\n  CHECK iv_id IS NOT INITIAL.       \" ohne ID: Methode verlassen\n  LOOP AT mt_zeilen ASSIGNING FIELD-SYMBOL(<ls_z>).\n    IF <ls_z>-gesperrt = abap_true.\n      CONTINUE.\n    ENDIF.\n    IF <ls_z>-id = iv_id.\n      rv_treffer = <ls_z>-wert.\n      RETURN.\n    ENDIF.\n  ENDLOOP.\nENDMETHOD.","pitfall":"CHECK außerhalb von Schleifen verlässt die gesamte Verarbeitungseinheit. Das ist in Methoden gewollt, in Berichten aber leicht überraschend.","lesson":"abap-m7-l2","tested":false},{"id":"abap-template-format","cat":"Strings","term":"String-Template: Formatierung (WIDTH, ALIGN, DECIMALS, DATE)","syntax":"|{ wert WIDTH = 10 ALIGN = RIGHT PAD = '0' DECIMALS = 2 DATE = ISO }|","text":"In |…| lassen sich Werte direkt formatieren: Breite, Ausrichtung, Auffüllzeichen, Nachkommastellen, Datum und Zahlen nach Benutzer- oder ISO-Format. Das ersetzt WRITE … TO und die Funktion CONCATENATE.","code":"DATA(lv_nr)  = |{ 42 WIDTH = 6 ALIGN = RIGHT PAD = '0' }|.       \" 000042\nDATA(lv_zahl) = |{ '3.14159' DECIMALS = 2 }|.                    \" 3.14\nDATA(lv_datum) = |{ sy-datum DATE = ISO }|.                      \" 2026-11-13\nDATA(lv_text) = |Kunde { ls_kunde-name } hat { lines( lt_best ) } Bestellungen|.\nDATA(lv_gross) = |{ lv_text CASE = UPPER }|.","pitfall":"Zahlen- und Datumsformat hängen vom Benutzer ab (USER). Für Dateien und Schnittstellen explizit ISO oder RAW verwenden.","lesson":"abap-m7-l2","tested":false},{"id":"abap-split-concat","cat":"Strings","term":"SPLIT, CONCATENATE, split( ), concat_lines_of","syntax":"SPLIT text AT ',' INTO TABLE lt.    concat_lines_of( table = lt sep = ',' )    split( val = text sep = ',' )","text":"SPLIT zerlegt einen Text in Teile, CONCATENATE setzt Teile zusammen. Moderne Funktionen (split, concat_lines_of, segment) arbeiten mit Rückgabewerten. SHIFT und TRANSLATE verschieben und wandeln Zeichen.","code":"SPLIT lv_csv AT ',' INTO TABLE DATA(lt_teile).\nDATA(lv_zeile) = concat_lines_of( table = lt_teile sep = ';' ).\nDATA(lv_feld)  = segment( val = lv_csv index = 2 sep = ',' ).\nCONCATENATE 'a' 'b' INTO DATA(lv_ab) SEPARATED BY space.\nTRANSLATE lv_name TO UPPER CASE.\nREPLACE ALL OCCURRENCES OF ',' IN lv_text WITH ';'.","pitfall":"CSV-Felder können das Trennzeichen in Anführungszeichen enthalten. Für echte CSV-Dateien einen Parser nutzen, nicht SPLIT.","lesson":"abap-m7-l2","tested":false},{"id":"abap-regex","cat":"Strings","term":"Reguläre Ausdrücke (find, matches, replace mit pcre)","syntax":"find( val = text pcre = '\\d+' )    matches( val = text pcre = '…' )    replace( val = text pcre = '…' with = '…' )","text":"ABAP unterstützt PCRE-Ausdrücke. find liefert die Position, matches prüft, ob der ganze Text passt, replace ersetzt. Mit FIND … SUBMATCHES holt man Gruppen aus dem Treffer.","code":"DATA(lv_pos) = find( val = 'Bestellung 4711' pcre = '\\d+' ).\nDATA(lv_ok)  = matches( val = 'DE12345' pcre = '[A-Z]{2}\\d{5}' ).\nDATA(lv_neu) = replace( val = 'a  b   c' pcre = '\\s+' with = ' ' occ = 0 ).\nFIND PCRE '(\\d+)-(\\d+)' IN lv_text SUBMATCHES DATA(lv_von) DATA(lv_bis).","pitfall":"Reguläre Ausdrücke aus Benutzereingaben können das System lange beschäftigen (ReDoS). Eingaben beschränken und prüfen.","lesson":"abap-m7-l2","tested":false},{"id":"abap-datetime","cat":"Grundlagen","term":"Datum und Zeit: sy-datum, Zeitstempel, utclong","syntax":"sy-datum  sy-uzeit    cl_abap_context_info=>get_system_date( )    utclong_current( )    utclong_add( … )","text":"Datumsfelder (Typ d) lassen sich mit Tagen addieren. In ABAP Cloud liefert cl_abap_context_info Datum und Zeit, utclong_current den aktuellen UTC-Zeitstempel. Mit utclong_add und utclong_diff rechnet man Zeitstempel.","code":"DATA(lv_heute) = cl_abap_context_info=>get_system_date( ).\nDATA(lv_faellig) = lv_heute + 30.\nDATA(lv_jetzt) = utclong_current( ).\nDATA(lv_morgen) = utclong_add( val = lv_jetzt days = 1 ).\nDATA(lv_diff) = utclong_diff( high = lv_morgen low = lv_jetzt ).   \" Sekunden\n\" klassisch: sy-datum, sy-uzeit, GET TIME STAMP FIELD lv_ts.","pitfall":"Systemzeit und Benutzerzeitzone sind nicht dasselbe. Zeitstempel in UTC speichern und erst zur Anzeige in die Zeitzone umrechnen.","lesson":"abap-m7-l1","tested":false},{"id":"abap-authority-check","cat":"Berechtigung und Verbuchung","term":"AUTHORITY-CHECK","syntax":"AUTHORITY-CHECK OBJECT 'OBJEKT' ID 'ACTVT' FIELD '03' ID 'FELD' FIELD wert.","text":"Prüft, ob der angemeldete Benutzer eine Berechtigung hat. Das Ergebnis steht in sy-subrc: 0 bedeutet erlaubt. ACTVT ist die Aktivität (01 anlegen, 02 ändern, 03 anzeigen, 06 löschen).","code":"AUTHORITY-CHECK OBJECT 'Z_BEST'\n  ID 'ACTVT' FIELD '02'\n  ID 'LAND'  FIELD lv_land.\nIF sy-subrc <> 0.\n  RAISE EXCEPTION NEW zcx_keine_berechtigung( ).\nENDIF.","pitfall":"Berechtigungen immer im Backend prüfen, nicht nur in der Oberfläche. In RAP und CDS übernehmen das authorization master und DCL-Rollen.","lesson":"abap-m12-l2","tested":false},{"id":"abap-commit-work","cat":"Berechtigung und Verbuchung","term":"COMMIT WORK, ROLLBACK WORK und Update-Task","syntax":"COMMIT WORK [AND WAIT].    ROLLBACK WORK.    CALL FUNCTION … IN UPDATE TASK.","text":"COMMIT WORK schreibt alle Änderungen der Logischen Arbeitseinheit (LUW) in die Datenbank, ROLLBACK WORK verwirft sie. Verbuchungsbausteine IN UPDATE TASK laufen erst beim Commit. AND WAIT wartet, bis die Verbuchung fertig ist.","code":"INSERT zbestellung FROM @ls_bestellung.\nCALL FUNCTION 'Z_BESTAND_BUCHEN' IN UPDATE TASK EXPORTING iv_id = ls_bestellung-id.\nIF sy-subrc = 0.\n  COMMIT WORK AND WAIT.\nELSE.\n  ROLLBACK WORK.\nENDIF.","pitfall":"In RAP-Handlermethoden niemals COMMIT WORK oder ROLLBACK WORK aufrufen. Das Framework steuert den Commit selbst. Direkter Commit führt zu Laufzeitfehlern.","lesson":"abap-m12-l3","tested":false},{"id":"abap-badi","cat":"Erweiterungen","term":"BAdI: GET BADI und CALL BADI","syntax":"GET BADI lo_badi.    CALL BADI lo_badi->methode EXPORTING … .","text":"BAdIs (Business Add-Ins) sind vorgesehene Erweiterungspunkte. Der Aufrufer holt die Implementierungen mit GET BADI und ruft sie auf, ohne sie zu kennen. Eigene Implementierungen legt man im Enhancement Framework an.","code":"DATA lo_badi TYPE REF TO zbadi_bestellung.\nGET BADI lo_badi.\nCALL BADI lo_badi->pruefe\n  EXPORTING is_bestellung = ls_bestellung\n  CHANGING  cv_fehler     = lv_fehler.\n\n\" Implementierung\nCLASS zcl_bestellung_pruefung DEFINITION PUBLIC.\n  PUBLIC SECTION.\n    INTERFACES zif_badi_bestellung.\nENDCLASS.","pitfall":"Nur freigegebene BAdIs verwenden (Clean Core). Implizite Erweiterungen und Modifikationen von SAP-Code erschweren Upgrades.","lesson":"abap-m14-l1","tested":false},{"id":"abap-bali-numberrange","cat":"Berechtigung und Verbuchung","term":"Anwendungslog (BALI) und Nummernkreis","syntax":"cl_bali_log=>create_with_header(…)    cl_numberrange_runtime=>number_get(…)","text":"Der Anwendungslog sammelt Meldungen strukturiert und speichert sie in der Datenbank, damit der Betrieb Fehler nachvollziehen kann. Nummernkreise vergeben fortlaufende, eindeutige Nummern (z. B. Belegnummern), auch bei parallelen Zugriffen.","code":"\" Protokoll (ABAP Cloud: cl_bali_*)\nDATA(lo_log) = cl_bali_log=>create_with_header(\n  header = cl_bali_header_setter=>create( object = 'ZBESTELLUNG' subobject = 'IMPORT' ) ).\nlo_log->add_item( cl_bali_free_text_setter=>create( severity = if_bali_constants=>c_severity_error text = 'Import fehlgeschlagen' ) ).\ncl_bali_log_db=>get_instance( )->save_log( log = lo_log ).\n\n\" Nummernkreis\nTRY.\n    cl_numberrange_runtime=>number_get(\n      EXPORTING nr_range_nr = '01' object = 'ZBESTELL'\n      IMPORTING number = DATA(lv_nr) ).\n  CATCH cx_nr_object_not_found cx_number_ranges INTO DATA(lx_nr).\nENDTRY.","pitfall":"Die genauen Parameter und Ausnahmeklassen der Funktionen in der Dokumentation des eigenen Releases prüfen. Keine personenbezogenen Daten im Protokoll ablegen.","lesson":"abap-m10-l4","tested":false},{"id":"abap-cds-functions","cat":"CDS und RAP","term":"CDS: Funktionen, CASE, CAST, Aggregation","syntax":"case when … then … end    cast( x as abap.char( 10 ) )    concat( )    dats_add_days( )    sum( x ) … group by","text":"CDS-Views können rechnen und umwandeln: case für Fälle, cast für Typen, concat und substring für Text, dats_add_days für Datum, coalesce für NULL und Aggregate (sum, count, max). Mit $session.system_date greift man auf das Systemdatum zu.","code":"// Zeilenweise Funktionen\ndefine view entity ZI_BestellungAnzeige as select from zbestellung\n{\n  key bestell_id                                          as BestellId,\n      case when betrag > 1000 then 'A' else 'B' end       as Klasse,\n      dats_add_days( bestelldatum, 30, 'NULL' )           as Faellig,\n      concat( 'B-', cast( bestell_id as abap.char( 10 ) ) ) as Kennung,\n      coalesce( rabatt, 0 )                               as Rabatt\n}\n\n// Aggregation\ndefine view entity ZI_KundeSumme as select from zbestellung\n{\n  key kunde_id   as KundeId,\n      sum( betrag ) as Summe,\n      count( * )    as Anzahl\n}\ngroup by kunde_id","pitfall":"Berechnungen in CDS laufen in der Datenbank und sind schnell, aber nur mit den freigegebenen CDS-Funktionen. Rechenlogik mit Fachregeln gehört besser in die Anwendungsschicht.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-cds-semantics","cat":"CDS und RAP","term":"CDS: Semantics.amount und quantity","syntax":"@Semantics.amount.currencyCode: 'Waehrung'    @Semantics.quantity.unitOfMeasure: 'Einheit'","text":"Betrags- und Mengenfelder brauchen die Angabe, in welcher Währung oder Einheit sie stehen. Die Semantik-Annotation verknüpft beide Felder, damit Fiori Elements korrekt formatiert (Dezimalstellen, Währungssymbol) und Summen richtig bildet.","code":"define view entity ZI_Position as select from zposition\n{\n  key pos_id as PosId,\n      @Semantics.amount.currencyCode: 'Waehrung'\n      preis       as Preis,\n      waehrung    as Waehrung,\n      @Semantics.quantity.unitOfMeasure: 'Einheit'\n      menge       as Menge,\n      einheit     as Einheit\n}","pitfall":"Ohne diese Annotationen werden Beträge als reine Zahlen angezeigt und Summen über verschiedene Währungen addiert. Das ist fachlich falsch.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-rap-fields","cat":"CDS und RAP","term":"RAP: field (readonly, mandatory, numbering) und mapping","syntax":"field ( readonly ) F;    field ( mandatory ) F;    field ( numbering : managed ) Id;    mapping for tab { Feld = spalte; }","text":"In der Behavior Definition steuert field die Feldeigenschaften: readonly, mandatory, numbering : managed (Schlüssel automatisch vergeben). mapping verbindet CDS-Feldnamen mit den Spalten der Datenbanktabelle.","code":"define behavior for ZI_Bestellung alias Bestellung\n  persistent table zbestellung\n  lock master\n  authorization master ( instance )\n{\n  create; update; delete;\n  field ( numbering : managed, readonly ) BestellId;\n  field ( readonly ) Status, LastChanged;\n  field ( mandatory ) Betrag;\n\n  mapping for zbestellung\n  {\n    BestellId   = bestell_id;\n    Betrag      = betrag;\n    Status      = status;\n    LastChanged = last_changed;\n  }\n}","pitfall":"Pflichtfelder (mandatory) werden von der Oberfläche geprüft, aber nicht serverseitig erzwungen. Zusätzlich eine Validation schreiben.","lesson":"abap-m12-quellen-rap-zuerst-verstehen-daten-verhalten-und-managed-unmanaged","tested":false},{"id":"abap-rap-composition","cat":"CDS und RAP","term":"RAP: composition und association to parent","syntax":"composition [0..*] of ZI_Position as _Positionen    association to parent ZI_Bestellung as _Bestellung    create _Positionen { create; }","text":"Ein Business Object kann aus mehreren Entitäten bestehen (Bestellung mit Positionen). Der Kopf enthält die composition, die Position verweist mit association to parent zurück. In der Behavior Definition erlaubt man das Anlegen von Kindern über den Kopf.","code":"// CDS Kopf\ndefine root view entity ZI_Bestellung as select from zbestellung\n  composition [0..*] of ZI_Position as _Positionen\n{ key bestell_id as BestellId, _Positionen }\n\n// CDS Position\ndefine view entity ZI_Position as select from zposition\n  association to parent ZI_Bestellung as _Bestellung on $projection.BestellId = _Bestellung.BestellId\n{ key bestell_id as BestellId, key pos_id as PosId, _Bestellung }\n\n// Behavior\ndefine behavior for ZI_Bestellung alias Bestellung\n{ create; association _Positionen { create; } }\ndefine behavior for ZI_Position alias Position\n{ update; delete; field ( readonly ) BestellId; }","pitfall":"Die Kind-Entität erbt Sperre und Berechtigung vom Kopf (lock dependent, authorization dependent). Das muss in der Behavior Definition der Position angegeben werden.","lesson":"abap-m12-quellen-rap-zuerst-verstehen-daten-verhalten-und-managed-unmanaged","tested":false,"codeLang":"abap"},{"id":"abap-rap-messages","cat":"CDS und RAP","term":"RAP: Fehler melden (failed, reported, new_message)","syntax":"APPEND VALUE #( %tky = … ) TO failed-bestellung.    reported-bestellung = VALUE #( … %msg = new_message_with_text( … ) )","text":"In Validierungen und Aktionen meldet man Fehler über zwei Tabellen: failed markiert die betroffene Instanz (verhindert das Speichern), reported enthält die Meldung für den Benutzer. %element markiert das Feld, damit Fiori es hervorhebt.","code":"METHOD pruefeBetrag.\n  READ ENTITIES OF zi_bestellung IN LOCAL MODE\n    ENTITY Bestellung FIELDS ( Betrag ) WITH CORRESPONDING #( keys )\n    RESULT DATA(lt_best).\n  LOOP AT lt_best INTO DATA(ls_b) WHERE Betrag <= 0.\n    APPEND VALUE #( %tky = ls_b-%tky ) TO failed-bestellung.\n    APPEND VALUE #(\n      %tky = ls_b-%tky\n      %msg = new_message_with_text( severity = if_abap_behv_message=>severity-error text = 'Betrag muss größer 0 sein' )\n      %element-betrag = if_abap_behv=>mk-on ) TO reported-bestellung.\n  ENDLOOP.\nENDMETHOD.","pitfall":"Feste Texte sind nicht übersetzbar. Für Produktivcode Nachrichtenklassen und eine eigene Methode für die Meldungen nutzen.","lesson":"abap-m12-quellen-validierung-determination-und-action-mit-eml-auseinanderhalten","tested":false},{"id":"abap-rap-unmanaged","cat":"CDS und RAP","term":"RAP: unmanaged und Saver-Klasse","syntax":"unmanaged implementation in class zbp_… unique;    with unmanaged save;    cl_abap_behavior_saver","text":"Bei unmanaged schreibt man die Logik zum Anlegen, Ändern und Löschen selbst, zum Beispiel, wenn bestehende Funktionsbausteine oder BAPIs benutzt werden. Mit with unmanaged save kann man in managed-Szenarien nur das Speichern selbst übernehmen. Die Saver-Klasse schreibt in die Datenbank.","code":"managed implementation in class zbp_i_bestellung unique;\nstrict ( 2 );\n\ndefine behavior for ZI_Bestellung alias Bestellung\n  with unmanaged save\n  lock master\n  authorization master ( instance )\n{\n  create; update; delete;\n}\n\nCLASS lsc_zi_bestellung DEFINITION INHERITING FROM cl_abap_behavior_saver.\n  PROTECTED SECTION.\n    METHODS save_modified REDEFINITION.\nENDCLASS.\nCLASS lsc_zi_bestellung IMPLEMENTATION.\n  METHOD save_modified.\n    IF create-bestellung IS NOT INITIAL.\n      \" bestehende API aufrufen\n    ENDIF.\n  ENDMETHOD.\nENDCLASS.","pitfall":"Im Saver gibt es kein COMMIT WORK, das übernimmt das Framework. Außerdem dürfen im Saver keine neuen Änderungen über EML mehr ausgelöst werden.","lesson":"abap-m12-l3","tested":false},{"id":"abap-unit-lifecycle","cat":"Tests","term":"ABAP Unit: setup, class_setup, assert_*, RISK LEVEL","syntax":"METHODS m FOR TESTING RISK LEVEL HARMLESS DURATION SHORT.    METHODS setup.    CLASS-METHODS class_setup.","text":"Testklassen werden mit FOR TESTING markiert. setup läuft vor jeder Testmethode, teardown danach, class_setup einmal pro Klasse. RISK LEVEL und DURATION beschreiben Einfluss und Dauer. cl_abap_unit_assert prüft Ergebnisse (assert_equals, assert_true, assert_initial, assert_bound, fail).","code":"CLASS ltc_rechner DEFINITION FINAL FOR TESTING RISK LEVEL HARMLESS DURATION SHORT.\n  PRIVATE SECTION.\n    DATA mo_cut TYPE REF TO zcl_rechner.\n    METHODS setup.\n    METHODS addiert FOR TESTING.\n    METHODS teilt_durch_null FOR TESTING.\nENDCLASS.\nCLASS ltc_rechner IMPLEMENTATION.\n  METHOD setup.\n    mo_cut = NEW #( ).\n  ENDMETHOD.\n  METHOD addiert.\n    cl_abap_unit_assert=>assert_equals( act = mo_cut->add( a = 2 b = 3 ) exp = 5 ).\n  ENDMETHOD.\n  METHOD teilt_durch_null.\n    TRY.\n        mo_cut->teile( a = 1 b = 0 ).\n        cl_abap_unit_assert=>fail( 'Ausnahme erwartet' ).\n      CATCH zcx_rechner.\n    ENDTRY.\n  ENDMETHOD.\nENDCLASS.","pitfall":"Tests, die auf echte Datenbankinhalte angewiesen sind, sind fragil. Datenzugriff über Testdoubles oder cl_osql_test_environment ersetzen.","lesson":"abap-m16-l3","tested":false},{"id":"abap-sort-delete-dup","cat":"Interne Tabellen","term":"SORT und DELETE ADJACENT DUPLICATES","syntax":"SORT itab BY feld [DESCENDING].    DELETE ADJACENT DUPLICATES FROM itab COMPARING feld.","text":"SORT ordnet eine interne Tabelle. DELETE ADJACENT DUPLICATES entfernt doppelte Zeilen, die direkt hintereinander stehen. Deshalb muss vorher nach denselben Feldern sortiert werden.","code":"SORT lt_kunden BY land ort.\nDELETE ADJACENT DUPLICATES FROM lt_kunden COMPARING land ort.","pitfall":"Ohne vorheriges SORT bleiben Duplikate stehen, die nicht nebeneinander liegen. Bei Sorted- und Hashed-Tabellen ist SORT nicht nötig bzw. nicht erlaubt.","lesson":"abap-m8-l1","tested":false},{"id":"abap-group-by","cat":"Interne Tabellen","term":"LOOP AT … GROUP BY","syntax":"LOOP AT itab INTO DATA(wa) GROUP BY wa-feld INTO DATA(gruppe).","text":"Gruppiert Zeilen einer internen Tabelle nach einem Schlüssel, ohne vorher zu sortieren. In der inneren Schleife läuft man über die Mitglieder der Gruppe.","code":"LOOP AT lt_bestellungen INTO DATA(ls_b) GROUP BY ls_b-kunde INTO DATA(lv_kunde).\n  DATA(lv_summe) = 0.\n  LOOP AT GROUP lv_kunde INTO DATA(ls_member).\n    lv_summe += ls_member-betrag.\n  ENDLOOP.\nENDLOOP.","pitfall":"Die Gruppenvariable ist nur innerhalb der äußeren Schleife gültig. Für reine Summen ist bei großen Mengen eine Aggregation in der Datenbank (SUM, GROUP BY in SELECT) schneller.","lesson":"abap-m8-l1","tested":false},{"id":"abap-string-functions","cat":"Strings","term":"Stringfunktionen","syntax":"to_upper( )  to_lower( )  condense( )  replace( )  substring( )  find( )  strlen( )  contains( )","text":"Funktionale Ausdrücke liefern ein Ergebnis und lassen sich direkt in Anweisungen verwenden. replace ersetzt Text, condense entfernt überflüssige Leerzeichen, find liefert die Position oder -1.","code":"DATA(lv_name)   = condense( val = `  Max   Muster  ` ).\nDATA(lv_gross)  = to_upper( lv_name ).\nDATA(lv_neu)    = replace( val = lv_name sub = `Max` with = `Erika` ).\nDATA(lv_pos)    = find( val = lv_name sub = `Muster` ).\nIF contains( val = lv_name sub = `Muster` ).\n  \" …\nENDIF.","pitfall":"Texte in Backticks (`…`) behalten Leerzeichen am Ende, Texte in einfachen Hochkommas ('…') werden bei TYPE c abgeschnitten.","lesson":"abap-m7-l2","tested":false},{"id":"abap-conv-cast","cat":"Grundlagen","term":"CONV, CAST und EXACT","syntax":"CONV typ( wert )    CAST klasse( objekt )    EXACT typ( wert )","text":"CONV wandelt einen Wert in einen Zieltyp um. CAST wandelt Objektreferenzen (Up- und Downcast). EXACT wandelt ebenfalls um, löst aber eine Ausnahme aus, wenn dabei Information verloren ginge.","code":"DATA(lv_text)  = CONV string( 42 ).\nDATA(lv_zahl)  = CONV i( '17' ).\nDATA(lo_basis) = CAST zif_tier( NEW zcl_hund( ) ).\nTRY.\n    DATA(lv_kurz) = EXACT i( 3000000000 ).\n  CATCH cx_sy_conversion_error.\n    \" Wert passt nicht in i\nENDTRY.","pitfall":"Normale Zuweisungen schneiden Werte still ab oder runden. Wo das ein Fehler wäre, EXACT verwenden.","lesson":"abap-m7-l1","tested":false},{"id":"abap-corresponding","cat":"Grundlagen","term":"CORRESPONDING","syntax":"ziel = CORRESPONDING #( quelle MAPPING ziel_feld = quell_feld EXCEPT feld ).","text":"Kopiert gleichnamige Felder von Struktur zu Struktur oder von Tabelle zu Tabelle. MAPPING ordnet unterschiedliche Namen zu, EXCEPT schließt Felder aus.","code":"DATA(ls_ziel) = CORRESPONDING ty_ziel(\n  ls_quelle\n  MAPPING kundennr = kunnr\n  EXCEPT  erstellt_am ).","pitfall":"Bei Tabellen ersetzt CORRESPONDING den bisherigen Inhalt des Ziels. Mit BASE( ziel ) bleiben vorhandene Zeilen erhalten, mit DEEP werden verschachtelte Tabellen mitkopiert.","lesson":"abap-m8-l1","tested":false},{"id":"abap-let","cat":"Kontrollfluss","term":"LET in Ausdrücken","syntax":"COND #( LET x = … IN WHEN … THEN … )    VALUE #( FOR … LET … )","text":"LET definiert eine Hilfsvariable, die nur innerhalb des Ausdrucks gilt. Das vermeidet doppelte Berechnungen und macht lange Ausdrücke lesbar.","code":"DATA(lv_text) = COND string(\n  LET lv_rest = lv_limit - lv_stand IN\n  WHEN lv_rest < 0 THEN |Limit um { abs( lv_rest ) } überschritten|\n  WHEN lv_rest = 0 THEN |Limit erreicht|\n  ELSE |noch { lv_rest } frei| ).","pitfall":"Die LET-Variable existiert nur im Ausdruck. Wer sie danach braucht, muss sie mit DATA vorher anlegen.","lesson":"abap-m8-l1","tested":false},{"id":"abap-for-all-entries","cat":"Datenbank (Open SQL)","term":"FOR ALL ENTRIES","syntax":"SELECT … FROM tab FOR ALL ENTRIES IN itab WHERE feld = @itab-feld.","text":"Liest zu jeder Zeile einer internen Tabelle passende Datensätze. Doppelte Ergebniszeilen werden entfernt. Die Tabelle darf nicht leer sein.","code":"IF lt_auftraege IS NOT INITIAL.\n  SELECT kunnr, name1\n    FROM kna1\n    FOR ALL ENTRIES IN @lt_auftraege\n    WHERE kunnr = @lt_auftraege-kunnr\n    INTO TABLE @DATA(lt_kunden).\nENDIF.","pitfall":"Ist die Tabelle leer, liest die Anweisung ALLE Datensätze. Immer vorher prüfen. Meist ist ein JOIN oder eine CDS-View die bessere Lösung.","lesson":"abap-m9-l1","tested":false},{"id":"abap-select-join-agg","cat":"Datenbank (Open SQL)","term":"JOIN, GROUP BY und Aggregate","syntax":"SELECT a~feld, SUM( b~betrag ) AS summe FROM a INNER JOIN b ON … GROUP BY a~feld","text":"Verbindet Tabellen und rechnet in der Datenbank. Aggregatfunktionen wie SUM, COUNT, MAX und AVG liefern verdichtete Werte, sodass weniger Daten zum Anwendungsserver wandern.","code":"SELECT k~land,\n       COUNT( * ) AS anzahl,\n       SUM( a~netwr ) AS umsatz\n  FROM kna1 AS k\n  INNER JOIN vbak AS a ON a~kunnr = k~kunnr\n  GROUP BY k~land\n  INTO TABLE @DATA(lt_umsatz).","pitfall":"Alle nicht aggregierten Felder der Liste müssen im GROUP BY stehen. Rechnen in der Datenbank („Code Pushdown“) ist fast immer schneller als eine Schleife in ABAP.","lesson":"abap-m9-l1","tested":false},{"id":"abap-cds-assoc","cat":"CDS und RAP","term":"CDS: Associations und Parameter","syntax":"association [0..1] to Ziel as _Alias on …    define view entity X with parameters p : abap.dats","text":"Associations beschreiben Beziehungen zu anderen Views, ohne sofort zu joinen. Der Join passiert erst, wenn der Pfad (_Alias) genutzt wird. Parameter machen eine View wiederverwendbar.","code":"define view entity ZI_Bestellung\n  as select from zbestellung as b\n  association [0..1] to ZI_Kunde as _Kunde on _Kunde.KundenId = b.kunden_id\n{\n  key b.bestell_id as BestellId,\n      b.kunden_id  as KundenId,\n      b.betrag     as Betrag,\n      _Kunde\n}","pitfall":"Associations im Select-Liste „veröffentlichen“ (_Kunde), sonst können andere Views sie nicht nutzen. Kardinalität ehrlich angeben, sie beeinflusst Join-Art und Ergebnis.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false,"codeLang":"abap"},{"id":"abap-cds-annotations","cat":"CDS und RAP","term":"CDS: Annotationen und Zugriffskontrolle","syntax":"@AccessControl.authorizationCheck: #CHECK    define role … grant select on …","text":"Annotationen beschreiben Verhalten und Darstellung einer View. Mit einer DCL-Rolle (define role) legt man fest, welche Zeilen ein Benutzer sehen darf, abhängig von Berechtigungsobjekten.","code":"@AccessControl.authorizationCheck: #CHECK\n@EndUserText.label: 'Bestellung'\ndefine view entity ZI_Bestellung as select from zbestellung { key bestell_id as BestellId, land as Land }\n\n@EndUserText.label: 'Zugriff Bestellung'\ndefine role ZI_Bestellung {\n  grant select on ZI_Bestellung\n    where ( Land ) = aspect pfcg_auth( Z_BEST, Z_LAND, ACTVT = '03' );\n}","pitfall":"#NOT_REQUIRED schaltet die Prüfung ab. Das ist nur für bewusst öffentliche Daten vertretbar und sollte im Review begründet sein.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-amdp","cat":"CDS und RAP","term":"AMDP und CDS-Tabellenfunktion","syntax":"CLASS … IF_AMDP_MARKER_HDB    METHODS m BY DATABASE PROCEDURE FOR HDB LANGUAGE SQLSCRIPT","text":"AMDP erlaubt, SQLScript direkt in einer ABAP-Methode zu schreiben und in der HANA-Datenbank auszuführen. Eine CDS-Tabellenfunktion bindet so eine Methode als Datenquelle ein.","code":"CLASS zcl_umsatz DEFINITION PUBLIC FINAL CREATE PUBLIC.\n  PUBLIC SECTION.\n    INTERFACES if_amdp_marker_hdb.\n    CLASS-METHODS berechne FOR TABLE FUNCTION zi_umsatz_tf.\nENDCLASS.\n\nCLASS zcl_umsatz IMPLEMENTATION.\n  METHOD berechne BY DATABASE FUNCTION FOR HDB LANGUAGE SQLSCRIPT OPTIONS READ-ONLY USING vbak.\n    RETURN SELECT mandt, kunnr, SUM( netwr ) AS umsatz\n             FROM vbak GROUP BY mandt, kunnr;\n  ENDMETHOD.\nENDCLASS.","pitfall":"USING nennt alle Datenbankobjekte, die die Methode liest. Fehlt eine, scheitert die Aktivierung. AMDP bindet an HANA und ist in ABAP Cloud nicht erlaubt. Zuerst prüfen, ob CDS-Mittel ausreichen.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-rap-determination","cat":"CDS und RAP","term":"RAP: determination und validation","syntax":"determination x on modify { create; field f; }    validation y on save { create; field f; }","text":"Eine Determination berechnet Felder automatisch (z. B. Status setzen). Eine Validation prüft Daten vor dem Speichern und meldet Fehler. Beide werden im Behavior Definition deklariert und in der Behavior Pool Class implementiert.","code":"managed implementation in class zbp_i_bestellung unique;\nstrict ( 2 );\n\ndefine behavior for ZI_Bestellung alias Bestellung\n  persistent table zbestellung\n  lock master\n  authorization master ( instance )\n{\n  create; update; delete;\n  determination setzeStatus on modify { create; }\n  validation pruefeBetrag on save { create; field Betrag; }\n}","pitfall":"Validierungen gehören auf save, Determinationen auf modify. Eine Validation darf Daten nicht ändern, sie meldet nur Fehler über failed und reported.","lesson":"abap-m12-quellen-validierung-determination-und-action-mit-eml-auseinanderhalten","tested":false},{"id":"abap-rap-action","cat":"CDS und RAP","term":"RAP: action","syntax":"action ( features : instance ) freigeben result [1] $self;","text":"Eine Action ist ein benannter Vorgang auf einem Business Object, z. B. „freigeben“. Sie erscheint als Button in Fiori Elements und lässt sich per EML aufrufen. features steuert, wann sie bedienbar ist.","code":"define behavior for ZI_Bestellung alias Bestellung\n{\n  action ( features : instance ) freigeben result [1] $self;\n}\n\n\" Implementierung\nMETHOD freigeben.\n  MODIFY ENTITIES OF zi_bestellung IN LOCAL MODE\n    ENTITY Bestellung UPDATE FIELDS ( Status )\n    WITH VALUE #( FOR k IN keys ( %tky = k-%tky Status = 'F' ) ).\n  READ ENTITIES OF zi_bestellung IN LOCAL MODE\n    ENTITY Bestellung ALL FIELDS WITH CORRESPONDING #( keys ) RESULT DATA(lt_b).\n  result = VALUE #( FOR b IN lt_b ( %tky = b-%tky %param = b ) ).\nENDMETHOD.","pitfall":"In einer Behavior Pool Class IN LOCAL MODE verwenden, sonst greifen Berechtigungs- und Feature-Prüfungen erneut. Wer (features : instance) deklariert, muss die Methode get_instance_features implementieren.","lesson":"abap-m12-quellen-validierung-determination-und-action-mit-eml-auseinanderhalten","tested":false},{"id":"abap-rap-draft","cat":"CDS und RAP","term":"RAP: Draft","syntax":"with draft;    draft table zbestellung_d;    draft action Edit; Activate; Discard; Resume;","text":"Mit Draft speichert die Oberfläche Zwischenstände, ohne die echten Daten zu ändern. Dafür gibt es eine Draft-Tabelle und feste Standard-Actions (Edit, Activate, Discard, Resume) sowie Prepare für die Prüfung vor dem Aktivieren.","code":"managed implementation in class zbp_i_bestellung unique;\nstrict ( 2 );\nwith draft;\n\ndefine behavior for ZI_Bestellung alias Bestellung\n  persistent table zbestellung\n  draft table zbestellung_d\n  lock master total etag LastChanged\n  etag master LocalLastChanged\n{\n  create; update; delete;\n  draft action Edit;\n  draft action Activate optimized;\n  draft action Discard;\n  draft action Resume;\n  draft determine action Prepare { validation pruefeBetrag; }\n}","pitfall":"Ohne passendes ETag-Feld und Sperrkonzept gehen bei parallelem Bearbeiten Änderungen verloren. Die Draft-Tabelle muss zur Persistenztabelle passen.","lesson":"abap-m12-l1","tested":false},{"id":"abap-rap-projection","cat":"CDS und RAP","term":"Projection View und Service","syntax":"define root view entity ZC_… as projection on ZI_…    define service ZUI_… { expose … }","text":"Die Projection View schneidet das Business Object für eine App zu (Felder, Verhalten). Eine Service Definition legt fest, was ein Service anbietet, die Service Binding macht daraus einen OData-V4-UI-Service.","code":"@EndUserText.label: 'Bestellung (App)'\n@Metadata.allowExtensions: true\ndefine root view entity ZC_Bestellung\n  provider contract transactional_query\n  as projection on ZI_Bestellung\n{\n  key BestellId,\n      Betrag,\n      Status\n}\n\n\" Behavior Definition der Projektion (eigene Datei)\nprojection;\nstrict ( 2 );\ndefine behavior for ZC_Bestellung alias Bestellung\n{\n  use create; use update; use delete;\n}\n\n@EndUserText.label: 'Service Bestellung'\ndefine service ZUI_BESTELLUNG {\n  expose ZC_Bestellung as Bestellung;\n}","pitfall":"Die Service Binding (Typ „OData V4 – UI“) wird in den ADT angelegt und muss veröffentlicht werden. Erst danach lässt sich die App starten.","lesson":"abap-m12-quellen-vom-business-object-zum-odata-v4-ui-service","tested":false},{"id":"abap-eml-modify","cat":"CDS und RAP","term":"EML: MODIFY, COMMIT ENTITIES","syntax":"MODIFY ENTITIES OF zi_… ENTITY e CREATE FIELDS ( … ) WITH …    COMMIT ENTITIES.","text":"EML (Entity Manipulation Language) ändert Daten über das Business Object und nicht direkt in der Tabelle. Die Änderungen liegen zuerst im Puffer; COMMIT ENTITIES schreibt sie in die Datenbank.","code":"MODIFY ENTITIES OF zi_bestellung\n  ENTITY Bestellung\n    CREATE FIELDS ( Betrag Status )\n    WITH VALUE #( ( %cid = 'neu1' Betrag = 100 Status = 'N' ) )\n  MAPPED DATA(mapped)\n  FAILED DATA(failed)\n  REPORTED DATA(reported).\n\nIF failed IS INITIAL.\n  COMMIT ENTITIES.\nENDIF.","pitfall":"Ohne COMMIT ENTITIES bleibt die Änderung im Puffer. Vor dem Commit failed prüfen, sonst wird trotz Fehler gespeichert.","lesson":"abap-m12-senior-eml-tests","tested":false},{"id":"abap-lock-object","cat":"Datenbank (Open SQL)","term":"Sperrobjekte (ENQUEUE/DEQUEUE)","syntax":"CALL FUNCTION 'ENQUEUE_EZ…'    CALL FUNCTION 'DEQUEUE_EZ…'","text":"Sperrobjekte verhindern, dass zwei Benutzer denselben Datensatz gleichzeitig ändern. Aus dem Sperrobjekt in der SE11 entstehen zwei Funktionsbausteine, die ENQUEUE sperrt und DEQUEUE wieder freigibt.","code":"CALL FUNCTION 'ENQUEUE_EZBESTELLUNG'\n  EXPORTING bestell_id = lv_id\n  EXCEPTIONS foreign_lock = 1 system_failure = 2 OTHERS = 3.\nIF sy-subrc <> 0.\n  MESSAGE e001(zmsg) WITH lv_id.\nENDIF.\n\" … ändern …\nCALL FUNCTION 'DEQUEUE_EZBESTELLUNG' EXPORTING bestell_id = lv_id.","pitfall":"Sperren nach dem Ändern immer freigeben (am Ende der Logischen Arbeitseinheit). In RAP übernimmt das die Anweisung lock master.","lesson":"abap-m12-l2","tested":false},{"id":"abap-message","cat":"Fehler","term":"MESSAGE und Nachrichtenklasse","syntax":"MESSAGE e001(zmsg) WITH wert.    MESSAGE |Text| TYPE 'I'.","text":"MESSAGE gibt Meldungen aus. Der Typ steuert die Wirkung: S Erfolg, I Information, W Warnung, E Fehler, A Abbruch, X Kurzdump. Texte liegen in einer Nachrichtenklasse (SE91) und lassen sich übersetzen.","code":"MESSAGE e001(zmsg) WITH lv_id.\nMESSAGE s002(zmsg).\nMESSAGE |Bestellung { lv_id } gesperrt| TYPE 'I' DISPLAY LIKE 'E'.","pitfall":"Feste Texte im Code sind nicht übersetzbar. In neuer Entwicklung Nachrichtenklassen oder Exceptions mit Textquelle (IF_T100_MESSAGE) nutzen.","lesson":"abap-m10-l4","tested":false},{"id":"abap-assert-raise","cat":"Fehler","term":"ASSERT, RAISE EXCEPTION und CLEANUP","syntax":"ASSERT bedingung.    RAISE EXCEPTION NEW zcx_fehler( … ).    CLEANUP.","text":"ASSERT prüft Annahmen, die nie verletzt sein dürfen, und bricht sonst ab. RAISE EXCEPTION löst eine behandelbare Ausnahme aus. CLEANUP räumt in einer TRY-Anweisung auf, wenn die Ausnahme nicht abgefangen wird.","code":"ASSERT lv_betrag >= 0.\n\n\" Ausnahme auslösen und behandeln\nTRY.\n    IF lv_id IS INITIAL.\n      RAISE EXCEPTION NEW zcx_ungueltig( ).\n    ENDIF.\n  CATCH zcx_ungueltig INTO DATA(lx).\n    MESSAGE lx TYPE 'E'.\nENDTRY.\n\n\" CLEANUP: Methode reicht die Ausnahme weiter (RAISING), räumt aber vorher auf\nMETHOD verarbeite RAISING zcx_ungueltig.\n  TRY.\n      pruefe( iv_id ).\n    CLEANUP.\n      CLEAR mt_puffer.\n  ENDTRY.\nENDMETHOD.","pitfall":"ASSERT nicht für Benutzereingaben verwenden, sondern nur für Programmfehler. Der CLEANUP-Block läuft nur, wenn die Ausnahme die TRY-Anweisung verlässt, nicht wenn ein CATCH sie abfängt.","lesson":"abap-m10-l4","tested":false},{"id":"abap-events","cat":"Klassen","term":"Ereignisse (EVENTS, SET HANDLER)","syntax":"EVENTS name.    RAISE EVENT name.    SET HANDLER objekt->methode FOR ALL INSTANCES.","text":"Ereignisse entkoppeln Klassen: Der Auslöser meldet, dass etwas passiert ist, beliebig viele Handler reagieren darauf, ohne dass der Auslöser sie kennt.","code":"CLASS zcl_lager DEFINITION PUBLIC.\n  PUBLIC SECTION.\n    EVENTS bestand_niedrig EXPORTING VALUE(artikel) TYPE string.\n    METHODS entnehmen IMPORTING artikel TYPE string menge TYPE i.\nENDCLASS.\n\nCLASS zcl_einkauf DEFINITION PUBLIC.\n  PUBLIC SECTION.\n    METHODS on_niedrig FOR EVENT bestand_niedrig OF zcl_lager IMPORTING artikel.\nENDCLASS.\n\nSET HANDLER lo_einkauf->on_niedrig FOR lo_lager.","pitfall":"Handler bleiben registriert, solange das Objekt lebt. Referenzen aufräumen, sonst entstehen Speicherlecks und unerwartete Aufrufe.","lesson":"abap-m16-l3","tested":false},{"id":"abap-case-type-of","cat":"Kontrollfluss","term":"CASE TYPE OF und IS INSTANCE OF","syntax":"CASE TYPE OF objekt.  WHEN TYPE klasse INTO DATA(x).  …  ENDCASE.","text":"Verzweigt nach dem tatsächlichen Typ eines Objekts und erzeugt gleich eine typisierte Variable. IS INSTANCE OF prüft den Typ in einer Bedingung.","code":"CASE TYPE OF lo_tier.\n  WHEN TYPE zcl_hund INTO DATA(lo_hund).\n    lo_hund->belle( ).\n  WHEN TYPE zcl_katze INTO DATA(lo_katze).\n    lo_katze->schnurre( ).\n  WHEN OTHERS.\n    \" unbekannt\nENDCASE.","pitfall":"Viele WHEN-Zweige nach Typ sind ein Hinweis, dass die Methode besser in der Klasse selbst (Polymorphie) stehen sollte.","lesson":"abap-m17-l1","tested":false},{"id":"abap-test-double","cat":"Tests","term":"ABAP Unit: Test Doubles","syntax":"cl_abap_testdouble=>create( 'zif_x' )    cl_osql_test_environment=>create( … )","text":"Test Doubles ersetzen Abhängigkeiten im Unit-Test. Für Interfaces erzeugt cl_abap_testdouble Attrappen. Für Datenbanktabellen und CDS-Views ersetzt cl_osql_test_environment die echten Daten durch Testdaten.","code":"DATA(lo_preise) = CAST zif_preisdienst( cl_abap_testdouble=>create( 'zif_preisdienst' ) ).\n\" 1. Verhalten festlegen: configure_call, dann die Methode mit den erwarteten Parametern „aufrufen“\ncl_abap_testdouble=>configure_call( lo_preise )->returning( 9 )->and_expect( )->is_called_once( ).\nlo_preise->preis( 'A1' ).\n\n\" 2. Doppelgänger in das zu testende Objekt einbauen und prüfen\nDATA(lo_cut) = NEW zcl_warenkorb( lo_preise ).\ncl_abap_unit_assert=>assert_equals( act = lo_cut->summe( ) exp = 9 ).\ncl_abap_testdouble=>verify_expectations( lo_preise ).","pitfall":"Dependency Injection über den Konstruktor ist die Voraussetzung. Wer Abhängigkeiten selbst mit NEW erzeugt, kann sie nicht ersetzen.","lesson":"abap-m10-l1","tested":false}]},{"id":"fiori","label":"SAP Fiori / UI5","codeLang":"javascript","intro":"Fiori ist das Bedienkonzept von SAP, SAPUI5 das zugehörige Web-Framework. Bei Fiori elements entsteht die Oberfläche aus Metadaten und Annotationen, bei freien UI5-Apps aus XML-Views, Controllern und Models.","notice":"Diese Beispiele sind nicht in einem SAP-System oder mit dem UI5-Tooling ausgeführt. Sie folgen der dokumentierten Struktur; vor dem Einsatz im eigenen Projekt prüfen.","runner":"","entries":[{"id":"fiori-manifest-app","cat":"App-Aufbau","term":"manifest.json: sap.app und sap.ui5","syntax":"{ \"sap.app\": { \"id\": … }, \"sap.ui5\": { \"dependencies\": …, \"models\": …, \"routing\": … } }","text":"Die manifest.json ist der Steckbrief einer App: ID, Version, Datenquellen, benötigte UI5-Bibliotheken, Models und Routing. Fiori elements Apps bestehen fast nur aus dieser Datei und den Annotationen.","code":"{\n  \"_version\": \"1.65.0\",\n  \"sap.app\": {\n    \"id\": \"meine.bestellungen\",\n    \"type\": \"application\",\n    \"title\": \"{{appTitle}}\",\n    \"i18n\": \"i18n/i18n.properties\",\n    \"dataSources\": {\n      \"mainService\": { \"uri\": \"/sap/opu/odata4/sap/zui_bestellung/srvd/sap/zui_bestellung/0001/\", \"type\": \"OData\", \"settings\": { \"odataVersion\": \"4.0\" } }\n    }\n  },\n  \"sap.ui5\": {\n    \"dependencies\": { \"minUI5Version\": \"1.136.0\", \"libs\": { \"sap.m\": {}, \"sap.fe.templates\": {} } },\n    \"models\": { \"\": { \"dataSource\": \"mainService\", \"settings\": { \"operationMode\": \"Server\", \"autoExpandSelect\": true } } }\n  }\n}","pitfall":"Die Werte (Versionen, URIs) sind Beispiele. Die aktuelle _version und minUI5Version der Ziel-Landschaft nachsehen, nicht abschreiben.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"javascript"},{"id":"fiori-manifest-routing","cat":"App-Aufbau","term":"manifest.json: Routing und Targets (Fiori elements)","syntax":"\"routing\": { \"routes\": [ { \"pattern\": \":?query:\", \"name\": \"…\", \"target\": \"…\" } ], \"targets\": { … } }","text":"Routen verbinden eine URL mit einer Seite (Target). Bei Fiori elements besteht eine App aus einem List Report und einer Object Page, deren Einstellungen in den Targets stehen.","code":"\"routing\": {\n  \"routes\": [\n    { \"pattern\": \":?query:\", \"name\": \"BestellungList\", \"target\": \"BestellungList\" },\n    { \"pattern\": \"Bestellung({key}):?query:\", \"name\": \"BestellungObjectPage\", \"target\": \"BestellungObjectPage\" }\n  ],\n  \"targets\": {\n    \"BestellungList\": {\n      \"type\": \"Component\", \"id\": \"BestellungList\", \"name\": \"sap.fe.templates.ListReport\",\n      \"options\": { \"settings\": { \"contextPath\": \"/Bestellung\", \"variantManagement\": \"Page\" } }\n    },\n    \"BestellungObjectPage\": {\n      \"type\": \"Component\", \"id\": \"BestellungObjectPage\", \"name\": \"sap.fe.templates.ObjectPage\",\n      \"options\": { \"settings\": { \"contextPath\": \"/Bestellung\" } }\n    }\n  }\n}","pitfall":"Tippfehler in Targets oder contextPath führen zu einer leeren Seite ohne klare Fehlermeldung. Browser-Konsole und Netzwerk-Tab prüfen.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"javascript"},{"id":"fiori-ann-lineitem","cat":"Annotationen (Fiori elements)","term":"UI.LineItem","syntax":"@UI.lineItem: [{ position: 10, label: '…', importance: #HIGH }]","text":"Legt die Spalten der Tabelle im List Report fest. position bestimmt die Reihenfolge, importance steuert, welche Spalten auf kleinen Bildschirmen zuerst ausgeblendet werden.","code":"@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @UI.lineItem: [{ position: 10, importance: #HIGH }]\n  BestellId;\n\n  @UI.lineItem: [{ position: 20, importance: #HIGH, label: 'Betrag' }]\n  Betrag;\n\n  @UI.lineItem: [{ position: 30, importance: #MEDIUM }]\n  Status;\n}","pitfall":"Annotationen stehen in einer Metadata Extension (Layer #CORE bzw. #CUSTOMER), die Projection View braucht @Metadata.allowExtensions: true. Neue Annotationen erscheinen erst, wenn das Metadaten-Dokument neu geladen wird (Browser-Cache leeren).","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"abap"},{"id":"fiori-ann-selection","cat":"Annotationen (Fiori elements)","term":"UI.SelectionField und UI.HeaderInfo","syntax":"@UI.selectionField: [{ position: 10 }]    @UI.headerInfo: { typeName: …, title: { value: … } }","text":"selectionField legt fest, welche Felder als Filter im List Report erscheinen. headerInfo benennt den Objekttyp und bestimmt Titel und Untertitel der Object Page.","code":"@Metadata.layer: #CORE\n@UI.headerInfo: {\n  typeName: 'Bestellung',\n  typeNamePlural: 'Bestellungen',\n  title: { type: #STANDARD, value: 'BestellId' },\n  description: { value: 'Status' }\n}\nannotate entity ZC_Bestellung with\n{\n  @UI.selectionField: [{ position: 10 }]\n  Status;\n}","pitfall":"Zu viele Filterfelder überfordern. Die meistgenutzten drei bis fünf Felder nach vorn, den Rest im „Filter anpassen“-Dialog.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"abap"},{"id":"fiori-ann-facets","cat":"Annotationen (Fiori elements)","term":"UI.Facet, FieldGroup und Identification","syntax":"@UI.facet: [{ type: #COLLECTION|#FIELDGROUP_REFERENCE|#LINEITEM_REFERENCE, … }]","text":"Facets gliedern die Object Page in Abschnitte. Eine FieldGroup bündelt Felder zu einem Block, ein LineItem-Facet zeigt eine Tabelle (z. B. Positionen).","code":"@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @UI.facet: [\n    { id: 'Allgemein', type: #COLLECTION, label: 'Allgemein', position: 10 },\n    { id: 'Basis', type: #FIELDGROUP_REFERENCE, parentId: 'Allgemein', targetQualifier: 'Basis', position: 10 },\n    { id: 'Positionen', type: #LINEITEM_REFERENCE, label: 'Positionen', targetElement: '_Positionen', position: 20 }\n  ]\n  @UI.fieldGroup: [{ qualifier: 'Basis', position: 10 }]\n  BestellId;\n\n  @UI.fieldGroup: [{ qualifier: 'Basis', position: 20 }]\n  Betrag;\n}","pitfall":"Der targetQualifier der Facet muss zum qualifier der FieldGroup passen, sonst bleibt der Abschnitt leer.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"abap"},{"id":"fiori-ann-valuehelp","cat":"Annotationen (Fiori elements)","term":"Wertehilfe (Common.ValueList)","syntax":"@Consumption.valueHelpDefinition: [{ entity: { name: …, element: … } }]","text":"Hängt an ein Feld eine Eingabehilfe, die Werte aus einer anderen View anbietet. Fiori elements zeigt sie als Dialog oder Dropdown, ohne Code in der Oberfläche.","code":"@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @Consumption.valueHelpDefinition: [{\n    entity: { name: 'ZI_Kunde', element: 'KundenId' }\n  }]\n  KundenId;\n}","pitfall":"Für lange Listen eine Suchfunktion oder Filterung mitliefern und Werte nicht vollständig laden.","lesson":"abap-m13-l2","tested":false,"codeLang":"abap"},{"id":"fiori-xmlview","cat":"SAPUI5 (freie Apps)","term":"XML-View: Controls und Namensräume","syntax":"<mvc:View xmlns=\"sap.m\" xmlns:mvc=\"sap.ui.core.mvc\" controllerName=\"…\">","text":"Eine XML-View beschreibt die Oberfläche deklarativ. Die xmlns-Angaben bestimmen, aus welcher Bibliothek ein Element kommt (sap.m für mobile Controls). controllerName verknüpft die View mit ihrem Controller.","code":"<mvc:View controllerName=\"meine.bestellungen.controller.Liste\"\n          xmlns=\"sap.m\" xmlns:mvc=\"sap.ui.core.mvc\">\n  <Page title=\"{i18n>listeTitel}\">\n    <content>\n      <Button text=\"{i18n>neu}\" press=\".onNeu\" type=\"Emphasized\"/>\n    </content>\n  </Page>\n</mvc:View>","pitfall":"Event-Handler mit führendem Punkt schreiben (.onNeu), damit sie im Controller gefunden werden.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"html"},{"id":"fiori-binding","cat":"SAPUI5 (freie Apps)","term":"Datenbindung und Formatter","syntax":"text=\"{/pfad}\"    items=\"{/Bestellung}\"    text=\"{path: 'betrag', formatter: '.formatBetrag'}\"","text":"Binding verbindet ein Control mit einem Model. Mit items=\"{…}\" erzeugt man pro Datensatz ein Listenelement aus einer Vorlage (Template). Ein Formatter wandelt den Wert vor der Anzeige um.","code":"<List items=\"{path: '/Bestellung', sorter: {path: 'BestellId'}}\">\n  <ObjectListItem\n    title=\"{BestellId}\"\n    number=\"{path: 'Betrag', type: 'sap.ui.model.type.Float', formatOptions: {decimals: 2}}\"\n    numberUnit=\"EUR\">\n    <firstStatus>\n      <ObjectStatus text=\"{path: 'Status', formatter: '.formatStatus'}\"/>\n    </firstStatus>\n  </ObjectListItem>\n</List>","pitfall":"Formatter dürfen nur umrechnen, keine Daten ändern oder nachladen. Sonst werden sie bei jedem Rendern erneut ausgeführt.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"html"},{"id":"fiori-controller","cat":"SAPUI5 (freie Apps)","term":"Controller und Model","syntax":"sap.ui.define([…], function (Controller, JSONModel) { return Controller.extend(\"…\", { onInit() { … } }); })","text":"Der Controller enthält die Logik der View. In onInit legt man Models an, Event-Handler reagieren auf Eingaben. Das JSONModel hält Daten im Browser, das ODataModel spricht mit dem Backend.","code":"sap.ui.define([\n  \"sap/ui/core/mvc/Controller\",\n  \"sap/ui/model/json/JSONModel\",\n  \"sap/m/MessageToast\"\n], function (Controller, JSONModel, MessageToast) {\n  \"use strict\";\n  return Controller.extend(\"meine.bestellungen.controller.Liste\", {\n    onInit() {\n      this.getView().setModel(new JSONModel({ anzahl: 0 }), \"ui\");\n    },\n    onNeu() {\n      const model = this.getView().getModel(\"ui\");\n      model.setProperty(\"/anzahl\", model.getProperty(\"/anzahl\") + 1);\n      MessageToast.show(\"Neu angelegt\");\n    }\n  });\n});","pitfall":"Texte nicht fest im Controller schreiben, sondern über das i18n-ResourceModel laden, damit sie übersetzbar bleiben.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-odata-v4","cat":"SAPUI5 (freie Apps)","term":"OData V4: Binding, Filter und Aktionen","syntax":"oContext = oBinding.create({…})    oModel.bindContext(\"/Bestellung(…)/freigeben(…)\").execute()","text":"Das OData-V4-Model arbeitet über Bindings und Contexts. Mit create() legt man einen Datensatz an, mit setProperty ändert man ihn, submitBatch schickt die Änderungen. Aktionen (z. B. aus RAP) ruft man über ein Operations-Binding auf.","code":"// MessageToast und MessageBox über sap.ui.define importieren\nonFreigeben() {\n  const model = this.getView().getModel();\n  const kontext = this.byId(\"tabelle\").getSelectedItem().getBindingContext();\n  // gebundene Aktion: Namespace des Services + Aktionsname, (...) steht für die Parameter\n  const aktion = model.bindContext(\"com.sap.gateway.srvd.zui_bestellung.v0001.freigeben(...)\", kontext);\n  aktion.execute()\n    .then(() => MessageToast.show(\"Freigegeben\"))\n    .catch((fehler) => MessageBox.error(fehler.message));\n}","pitfall":"Fehler immer abfangen und dem Benutzer verständlich zeigen. Rohe Servertexte (Stacktraces, interne Namen) gehören nicht in die Oberfläche.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-i18n","cat":"SAPUI5 (freie Apps)","term":"i18n und Übersetzungen","syntax":"{i18n>schluessel}    oBundle.getText(\"schluessel\", [param])","text":"Texte stehen in Properties-Dateien (i18n.properties, i18n_de.properties). Im Code und in Views verweist man nur auf den Schlüssel. So lässt sich eine App ohne Codeänderung übersetzen.","code":"# i18n/i18n_de.properties\nlisteTitel=Bestellungen\nneu=Neu anlegen\nanzahl={0} Bestellungen gefunden\n\n// Controller\nconst bundle = this.getOwnerComponent().getModel(\"i18n\").getResourceBundle();\nMessageToast.show(bundle.getText(\"anzahl\", [12]));","pitfall":"Properties-Dateien sind ISO-8859-1 oder UTF-8 je nach Projekteinstellung. Umlaute prüfen, sonst erscheinen Sonderzeichen falsch.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"bash"},{"id":"fiori-ui5-cli","cat":"Entwicklung","term":"UI5 Tooling (ui5 serve, build)","syntax":"npm install    ui5 serve    ui5 build --all    ui5 --version","text":"Das UI5 Tooling startet einen lokalen Entwicklungsserver, baut die App für die Auslieferung und prüft die ui5.yaml. Fiori Tools (SAP Business Application Studio, VS Code) setzen darauf auf.","code":"npm install --save-dev @ui5/cli\nnpx ui5 serve --open index.html\nnpx ui5 build --all --clean-dest","pitfall":"Die App läuft lokal gegen Mockdaten oder einen Proxy auf das Backend. Zugangsdaten gehören nicht in die ui5.yaml, sondern in Umgebungsvariablen.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"bash"},{"id":"fiori-controller-ext","cat":"Erweiterbarkeit","term":"Controller Extension (Fiori elements V4)","syntax":"sap.ui.define([\"sap/ui/core/mvc/ControllerExtension\"], …)","text":"Mit einer Controller Extension ergänzt man eigenes Verhalten in einer Fiori elements App, ohne den Standard zu kopieren. Sie wird im manifest.json bei der Seite eingetragen.","code":"// ext/controller/ObjectPageExt.controller.js\nsap.ui.define([\"sap/ui/core/mvc/ControllerExtension\"], function (ControllerExtension) {\n  \"use strict\";\n  return ControllerExtension.extend(\"meine.bestellungen.ext.controller.ObjectPageExt\", {\n    override: {\n      onInit() {\n        // eigene Initialisierung\n      }\n    }\n  });\n});\n\n// manifest.json: Erweiterung bei der Seite eintragen\n// \"sap.ui5\": { \"extends\": { \"extensions\": { \"sap.ui.controllerExtensions\": {\n//   \"sap.fe.templates.ObjectPage.ObjectPageController#meine.bestellungen::BestellungObjectPage\": {\n//     \"controllerName\": \"meine.bestellungen.ext.controller.ObjectPageExt\" } } } } }","pitfall":"Nur offiziell freigegebene Erweiterungspunkte nutzen. Zugriffe auf interne Objekte können bei Updates brechen.","lesson":"abap-m13-l1","tested":false,"codeLang":"javascript"},{"id":"fiori-custom-action","cat":"Erweiterbarkeit","term":"Benutzerdefinierte Aktion im Manifest","syntax":"\"controlConfiguration\": { \"@com.sap.vocabularies.UI.v1.LineItem\": { \"actions\": { … } } }","text":"Eigene Buttons fügt man ohne Annotation über das manifest.json in die Tabelle oder Kopfzeile ein. press verweist auf eine Funktion der Controller Extension.","code":"\"controlConfiguration\": {\n  \"@com.sap.vocabularies.UI.v1.LineItem\": {\n    \"actions\": {\n      \"pruefen\": {\n        \"press\": \"meine.bestellungen.ext.Aktionen.onPruefen\",\n        \"visible\": true,\n        \"requiresSelection\": true,\n        \"text\": \"{i18n>pruefen}\"\n      }\n    }\n  }\n}\n\n// ext/Aktionen.js: ein Modul mit der Handler-Funktion\nsap.ui.define([\"sap/m/MessageToast\"], function (MessageToast) {\n  \"use strict\";\n  return {\n    onPruefen(kontext, ausgewaehlteKontexte) {\n      MessageToast.show(ausgewaehlteKontexte.length + \" Bestellungen geprüft\");\n    }\n  };\n});","pitfall":"Der Handler ist ein eigenes Modul, keine Methode der Controller Extension. Wo möglich, besser eine RAP-Action im Backend definieren: sie ist testbar, wiederverwendbar und berechtigungsgeprüft.","lesson":"abap-m13-l1","tested":false,"codeLang":"javascript"},{"id":"fiori-side-effects","cat":"Erweiterbarkeit","term":"Side Effects (RAP)","syntax":"side effects { field Betrag affects field Gesamtbetrag, entity _Positionen; }","text":"Side Effects teilen der Oberfläche mit, welche Daten sich nach einer Änderung neu laden müssen. Ohne sie zeigt die Seite berechnete Felder erst nach manuellem Aktualisieren korrekt.","code":"define behavior for ZI_Bestellung alias Bestellung\n{\n  side effects {\n    field Menge affects field Gesamtbetrag;\n    action freigeben affects field Status, messages;\n  }\n}","pitfall":"Zu viele Side Effects erzeugen unnötige Serveranfragen. Nur die tatsächlich abhängigen Felder angeben.","lesson":"abap-m13-senior-side-effects","tested":false},{"id":"fiori-launchpad-intent","cat":"Launchpad","term":"Intent: Semantic Object und Action","syntax":"#SemanticObject-action?param=wert","text":"Kacheln im Fiori Launchpad rufen Apps über einen Intent auf. Er besteht aus Semantic Object (z. B. Bestellung) und Action (z. B. display). Die Zuordnung zur App liegt im Target Mapping.","code":"\"crossNavigation\": {\n  \"inbounds\": {\n    \"BestellungAnzeigen\": {\n      \"semanticObject\": \"Bestellung\",\n      \"action\": \"display\",\n      \"signature\": {\n        \"parameters\": { \"BestellId\": { \"required\": true } },\n        \"additionalParameters\": \"allowed\"\n      }\n    }\n  }\n}\n\n// Aufruf aus einer anderen App\nconst nav = await sap.ushell.Container.getServiceAsync(\"Navigation\");\nnav.navigate({ target: { semanticObject: \"Bestellung\", action: \"display\" }, params: { BestellId: \"4711\" } });","pitfall":"Nach dem Transport fehlen häufig Katalog, Gruppe oder Rolle. Dann erscheint die Kachel nicht. Zuerst Rollenzuordnung und Target Mapping prüfen.","lesson":"abap-m13-senior-launchpad","tested":false,"codeLang":"javascript"},{"id":"fiori-a11y-ux","cat":"Entwicklung","term":"Barrierefreiheit und Oberflächenregeln","syntax":"labelFor    required    valueState    tooltip    ariaLabelledBy","text":"SAPUI5-Controls bringen viele Barrierefreiheits-Funktionen mit, verlangen aber saubere Beschriftung: Jedes Eingabefeld braucht ein Label, Icons ohne Text brauchen einen Tooltip bzw. Alternativtext, Fehler brauchen Text statt nur Farbe.","code":"<Label text=\"{i18n>betrag}\" labelFor=\"betragInput\" required=\"true\"/>\n<Input id=\"betragInput\" value=\"{Betrag}\" valueState=\"{ui>/betragStatus}\"\n       valueStateText=\"{i18n>betragFehler}\"/>\n<Button icon=\"sap-icon://delete\" tooltip=\"{i18n>loeschen}\" ariaLabelledBy=\"loeschenText\"/>\n<Text id=\"loeschenText\" text=\"{i18n>loeschen}\" visible=\"false\"/>","pitfall":"Nur mit Tastatur und einem Screenreader prüfen, nicht nur mit dem Automatiktest. In Deutschland gilt für viele Angebote das BFSG.","lesson":"abap-m13-l2","tested":false,"codeLang":"html"},{"id":"fiori-ann-datapoint","cat":"Annotationen (Fiori elements)","term":"UI.DataPoint, UI.Chart und Kritikalität","syntax":"@UI.dataPoint: { title: …, criticality: 'Feld' }    @UI.lineItem: [{ criticality: 'Feld' }]","text":"Ein DataPoint zeigt einen Kennwert (Titel, Wert, Ampelfarbe) im Kopfbereich der Object Page. Die Kritikalität kommt aus einem Feld der View: 0 neutral, 1 negativ (rot), 2 kritisch (gelb), 3 positiv (grün). Dasselbe Feld färbt Spalten der Tabelle.","code":"// in der CDS-View\ncase Status when 'F' then 3 when 'N' then 2 else 0 end as StatusKritikalitaet\n\n// Metadata Extension\n@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @UI.dataPoint: { title: 'Status', criticality: 'StatusKritikalitaet' }\n  @UI.lineItem: [{ position: 30, criticality: 'StatusKritikalitaet' }]\n  Status;\n}","pitfall":"Farbe darf nie der einzige Hinweis sein (WCAG). Der Statustext muss zusätzlich sichtbar bleiben.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"abap"},{"id":"fiori-ann-actions","cat":"Annotationen (Fiori elements)","term":"Aktionen: UI.lineItem und UI.identification mit dataAction","syntax":"@UI.lineItem: [{ type: #FOR_ACTION, dataAction: 'freigeben', label: … }]","text":"RAP-Actions erscheinen als Button, sobald man sie annotiert. In lineItem steht die Schaltfläche über der Tabelle, in identification im Kopf der Object Page. dataAction nennt die Action, inPlace steuert, ob sie ohne Navigation ausgeführt wird.","code":"@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @UI.lineItem: [\n    { position: 10 },\n    { type: #FOR_ACTION, dataAction: 'freigeben', label: 'Freigeben', invocationGrouping: #CHANGE_SET }\n  ]\n  @UI.identification: [{ type: #FOR_ACTION, dataAction: 'freigeben', label: 'Freigeben', position: 10 }]\n  BestellId;\n}","pitfall":"Die Action muss in der Projection Behavior Definition mit use action freigeben; freigegeben werden, sonst erscheint der Button nicht.","lesson":"abap-m13-l1","tested":false,"codeLang":"abap"},{"id":"fiori-ann-text","cat":"Annotationen (Fiori elements)","term":"Texte zu Schlüsseln und Suche","syntax":"@ObjectModel.text.element: ['StatusText']    @UI.textArrangement: #TEXT_FIRST    @Search.defaultSearchElement: true","text":"Technische Schlüssel (Status F, Land DE) sind für Anwender unverständlich. Mit text.element verbindet man den Schlüssel mit seinem Klartext, textArrangement bestimmt die Anzeige (Text zuerst, Text und ID, nur Text). Search.defaultSearchElement nimmt das Feld in die Volltextsuche auf.","code":"@Metadata.layer: #CORE\nannotate entity ZC_Bestellung with\n{\n  @ObjectModel.text.element: ['StatusText']\n  @UI.textArrangement: #TEXT_FIRST\n  @UI.selectionField: [{ position: 20 }]\n  Status;\n\n  @Search.defaultSearchElement: true\n  @Search.fuzzinessThreshold: 0.8\n  KundenName;\n}","pitfall":"Die Volltextsuche (Search) braucht Indexierung in der Datenbank und kann Last erzeugen. Nur wirklich gesuchte Felder aufnehmen.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"abap"},{"id":"fiori-ann-presentation","cat":"Annotationen (Fiori elements)","term":"UI.presentationVariant und selectionVariant","syntax":"@UI.presentationVariant: [{ sortOrder: [{ by: 'Feld', direction: #DESC }], visualizations: [{ type: #AS_LINEITEM }] }]","text":"Die PresentationVariant legt Standardsortierung und Darstellung fest, eine SelectionVariant eine vorbelegte Filterung. Zusammen bilden sie Varianten und Ansichten, zum Beispiel „Offene Bestellungen“ als Reiter.","code":"@Metadata.layer: #CORE\n@UI.presentationVariant: [{\n  sortOrder: [{ by: 'Faellig', direction: #ASC }],\n  visualizations: [{ type: #AS_LINEITEM }]\n}]\n@UI.selectionVariant: [{\n  qualifier: 'Offen',\n  text: 'Offen',\n  filter: 'Status EQ N'\n}]\nannotate entity ZC_Bestellung with\n{\n  Faellig;\n}","pitfall":"Die genaue Schreibweise der Filter-Zeichenfolge und der Variantennamen in der aktuellen Dokumentation prüfen. Sie unterscheidet sich je nach Fiori-elements-Version.","lesson":"abap-m13-l3","tested":false,"codeLang":"abap"},{"id":"fiori-table-settings","cat":"App-Aufbau","term":"manifest.json: tableSettings (Tabellentyp, Auswahl, Anlegen)","syntax":"\"tableSettings\": { \"type\": \"ResponsiveTable\", \"selectionMode\": \"Multi\", \"creationMode\": { \"name\": \"Inline\" } }","text":"Im Manifest stellt man das Verhalten der Tabelle ein: Typ (ResponsiveTable, GridTable, AnalyticalTable), Mehrfachauswahl, Anlegemodus (NewPage, Inline, CreationRow) und Funktionen wie Export.","code":"\"controlConfiguration\": {\n  \"@com.sap.vocabularies.UI.v1.LineItem\": {\n    \"tableSettings\": {\n      \"type\": \"ResponsiveTable\",\n      \"selectionMode\": \"Multi\",\n      \"creationMode\": { \"name\": \"NewPage\" },\n      \"enableExport\": true,\n      \"condensedTableLayout\": true\n    }\n  }\n}","pitfall":"GridTable ist für große Datenmengen am Desktop gedacht, ResponsiveTable passt für Mobilgeräte. Die Wahl beeinflusst Bedienbarkeit und Barrierefreiheit.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"javascript"},{"id":"fiori-custom-column-section","cat":"Erweiterbarkeit","term":"Eigene Spalte oder Abschnitt (Fragment)","syntax":"\"columns\": { \"id\": { \"header\": …, \"template\": \"ns.ext.fragment.X\", \"position\": { \"anchor\": …, \"placement\": \"After\" } } }","text":"Wenn die Annotationen nicht genügen, ergänzt man eigene Spalten oder Abschnitte als XML-Fragment. Im Manifest steht, wo sie erscheinen (anchor, placement). Das Fragment selbst enthält die Controls.","code":"// manifest.json\n\"@com.sap.vocabularies.UI.v1.LineItem\": {\n  \"columns\": {\n    \"Risiko\": {\n      \"header\": \"{i18n>risiko}\",\n      \"template\": \"meine.bestellungen.ext.fragment.Risiko\",\n      \"position\": { \"anchor\": \"DataField::Betrag\", \"placement\": \"After\" },\n      \"availability\": \"Default\"\n    }\n  }\n}\n\n<!-- ext/fragment/Risiko.fragment.xml -->\n<core:FragmentDefinition xmlns=\"sap.m\" xmlns:core=\"sap.ui.core\">\n  <ObjectStatus text=\"{= ${Betrag} > 1000 ? 'Hoch' : 'Normal' }\" state=\"{= ${Betrag} > 1000 ? 'Warning' : 'None' }\"/>\n</core:FragmentDefinition>","pitfall":"Eigene Fragmente sind nicht automatisch barrierefrei. Beschriftung, Fokus und Farbe unabhängig prüfen. Die anchor-Namen genau aus der Dokumentation übernehmen.","lesson":"abap-m13-l1","tested":false,"codeLang":"html"},{"id":"fiori-fragment-dialog","cat":"SAPUI5 (freie Apps)","term":"Dialog als Fragment laden","syntax":"Fragment.load({ id, name, controller }).then((dlg) => { view.addDependent(dlg); dlg.open(); })","text":"Dialoge liegen in eigenen XML-Fragmenten und werden erst bei Bedarf geladen. addDependent verbindet den Dialog mit dem Model und dem Lebenszyklus der View. Beim Schließen sollte man ihn zerstören oder wiederverwenden.","code":"sap.ui.define([\"sap/ui/core/mvc/Controller\", \"sap/ui/core/Fragment\"], function (Controller, Fragment) {\n  \"use strict\";\n  return Controller.extend(\"meine.bestellungen.controller.Liste\", {\n    async onOeffneDialog() {\n      this._dialog ??= await Fragment.load({\n        id: this.getView().getId(),\n        name: \"meine.bestellungen.view.BestellDialog\",\n        controller: this\n      });\n      this.getView().addDependent(this._dialog);\n      this._dialog.open();\n    },\n    onSchliesse() {\n      this._dialog.close();\n    }\n  });\n});","pitfall":"Ohne id wird dieselbe Fragment-ID mehrfach vergeben, die Controls lassen sich dann nicht eindeutig ansprechen. Dialoge in Dialog-Titel und Fokussteuerung auf Barrierefreiheit prüfen.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-routing-nav","cat":"SAPUI5 (freie Apps)","term":"Routing: navTo und attachPatternMatched","syntax":"this.getOwnerComponent().getRouter().navTo(\"detail\", { id })    getRoute(\"detail\").attachPatternMatched(fn, this)","text":"In einer freien UI5-App legt das Manifest Routen und Ziele (Targets) fest. Der Router wechselt Seiten über navTo und ruft bei passender URL die Methode aus attachPatternMatched auf, in der man die Parameter liest.","code":"// manifest.json (Auszug)\n\"routing\": {\n  \"config\": { \"routerClass\": \"sap.m.routing.Router\", \"viewType\": \"XML\", \"viewPath\": \"meine.bestellungen.view\", \"controlId\": \"app\", \"controlAggregation\": \"pages\" },\n  \"routes\": [\n    { \"name\": \"liste\",  \"pattern\": \"\",         \"target\": \"liste\"  },\n    { \"name\": \"detail\", \"pattern\": \"detail/{id}\", \"target\": \"detail\" }\n  ],\n  \"targets\": { \"liste\": { \"viewName\": \"Liste\" }, \"detail\": { \"viewName\": \"Detail\" } }\n}\n\n// Controller Liste\nonPress(event) {\n  const id = event.getSource().getBindingContext().getProperty(\"BestellId\");\n  this.getOwnerComponent().getRouter().navTo(\"detail\", { id });\n}\n\n// Controller Detail\nonInit() {\n  this.getOwnerComponent().getRouter().getRoute(\"detail\").attachPatternMatched(this._onMatched, this);\n},\n_onMatched(event) {\n  const { id } = event.getParameter(\"arguments\");\n  this.getView().bindElement({ path: `/Bestellung('${id}')` });\n}","pitfall":"Parameter aus der URL sind Benutzereingaben. Nie direkt in Pfade oder HTML einsetzen, ohne sie zu prüfen und zu kodieren.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-filter-sorter","cat":"SAPUI5 (freie Apps)","term":"Filter, FilterOperator und Sorter","syntax":"new Filter(\"Feld\", FilterOperator.EQ, \"x\")    binding.filter([...])    binding.sort(new Sorter(\"Feld\", true))","text":"Filter und Sorter wirken auf das Binding einer Liste oder Tabelle. Bei OData-Models geht die Filterung als $filter an den Server. Mehrere Filter lassen sich mit and/or verknüpfen.","code":"sap.ui.define([\n  \"sap/ui/model/Filter\", \"sap/ui/model/FilterOperator\", \"sap/ui/model/Sorter\"\n], function (Filter, FilterOperator, Sorter) {\n  \"use strict\";\n  return {\n    onSuche(event) {\n      const text = event.getParameter(\"query\");\n      const binding = this.byId(\"tabelle\").getBinding(\"items\");\n      binding.filter(text\n        ? new Filter({ filters: [\n            new Filter(\"BestellId\", FilterOperator.Contains, text),\n            new Filter(\"KundenName\", FilterOperator.Contains, text)\n          ], and: false })\n        : []);\n      binding.sort(new Sorter(\"Faellig\", true));\n    }\n  };\n});","pitfall":"Auf großen Tabellen immer serverseitig filtern (operationMode Server). Clientseitiges Filtern lädt zuerst alles.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-expression-binding","cat":"SAPUI5 (freie Apps)","term":"Expression Binding und Formatter-Modul","syntax":"{= ${Feld} > 100 ? \"Ja\" : \"Nein\" }    {path: \"x\", formatter: \".formatter.status\"}","text":"Expression Binding rechnet kleine Ausdrücke direkt in der View: Vergleiche, ? :, !, && und ||. Für längere Logik schreibt man ein eigenes Formatter-Modul und hängt es an den Controller.","code":"<ObjectStatus\n  text=\"{= ${Betrag} > 1000 ? 'Hoch' : 'Normal' }\"\n  state=\"{= ${Status} === 'F' ? 'Success' : 'Warning' }\"\n  visible=\"{= !!${Status} }\"/>\n<Text text=\"{path: 'Status', formatter: '.formatter.statusText'}\"/>\n\n// model/formatter.js\nsap.ui.define([], function () {\n  \"use strict\";\n  return { statusText(code) { return { N: \"Neu\", F: \"Freigegeben\" }[code] ?? code; } };\n});","pitfall":"Lange Ausdrücke in der View sind schwer zu testen und zu lesen. Ab zwei Bedingungen lieber einen Formatter mit Unit-Test.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"html"},{"id":"fiori-messages","cat":"SAPUI5 (freie Apps)","term":"MessageToast, MessageBox und MessageManager","syntax":"MessageToast.show(text)    MessageBox.confirm(text, { onClose })    MessageBox.error(text)","text":"MessageToast meldet kurz und nicht blockierend. MessageBox fordert eine Entscheidung oder meldet einen Fehler im Dialog. Der MessageManager sammelt Meldungen und bindet sie an Felder.","code":"MessageBox.confirm(this.getText(\"loeschenFrage\"), {\n  title: this.getText(\"loeschenTitel\"),\n  actions: [MessageBox.Action.DELETE, MessageBox.Action.CANCEL],\n  emphasizedAction: MessageBox.Action.CANCEL,\n  onClose: (aktion) => {\n    if (aktion === MessageBox.Action.DELETE) {\n      this._loesche();\n      MessageToast.show(this.getText(\"geloescht\"));\n    }\n  }\n});","pitfall":"MessageToast verschwindet nach kurzer Zeit und ist für Screenreader flüchtig. Wichtige Fehler als MessageBox oder ValueState am Feld melden.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-odata-v2","cat":"SAPUI5 (freie Apps)","term":"OData V2 Model: read, create, update, remove","syntax":"oModel.read(\"/Menge\", { filters, success, error })    oModel.create(path, data, { … })","text":"Ältere Apps und Services nutzen OData V2. Das V2-Model arbeitet mit Pfaden und Callbacks statt mit Bindings und Promises (V4). Änderungen an Elementen gehen mit update, Löschen mit remove.","code":"const model = this.getView().getModel();\nmodel.read(\"/BestellungSet\", {\n  filters: [new Filter(\"Status\", FilterOperator.EQ, \"N\")],\n  success: (daten) => this.getView().getModel(\"ui\").setProperty(\"/liste\", daten.results),\n  error: (fehler) => MessageBox.error(this.getText(\"ladenFehler\"))\n});\nmodel.create(\"/BestellungSet\", { Betrag: \"100.00\" }, {\n  success: () => MessageToast.show(this.getText(\"angelegt\")),\n  error: () => MessageBox.error(this.getText(\"anlegenFehler\"))\n});","pitfall":"Neue Services sind OData V4 (RAP). V2 und V4 lassen sich nicht mischen. Beim Wechsel ändern sich Models, Bindings und Fehlerbehandlung.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"},{"id":"fiori-ui5-yaml","cat":"Entwicklung","term":"ui5.yaml: Framework und Proxy","syntax":"framework: { name: SAPUI5, version: …, libraries: […] }    server: customMiddleware: [ fiori-tools-proxy ]","text":"Die ui5.yaml beschreibt Projekt, UI5-Bibliotheken und Entwicklungsserver. Die Middleware fiori-tools-proxy leitet Backend-Aufrufe an das SAP-System weiter, damit die App lokal gegen echte Daten läuft, ohne CORS-Probleme.","code":"specVersion: \"4.0\"\nmetadata:\n  name: meine.bestellungen\ntype: application\nframework:\n  name: SAPUI5\n  version: \"1.136.0\"\n  libraries:\n    - name: sap.m\n    - name: sap.ui.core\n    - name: sap.fe.templates\nserver:\n  customMiddleware:\n    - name: fiori-tools-proxy\n      afterMiddleware: compression\n      configuration:\n        backend:\n          - path: /sap\n            url: https://system.example.com","pitfall":"Versionen und URLs sind Platzhalter. Keine Zugangsdaten in die Datei schreiben, sondern in eine nicht versionierte .env verwenden.","lesson":"abap-m13-quellen-fiori-ux-und-elements-list-report-und-object-page-mit-fiori-tools","tested":false,"codeLang":"bash"},{"id":"fiori-testing","cat":"Entwicklung","term":"Tests: QUnit und OPA5","syntax":"QUnit.test(\"…\", (assert) => …)    opaTest(\"…\", (Given, When, Then) => …)","text":"QUnit testet einzelne Funktionen (Formatter, Hilfsmodule). OPA5 steuert die laufende App wie ein Benutzer: Seite starten, Button drücken, prüfen, was zu sehen ist. Das Fiori-Tooling erzeugt beides als Vorlage.","code":"// webapp/test/unit/model/formatter.js\nsap.ui.define([\"meine/bestellungen/model/formatter\"], function (formatter) {\n  \"use strict\";\n  QUnit.module(\"formatter\");\n  QUnit.test(\"statusText übersetzt den Code\", function (assert) {\n    assert.strictEqual(formatter.statusText(\"N\"), \"Neu\");\n    assert.strictEqual(formatter.statusText(\"?\"), \"?\");\n  });\n});\n\n// OPA5 (Auszug)\nopaTest(\"Liste zeigt Bestellungen\", function (Given, When, Then) {\n  Given.iStartMyApp();\n  Then.onTheListPage.theTableShouldHaveEntries();\n  Then.iTeardownMyApp();\n});","pitfall":"OPA5-Tests sind langsam und fragil bei Änderungen an der Oberfläche. Wenige, wichtige Abläufe abdecken, den Rest mit schnellen QUnit-Tests.","lesson":"abap-m13-quellen-javascript-und-ui5-brucke-model-xml-view-und-controller","tested":false,"codeLang":"javascript"}]},{"id":"btp","label":"SAP BTP","codeLang":"bash","intro":"Die SAP Business Technology Platform (BTP) ist die Cloud-Plattform von SAP. Apps laufen meist in der Cloud-Foundry-Umgebung oder in der ABAP-Umgebung. Gesteuert wird sie über die Kommandozeilen cf und btp sowie über MTA-Dateien.","notice":"Diese Beispiele sind nicht gegen ein BTP-Konto ausgeführt. Sie folgen der dokumentierten Syntax; Regionen, Organisationen, Plan- und Servicenamen sind Platzhalter.","runner":"","entries":[{"id":"btp-cf-login","cat":"Cloud Foundry (cf CLI)","term":"cf login, target und sso","syntax":"cf login -a <api-endpunkt> --sso    cf target -o <org> -s <space>","text":"Meldet an einer Cloud-Foundry-Umgebung an. Mit --sso erhält man einen Einmalcode im Browser (für Single Sign-on), sodass das Passwort nie im Terminal steht. cf target wechselt Organisation und Space.","code":"cf login -a https://api.cf.eu10.hana.ondemand.com --sso\ncf target -o meine-org -s dev\ncf target","pitfall":"Der API-Endpunkt hängt von Region und Anbieter ab. Passwörter und Einmalcodes nie in Skripte oder Repositories schreiben.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-push","cat":"Cloud Foundry (cf CLI)","term":"cf push und manifest.yml","syntax":"cf push    cf push -f manifest.yml    cf restart <app>    cf scale <app> -i 2","text":"Lädt eine App hoch und startet sie. Die manifest.yml beschreibt Name, Speicher, Instanzen, Buildpack und Umgebungsvariablen. cf scale ändert Instanzen oder Speicher im laufenden Betrieb.","code":"cf push -f manifest.yml\ncf scale meine-app -i 2 -m 512M\ncf restart meine-app\n\n# manifest.yml\n# applications:\n#   - name: meine-app\n#     memory: 256M\n#     instances: 1\n#     buildpacks: [nodejs_buildpack]\n#     path: ./dist","pitfall":"Geheimnisse gehören nicht in die manifest.yml. Dafür gebundene Services oder Umgebungsvariablen über das Konto nutzen.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-inspect","cat":"Cloud Foundry (cf CLI)","term":"cf apps, logs, env, events","syntax":"cf apps    cf logs <app> --recent    cf env <app>    cf events <app>","text":"Zeigen den Zustand einer App. cf logs --recent gibt die letzten Protokollzeilen aus, cf logs (ohne --recent) streamt live, cf env listet die Umgebung samt gebundener Services.","code":"cf apps\ncf logs meine-app --recent\ncf events meine-app\ncf env meine-app","pitfall":"cf env enthält Zugangsdaten der gebundenen Services (VCAP_SERVICES). Ausgabe nie in Tickets, Chats oder Logs weitergeben.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-service","cat":"Cloud Foundry (cf CLI)","term":"cf create-service, bind-service, create-service-key","syntax":"cf marketplace    cf create-service <service> <plan> <instanz>    cf bind-service <app> <instanz>","text":"Services (Datenbank, XSUAA, Destination, ABAP-Umgebung) werden aus dem Marketplace als Instanz angelegt und an Apps gebunden. Ein Service Key liefert Zugangsdaten für Werkzeuge oder externe Clients.","code":"cf marketplace\ncf create-service xsuaa application meine-xsuaa -c xs-security.json\ncf bind-service meine-app meine-xsuaa\ncf restage meine-app\ncf create-service-key meine-xsuaa schluessel-dev","pitfall":"Nach bind-service muss die App mit restage oder restart neu starten, sonst sieht sie die neuen Zugangsdaten nicht. Service Keys nach Gebrauch löschen.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-mta","cat":"Deployment (MTA)","term":"mta.yaml: Module, Ressourcen, Abhängigkeiten","syntax":"modules:  - name: …  type: …  requires: [ … ]    resources:  - name: …  type: org.cloudfoundry.managed-service","text":"Ein Multitarget Application (MTA) bündelt mehrere Module (Backend, UI) und die benötigten Services (resources) in einer Beschreibung. Mit requires verbindet man Module mit Ressourcen, sodass die Zugangsdaten automatisch gebunden werden.","code":"_schema-version: \"3.3\"\nID: bestellungen\nversion: 1.0.0\n\nmodules:\n  - name: bestellungen-srv\n    type: nodejs\n    path: srv\n    requires:\n      - name: bestellungen-auth\n    provides:\n      - name: srv-api\n        properties:\n          url: ${default-url}\n\nresources:\n  - name: bestellungen-auth\n    type: org.cloudfoundry.managed-service\n    parameters:\n      service: xsuaa\n      service-plan: application\n      path: ./xs-security.json","pitfall":"Einrückung und Namen müssen exakt stimmen. Namen in requires müssen zu resources oder provides eines anderen Moduls passen.","lesson":"abap-m14-l2","tested":false,"codeLang":"bash"},{"id":"btp-mbt-deploy","cat":"Deployment (MTA)","term":"mbt build und cf deploy","syntax":"mbt build -t gen --mtar app.mtar    cf deploy gen/app.mtar","text":"Das Multitarget Application Build Tool (mbt) erzeugt aus der mta.yaml ein Archiv (.mtar). cf deploy (Plugin multiapps) installiert es und legt Apps und Services in einem Schritt an.","code":"npm install --global mbt\nmbt build -t gen --mtar bestellungen.mtar\ncf deploy gen/bestellungen.mtar\ncf mta bestellungen","pitfall":"Das Deployment ersetzt vorhandene Apps. Erst in Entwicklungs- oder Testspace ausrollen und Rollback (alte .mtar behalten) planen.","lesson":"abap-m14-l2","tested":false},{"id":"btp-xs-security","cat":"Sicherheit und Identität","term":"xs-security.json (Scopes und Rollen)","syntax":"{ \"xsappname\": …, \"scopes\": [ … ], \"role-templates\": [ … ] }","text":"Beschreibt für den Service XSUAA, welche Berechtigungen (Scopes) eine App kennt und welche Rollenvorlagen daraus entstehen. Administratoren ordnen die Rollen im Cockpit Gruppen und Benutzern zu.","code":"{\n  \"xsappname\": \"bestellungen\",\n  \"tenant-mode\": \"dedicated\",\n  \"scopes\": [\n    { \"name\": \"$XSAPPNAME.Lesen\", \"description\": \"Bestellungen lesen\" },\n    { \"name\": \"$XSAPPNAME.Schreiben\", \"description\": \"Bestellungen ändern\" }\n  ],\n  \"role-templates\": [\n    { \"name\": \"Betrachter\", \"scope-references\": [\"$XSAPPNAME.Lesen\"] },\n    { \"name\": \"Bearbeiter\", \"scope-references\": [\"$XSAPPNAME.Lesen\", \"$XSAPPNAME.Schreiben\"] }\n  ]\n}","pitfall":"Scopes im Backend immer serverseitig prüfen. Ausgeblendete Schaltflächen in der Oberfläche sind kein Schutz.","lesson":"abap-m14-senior-btp-identity","tested":false,"codeLang":"javascript"},{"id":"btp-destination","cat":"Sicherheit und Identität","term":"Destination","syntax":"Name, URL, Authentication, ProxyType, Properties","text":"Eine Destination ist ein benannter Verbindungseintrag auf ein Zielsystem (URL, Anmeldeart, Proxytyp). Apps verwenden nur den Namen und lesen URL und Zugangsdaten aus dem Destination Service. So stehen sie nie im Code.","code":"# Beispiel einer Destination (Eigenschaften)\nName=S4_ODATA\nType=HTTP\nURL=https://s4.example.com/sap/opu/odata4/…\nAuthentication=OAuth2SAMLBearerAssertion\nProxyType=Internet\nProperty:HTML5.DynamicDestination=true\nProperty:WebIDEEnabled=true","pitfall":"Für Systeme im Firmennetz ist ProxyType=OnPremise mit Cloud Connector nötig. Mit Internet erreicht die Cloud das Zielsystem nicht.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-cloud-connector","cat":"Sicherheit und Identität","term":"Cloud Connector und Principal Propagation","syntax":"Subaccount → Cloud Connector → virtueller Host → internes System","text":"Der Cloud Connector baut eine ausgehende, verschlüsselte Verbindung aus dem Firmennetz in die BTP auf, ohne dass Ports nach außen geöffnet werden. Er gibt nur freigegebene Pfade frei. Mit Principal Propagation reicht er die Identität des Benutzers an das Backend weiter.","code":"# Prüfpunkte nach der Einrichtung\n1. Cloud Connector zeigt Verbindung zum Subaccount: „connected“\n2. System-Mapping: virtueller Host s4virtuell:443 → interner Host\n3. Ressourcen: nur nötige Pfade, z. B. /sap/opu/odata4/ freigeben\n4. Destination: ProxyType=OnPremise, URL=http://s4virtuell:443/…\n5. In der Destination „Check Connection“ ausführen","pitfall":"Freigaben so eng wie möglich halten (Pfadpräfix statt „/“). Wer „/“ freigibt, öffnet das gesamte Backend für die Cloud-Anwendung.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-cli","cat":"Konto und Verwaltung (btp CLI)","term":"btp login, list, create","syntax":"btp login    btp list accounts/subaccount    btp create accounts/subaccount …","text":"Die btp CLI verwaltet Global Account, Subaccounts, Berechtigungen und Entitlements per Skript. Mit btp help <aktion> sieht man alle Parameter der installierten Version.","code":"btp login --sso\nbtp list accounts/subaccount\nbtp get accounts/subaccount <subaccount-id>\nbtp help create accounts/subaccount","pitfall":"Die Befehlsgruppen und Parameter ändern sich. Nicht aus Beispielen kopieren, sondern mit btp help in der installierten Version prüfen.","lesson":"abap-m14-l2","tested":false},{"id":"btp-abap-env","cat":"ABAP-Umgebung","term":"ABAP-Umgebung: Instanz und Service Key","syntax":"cf create-service abap standard <name> -c config.json    cf create-service-key <name> <key>","text":"In der ABAP-Umgebung (Steampunk) entwickelt man mit ABAP Cloud und den ABAP Development Tools (ADT). Die Verbindung zur Instanz entsteht über einen Service Key mit den Anmeldeinformationen oder über das Cockpit.","code":"cf create-service abap standard mein-abap -c '{\"admin_email\":\"admin@example.org\",\"is_development_allowed\":true}'\ncf create-service-key mein-abap adt-zugang\ncf service-key mein-abap adt-zugang","pitfall":"Die Ausgabe von cf service-key enthält Zugangsdaten. Nur lokal verwenden und den Key danach löschen, wenn er nicht mehr gebraucht wird.","lesson":"abap-m14-l1","tested":false},{"id":"btp-released-api","cat":"ABAP-Umgebung","term":"Released APIs und Clean Core","syntax":"ABAP Cloud: nur freigegebene Objekte (C1-Vertrag) nutzen","text":"In ABAP Cloud darf Code nur freigegebene Schnittstellen verwenden (C1-Vertrag). So bleiben Erweiterungen upgradesicher und der Kern „sauber“. ADT zeigt die Freigabe im Property-Reiter eines Objekts.","code":"\" Erlaubt: freigegebene Klasse\nDATA(lv_datum) = cl_abap_context_info=>get_system_date( ).\n\n\" Nicht erlaubt in ABAP Cloud: direkter Zugriff auf nicht freigegebene Tabellen (z. B. MARA)\n\" Stattdessen: freigegebene CDS-View, z. B. I_Product","pitfall":"Der ATC-Check mit der Variante für ABAP Cloud findet Verstöße früh. Vor jedem Transport laufen lassen.","lesson":"abap-m14-l1","tested":false,"codeLang":"abap"},{"id":"btp-s4-migration","cat":"ABAP-Umgebung","term":"S/4HANA: Custom-Code-Migration","syntax":"ATC-Variante S4HANA_READINESS_<Version>    SUSG / SCMON (Nutzung)","text":"Vor der Migration wird der eigene Code (Z-Objekte) geprüft: Welche Programme nutzt jemand wirklich (Nutzungsdaten), welche verletzen S/4HANA-Regeln (ATC-Check), welche lassen sich löschen? Das senkt Aufwand und Risiko.","code":"1. Nutzung sammeln (SCMON/SUSG) – mindestens ein Geschäftsjahr\n2. Ungenutzten Code kennzeichnen und nach Freigabe entfernen\n3. ATC-Prüfung mit der S4HANA_READINESS-Variante passend zur Ziel-Version (Name je nach System)\n4. Funde nach Priorität beheben, dann Regressionstests\n5. Erweiterungen schrittweise nach Clean-Core-Level A/B verlagern","pitfall":"Nutzungsdaten über einen zu kurzen Zeitraum übersehen Jahresabschluss-Programme. Vor dem Löschen immer die Fachabteilung fragen.","lesson":"abap-m14-senior-s4-migration","tested":false},{"id":"btp-extension-models","cat":"ABAP-Umgebung","term":"Erweiterungsarten im Vergleich","syntax":"Key User – Developer (in-app) – Side-by-Side (BTP)","text":"Key-User-Erweiterungen nehmen Fachanwender direkt in der App vor (Felder, Regeln). Developer-Erweiterungen (in-app) schreibt man in ABAP Cloud im selben System. Side-by-Side-Erweiterungen laufen als eigene App auf der BTP und sprechen den Kern über APIs und Events an.","code":"Faustregel zur Auswahl:\n- Nur ein Feld oder eine Maske ergänzen?        → Key User\n- Logik in der Transaktion, gleiche Daten?      → Developer (in-app)\n- Eigene App, anderer Lebenszyklus, externe Nutzer? → Side-by-Side","pitfall":"Side-by-Side ist nicht automatisch besser. Es bringt zusätzliche Kosten, Betrieb und Latenz. Die Wahl nach Datennähe und Änderungsrhythmus treffen.","lesson":"abap-m14-l3","tested":false},{"id":"btp-cf-lifecycle","cat":"Cloud Foundry (cf CLI)","term":"cf start, stop, restart, restage, delete, rolling","syntax":"cf stop <app>    cf restart <app> --strategy rolling    cf restage <app>    cf delete <app> -r","text":"stop und start halten eine App an oder starten sie. restart startet neu, mit --strategy rolling ohne Ausfall (Instanzen nacheinander). restage baut die App mit dem Buildpack neu (nötig nach Änderung gebundener Services). delete -r entfernt auch die Routen.","code":"cf stop meine-app\ncf start meine-app\ncf restart meine-app --strategy rolling\ncf restage meine-app\ncf push meine-app --strategy rolling\ncf delete meine-app -r -f","pitfall":"cf delete ist endgültig und löscht Logs der App. Gebundene Services bleiben bestehen und laufen (und kosten) weiter, bis man sie ebenfalls löscht.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-env-vars","cat":"Cloud Foundry (cf CLI)","term":"cf set-env, unset-env und VCAP_SERVICES","syntax":"cf set-env <app> NAME wert    cf unset-env <app> NAME    cf restage <app>","text":"Umgebungsvariablen steuern das Verhalten einer App je Space. Zugangsdaten gebundener Services stehen automatisch als JSON in VCAP_SERVICES. Nach einer Änderung braucht die App einen Neustart (restage).","code":"cf set-env meine-app LOG_LEVEL info\ncf unset-env meine-app LOG_LEVEL\ncf restage meine-app\n\n# Ausgabe enthält Geheimnisse – nicht teilen\ncf env meine-app","pitfall":"Mit set-env gesetzte Werte stehen im Klartext in der App-Konfiguration. Geheimnisse besser über Service-Bindings oder einen Credential Store verwalten.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-vcap-xsenv","cat":"Sicherheit und Identität","term":"VCAP_SERVICES lesen (@sap/xsenv)","syntax":"const xsenv = require(\"@sap/xsenv\");  xsenv.getServices({ uaa: { tag: \"xsuaa\" } })","text":"Gebundene Services liefern ihre Zugangsdaten in der Umgebungsvariable VCAP_SERVICES. Die Bibliothek @sap/xsenv liest sie komfortabel aus und findet Services über Name oder Tag. Lokal können die Werte aus einer default-env.json kommen.","code":"import xsenv from \"@sap/xsenv\";\n\nconst { uaa } = xsenv.getServices({ uaa: { tag: \"xsuaa\" } });\n// uaa.url, uaa.clientid, uaa.xsappname … (clientsecret nie ausgeben oder loggen)\n\n// ohne Bibliothek\nconst vcap = JSON.parse(process.env.VCAP_SERVICES ?? \"{}\");\nconst xsuaa = vcap.xsuaa?.[0]?.credentials;","pitfall":"default-env.json für lokale Entwicklung enthält echte Zugangsdaten und gehört in .gitignore. Niemals committen.","lesson":"abap-m14-senior-btp-identity","tested":false,"codeLang":"javascript"},{"id":"btp-cf-ssh-health","cat":"Cloud Foundry (cf CLI)","term":"cf ssh, cf app und Health Check","syntax":"cf ssh <app>    cf app <app>    cf set-health-check <app> http --endpoint /health","text":"cf app zeigt Instanzen, Speicher und Zustand. cf ssh öffnet eine Shell im Container, wenn SSH für den Space erlaubt ist. Ein HTTP-Health-Check prüft einen Endpunkt, damit Cloud Foundry hängende Instanzen neu startet.","code":"cf app meine-app\ncf set-health-check meine-app http --endpoint /health\ncf restart meine-app\ncf ssh meine-app","pitfall":"Änderungen per SSH gehen beim nächsten Neustart verloren und sind kein Weg, Fehler dauerhaft zu beheben. SSH in Produktion nach Möglichkeit deaktiviert lassen.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-routes","cat":"Cloud Foundry (cf CLI)","term":"cf routes, map-route, create-route","syntax":"cf routes    cf map-route <app> <domain> --hostname <name>    cf unmap-route …","text":"Eine Route verbindet Hostname und Domain mit einer App. Mehrere Routen auf eine App oder mehrere Apps auf eine Route sind möglich (zum Beispiel für Blue-Green-Deployments).","code":"cf routes\ncf create-route cfapps.eu10.hana.ondemand.com --hostname bestellungen-test\ncf map-route meine-app cfapps.eu10.hana.ondemand.com --hostname bestellungen-test\ncf unmap-route meine-app cfapps.eu10.hana.ondemand.com --hostname bestellungen-test","pitfall":"Hostnamen sind je Domain global eindeutig. Ein bereits vergebener Name lässt sich nicht noch einmal anlegen. Eine öffentliche Route ist von jedem erreichbar: Zugriff immer über Anmeldung schützen.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-org-space","cat":"Cloud Foundry (cf CLI)","term":"Orgs, Spaces und Rollen","syntax":"cf orgs    cf spaces    cf create-space <name>    cf set-space-role <user> <org> <space> SpaceDeveloper","text":"Cloud Foundry gliedert sich in Organisationen (Subaccount) und Spaces (zum Beispiel dev, test, prod). Rollen wie SpaceDeveloper oder SpaceManager steuern, wer Apps ausrollen darf. cf services listet die Service-Instanzen des Spaces.","code":"cf orgs\ncf spaces\ncf create-space test\ncf set-space-role anna@example.org meine-org test SpaceDeveloper\ncf services\ncf marketplace -e abap","pitfall":"Produktionsspaces mit möglichst wenigen Entwicklern (Prinzip der minimalen Rechte). Ausrollen in Produktion über eine Pipeline, nicht von Hand.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-approuter","cat":"Sicherheit und Identität","term":"Application Router: xs-app.json","syntax":"{ \"welcomeFile\": …, \"authenticationMethod\": \"route\", \"routes\": [ { \"source\": …, \"destination\": …, \"authenticationType\": \"xsuaa\" } ] }","text":"Der Application Router ist der Eingang einer BTP-App: Er übernimmt die Anmeldung (XSUAA), reicht den Token weiter und leitet Pfade an Backends (Destinations) weiter. Die Regeln stehen in der xs-app.json.","code":"{\n  \"welcomeFile\": \"/index.html\",\n  \"authenticationMethod\": \"route\",\n  \"logout\": { \"logoutEndpoint\": \"/do/logout\" },\n  \"routes\": [\n    {\n      \"source\": \"^/api/(.*)$\",\n      \"target\": \"$1\",\n      \"destination\": \"srv-api\",\n      \"authenticationType\": \"xsuaa\",\n      \"csrfProtection\": true\n    },\n    {\n      \"source\": \"^(.*)$\",\n      \"target\": \"$1\",\n      \"service\": \"html5-apps-repo-rt\",\n      \"authenticationType\": \"xsuaa\"\n    }\n  ]\n}","pitfall":"Eine Route mit authenticationType none ist öffentlich. Nur für wirklich öffentliche Dateien verwenden. Backend zusätzlich selbst gegen Token prüfen.","lesson":"abap-m14-senior-btp-identity","tested":false,"codeLang":"javascript"},{"id":"btp-token-test","cat":"Sicherheit und Identität","term":"Token abrufen (client_credentials) und Scopes prüfen","syntax":"curl -u \"$CLIENT_ID:$CLIENT_SECRET\" -d grant_type=client_credentials \"$UAA_URL/oauth/token\"","text":"Zum Testen einer geschützten API holt man mit den Zugangsdaten eines Service Keys ein Access-Token und schickt es als Bearer-Header mit. Im Token (JWT) stehen die Scopes, die die App prüft.","code":"# Zugangsdaten aus einem Service Key in Umgebungsvariablen (nicht im Skript!)\nTOKEN=$(curl -s -u \"$CLIENT_ID:$CLIENT_SECRET\" -d grant_type=client_credentials \"$UAA_URL/oauth/token\" | jq -r .access_token)\n\ncurl -H \"Authorization: Bearer $TOKEN\" https://meine-app.cfapps.eu10.hana.ondemand.com/api/aufgaben\n\n# Scopes ansehen (nur lokal dekodieren, Token nie in Online-Dekodierer einfügen)\necho \"$TOKEN\" | cut -d. -f2 | base64 -d 2>/dev/null | jq .scope","pitfall":"Token und Client Secret sind Geheimnisse. Nicht in Shell-Verlauf, Tickets oder Chats einfügen. Token haben eine kurze Lebensdauer (meist 12 Stunden oder weniger).","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-destination-code","cat":"Sicherheit und Identität","term":"Destination im Code nutzen (SAP Cloud SDK)","syntax":"executeHttpRequest({ destinationName: \"S4_ODATA\" }, { method: \"get\", url: \"/pfad\" })","text":"Das SAP Cloud SDK löst eine Destination zur Laufzeit auf (URL, Anmeldeart, Proxy), sodass der Code nur den Namen kennt. Das funktioniert auch für Systeme hinter dem Cloud Connector.","code":"import { executeHttpRequest } from \"@sap-cloud-sdk/http-client\";\n\nconst antwort = await executeHttpRequest(\n  { destinationName: \"S4_ODATA\" },\n  { method: \"get\", url: \"/sap/opu/odata4/sap/api_business_partner/srvd_a2x/sap/businesspartner/0001/BusinessPartner?$top=5\" }\n);\nconsole.log(antwort.data.value.length);","pitfall":"Antworten fremder Systeme nicht ungeprüft weitergeben. Fehler abfangen und ohne interne Details an den Aufrufer melden.","lesson":"abap-m14-senior-btp-identity","tested":false,"codeLang":"javascript"},{"id":"btp-cap-commands","cat":"CAP (Cloud Application Programming Model)","term":"cds init, watch, add, deploy","syntax":"cds init <projekt>    cds watch    cds add hana,xsuaa,mta    cds build    cds deploy","text":"CAP ist das Programmiermodell von SAP für Cloud-Anwendungen in Node.js oder Java. cds init legt ein Projekt an, cds watch startet lokal mit automatischem Neuladen und einer SQLite-Datenbank, cds add ergänzt Bausteine wie HANA, Anmeldung und das MTA-Archiv.","code":"npm install --global @sap/cds-dk\ncds init bestellungen\ncd bestellungen\ncds add hana,xsuaa,mta\ncds watch\n\nmbt build\ncf deploy mta_archives/bestellungen_1.0.0.mtar","pitfall":"cds watch nutzt lokal eine Mock-Anmeldung und SQLite. Das Verhalten mit echter Anmeldung und HANA muss in einer Testumgebung geprüft werden.","lesson":"abap-m14-l1","tested":false},{"id":"btp-cap-model","cat":"CAP (Cloud Application Programming Model)","term":"CAP: Datenmodell, Service und Zugriffsschutz (CDS)","syntax":"entity X : cuid, managed { … }    service S { entity X as projection on db.X; }    @requires / @restrict","text":"Das Datenmodell wird in CDS beschrieben (db/schema.cds), ein Service legt fest, was nach außen sichtbar ist (srv/…cds). cuid liefert eine UUID als Schlüssel, managed ergänzt Zeitstempel und Benutzer. @restrict regelt, wer lesen oder schreiben darf.","code":"// db/schema.cds\nnamespace de.rootpfad;\nusing { cuid, managed } from '@sap/cds/common';\nentity Bestellung : cuid, managed {\n  titel  : String(100) @mandatory;\n  betrag : Decimal(10,2);\n  status : String(1) default 'N';\n}\n\n// srv/bestell-service.cds\nusing de.rootpfad as db from '../db/schema';\n@requires: 'authenticated-user'\nservice BestellService {\n  @restrict: [{ grant: 'READ', to: 'Betrachter' }, { grant: ['CREATE','UPDATE'], to: 'Bearbeiter' }]\n  entity Bestellung as projection on db.Bestellung;\n  action freigeben(id: UUID) returns Bestellung;\n}","pitfall":"Ohne @requires oder @restrict ist ein Service für jeden Angemeldeten (oder sogar anonym) offen. Rollen im CDS und in der xs-security.json müssen zusammenpassen.","lesson":"abap-m14-l1","tested":false,"codeLang":"javascript"},{"id":"btp-btp-cli-roles","cat":"Konto und Verwaltung (btp CLI)","term":"btp: Entitlements und Rollensammlungen","syntax":"btp assign accounts/entitlement …    btp assign security/role-collection \"<name>\" --to-user <user>","text":"Bevor man einen Service anlegen kann, braucht das Subaccount ein Entitlement (Kontingent). Rechte für Benutzer vergibt man über Rollensammlungen. Mit btp help <aktion> sieht man die genauen Parameter der installierten Version.","code":"btp list accounts/entitlement --subaccount <subaccount-id>\nbtp assign accounts/entitlement --to-subaccount <subaccount-id> --for-service abap --plan standard --amount 1\nbtp list security/role-collection --subaccount <subaccount-id>\nbtp assign security/role-collection \"Bestellung Bearbeiter\" --to-user anna@example.org --subaccount <subaccount-id>\nbtp help assign accounts/entitlement","pitfall":"Entitlements können Kosten verursachen. Mengen und Pläne vorher klären. Rollensammlungen sparsam und nach dem Prinzip der minimalen Rechte vergeben.","lesson":"abap-m14-senior-btp-identity","tested":false},{"id":"btp-mta-extension","cat":"Deployment (MTA)","term":"MTA-Erweiterung, undeploy und Versionsregeln","syntax":"cf deploy app.mtar -e prod.mtaext    cf undeploy <id> --delete-services    cf deploy … --version-rule ALL","text":"Eine .mtaext-Datei ergänzt die mta.yaml für eine Umgebung (zum Beispiel andere Instanzzahl oder Service-Plan), ohne die Hauptdatei zu ändern. undeploy entfernt eine gesamte MTA. --version-rule steuert, ob ältere Versionen überschrieben werden.","code":"# prod.mtaext\n# _schema-version: \"3.3\"\n# ID: bestellungen.prod\n# extends: bestellungen\n# modules:\n#   - name: bestellungen-srv\n#     parameters: { instances: 2, memory: 512M }\n\ncf deploy gen/bestellungen.mtar -e prod.mtaext --version-rule ALL\ncf mta bestellungen\ncf undeploy bestellungen --delete-services --delete-service-keys","pitfall":"--delete-services entfernt auch Datenbanken und deren Inhalt. Vor dem Undeploy Sicherung prüfen und die Service-Liste kontrollieren.","lesson":"abap-m14-l2","tested":false},{"id":"btp-cf-user-provided","cat":"Cloud Foundry (cf CLI)","term":"cf create-user-provided-service","syntax":"cf create-user-provided-service <name> -p '{\"url\":\"…\"}'    cf bind-service …","text":"Ein User-Provided Service legt beliebige Zugangsdaten (zum Beispiel für ein externes System) als Service-Instanz ab. Die App liest sie wie jedes andere Binding aus VCAP_SERVICES. Praktisch, wenn kein Marketplace-Service existiert.","code":"cf create-user-provided-service mein-drittsystem -p url,token\n# Eingabe der Werte erfolgt interaktiv und landet nicht im Shell-Verlauf\ncf bind-service meine-app mein-drittsystem\ncf restage meine-app","pitfall":"Werte nicht als Parameter im Befehl angeben (Shell-Verlauf). Die interaktive Eingabe oder eine Datei mit eingeschränkten Rechten verwenden.","lesson":"abap-m14-senior-btp-identity","tested":false}]}];
